def _clean_display_text(value):
    if not isinstance(value, str):
        return value
    replacements = {
        "AA" + "YacA": "Ağacı",
        "AA" + "Y": "ş",
        "AY" + "ampiyon": "şampiyon",
        "AY" + "ampiyonluk": "şampiyonluk",
        "do" + "AY" + "dun": "doğdun",
        "yAldlar": "yıldızlar",
        "yAllar": "yıllar",
        "yaAYA": "yaşa",
        "yar" + "AA" + "YA": "yarısı",
        "TA1/4rkiye": "Türkiye",
        "TArkiye": "Türkiye",
        "SAA1/4per": "Süper",
        "SAper": "Süper",
        "FenerbahASe": "Fenerbahçe",
        "FENERBAHAE": "FENERBAHÇE",
        "A+": "ç",
        "A1/4": "ü",
        "A-": "ı",
        "Ã§": "ç",
        "Ã‡": "Ç",
        "ÅŸ": "ş",
        "Åž": "Ş",
        "ÄŸ": "ğ",
        "Äž": "Ğ",
        "Ä±": "ı",
        "Ä°": "İ",
        "Ã¼": "ü",
        "Ãœ": "Ü",
        "Ã¶": "ö",
        "Ã–": "Ö",
        "a" + "TM" + "A": "Tired",
    }
    for bad, good in replacements.items():
        value = value.replace(bad, good)
    return value


def _set_sleeping_state(m, guild_id=None, sleeping=False, sleep_until=None):
    internal = m.setdefault("internal", {})
    internal["is_sleeping"] = bool(sleeping)
    internal["sleep_until"] = sleep_until
    if guild_id:
        gs = internal.setdefault("guild_states", {}).setdefault(
            str(guild_id), {"is_sleeping": False, "mood": "Content", "last_interaction_at": None}
        )
        gs["is_sleeping"] = bool(sleeping)
        gs["sleep_until"] = sleep_until


def _set_dead_state(m, guild_id, dead=True, cause=None):
    """Set or clear the per-guild death state and sync to global internal."""
    internal = m.setdefault("internal", {})
    gs = internal.setdefault("guild_states", {}).setdefault(
        str(guild_id) if guild_id else "dm",
        {"is_sleeping": False, "is_dead": False, "mood": "Content", "last_interaction_at": None},
    )
    gs["is_dead"] = bool(dead)
    internal["is_dead"] = bool(dead)
    if cause is not None:
        internal["cause_of_death"] = cause


# Maps our lang codes -> LibreTranslate language codes (None = no translation needed)
_LIBRE_LANG_MAP = {
    "TR": "tr",
    "ES": "es",
    "ZH": "zh",
    "DE": "de",
    "FR": "fr",
    "JA": "ja",
    "EN-GB": None,
    "EN-US": None,
}

# Public LibreTranslate mirrors tried in order
_LIBRE_HOSTS = [
    "https://libretranslate.com",
    "https://translate.argosopentech.com",
    "https://translate.fedilab.app",
]


async def _translate_text(text: str, target: str) -> str:
    """Translate text to target LibreTranslate language code.
    Preserves **bold** and `code` tokens by replacing them with placeholders
    before translating, then restoring them. Returns original on any error.
    """
    if not text or not target or aiohttp is None:
        return text

    placeholder_map: list = []
    protected = text

    def _protect(pattern):
        nonlocal protected
        matches = list(re.finditer(pattern, protected))
        for m in reversed(matches):
            idx = len(placeholder_map)
            token = f"⟦{idx}⟧"
            placeholder_map.append((token, m.group(0)))
            protected = protected[:m.start()] + token + protected[m.end():]

    _protect(r"\*\*[^*]+\*\*")   # **bold / sounds**
    _protect(r"`[^`]+`")          # `code`
    _protect(r"https?://\S+")     # URLs

    to_translate = protected if placeholder_map else text

    timeout = aiohttp.ClientTimeout(total=8)
    for host in _LIBRE_HOSTS:
        try:
            async with aiohttp.ClientSession(timeout=timeout) as session:
                payload = {"q": to_translate, "source": "en", "target": target, "format": "text"}
                async with session.post(f"{host}/translate", json=payload) as resp:
                    if resp.status != 200:
                        continue
                    data = await resp.json()
                    translated = data.get("translatedText", "")
                    if not translated:
                        continue
                    for token, original in placeholder_map:
                        translated = translated.replace(token, original)
                    return translated
        except Exception:
            continue

    return text  # all mirrors failed; return original unchanged


_CAT_SOUNDS = [
    "**mrr.**", "**mrrp.**", "**...mrr.**", "**prrr.**", "**prrt.**",
    "**mrow.**", "**mreow.**", "**...mrow.**", "**hff.**", "**...hff.**",
    "**mrrrow.**", "**prp.**", "**...prrr.**", "**mrrup.**", "**reow.**",
    "**...mrrp.**", "**mrf.**", "**...mrf.**", "**prrp.**", "**mreoww.**",
]

def _strip_to_cat_sounds(text: str) -> str:
    """When narrator is off, strip all italic narration and bold narration,
    leaving only raw cat sounds, then pad with extra sounds if the result is thin."""
    import re
    # Extract bold cat-sound tokens like **mrr.** or *mrr* — anything bold/italic short
    kept = []
    # Keep **word** bold tokens that look like sounds (short, no spaces)
    for m in re.finditer(r'\*\*([^*\n]{1,20})\*\*', text):
        kept.append(f"**{m.group(1)}**")
    # Keep *word* italic tokens that look like sounds (short, no spaces, no sentence structure)
    for m in re.finditer(r'(?<!\*)\*([^*\n]{1,15})\*(?!\*)', text):
        val = m.group(1).strip()
        # Only keep if it looks like a sound (no spaces, or very short with one space max)
        if len(val.split()) <= 2 and not val[0].isupper():
            kept.append(f"*{val}*")
    if kept:
        # Deduplicate while preserving order
        seen = set()
        result = []
        for k in kept:
            if k not in seen:
                seen.add(k)
                result.append(k)
        return " ".join(result)
    # Nothing kept — return a random cat sound
    return random.choice(_CAT_SOUNDS)


def _install_send_cleaner():
    if getattr(discord.abc.Messageable, "_yarnaby_send_cleaned", False):
        return
    original_send = discord.abc.Messageable.send

    async def cleaned_send(self, content=None, *args, **kwargs):
        if content is not None:
            content = _clean_display_text(content)
            # --- NARRATOR MODE CHECK ---
            try:
                guild_id = str(getattr(getattr(self, 'guild', None), 'id', None))
                narrator_off = bot.db["internal"].get("guild_states", {}).get(guild_id, {}).get("narrator_off", False)
                if narrator_off and content:
                    content = _strip_to_cat_sounds(content)
            except Exception:
                pass
            try:
                guild_id = getattr(getattr(self, 'guild', None), 'id', None)
                lang_code = _get_lang(bot.db, guild_id)
                libre_target = _LIBRE_LANG_MAP.get(lang_code)
                if libre_target:
                    content = await _translate_text(content, libre_target)
            except Exception:
                pass  # never break sending due to translation failure

        if "embed" in kwargs and kwargs["embed"] is not None:
            try:
                emb = kwargs["embed"]
                guild_id = getattr(getattr(self, 'guild', None), 'id', None)
                lang_code = _get_lang(bot.db, guild_id)
                libre_target = _LIBRE_LANG_MAP.get(lang_code)
                if emb.title:
                    emb.title = _clean_display_text(emb.title)
                    if libre_target:
                        emb.title = await _translate_text(emb.title, libre_target)
                if emb.description:
                    emb.description = _clean_display_text(emb.description)
                    if libre_target:
                        emb.description = await _translate_text(emb.description, libre_target)
            except Exception:
                pass
        return await original_send(self, content, *args, **kwargs)

    discord.abc.Messageable.send = cleaned_send
    discord.abc.Messageable._yarnaby_send_cleaned = True



def _resolve_messageable(client, channel_id):
    """Resolve a channel id to a messageable channel, or None.

    Wraps `client.get_channel` and narrows the result so static checkers
    know the returned object actually has `.send()`. Returns None when the
    id is empty, the channel is not in the cache, or the channel is not
    messageable (e.g. CategoryChannel / ForumChannel).
    """
    if not channel_id:
        return None
    try:
        ch = client.get_channel(int(channel_id))
    except (TypeError, ValueError):
        return None
    if ch is None:
        return None
    if isinstance(ch, discord.abc.Messageable):
        return ch
    return None


def _track_item(m, item, rarity=None, source="gift"):
    """Add or bump an item in Yarnaby's inventory."""
    inv = m.setdefault("inventory", {})
    entry = inv.setdefault(
        item,
        {"count": 0, "rarity": rarity, "source": source, "first_added": None, "last_added": None},
    )
    entry["count"] += 1
    if rarity and not entry.get("rarity"):
        entry["rarity"] = rarity
    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if not entry.get("first_added"):
        entry["first_added"] = now_str
    entry["last_added"] = now_str


def _cooldown_remaining(m, key, seconds):
    """Return how many seconds remain on a named cooldown (0 if ready)."""
    cd = m.setdefault("cooldowns", {})
    last_str = cd.get(key)
    if not last_str:
        return 0
    try:
        last = datetime.strptime(last_str, "%Y-%m-%d %H:%M:%S")
    except Exception:
        return 0
    elapsed = (datetime.now() - last).total_seconds()
    return max(0, int(seconds - elapsed))


def _set_cooldown(m, key):
    m.setdefault("cooldowns", {})[key] = datetime.now().strftime(
        "%Y-%m-%d %H:%M:%S"
    )


def _categorize_offering(item: str, kind: str) -> str:
    """Classify an item into a coarse category for the archive's secret thoughts.

    `kind` is "feed" or "gift". Falls back to a generic neutral bucket when
    no known wordlist matches. Defined here at module scope so the wordlist
    constants resolve at call time, not at import time.
    """
    s = (item or "").lower()
    try:
        if kind == "feed":
            if any(w in s for w in FEED_DISGUSTING):
                return "feed_disgusting"
            if any(w in s for w in FEED_TOXIC):
                return "feed_toxic"
            if any(w in s for w in FEED_INEDIBLE):
                return "feed_inedible"
            if any(w in s for w in FEED_LOVES):
                return "feed_loves"
            if any(w in s for w in FEED_HATES):
                return "feed_hates"
            return "feed_neutral"
        # gift
        if any(w in s for w in GIFT_DISGUSTING):
            return "gift_disgusting"
        if any(w in s for w in GIFT_TOXIC):
            return "gift_toxic"
        if any(t in s for t in ADIDAS_CAP_TERMS) or any(t in s for t in ADIDAS_SHOES_TERMS):
            return "gift_adidas"
        if any(w in s for w in GIFT_PAPER):
            return "gift_paper"
        if any(w in s for w in GIFT_LIQUID):
            return "gift_liquid"
        if any(w in s for w in GIFT_LOVES):
            return "gift_loves"
        if any(w in s for w in GIFT_TOY_BIG):
            return "gift_toy_big"
        if any(w in s for w in GIFT_USEFUL):
            return "gift_useful"
        if any(w in s for w in GIFT_WEIRD):
            return "gift_weird"
    except NameError:
        # Wordlists not yet loaded (shouldn't happen at runtime).
        return f"{kind}_neutral"
    return "gift_neutral"


def _log_offering(m, kind: str, item: str, user_id: str, user_name: str) -> None:
    """Append an offering (feed/gift) to the rolling archive (max 25)."""
    archive = m.setdefault("offering_archive", [])
    _now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    archive.append({
        "kind": kind,
        "item": item,
        "user_id": user_id,
        "user_name": user_name,
        "category": _categorize_offering(item, kind),
        "at": _now_str,
    })
    if len(archive) > 25:
        del archive[: len(archive) - 25]
    if kind == "feed":
        m.setdefault("internal", {})["last_fed_item"] = item
        m["internal"]["last_fed_at"] = _now_str
        m["internal"]["last_fed_by"] = user_id


