def _is_birthday_today():
    """True if today (Istanbul time) is Yarnaby's / The Creator's birthday."""
    local_now = datetime.now(timezone.utc).replace(tzinfo=None) + ISTANBUL_OFFSET
    return (
        local_now.month == CREATION_DATE_MONTH
        and local_now.day == CREATION_DATE_DAY
    )


def _time_ago(ts_str):
    """Return human-readable time-since for an ISO-ish timestamp string."""
    if not ts_str:
        return "never"
    try:
        ts = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
    except Exception:
        return "unknown"
    delta = datetime.now() - ts
    secs = int(delta.total_seconds())
    if secs < 60:
        return f"{secs}s ago"
    mins = secs // 60
    if mins < 60:
        return f"{mins}m ago"
    hrs = mins // 60
    if hrs < 24:
        return f"{hrs}h ago"
    days = hrs // 24
    return f"{days}d ago"


# --- Creator absence / comfort-object / homecoming helpers ---
def _creator_gone_seconds(m):
    """Seconds since the Creator was last seen, or 0 if unknown."""
    last_str = m["internal"].get("doctor_last_seen")
    if not last_str:
        return 0
    try:
        last = datetime.strptime(last_str, "%Y-%m-%d %H:%M:%S")
    except Exception:
        return 0
    return max(0, int((datetime.now() - last).total_seconds()))


def _creator_gone_days(m):
    return _creator_gone_seconds(m) // 86400


def _select_comfort_object(m):
    """Pick the single item in the hoard he should latch onto. Returns the
    item key (string) or None if there's nothing suitable."""
    inv = m.get("inventory", {})
    if not inv:
        return None
    rarity_rank = {
        "Chromatic": 8, "Ultra Legendary": 7, "Legendary": 6,
        "Mythic": 5, "Epic": 4, "Super Rare": 3, "Rare": 2, "Common": 1,
    }
    candidates = [
        (name, entry) for name, entry in inv.items()
        if (entry.get("rarity") or "Common") != "Cursed"
    ]
    if not candidates:
        return None
    candidates.sort(
        key=lambda kv: (
            rarity_rank.get(kv[1].get("rarity") or "Common", 0),
            kv[1].get("count", 1),
            kv[1].get("last_added", ""),
        ),
        reverse=True,
    )
    return candidates[0][0]


def _ensure_comfort_object(m):
    """If the Creator has been gone long enough and no comfort object is set,
    pick one. If their hoard is empty, leave it null and try again later."""
    gone_days = _creator_gone_days(m)
    if gone_days < COMFORT_OBJECT_THRESHOLD_DAYS:
        return None
    if m["internal"].get("comfort_object"):
        # If the picked item has since been removed from inventory, re-pick.
        if m["internal"]["comfort_object"] in m.get("inventory", {}):
            return m["internal"]["comfort_object"]
    pick = _select_comfort_object(m)
    if pick:
        m["internal"]["comfort_object"] = pick
        m["internal"]["comfort_object_assigned_at"] = datetime.now().strftime(
            "%Y-%m-%d %H:%M:%S"
        )
    return pick


def _clear_comfort_object(m):
    m["internal"]["comfort_object"] = None
    m["internal"]["comfort_object_assigned_at"] = None


