async def _fetch_fb_incidents_api_football(event_id):
    """Translate api-football events into Sofascore-shaped incidents so the
    rest of the bot's narration code keeps working unchanged."""
    data = await _fb_api_football_get("fixtures/events", {"fixture": event_id})
    if not data or not isinstance(data, dict):
        return []
    items = data.get("response") or []
    home_id = await _fb_af_fixture_home_id(event_id)

    out = []
    for ev in items:
        t = (ev.get("type") or "").lower()
        detail = (ev.get("detail") or "").lower()

        if "goal" in t:
            inc_type = "goal"
            if "own" in detail:
                inc_class = "ownGoal"
            elif "penalty" in detail and "missed" in detail:
                inc_class = "missedPenalty"
            elif "penalty" in detail:
                inc_class = "penalty"
            else:
                inc_class = "regular"
        elif "card" in t:
            inc_type = "card"
            if "yellow" in detail and "red" in detail:
                inc_class = "yellowRed"
            elif "red" in detail:
                inc_class = "red"
            else:
                inc_class = "yellow"
        elif "subst" in t:
            inc_type = "substitution"
            inc_class = "regular"
        else:
            continue  # skip VAR / Var-related noise we don't narrate

        team_id = (ev.get("team") or {}).get("id")
        time_dict = ev.get("time") or {}
        minute = time_dict.get("elapsed")
        extra = time_dict.get("extra")
        player_name = ((ev.get("player") or {}).get("name") or "")
        synth_id = f"af-{minute or 0}-{extra or 0}-{inc_type}-{player_name}"

        entry = {
            "id": synth_id,
            "incidentType": inc_type,
            "incidentClass": inc_class,
            "player": {"name": player_name or None},
            "isHome": (team_id == home_id) if home_id is not None else False,
            "time": minute,
            "addedTime": extra,
        }
        if inc_type == "substitution":
            # api-football: ev["player"] = player coming OFF, ev["assist"] = player coming ON
            entry["playerOut"] = {"name": player_name or None}
            entry["playerIn"] = {"name": (ev.get("assist") or {}).get("name") or None}
        out.append(entry)
    return out


async def _fetch_fb_table_sofascore():
    """Return the current Süper Lig standings as a list of row dicts.

    Each row: {position, team, matches, wins, draws, losses, gf, ga, gd, points, is_fb}.
    Returns None on failure or if no Süper Lig season can be located.
    """
    seasons_url = (
        f"https://api.sofascore.com/api/v1/team/{FENERBAHCE_TEAM_ID}/standings/seasons"
    )
    seasons = await _fb_http_get(seasons_url)
    if not seasons or not isinstance(seasons, dict):
        return None

    tournament_id = season_id = None
    for entry in seasons.get("tournamentSeasons") or []:
        tour = entry.get("tournament") or {}
        name = (tour.get("name") or "").lower()
        # Prefer Turkish Süper Lig (uniqueTournament id 52). Fall back on name match.
        unique = (tour.get("uniqueTournament") or {}).get("id")
        if unique == 52 or "super lig" in name or "süper lig" in name:
            tournament_id = tour.get("id") or unique
            ssns = entry.get("seasons") or []
            if ssns:
                season_id = ssns[0].get("id")
            break

    if not tournament_id or not season_id:
        return None

    table_url = (
        f"https://api.sofascore.com/api/v1/tournament/{tournament_id}"
        f"/season/{season_id}/standings/total"
    )
    data = await _fb_http_get(table_url)
    if not data or not isinstance(data, dict):
        return None

    standings = data.get("standings") or []
    if not standings:
        return None

    rows = standings[0].get("rows") or []
    out = []
    for r in rows:
        team = (r.get("team") or {}).get("name") or "?"
        team_id = (r.get("team") or {}).get("id")
        gf = r.get("scoresFor", 0)
        ga = r.get("scoresAgainst", 0)
        out.append({
            "position": r.get("position"),
            "team": team,
            "matches": r.get("matches", 0),
            "wins": r.get("wins", 0),
            "draws": r.get("draws", 0),
            "losses": r.get("losses", 0),
            "gf": gf,
            "ga": ga,
            "gd": gf - ga,
            "points": r.get("points", 0),
            "is_fb": team_id == FENERBAHCE_TEAM_ID,
        })
    return out


async def fetch_fb_table():
    """Return standings - Sofascore first, ESPN fallback."""
    sofascore_rows = await _fetch_fb_table_sofascore()
    if sofascore_rows:
        return sofascore_rows
    espn_rows = await _fetch_fb_table_espn()
    if espn_rows:
        return espn_rows
    return None
def _fmt_match_minute(inc):
    """Format a Sofascore incident's minute as '45'' or '45+2''. Empty string if absent."""
    t = inc.get("time")
    if t is None:
        return ""
    added = inc.get("addedTime")
    if added:
        return f"{t}+{added}'"
    return f"{t}'"


