# ---------------------------------------------------------------------------
# REACTION HELPER
# Called at the top of every command to add three emoji reactions:
#   👑  — the message came from The Creator
#   💤  — Yarnaby is currently sleeping
#   ⭐  — non-Creator user has a trust score ≥ 4
# Failures are silently swallowed so a missing permission never breaks a cmd.
# ---------------------------------------------------------------------------
async def _add_reactions(ctx, m):
    """Add creator / sleep / score reactions to the triggering message."""
    try:
        is_creator = ctx.author.id == DOCTOR_ID
        is_sleeping = bool(m["internal"].get("is_sleeping", False))
        score = m["social_matrix"].get(str(ctx.author.id), {}).get("score", 0)

        if is_creator:
            try:
                await ctx.message.add_reaction("👑")
            except Exception:
                pass
        if is_sleeping:
            try:
                await ctx.message.add_reaction("💤")
            except Exception:
                pass
        is_dead = bool(m["internal"].get("is_dead", False))
        if is_dead:
            try:
                await ctx.message.add_reaction("💀")
            except Exception:
                pass
        is_helpless = bool(m["internal"].get("helpless", False))
        if is_helpless:
            try:
                await ctx.message.add_reaction("🤕")
            except Exception:
                pass
        if not is_creator and score >= 4:
            try:
                await ctx.message.add_reaction("⭐")
            except Exception:
                pass
    except Exception:
        pass

    # ── EASTER EGG ──────────────────────────────────────────────────────────
    # 1-in-5000 chance on any command. Skips the Creator (they already know).
    # Sends a hidden DM only to the user who triggered it.
    try:
        if ctx.author.id != DOCTOR_ID and random.random() < 0.0002:
            try:
                await ctx.author.send(
                    "🧶 **you found something.**\n\n"
                    "most people never see this message.\n"
                    "you did.\n\n"
                    "DM **The Creator** the password: `yarnadoge\"412`\n"
                    "take a screenshot of this message as proof.\n\n"
                    "if you do — you get a **free permanent Yarnaby app user slot.**\n"
                    "no catch. just you being lucky.\n\n"
                    "*don't share the password publicly or it won't count.*\n"
                    "🧶"
                )
            except Exception:
                pass  # DMs closed — silently skip, egg is lost
    except Exception:
        pass
    # ────────────────────────────────────────────────────────────────────────


# Defined early for possible reuse; not registered here because bot is created later and `inspect` already uses `sniff` as an alias.
# @bot.command(name="sniff", aliases=["sniffs", "sniffhim", "sniffspot"])
async def sniff_cmd(ctx, *, target: Optional[str] = None):
    """Let Yarnaby sniff something and decide if it's okay."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    target_text = (target or "").strip()

    if not target_text:
        await ctx.send(
            "*Yarnaby lifts his nose and sniffs the air once. Then again. He seems to approve of the room, for now.*"
        )
        return

    target_lower = target_text.lower()
    if any(w in target_lower for w in SNIFF_DISALLOWED):
        await ctx.send(
            "*Yarnaby recoils instantly. No. He will not sniff that. He will never sniff that. He is not doing those stuff, not now, not ever.*"
        )
        return

    approved = [
        "*He sniffs carefully, then gives a small approving chirp. Acceptable.*",
        "*A slow sniff. A blink. He leans a little closer. He approves.*",
        "*He sniffs once, twice, then sits down beside it like he has made a decision.*",
        "*His nose twitches. He decides this is fine and stays near it.*",
    ]
    rejected = [
        "*He sniffs it, pulls back, and makes a very small offended sound. No.*",
        "*One sniff is enough. He steps away and looks unimpressed.*",
        "*He sniffs the thing, then turns his head aside like he has already judged it.*",
    ]
    line = random.choice(approved if random.random() < (0.75 if is_doctor else 0.55) else rejected)
    if u_id in m["social_matrix"] and not is_doctor:
        m["social_matrix"][u_id]["score"] = min(10, m["social_matrix"][u_id].get("score", 0) + (1 if line in approved else 0))
    save_db(m)
    await ctx.send(f"{line} *(target: **{target_text}**)*")



