def save_db(data):
    """Atomic write: temp file -> fsync -> os.replace.
    A crash mid-save can never leave a half-written DATABASE again."""
    dir_ = os.path.dirname(os.path.abspath(DATABASE)) or "."
    fd, tmp = tempfile.mkstemp(prefix=".tmp_db_", suffix=".json", dir=dir_)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=4, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, DATABASE)
    except Exception:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def load_db():
    """Self-healing load: if the file is missing return defaults; if it's
    corrupted with trailing junk (the 'Extra data' crash), back it up and
    keep the first valid JSON object instead of crashing the bot."""
    if not os.path.exists(DATABASE):
        return _default_db()

    with open(DATABASE, "r", encoding="utf-8") as f:
        raw = f.read()

    if not raw.strip():
        return _default_db()

    # Happy path.
    try:
        return json.loads(raw)
    except json.JSONDecodeError as e:
        print(f"[load_db] {DATABASE} is corrupted ({e}). Attempting recovery...")

    # Recovery: parse only the FIRST complete JSON object.
    try:
        obj, end = json.JSONDecoder().raw_decode(raw.lstrip())
    except json.JSONDecodeError as e:
        backup = DATABASE + ".unrecoverable"
        try:
            os.replace(DATABASE, backup)
            print(f"[load_db] Could not recover ({e}). Backed up to {backup}. Starting fresh.")
        except OSError:
            pass
        return _default_db()

    leftover = raw.lstrip()[end:].strip()
    backup = DATABASE + ".broken"
    try:
        with open(backup, "w", encoding="utf-8") as bf:
            bf.write(raw)
        print(f"[load_db] Backed up corrupted file to {backup}.")
    except OSError:
        pass

    if leftover:
        print(f"[load_db] Discarded {len(leftover)} extra characters of trailing junk.")

    try:
        save_db(obj)
        print(f"[load_db] Rewrote {DATABASE} with the recovered object.")
    except Exception as e:
        print(f"[load_db] Could not rewrite cleaned file ({e}). Continuing with in-memory copy.")

    return obj


def stat_bar(m):
    stats = m.get("stats", {})
    hunger = stats.get("hunger", 0)
    crave = stats.get("affection_crave", 0)
    tiredness = stats.get("tiredness", 0)
    mood = stats.get("mood", "Content")
    parts = [f"Hunger {hunger}/10", f"Affection {crave}/10"]
    if tiredness > 8:
        parts.append(f"Tired {tiredness}/10")
    parts.append(str(mood))
    return "*(" + " | ".join(parts) + ")*"


def _clamp_score(m, uid):
    """Ensure a user's score never exceeds 100."""
    entry = m["social_matrix"].get(str(uid))
    if entry is not None and entry.get("score", 0) > 100:
        entry["score"] = 100


def get_istanbul_time():
    return datetime.now(timezone.utc).replace(tzinfo=None) + ISTANBUL_OFFSET


def is_sleep_time():
    t = get_istanbul_time()
    mins = t.hour * 60 + t.minute
    return mins >= (19 * 60 + 30) or mins < (8 * 60)


def compute_mood(m):
    """Derive Yarnaby's mood from his current stats."""
    hunger = m["stats"].get("hunger", 0)
    crave = m["stats"].get("affection_crave", 0)
    tiredness = m["stats"].get("tiredness", 0)
    integrity = m["stats"].get("integrity", 100)
    if m["internal"].get("traumatized"):
        return "Traumatized"

    doctor_last_seen_str = m["internal"].get("doctor_last_seen")
    creator_gone_hrs = 0
    if doctor_last_seen_str:
        try:
            prev = datetime.strptime(doctor_last_seen_str, "%Y-%m-%d %H:%M:%S")
            creator_gone_hrs = (datetime.now() - prev).total_seconds() / 3600
        except Exception:
            creator_gone_hrs = 0

    if integrity < 40 or creator_gone_hrs > 72:
        return "Depressed (will recover)"
    if crave >= 12 and tiredness >= 12:
        return "Agitated"
    if crave >= 10 or creator_gone_hrs > 36:
        return "Sad"
    if hunger <= 2 and crave <= 2 and tiredness <= 5:
        return "Happy"
    if crave <= 3 and hunger <= 5 and tiredness <= 8:
        return "Content"
    if 4 <= crave <= 9:
        return "Craving"
    return "Bored"


def update_mood(m):
    m["stats"]["mood"] = compute_mood(m)
    return m["stats"]["mood"]


def _get_season() -> str:
    """Return the current meteorological season based on month."""
    month = datetime.now().month
    if month in (12, 1, 2):
        return "winter"
    elif month in (3, 4, 5):
        return "spring"
    elif month in (6, 7, 8):
        return "summer"
    else:
        return "autumn"


def _get_lang(m: dict, guild_id=None) -> str:
    """Return the language code for a guild, defaulting to EN-US."""
    if guild_id:
        guild_langs = m.get("settings", {}).get("guild_langs", {})
        return guild_langs.get(str(guild_id), "EN-US")
    return m.get("settings", {}).get("lang", "EN-US")


async def get_dynamic_prefix(bot, message):
    """Accept !cmd, /cmd, **cmd**/**cmd, and yarn!cmd."""
    return ["yarn!", "**", "!", "/"]


def parse_action_command(content):
    """
    Detect *cmd*, *cmd args*, **cmd**, **cmd args** style commands.
    Returns the inner text (e.g. 'nod', 'shake head') or None.
    """
    s = content.strip()
    m = re.fullmatch(r"\*{1,2}\s*([a-zA-Z][a-zA-Z _\-]{0,30})\s*\*{1,2}", s)
    if m:
        return m.group(1).strip().lower()
    return None


