@bot.command(name="poke", aliases=["pokehim", "jabatit"])
async def poke(ctx):
    """Poke Yarnaby."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        score = (
            m["social_matrix"].get(u_id, {}).get("score", 0) if not is_doctor else 99
        )
        if is_doctor:
            m["internal"]["is_sleeping"] = False
            m["internal"]["sleep_until"] = None
            m["internal"]["doctor_sleeping_together"] = False
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby's eye cracks open. He stares at you. He is awake now. He is not happy about it.*",
                        "*He jolts awake with a startled RROWW. He blinks. He sees you. He pouts enormously.*",
                        "*He wakes with a shudder. He looks at you. He looks at where he was sleeping. He pouts.*",
                    ]
                )
            )
        elif score <= -2:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby's eye opens. He sees who poked him. It closes again.*",
                        "*A low, dangerous sound emerges. He did not consent to being poked by this person.*",
                        "*He moves away from the poke without waking. He is extremely talented.*",
                    ]
                )
            )
        elif score >= 4:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby stirs. He cracks one eye, sees them, and makes a small, groggy chirp before resettling.*",
                        "*He shifts. He paws back at them sleepily, eyes still closed. Then he's out again.*",
                    ]
                )
            )
        else:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby makes a disgruntled sound and shifts position. He did not wake up.*",
                        "*He stirs. He does not open his eyes. He is asleep.*",
                    ]
                )
            )
        save_db(m)
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*You poke him. He registers it. He doesn't react further. He has bigger things sitting on him right now and a poke is very small compared to those things.* **...mrr...**",
            f"*He turns his head toward the poke slightly. His expression doesn't change. He turns back.* **...mrr...**",
        ]))
        return


    if is_doctor:
        await ctx.send(
            random.choice(
                [
                    "*Yarnaby whips around and bats at your hand - no claws, just wool. He stares at you afterward.*",
                    "*He freezes at the poke. Then immediately tries to bite your finger, gently.*",
                    "*He pounces sideways and crouches, tail twitching. He accepts the challenge.*",
                    "*He chirps sharply, indignant. Then headbutts you back.*",
                    "*He looks at your hand. He looks at you. He pokes you back with one paw, deadpan.*",
                ]
            )
        )
    else:
        score = m["social_matrix"].get(u_id, {}).get("score", 0)
        if score <= -2:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby whirls around and hisses. Short, sharp, absolutely not joking.*",
                        "*His wool stands on end. He stares at the offending hand.*",
                        "*He bares his teeth and takes one slow step back. Don't.*",
                    ]
                )
            )
        elif score >= 4:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby bats at them lightly and trills. He accepts this interaction.*",
                        "*He pokes them back with a paw - one tap, deliberate. He seems pleased.*",
                    ]
                )
            )
        else:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby turns and stares at the poker. He says nothing. He turns back around.*",
                        "*He flinches slightly at the touch. He fixes them with a flat stare.*",
                        "*He looks at them. He looks at where they poked him. He looks at them again.*",
                    ]
                )
            )
    save_db(m)


@bot.command(name="boop", aliases=["boophim"])
async def boop(ctx):
    """Boop Yarnaby's nose."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*Yarnaby's nose twitches in his sleep. He does not wake up.*")
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*Your finger reaches his nose. He blinks once. He doesn't boop back. He doesn't pull away. The nose is just there and now your finger has touched it and that's the whole event.* **...mrr...**",
            f"*Boop received. No response filed. He is running on minimal right now.* **...mrr...**",
        ]))
        return


    if is_doctor:
        await ctx.send(
            random.choice(
                [
                    "*Yarnaby goes cross-eyed staring at your finger. Then he sneezes. Hard.*",
                    "*His nose twitches. He stares at you. He boops you back with his own nose.*",
                    "*He freezes completely. Then he licks the end of your finger and walks away.*",
                    "*He recoils with great drama. Then paws at his own nose once. Offended.*",
                    "*He blinks. He goes still. He makes a very small, surprised sound. He recovers quickly.*",
                ]
            )
        )
    else:
        score = m["social_matrix"].get(u_id, {}).get("score", 0)
        if score <= -2:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby snaps his head back. He glares. He takes two steps away.*",
                        "*He bares his teeth at the approaching finger. Don't.*",
                    ]
                )
            )
        elif score >= 3:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby's nose twitches. He sneezes. He glares at them, mildly embarrassed.*",
                        "*He goes cross-eyed, then headbutts their hand. He accepts the boop.*",
                    ]
                )
            )
        else:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby pulls his head back and stares. He tolerates it. Barely.*",
                        "*He endures the boop with the dignity of a creature who has many feelings about this.*",
                    ]
                )
            )
    save_db(m)


@bot.command(name="hug", aliases=["hughim", "arms"])
async def hug(ctx):
    """Try to hug Yarnaby."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(
                random.choice(
                    [
                        "*You settle in beside him. He doesn't wake. He shifts, presses closer in his sleep, and is still.*",
                        "*He makes a tiny sound without waking. He doesn't move away. He presses back.*",
                    ]
                )
            )
        else:
            score = m["social_matrix"].get(u_id, {}).get("score", 0)
            if score >= 5:
                await ctx.send(
                    "*He stirs slightly but doesn't wake. He doesn't pull away.*"
                )
            else:
                await ctx.send(
                    "*Yarnaby shifts in his sleep and moves just slightly out of reach.*"
                )
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*He doesn't resist the hug. His body is where it is and your arms go around it and he doesn't move — not into it, not away from it. He is just there. Still. Waiting. His breathing is slow.* **...mrr...**",
            f"*You hug him and he is completely passive inside it. No tension, no softening. He endures it the way he endures everything right now — quietly, without complaint, without presence.* **...mrr...**",
            f"*He lets you. That's all. He lets you.* **...mrr...**",
        ]))
        return


    if is_doctor:
        m["stats"]["affection_crave"] = max(0, m["stats"]["affection_crave"] - 5)
        await ctx.send(
            random.choice(
                [
                    "*Yarnaby goes rigid for exactly one second - then melts. His paws find your arm. He doesn't let go.*",
                    "*He makes a sound of protest that lasts about half a second before he tucks himself into the hug entirely.*",
                    "*He stiffens. He endures it. He presses closer. He endures it more. He will not admit this.*",
                    "*He presses his face into your shoulder and makes a low, continuous rumble. He is being held. He is okay with this.*",
                    "*He tolerates the hug for approximately zero seconds before actively leaning into it. He does not acknowledge this.*",
                ]
            )
        )
    else:
        score = m["social_matrix"].get(u_id, {}).get("score", 0)
        if score <= -2:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby sees it coming. He is already gone. He was never there.*",
                        "*He sidesteps the attempt cleanly and sits a meter away. He stares.*",
                        "*He backs away. He is not a hug-available creature for this person.*",
                    ]
                )
            )
        elif score >= 5:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby doesn't quite hug back - but he leans in. He stays there.*",
                        "*He stiffens, then slowly relaxes against them. He presses his head to their chest and stays.*",
                        "*He allows it. More than allows it. He tucks himself in and makes a quiet sound.*",
                    ]
                )
            )
            m["social_matrix"][u_id]["score"] += 1
        else:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby takes one step back. He wasn't ready for that. He eyes them from a safe distance.*",
                        "*He tenses and holds still for about two seconds before sliding out of it. He pads away.*",
                    ]
                )
            )
    save_db(m)


