def _get_sickness_level(health: int, temp: str) -> int:
    """Return a 0-4 sickness severity score from health (0-100) and temperature string.

    Level 0 - Healthy
    Level 1 - Sniffling
    Level 2 - Under the weather
    Level 3 - Sick
    Level 4 - Critical
    """
    temp_score = {"warm": 0, "chilly": 1, "cold": 2, "feverish": 3}.get(temp, 0)
    if health >= 70:
        health_score = 0
    elif health >= 50:
        health_score = 1
    elif health >= 25:
        health_score = 2
    else:
        health_score = 3
    return min(4, temp_score + health_score)


def _match_any(haystack, needles):
    return any(n in haystack for n in needles)


