@bot.command(name="call", aliases=["callhim", "comeover"])
async def call(ctx):
    """Call out to Yarnaby - he travels from wherever he is."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(
                random.choice(
                    [
                        "*You call out. One ear flicks. He doesn't wake up - but he tilts his head slightly toward you.*",
                        "*He's asleep. He hears you, somewhere in his dream. He doesn't stir.*",
                    ]
                )
            )
        else:
            await ctx.send("*Yarnaby is asleep. He doesn't hear you.*")
        return

    target_channel_id = str(ctx.channel.id)
    current_channel_id = m["internal"].get("current_channel_id") or target_channel_id

    same_channel = current_channel_id == target_channel_id
    score = (
        99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    )
    likes_caller = is_doctor or score >= 0
    hates_caller = score <= -3

    # --- Already in the same channel ---
    if same_channel:
        if is_doctor:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby's head snaps up immediately. He hears you. He comes.*",
                        "*He appears from wherever he was without delay. He pouts up at you. Present.*",
                        "*He gallops over, skids slightly, and sits at your feet. He is here. He answered.*",
                    ]
                )
            )
        elif likes_caller:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby hears it and comes. He pads toward the voice with genuine interest.*",
                        "*He trots over and sits nearby. He came. He decided to come.*",
                    ]
                )
            )
        elif hates_caller:
            await ctx.send(
                "*Yarnaby hears it. He does not answer it.*"
            )
        else:
            await ctx.send(
                random.choice(
                    [
                        "*Yarnaby hears it. He looks in your direction. He doesn't come immediately. Maybe in a while.*",
                        "*He glances over. He acknowledges the call. He doesn't move.*",
                    ]
                )
            )
        save_db(m)
        return

    # --- He's in another channel - TRAVEL SEQUENCE ---
    other_channel = _resolve_messageable(bot, current_channel_id)
    other_mention = (
        f"<#{current_channel_id}>" if other_channel else f"#{current_channel_id}"
    )
    travel_seconds = random.randint(4, 9)

    if hates_caller or (not is_doctor and score < 0):
        # He pretends he's coming, but he doesn't show up.
        await ctx.send(
            f"*Yarnaby is coming from {other_mention}.*"
        )
        await asyncio.sleep(travel_seconds)
        await ctx.send(
            "*Oh wait, where is he? Oh... he didn't come.*"
        )
        save_db(m)
        return

    await ctx.send(
        f"*Yarnaby is coming from {other_mention}, he's gonna be here in {travel_seconds} seconds...*"
    )
    await asyncio.sleep(travel_seconds)
    await ctx.send(
        random.choice(
            [
                "*Oh, he's already here.*",
                "*A clatter of paws - and there he is.*",
                "*He skids around the corner, slightly dishevelled, but here.*",
            ]
        )
    )
    # Update his current location
    m["internal"]["current_channel_id"] = target_channel_id
    save_db(m)


@bot.command(name="nod")
async def nod_cmd(ctx):
    """Nod at Yarnaby - he nods back."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send("*Yarnaby is asleep. No nodding back.*")
        return
    if m["internal"].get("helpless", False):
        await ctx.send(random.choice([
            "*His head dips — barely. A nod that costs him something.* **...mrr...**",
            "*He nods. Once. Very slowly. His eyes stay on you.* **...mrr...**",
        ]))
        return
    is_doctor = ctx.author.id == DOCTOR_ID
    score = m["social_matrix"].get(str(ctx.author.id), {}).get("score", 0)
    if is_doctor or score >= 0:
        await ctx.send(
            random.choice(
                [
                    "*Yarnaby blinks at you, then dips his head once. A returning nod.*",
                    "*He tilts his head, considers it, and nods. Agreement.*",
                    "*Slow, deliberate. He nods back at you.*",
                ]
            )
        )
    else:
        await ctx.send("*He stares at you. He does not nod.*")


@bot.command(name="shake_head", aliases=["shakehead"])
async def shake_head_cmd(ctx):
    """Shake your head at Yarnaby - he shakes back."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send("*Yarnaby is asleep. He doesn't react.*")
        return
    if m["internal"].get("helpless", False):
        await ctx.send(random.choice([
            "*His head moves — very slightly, just enough to count. He shakes it once.* **...mrr...**",
            "*He manages one small, slow shake. It's all there is right now.* **...mrr...**",
        ]))
        return
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    if is_doctor:
        await ctx.send(random.choice([
            "*Yarnaby shakes his head back — dramatically, ears flying. Then fixes The Creator with a satisfied stare.* **chrrp.**",
            "*He shakes his head right back, then tilts it and shakes again. He is very committed to this interaction.* **prrr.**",
        ]))
    elif score >= 3:
        await ctx.send(random.choice([
            "*Yarnaby shakes his head right back at you, ears flopping.*",
            "*A small, sharp shake. He's mirroring you.*",
            "*He blinks. Then a firm head-shake. Acknowledged.*",
        ]))
    else:
        await ctx.send(random.choice([
            "*He watches your head shake. He does not shake back. He stares.* **...mrr.**",
            "*His ear flicks. That is all.* **mrr.**",
        ]))


