@bot.command(name="inventory", aliases=["inv", "hoard"])
async def inventory_cmd(ctx):
    """See everything Yarnaby has hoarded over time."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    inv = m.get("inventory", {})
    if not inv:
        await ctx.send(
            random.choice([
                "*Yarnaby pads to his secret place and looks around. There's nothing in there yet. He pouts at you. He'd like more. **mrrp.***",
                "*He noses around the corner of the factory where things are supposed to live. Empty. He flicks his tail at you accusingly. **mrr.***",
                "*The hoard-spot is bare. He sits down in it and stares up at you. The implication is unmistakable. **chrrp?***",
                "*He digs at the empty corner with a paw, finds nothing, and looks deeply betrayed. **brrt.***",
            ])
        )
        return

    # Group by rarity tier (highest first)
    rarity_buckets: dict = {}
    total = 0
    cursed_count = 0
    for name, info in inv.items():
        count = info.get("count", 1)
        rarity = info.get("rarity") or "Common"
        rarity_buckets.setdefault(rarity, []).append((name, info))
        total += count
        if rarity == "Cursed":
            cursed_count += count

    # Order: Cursed last (set apart), then Chromatic -> Common
    display_order = [
        "Chromatic", "Ultra Legendary", "Legendary", "Mythic",
        "Epic", "Super Rare", "Rare", "Common",
    ]
    # Append any unknown rarities not in our standard list (excluding Cursed)
    for r in rarity_buckets.keys():
        if r not in display_order and r != "Cursed":
            display_order.append(r)

    # Pick favourite for the header
    fav_name = _select_comfort_object(m)

    intro_lines = [
        "*He pads to his secret corner. He sniffs each thing. He looks up at you, ears forward. **chrrp.** He's letting you see.*",
        "*Yarnaby leads you to the hoard. He sits beside it, very still, very proud. **prrt.** Look. Look at what he has.*",
        "*He tugs the cushion aside with his nose. The collection is revealed. A small, satisfied **mrrt.***",
        "*He noses through his stash, ordering it for you. Tail flicks. **prrr.** Here. All of it.*",
    ]

    header = ["**[Yarnaby's Hoard]**", random.choice(intro_lines), ""]
    if fav_name:
        fav_entry = inv.get(fav_name, {})
        fav_emoji = RARITY_EMOJI.get(fav_entry.get("rarity") or "", "")
        header.append(f"*Comfort object right now: {fav_emoji} **{fav_name}** - he won't part with this one easily.*")
        header.append("")

    body: list = []
    shown = 0
    LIMIT = 30
    for rarity in display_order:
        bucket = rarity_buckets.get(rarity)
        if not bucket:
            continue
        # Sort items inside a bucket by recency
        bucket.sort(key=lambda kv: kv[1].get("last_added", ""), reverse=True)
        emoji = RARITY_EMOJI.get(rarity, "")
        body.append(f"**{emoji} {rarity}**")
        for name, info in bucket:
            if shown >= LIMIT:
                break
            count = info.get("count", 1)
            mark = " *" if name == fav_name else ""
            line = f"- **{name}** x{count}{mark}"
            body.append(line)
            shown += 1
        body.append("")
        if shown >= LIMIT:
            break

    # Cursed gets its own quiet section at the bottom (he doesn't like talking about these)
    cursed_bucket = rarity_buckets.get("Cursed")
    if cursed_bucket and shown < LIMIT + 10:
        body.append(f"** Cursed** - *he doesn't like to look at these.*")
        for name, info in sorted(cursed_bucket, key=lambda kv: kv[1].get("last_added", ""), reverse=True):
            count = info.get("count", 1)
            body.append(f"- *{name}* x{count}")
        body.append("")

    unique_count = len(inv)
    if unique_count > shown:
        body.append(f"*...and {unique_count - shown} more tucked further into the corner.*")
        body.append("")

    footer_line = (
        f"**Total: {total} items** across **{unique_count}** unique things."
    )
    if cursed_count:
        footer_line += f" *(Including {cursed_count} cursed.)*"
    body.append(footer_line)

    # Splitting safely under Discord's 2000-char limit
    full = "\n".join(header + body)
    if len(full) <= 1900:
        await ctx.send(full)
    else:
        # First chunk: header. Then group bucket sections.
        await ctx.send("\n".join(header))
        chunk = ""
        for line in body:
            if len(chunk) + len(line) + 1 > 1900:
                if chunk:
                    await ctx.send(chunk)
                chunk = line
            else:
                chunk = (chunk + "\n" + line) if chunk else line
        if chunk:
            await ctx.send(chunk)


# --- Helpers for the inventory-aware commands below ---
_RARITY_ORDER = [
    "Common", "Rare", "Super Rare", "Epic",
    "Mythic", "Legendary", "Ultra Legendary", "Chromatic", "Cursed",
]


def _resolve_inv_item(inv: dict, query: str):
    """Find an inventory item by case-insensitive substring match. Returns the
    canonical key and its entry, or (None, None) if not found."""
    if not query:
        return None, None
    q = query.strip().lower()
    if not q:
        return None, None
    # exact (case-insensitive) first
    for name, entry in inv.items():
        if name.lower() == q:
            return name, entry
    # substring match next - prefer shortest match for least ambiguity
    candidates = [(name, entry) for name, entry in inv.items() if q in name.lower()]
    if not candidates:
        return None, None
    candidates.sort(key=lambda kv: len(kv[0]))
    return candidates[0]


# --- STEAL helpers ---
_STEAL_TRIVIAL_RARITIES = {"Common", "Crinkled", "Curious", "Useful", "Hidden"}
_STEAL_MINOR_RARITIES = {"Loved", "Beloved", "Rare", "Super Rare"}
_STEAL_TREASURED_RARITIES = {"Adored", "Epic", "Mythic", "Legendary", "Ultra Legendary", "Chromatic"}


def _steal_tier(rarity, is_favorite):
    if is_favorite:
        return "favorite"
    if rarity == "Cursed":
        return "cursed"
    if rarity in _STEAL_TREASURED_RARITIES:
        return "treasured"
    if rarity in _STEAL_MINOR_RARITIES:
        return "minor"
    return "trivial"


def _remove_inventory_item(m, name):
    """Decrement count by 1 and delete entry if it hits 0. Clears comfort object if it's now gone."""
    inv = m.setdefault("inventory", {})
    entry = inv.get(name)
    if not entry:
        return
    entry["count"] = max(0, entry.get("count", 1) - 1)
    if entry["count"] <= 0:
        inv.pop(name, None)
    if m["internal"].get("comfort_object") == name and name not in inv:
        _clear_comfort_object(m)


