@bot.command(name="whisper")
async def whisper_cmd(ctx, *, text: str = ""):
    """Whisper something to him - he reacts based on what you say."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if not text.strip():
        await ctx.send("*You lean close, but say nothing. Yarnaby tilts his head, waiting.*")
        return

        if m["internal"]["is_sleeping"]:
            await ctx.send(
                "*You whisper softly. He doesn't wake. One ear flicks toward the sound.*"
            )
            return

    text_lower = text.lower()
    sweet_words = ["love", "good", "sweet", "soft", "warm", "miss", "stay", "happy", "best", "beautiful"]
    sad_words = ["sorry", "miss", "wish", "remember", "alone", "gone", "hurt"]
    is_sweet = any(w in text_lower for w in sweet_words)
    is_sad = any(w in text_lower for w in sad_words)

    if is_doctor and (is_sweet or is_sad):
        await ctx.send(
            "*Yarnaby goes completely still as The Creator whispers. His glass eyes catch the light. He pushes his forehead gently against you and stays there.*"
        )
        m["stats"]["affection_crave"] = max(0, m["stats"]["affection_crave"] - 4)
    elif is_sweet:
        await ctx.send(
            "*Yarnaby leans in carefully, ears forward. He listens to every word. A small, surprised purr starts up. He looks at you like he's just decided something.*"
        )
        m["stats"]["affection_crave"] = max(0, m["stats"]["affection_crave"] - 2)
    elif is_sad:
        await ctx.send(
            "*He listens silently. After a moment he sits down right next to you, very close, and stays. He doesn't know what to do, but he is here.*"
        )
    else:
        await ctx.send(
            "*Yarnaby tilts his head as you whisper. He blinks slowly. He doesn't fully understand, but he is paying attention.*"
        )
    save_db(m)


@bot.command(name="birthday", aliases=["anniversary"])
async def birthday_cmd(ctx):
    """When is Yarnaby's anniversary?"""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    if m["internal"].get("helpless", False):
        await ctx.send(random.choice([
            "*He blinks slowly. The date matters to him even now. He holds up one paw — December. Somewhere in there.* **...mrr...**",
            "*He looks at the question with quiet eyes. December 24th. He knows. He always knows.* **...mrr...**",
        ]))
        return
    today = datetime.now(timezone.utc).replace(tzinfo=None) + ISTANBUL_OFFSET
    bday_this_year = datetime(today.year, CREATION_DATE_MONTH, CREATION_DATE_DAY)
    if today.date() > bday_this_year.date():
        bday_next = datetime(today.year + 1, CREATION_DATE_MONTH, CREATION_DATE_DAY)
    else:
        bday_next = bday_this_year
    days_left = (bday_next.date() - today.date()).days
    last_celebrated = m["internal"].get("last_birthday_year")

    if days_left == 0:
        await ctx.send(
            "**[Today is the day - December 24th.]**\n"
            "*Yarnaby was first wound together on this date - the same day The Creator (Adidas Doge) was born. "
            "He doesn't know what a birthday is. He just feels warmer, and the rare things in the factory feel a little closer to him today.*\n"
            "*(Birthday boost active: rare events are ~100x more likely all day.)*"
        )
        return

    age_so_far = max(1, today.year - 2024)
    line = (
        f"*Yarnaby's anniversary - the day Experiment 1166 was first wound together, **and** the same day "
        f"The Creator (Adidas Doge) was born - is **{CREATION_DATE_DAY:02d}/{CREATION_DATE_MONTH:02d}** (December 24th). "
        f"That's **{days_left} day(s)** away.*\n"
        f"*On that day, rare events become ~100x more likely. He doesn't know why. He just feels it.*"
    )
    if last_celebrated:
        line += f"\n*Last marked: {last_celebrated}. (He is now in roughly his {age_so_far}th year.)*"
    await ctx.send(line)


