def _ensure_art_defaults(m):
    m.setdefault("art_gallery", [])
    m.setdefault("internal", {}).setdefault("last_art_at", None)
    m["internal"].setdefault("last_art_file", None)
    m["internal"].setdefault("last_art_prompt", None)


def _art_prompt_to_art(prompt: str) -> tuple[str, str]:
    prompt = (prompt or "").strip()
    prompt_lower = prompt.lower()
    if not prompt:
        prompt = "something random"
        prompt_lower = prompt
    if any(w in prompt_lower for w in ["cat", "yarn", "yarnaby", "portrait"]):
        body = ["   /\\_/\\\\", "  ( o.o )", "   > ^ <", " ~~~bad~~~", "   yarnaby"]
    elif any(w in prompt_lower for w in ["house", "room", "home", "factory"]):
        body = ["  [__]", "  |  |", " _|__|_", " |_____|", "   bad"]
    else:
        body = ["  .-.", " (   )", "  `-`", "  bad", "  art"]
    slug = re.sub(r"[^a-z0-9]+", "_", prompt_lower).strip("_")[:32] or "random"
    filename = f"{datetime.now().strftime('%Y%m%d_%H%M%S')}_{slug}.txt"
    art_dir = Path("attached_assets") / "yarnaby_art"
    art_dir.mkdir(parents=True, exist_ok=True)
    path = art_dir / filename
    path.write_text("\n".join(body), encoding="utf-8")
    return str(path), "\n".join(body)


def _art_card(entry: dict[str, Any]) -> str:
    return (
        f"**{entry.get('title', 'Untitled Scribble')}**\n"
        f"*Prompt:* {entry.get('prompt', 'something random')}\n"
        f"*Result:* {entry.get('result', 'bad art')}\n"
        f"*When:* {entry.get('at', 'unknown')}"
    )


@bot.command(name="draw")
async def draw_cmd(ctx, *, prompt: Optional[str] = None):
    """Make Yarnaby draw something badly and save it."""
    m = bot.db
    await _add_reactions(ctx, m)
    _ensure_art_defaults(m)
    if m["internal"].get("is_sleeping"):
        await ctx.send("*He's asleep. The art muses are also asleep. Try again later.*")
        return
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    if m["internal"].get("helpless", False):
        await ctx.send(random.choice([
            "*He looks at his paw. He cannot hold anything right now. He cannot draw.* **...mrr...**",
            "*He blinks at the request. He knows what he would draw. He cannot pick up the paper.* **...mrr...**",
        ]))
        return
    prompt = (prompt or "").strip() or "something random"
    file_path, art_text = _art_prompt_to_art(prompt)
    entry = {
        "title": f"Bad drawing of {prompt}",
        "prompt": prompt,
        "result": art_text,
        "file": file_path,
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }
    m["art_gallery"].append(entry)
    if len(m["art_gallery"]) > 20:
        del m["art_gallery"][: len(m["art_gallery"]) - 20]
    m["internal"]["last_art_at"] = entry["at"]
    m["internal"]["last_art_file"] = file_path
    m["internal"]["last_art_prompt"] = prompt
    save_db(m)
    await ctx.send(random.choice([
        f"*Yarnaby draws **{prompt}**. It is terrible. He is proud of it.*",
        f"*He makes a new picture: **{prompt}**. The lines are bad. The effort is sincere.*",
        f"*Yarnaby has produced art. It is, unfortunately, very much art.*",
    ]))


