@bot.command(name="bath", aliases=["wash", "clean"])
async def bath_cmd(ctx):
    """Bathe Yarnaby (he hates it but needs it)."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
