@bot.command(name="vetfullcheck", aliases=["check_up", "vet_visit", "doctor", "fullheal", "vetcheckup"])
async def vetfullcheck_cmd(ctx):
    """Creator or vet: full checkup - heals all stats and gives a report."""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. A full checkup will have to wait until he wakes. He looks fine right now. Probably.*",
            "*He's napping. His stats can be checked when he's up.* **...zz.**",
        ]))
        return

    if not _is_vet(ctx.author.id):
        await ctx.send(
            random.choice([
                "*Yarnaby eyes you sideways. He doesn't think you're authorized to run a full checkup. **mrrp.***",
                "*He backs away from your hands. Not you. Only The Creator and the vets get to do the full inspection.*",
                "*He gives you a flat, measured look. He doesn't know your credentials. He's going to need credentials. **mrr.***",
            ])
        )
        return

    health_before = m["stats"].get("health", 100)
    temp_before = m["stats"].get("temperature", "warm")
    hunger_before = m["stats"].get("hunger", 0)
    mood_before = m["stats"].get("mood", "Content")
    cleanliness_before = m["stats"].get("cleanliness", 0)

    # Full recovery
    m["stats"]["health"] = 100
    m["stats"]["temperature"] = "warm"
    m["internal"]["recovering_from_toxic_until"] = None
    # Improve mood if bad
    if mood_before in ("Sad", "Agitated", "Depressed"):
        m["stats"]["mood"] = "Content"
    save_db(m)

    report_lines = [
        "**[Yarnaby - Full Checkup]**",
        f" Health: {health_before}/100 -> **100/100** OK",
        f" Temperature: **{temp_before}** -> **warm** OK",
        f" Hunger: **{hunger_before}** {'' if hunger_before > 60 else 'OK'}",
        f" Cleanliness: **{cleanliness_before}** {' (needs a bath)' if cleanliness_before > 70 else 'OK'}",
        f" Mood: **{mood_before}** -> **{m['stats']['mood']}**",
        "",
    ]
    is_creator_vet = ctx.author.id == DOCTOR_ID
    if is_creator_vet:
        report_lines.append(
            random.choice([
                "*He sat through the entire checkup with his eyes forward and his ears back - the specific posture of a creature who objects to this on principle but will cooperate anyway. He looks better. He won't admit it. **mrr.***",
                "*He submitted to every part of it without complaint, which tells you everything about how bad he was feeling. He looks better now. He presses his nose briefly to The Creator's hand. **prrt.***",
                "*He tolerated all of it - the checking, the pressing, the temperature thing - with the dignity of a small creature who knows this is being done with love. He is restored. He shakes himself once. **prrr.***",
            ])
        )
    else:
        report_lines.append(
            random.choice([
                "*He cooperated. Mostly. He side-eyed the vet twice and issued one formal protest sneeze, but he held still. He looks better now. He doesn't say thank you, but he doesn't move away either. **mrr.***",
                "*He allowed the checkup with the specific tolerance of a creature who has decided this person is, fine, probably trustworthy. He kept his ears back the whole time. He is better. He acknowledges this with one cautious **mrp.***",
                "*He sat through it. He gave the vet one very long, very evaluating stare at the start - and then decided to cooperate. He looks significantly better. He tucks his nose under his tail. Recovered. **mrrp.***",
            ])
        )
    await ctx.send("\n".join(report_lines))


