@bot.command(name="find", aliases=["search"])
async def find_cmd(ctx):
    """Search for the hidden yarn-ball."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return

    if not is_doctor:
        remaining = _cooldown_remaining(m, "find", COOLDOWN_FIND)
        if remaining > 0:
            await ctx.send(
                f"*You've already searched recently. Take a breath. (~{remaining}s)*"
            )
            return
    _set_cooldown(m, "find")

    hidden = m["internal"].get("hidden_ball")
    if not hidden:
        await ctx.send(
            random.choice(
                [
                    "*You search the usual spots. Nothing today. Yarnaby watches you from a corner, looking faintly amused.*",
                    "*Nothing hidden. Yarnaby trots over and bumps your hand, as if to apologize for the empty search.*",
                    "*No yarn-ball this time. He hasn't hidden one yet.*",
                ]
            )
        )
        save_db(m)
        return

    spot = hidden.get("spot", "somewhere")
    m["internal"]["hidden_ball"] = None
    _track_item(m, "found yarn-ball", rarity="Hidden", source="find")
    if (
        u_id in m["social_matrix"]
        and not is_doctor
        and m["social_matrix"][u_id].get("score", 0) < FIND_SCORE_CAP
    ):
        m["social_matrix"][u_id]["score"] = min(
            FIND_SCORE_CAP, m["social_matrix"][u_id].get("score", 0) + 2
        )
    await ctx.send(
        f"*You search carefully and find it - {spot}. A small, slightly squashed yarn-ball. Yarnaby appears at the edge of your vision the moment you pick it up. He looks pleased with himself. The hunt is over.*"
    )
    save_db(m)


@bot.command(name="lore", aliases=["fragments", "memory"])
async def lore_cmd(ctx):
    """View lore fragments unlocked through Chromatic fetches."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    unlocked = m.get("lore_unlocked", [])
    if not unlocked:
        await ctx.send(
            "*Yarnaby has not surfaced any of his older memories yet. Lore fragments are unlocked through Chromatic fetches - the rarest kind.*"
        )
        return
    total = len(LORE_FRAGMENTS)
    lines = [f"**[Yarnaby - Lore Fragments {len(unlocked)}/{total}]**", ""]
    lines.extend(unlocked)
    if len(unlocked) < total:
        lines.append("")
        lines.append(f"*{total - len(unlocked)} more fragment(s) remain. Keep fetching.*")
    await ctx.send("\n".join(lines))


@bot.command(name="about", aliases=["info", "version"])
async def about_cmd(ctx, *, stat: str = ""):
    """Yarnaby's version + full stat dashboard."""
