@bot.command(name="reset")
async def reset_cmd(ctx, *, target: Optional[str] = None):
    """Creator-only (full/stats wipe) or vet (!reset @user): manage memory."""
    # Vets can only reset a single user; full wipe and stats reset are Creator-only
    if ctx.author.id != DOCTOR_ID:
        if _is_vet(ctx.author.id) and ctx.message.mentions:
            pass  # vet doing !reset @user - allowed, handled below
        else:
            await ctx.send("*Yarnaby sits very still and stares at you. That is not your button to press.*")
            return

    m = bot.db
    await _add_reactions(ctx, m)

    # --- !reset @user ---
    if ctx.message.mentions:
        user = ctx.message.mentions[0]
        uid = str(user.id)
        if uid in m["social_matrix"]:
            del m["social_matrix"][uid]
            save_db(m)
            await ctx.send(
                f"*Yarnaby tilts his head at where **{user.display_name}** used to be in his memory. A long pause. Then he smooths his wool and looks away. Gone.*"
            )
        else:
            await ctx.send(
                f"*Yarnaby checks his records. **{user.display_name}** isn't in there. He was never logged.*"
            )
        return

    # --- !reset stats ---
    if target and target.strip().lower() == "stats":
        m["stats"]["hunger"] = 0
        m["stats"]["integrity"] = 100
        m["stats"]["affection_crave"] = 0
        m["stats"]["tiredness"] = 0
        m["stats"]["cleanliness"] = 0
        m["stats"]["personality_warmth"] = 0
        m["stats"]["mood"] = "Content"
        m["internal"]["is_sleeping"] = False
        m["internal"]["is_recovering"] = False
        save_db(m)
        await ctx.send(
            "*Yarnaby shakes himself from nose to tail - a long, full-body reset. His wool settles. He looks up at The Creator, composed and clean. Whatever was wrong is no longer on his face.*"
        )
        return

    # --- !reset (full wipe) - requires confirmation ---
    if not target or target.strip().upper() != "CONFIRM":
        await ctx.send(
            "*Yarnaby freezes. His glass eyes go very wide.*\n\n"
            "WARNING: **This will wipe all of Yarnaby's memory** - social scores, inventory, lore, birthdays, everything.\n"
            "Type `!reset CONFIRM` within 30 seconds if you're sure. There is no undo."
        )

        def check(msg):
            return (
                msg.author.id == DOCTOR_ID
                and msg.channel.id == ctx.channel.id
                and msg.content.strip().upper() in ("!RESET CONFIRM", "RESET CONFIRM")
            )

        try:
            await bot.wait_for("message", check=check, timeout=30.0)
        except asyncio.TimeoutError:
            await ctx.send("*Yarnaby exhales slowly. The moment has passed. He is still here. Everything is still here.*")
            return

    fresh = _default_db()
    fresh["internal"]["home_channel_id"] = m["internal"].get("home_channel_id")
    fresh["internal"]["last_channel_id"] = m["internal"].get("last_channel_id")
    bot.db = fresh
    save_db(fresh)
    await ctx.send(
        "*Yarnaby goes completely still. The light in his glass eyes dims for a moment - then returns, clear and blank. He looks around the channel like he's seeing it for the first time. He doesn't know anyone here yet. He is starting over.*"
    )


@bot.command(name="forgive", aliases=["pardon", "absolve"])
async def forgive_cmd(ctx, user: discord.Member = None):
    """Creator or vet: formally forgive a user - clears their grievance record and resets negative score."""
    if not _is_vet(ctx.author.id):
        await ctx.send(
            random.choice([
                "*Yarnaby considers this. He shakes his head, once, slowly. That's not your call to make.* **mrr.**",
                "*He tilts his head. He is the one who decides who gets forgiven. And he is listening for a different voice right now.* **...mrr...**",
            ])
        )
        return

    if not ctx.message.mentions:
        await ctx.send("*Who should he forgive? Mention them: `!forgive @user`.*")
        return

    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    user = ctx.message.mentions[0]
    uid = str(user.id)
    name = user.display_name
    is_forgiving_creator = uid == str(DOCTOR_ID)

    if is_forgiving_creator:
        await ctx.send(
            random.choice([
                f"*He blinks at whoever asked. Forgive **{name}**? He searches the grievance drawer. He finds nothing. There has never been anything there.* **prrr.**",
                f"*He tilts his head very slowly. **{name}** has no open file. The drawer where he keeps those things doesn't have a slot for The Creator. It never did.* **...prrr...**",
            ])
        )
        return

    if uid not in m["social_matrix"]:
        await ctx.send(
            f"*Yarnaby checks his memory for **{name}**. He comes up empty - they're not in his records. There's nothing filed against them because nothing is filed at all.* **mrr.**"
        )
        return

    entry = m["social_matrix"][uid]
    current_score = entry.get("score", 0)
    toxic_attempts = entry.get("toxic_attempts", [])

    # Pull feed_history for any FEED_HATES evidence
    fh_raw = m["internal"].get("feed_history", {}).get(uid, [])
    bad_feeds = [fi for fi in fh_raw if fi.get("item") and any(w in fi["item"] for w in FEED_HATES)]
    pineapple_feeds = [fi for fi in fh_raw if "pineapple" in fi.get("item", "")]

    # --- Determine offense tier ---
    # Serious: toxic attempt on record
    is_toxic_offense = bool(toxic_attempts)
    # Pineapple: deep food grudge
    is_pineapple_offense = bool(pineapple_feeds)
    # Moderate: score meaningfully negative even without toxic
    is_moderate_offense = current_score <= -5
    # Any offense at all
    has_offense = is_toxic_offense or is_pineapple_offense or is_moderate_offense or bool(bad_feeds) or current_score < 0

    if not has_offense:
        await ctx.send(
            random.choice([
                f"*He tilts his head. **{name}**. He searches. He finds no open file - nothing serious, nothing that needed carrying. He chirps softly. All is already fine.* **chrrp.**",
                f"*He blinks. There's nothing to forgive with **{name}**. He checks twice. Still nothing. He pads back to where he was sitting.* **...mrr...**",
                f"*He looks for the grievance and finds it empty. **{name}** has been, on the whole, acceptable. The drawer closes without him opening it.* **mrr.**",
            ])
        )
        return

    # --- Perform the forgiveness ---
    # Clear toxic attempts
    if "toxic_attempts" in entry:
        entry["toxic_attempts"] = []
    # Reset score to 0
    entry["score"] = 0
    save_db(m)

    # --- Tier the response ---
    forgiver_is_creator = ctx.author.id == DOCTOR_ID

    if is_toxic_offense:
        # The heaviest tier - he was shown something that could have hurt him
        most_recent_tox = toxic_attempts[-1]
        tox_item = most_recent_tox.get("item", "something dangerous")
        if forgiver_is_creator:
            await ctx.send(
                random.choice([
                    f"*He goes very still when The Creator says the name. **{name}.** He holds it for a long moment. He remembers the **{tox_item}** - he always will. But The Creator asked. He breathes out slowly. He pads to the centre of the room and sits down, facing forward. He is starting again. He does not say he has forgotten. He says he will try.* **...prrr...**",
                    f"*Yarnaby looks at The Creator for a long time. He looks at the space where **{name}** would be. He looks back. The **{tox_item}** is not something he lets go of easily - he doesn't let go of most things easily. But The Creator asked. He exhales. He closes the file. Not cheerfully. Quietly. With intention.* **...prrr...**",
                    f"*A long pause. Longer than usual. He heard the name - **{name}** - and he remembered all at once. The **{tox_item}**. The way he stepped back. The way he looked at them after. The Creator is asking him to set it down. He considers. He sets it down. Carefully. Like something fragile he doesn't want to break twice.* **...prrr...**",
                ])
            )
        else:
            await ctx.send(
                random.choice([
                    f"*He goes still when he hears **{name}**'s name. He is quiet for a longer time than usual. He remembers the **{tox_item}**. He remembers stepping back. He sets it aside - not easily, not happily, but deliberately. The score is gone. The memory isn't. He starts over anyway.* **...mrr...**",
                    f"*He pulls the file on **{name}** out slowly. He looks at it. He looks at whoever asked. He closes it. Not because it's empty - it isn't. But because he's been told to. He will watch more carefully this time.* **...mrr...**",
                ])
            )

    elif is_pineapple_offense:
        # Pineapple - a deep food grudge, slightly lighter but still loaded
        pa_item = pineapple_feeds[-1].get("item", "pineapple pizza")
        if forgiver_is_creator:
            await ctx.send(
                random.choice([
                    f"*He sits with the name **{name}** for a moment. He remembers the **{pa_item}**. He remembers it very specifically. But The Creator asked. He exhales slowly through his nose - the cat equivalent of a long, resigned breath - and pads forward. The file closes. He will not pretend it never happened. He will pretend it was a long time ago.* **...mrr...**",
                    f"*One ear twitches at the name **{name}**. He knows the file. He knows the **{pa_item}**. He knows exactly how he felt about it. The Creator is asking him to let it go. He considers this seriously. He lets it go. He does not seem entirely at peace with this. He will get there.* **...mrr...**",
                ])
            )
        else:
            await ctx.send(
                random.choice([
                    f"*He remembers the **{pa_item}**. He remembers it clearly. He sets the memory down, carefully, and closes the drawer on it. He is not happy about it. He is compliant about it. That is different.* **mrr.**",
                    f"*He hears **{name}**'s name and goes to the file immediately - he knows exactly which one. **{pa_item}.** He closes it. He turns away. He is moving forward now. At his own pace.* **...mrr...**",
                ])
            )

    elif is_moderate_offense or bad_feeds:
        # Moderate: repeated bad food or general trust erosion
        bad_item = bad_feeds[-1]["item"] if bad_feeds else None
        if forgiver_is_creator:
            lines = [
                f"*He considers **{name}**. He looks at The Creator. He nods - a small, deliberate movement of his head, which he rarely makes. The record clears. He will watch them fresh.* **prrr.**",
                f"*He pads to where **{name}** would sit and sniffs the air. He looks back at The Creator. He sits down. Whatever was accumulated - he has set it down. He's willing to try again.* **prrr.**",
            ]
            if bad_item:
                lines.append(
                    f"*He pulls out the file on **{name}** - the **{bad_item}**, mostly - and closes it. The Creator asked. He respects the request. He pads away, already moving on.* **...prrr...**"
                )
        else:
            lines = [
                f"*He turns **{name}**'s name over quietly. He looks at whoever asked. Then, with a small, resigned exhale, he lets the record go. He will start fresh with them. He is capable of that.* **mrr.**",
                f"*He blinks. He finds **{name}**'s file, looks at it, and closes it without reading it all the way through. That's probably easier. He starts again from zero.* **...mrr...**",
            ]
            if bad_item:
                lines.append(
                    f"*He notes the forgiveness of **{name}**. He notes the **{bad_item}** that started it. He sets both down. He is good at starting from a clean table when someone asks him to.* **mrr.**"
                )
        await ctx.send(random.choice(lines))

    else:
        # Light: score was just slightly negative, no specific food offense
        await ctx.send(
            random.choice([
                f"*He finds the small, quiet record he'd been keeping on **{name}** and closes it. It wasn't much. He wasn't holding it dramatically. But he notices it's gone, and he's fine with that.* **mrr.**",
                f"*He tilts his head at the name **{name}**, considers, and pads forward. Whatever was in that file - he's done with it. He sits down in a new position. Fresh start.* **chrrp.**",
                f"*The record on **{name}** was thin. He closes it anyway. He chirps once, softly. He is already thinking about something else.* **chrrp.**",
            ])
        )


# ==========================================
# CATEGORY 8: RUN
# ==========================================
async def _announce_offline():
    try:
        internal = bot.db["internal"]
        channel_id = (
            internal.get("home_channel_id")
            or internal.get("last_channel_id")
        )
        if not channel_id:
            print("[offline announce] no channel_id stored - skipping")
            return
        ch = _resolve_messageable(bot, channel_id)
        if ch is None:
            try:
                ch = await asyncio.wait_for(
                    bot.fetch_channel(int(channel_id)), timeout=5.0
                )
            except Exception as _fe:
                print(f"[offline announce: fetch_channel failed] {_fe}")
                ch = None
        if ch:
            await asyncio.wait_for(
                ch.send("**Adidas Doge is turning Yarnaby.APP offline. Probably for maintenance.**"),
                timeout=5.0,
            )
        else:
            print("[offline announce] channel not resolvable")
    except Exception as e:
        print(f"[offline announce failed] {e}")


@bot.command(name="while_you_were_gone", aliases=["away_log", "wyg"])
async def while_you_were_gone_cmd(ctx):
    """Full summary of everything that happened while The Creator was away."""
    m = bot.db
    await _add_reactions(ctx, m)
    is_creator = ctx.author.id == DOCTOR_ID
    log = m["internal"].get("away_log", []) or []
    gone_days = _creator_gone_days(m)

    if not log and gone_days < AWAY_LOG_THRESHOLD_DAYS:
        await ctx.send(
            "*Yarnaby tilts his head. You haven't been gone long enough for him to start keeping notes yet.*"
        )
        return
    if not log:
        await ctx.send(
            "*Yarnaby looks at the empty space where the log should be. Nothing happened. He is, quietly, a little disappointed in everyone.*"
        )
        return

    # --- Categorise all log entries ---
    creator_mentions = [e for e in log if e.get("type") == "creator_mention"]
    bot_mentions    = [e for e in log if e.get("type") == "mention"]
    leaves          = [e for e in log if e.get("type") == "leave"]
    kicks           = [e for e in log if e.get("type") == "kicked"]
    bans            = [e for e in log if e.get("type") == "ban"]
    server_joins    = [e for e in log if e.get("type") == "server_join"]
    other           = [e for e in log if e.get("type") not in
                       ("creator_mention","mention","leave","kicked","ban","server_join")]

    # Current server count
    server_count = len(bot.guilds)

    sections = []

    # Header
    if is_creator:
        sections.append(
            f"*Yarnaby drops a folded piece of paper at your feet and sits back. He has been watching. Here is everything:*\n"
            f"*(log covers **{len(log)}** events / gone **{gone_days}d**)*\n"
        )
    else:
        sections.append(
            f"*Yarnaby holds up his notes. He keeps these for the Creator. **{len(log)}** events logged ({gone_days}d):*\n"
        )

    # 1. Creator name mentions
    if creator_mentions:
        variant_counts = {}
        for e in creator_mentions:
            v = e.get("matched_variant", "unknown")
            variant_counts[v] = variant_counts.get(v, 0) + 1
        variant_str = ", ".join(f"**{v}** ×{c}" for v, c in sorted(variant_counts.items(), key=lambda x: -x[1]))
        recent_cm = creator_mentions[-3:]
        lines = [f"📣 **Your name came up {len(creator_mentions)}x** ({variant_str})"]
        for e in recent_cm:
            ex = e.get("excerpt","")[:100]
            guild = e.get("guild_name","?")
            lines.append(f"  └ `{e.get('ts','')[:16]}` **{e.get('author_name','?')}** in *{guild}*: {ex}")
        sections.append("\n".join(lines))

    # 2. Bot mentions
    if bot_mentions:
        mentioners = {}
        for e in bot_mentions:
            n = e.get("author_name","?")
            mentioners[n] = mentioners.get(n,0) + 1
        top = sorted(mentioners.items(), key=lambda x: -x[1])[:5]
        top_str = ", ".join(f"**{n}** ×{c}" for n,c in top)
        sections.append(f"💬 **Yarnaby mentioned {len(bot_mentions)}x** — top: {top_str}")

    # 3. Server joins
    if server_joins:
        lines = [f"🌐 **Added to {len(server_joins)} new server(s)** (now in **{server_count}** total)"]
        for e in server_joins[-5:]:
            nsfw = " ⚠️ NSFW flagged" if e.get("nsfw_flagged") else ""
            lines.append(f"  └ `{e.get('ts','')[:16]}` **{e.get('guild_name','?')}** ({e.get('member_count','?')} members){nsfw}")
        sections.append("\n".join(lines))
    else:
        sections.append(f"🌐 No new servers. Currently in **{server_count}**.")

    # 4. Kicks
    if kicks:
        lines = [f"👢 **{len(kicks)} member(s) kicked**"]
        for e in kicks[-5:]:
            by = f" by {e.get('kicked_by','?')}" if e.get('kicked_by') else ""
            guild = e.get("guild_name","?")
            lines.append(f"  └ `{e.get('ts','')[:16]}` **{e.get('author_name','?')}**{by} in *{guild}*")
        sections.append("\n".join(lines))

    # 5. Bans
    if bans:
        lines = [f"🔨 **{len(bans)} member(s) banned**"]
        for e in bans[-5:]:
            by = f" by {e.get('banned_by','?')}" if e.get('banned_by') else ""
            reason = f" — {e.get('reason','?')}" if e.get('reason') and e.get('reason') != 'no reason' else ""
            guild = e.get("guild_name","?")
            lines.append(f"  └ `{e.get('ts','')[:16]}` **{e.get('author_name','?')}**{by}{reason} in *{guild}*")
        sections.append("\n".join(lines))

    # 6. Leaves
    if leaves:
        names = [e.get("author_name","?") for e in leaves[-8:]]
        extra = f" (+{len(leaves)-8} more)" if len(leaves) > 8 else ""
        sections.append(f"📤 **{len(leaves)} member(s) left** — {', '.join(f'**{n}**' for n in names)}{extra}")

    # 7. Other
    if other:
        lines = [f"📋 **{len(other)} other event(s)**"]
        for e in other[-3:]:
            ex = e.get("excerpt","")[:80]
            lines.append(f"  └ `{e.get('ts','')[:16]}` {ex}")
        sections.append("\n".join(lines))

    # Send in chunks to respect Discord 2000-char limit
    full = "\n\n".join(sections)
    chunks = []
    while len(full) > 1900:
        split = full.rfind("\n", 0, 1900)
        if split == -1:
            split = 1900
        chunks.append(full[:split])
        full = full[split:].lstrip()
    chunks.append(full)

    for chunk in chunks:
        if chunk.strip():
            await ctx.send(chunk)


@bot.command(name="comfort", aliases=["comfort_object"])
async def comfort(ctx):
    """Show what Yarnaby has been carrying around since The Creator left."""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    gone_days = _creator_gone_days(m)
    if gone_days < COMFORT_OBJECT_THRESHOLD_DAYS:
        await ctx.send(
            f"*Yarnaby looks at you, then at his hoard. He hasn't latched onto anything yet - the Creator hasn't been gone long enough. ({gone_days}d)*"
        )
        return
    pick = _ensure_comfort_object(m)
    save_db(m)
    if not pick:
        await ctx.send(
            "*Yarnaby's hoard is empty. He has nothing to hold on to. He looks, very briefly, lost.*"
        )
        return
    assigned = m["internal"].get("comfort_object_assigned_at") or "?"
    await ctx.send(
        f"*Yarnaby pads over carrying **{pick}** in his teeth. He hasn't put it down since around `{assigned}`. He carries it to the entrance every night and sleeps with it. He'd very much like the Creator to come home and see he kept it safe.*"
    )


@bot.command(name="set_departure", aliases=["set_departure_date", "departure"])
async def set_departure_cmd(ctx):
    """[Creator only] Pin the date the Creator left, for yearly anniversaries.

    Usage: `!set_departure 2026-04-26`  - or `!set_departure today` - or
    `!set_departure clear` to remove.
    """
    if ctx.author.id != DOCTOR_ID:
        await ctx.send(
            "*Yarnaby looks at you, then very pointedly does nothing. This one's for the Creator.*"
        )
        return
    m = bot.db
    await _add_reactions(ctx, m)
    if not when:
        cur = m["internal"].get("departure_date")
        if cur:
            await ctx.send(f"*Departure date is currently set to `{cur}`.*")
        else:
            await ctx.send(
                "*No departure date set. Use `!set_departure YYYY-MM-DD` or `!set_departure today`.*"
            )
        return
    arg = when.strip().lower()
    if arg in ("clear", "none", "off", "unset"):
        m["internal"]["departure_date"] = None
        m["internal"]["last_anniversary_year"] = None
        save_db(m)
        await ctx.send("*Departure date cleared. Yarnaby will not mark an anniversary.*")
        return
    if arg == "today":
        chosen = datetime.now().date()
    else:
        try:
            chosen = datetime.strptime(arg, "%Y-%m-%d").date()
        except ValueError:
            await ctx.send(
                "*That date didn't parse. Try `YYYY-MM-DD`, e.g. `2026-04-26`.*"
            )
            return
    m["internal"]["departure_date"] = chosen.strftime("%Y-%m-%d")
    # Don't fire the anniversary the same day it's set.
    m["internal"]["last_anniversary_year"] = chosen.year
    save_db(m)
    await ctx.send(
        f"*Yarnaby tucks the date away somewhere safe: **{chosen.strftime('%Y-%m-%d')}**. He will remember.*"
    )


@bot.command(name="fb_status", aliases=["fb", "fenerbahce", "fener"])
async def fb_status_cmd(ctx):
    """Show what Yarnaby knows about Fenerbahçe right now."""
    if aiohttp is None:
        await ctx.send(
            "*Yarnaby's little radio isn't plugged in (network library missing).*"
        )
        return
    m = bot.db
    await _add_reactions(ctx, m)
    active = m["internal"].get("fb_match")
    if active:
        ev_id = active.get("event_id")
        opp = active.get("opponent", "?")
        state = await fetch_fb_event_state(ev_id, active.get("provider", "sofascore")) if ev_id else None
        if state:
            home = state["home_score"]
            away = state["away_score"]
            fb = home if active.get("fb_is_home") else away
            opp_s = away if active.get("fb_is_home") else home
            await ctx.send(
                f"*Live: **Fenerbahçe {fb}-{opp_s} {opp}** ({state.get('status_desc') or state.get('status_type') or 'live'}). Yarnaby is watching very intently.*"
            )
            return

    schedule = m["internal"].get("fb_schedule") or []
    if not schedule:
        # Try a fresh fetch on demand.
        schedule = await fetch_fb_upcoming()
        if schedule:
            m["internal"]["fb_schedule"] = schedule
            m["internal"]["fb_schedule_fetched_at"] = datetime.now().strftime(
                "%Y-%m-%d %H:%M:%S"
            )
            save_db(m)
