# ==========================================
# !fbsetfixture - manually set the next fixture
# ==========================================

@bot.command(name="fbsetfixture", aliases=["fbsetmatch", "fbaddmatch", "fbsetdate", "fbsetnext", "fbmanualfixture"])
async def fbsetfixture_cmd(ctx):
    """Manually set the next fixture date/time (Istanbul time).
    Usage: !fbsetfixture Galatasaray 2026-05-10 21:00
    Full:  !fbsetfixture Galatasaray 2026-05-10 21:00 away Süper Lig
    """
    import re as _re

    if not args:
        await ctx.send(
            "*He looks at you, ears forward. Give him the details.*\n"
            "`!fbsetfixture [opponent] [YYYY-MM-DD] [HH:MM]`\n"
            "Or: `!fbsetfixture [opponent] [DD Month YYYY] [HH:MM] [home/away] [tournament]`\n"
            "Time is **Istanbul time**. Home/away defaults to **home** if not given."
        )
        return

    #  Find date 
    MONTHS = "Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec"
    date_pat = _re.search(
        rf'(\d{{4}}-\d{{2}}-\d{{2}}'
        rf'|\d{{1,2}}[./]\d{{1,2}}[./]\d{{4}}'
        rf'|\d{{1,2}}\s+(?:{MONTHS})\w*\.?\s+\d{{4}}'
        rf'|\d{{1,2}}\s+(?:{MONTHS})\w*\.?)',
        args, _re.IGNORECASE
    )
    time_pat = _re.search(r'(\d{1,2}:\d{2})(?:\s|$)', args)

    if not date_pat or not time_pat:
        await ctx.send(
            "*He squints at that. He couldn't find a date or time.*\n"
            "Expected: `!fbsetfixture Galatasaray 2026-05-10 21:00`\n"
            "Or: `!fbsetfixture Galatasaray 10 May 2026 21:00`"
        )
        return

    date_str = date_pat.group(1).strip()
    time_str = time_pat.group(1).strip()

    # Opponent = everything before the date
    opponent = args[:date_pat.start()].strip().rstrip(",;")
    if not opponent:
        await ctx.send("*He waits. He needs an opponent name before the date.* **mrr.**")
        return

    # rest after the later of date-end / time-end
    after = args[max(date_pat.end(), time_pat.end()):].strip()

    #  home / away 
    fb_is_home = True
    after_lower = after.lower()
    if after_lower.startswith("away"):
        fb_is_home = False
        after = after[4:].strip()
    elif after_lower.startswith("home"):
        after = after[4:].strip()

    tournament = after.strip()

    #  Parse date 
    now_year = datetime.now().year
    dt_date = None
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d.%m.%Y"):
        try:
            dt_date = datetime.strptime(date_str, fmt)
            break
        except ValueError:
            pass
    if dt_date is None:
        for fmt in ("%d %B %Y", "%d %b %Y", "%d %B", "%d %b"):
            try:
                raw = datetime.strptime(date_str, fmt)
                dt_date = raw.replace(year=now_year) if raw.year == 1900 else raw
                break
            except ValueError:
                pass
    if dt_date is None:
        await ctx.send(
            f"*He stares at `{date_str}`. He can't read that date. Try `YYYY-MM-DD` or `10 May 2026`.* **mrr.**"
        )
        return

    #  Parse time and convert Istanbul -> UTC timestamp 
    try:
        hour, minute = map(int, time_str.split(":"))
        dt_istanbul = dt_date.replace(hour=hour, minute=minute, second=0, microsecond=0)
        # Istanbul is UTC+3 (no DST in Turkey since 2016)
        dt_utc = dt_istanbul - ISTANBUL_OFFSET
        kickoff_ts = int(dt_utc.replace(tzinfo=timezone.utc).timestamp())
    except Exception:
        await ctx.send(f"*He blinks at `{time_str}`. Time should be HH:MM.* **mrr.**")
        return

    #  Store 
    new_fixture = {
        "event_id": None,
        "provider": "manual",
        "kickoff_ts": kickoff_ts,
        "tournament": tournament,
        "fb_is_home": fb_is_home,
        "opponent": opponent,
    }

    m = bot.db
    await _add_reactions(ctx, m)
    schedule = m["internal"].get("fb_schedule") or []
    # Remove any previous manual entry for the same opponent (no duplicates)
    schedule = [s for s in schedule if not (
        s.get("provider") == "manual" and
        s.get("opponent", "").lower() == opponent.lower()
    )]
    schedule.insert(0, new_fixture)
    m["internal"]["fb_schedule"] = schedule
    m["internal"]["fb_schedule_fetched_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m)

    #  Confirm 
    istanbul_tz = timezone(ISTANBUL_OFFSET)
    confirm_dt = datetime.fromtimestamp(kickoff_ts, tz=timezone.utc).astimezone(istanbul_tz)
    confirm_date = confirm_dt.strftime("%d %B %Y")
    confirm_time = confirm_dt.strftime("%H:%M")
    ha_str = "at home" if fb_is_home else "away"

    await ctx.send(
        f"*He nods. He has it.*\n"
        f"**Fenerbahçe vs {opponent}** ({ha_str})\n"
        f" **{confirm_date}** at **{confirm_time} Istanbul time**"
        + (f"\n*{tournament}*" if tournament else "")
    )


