@bot.command(name="mimic", aliases=["copy", "echo"])
async def mimic_cmd(ctx, *, text: str = ""):
    """Have Yarnaby mimic a word, phrase, or message in his own non-verbal way."""
    if not text.strip():
        await ctx.send("*He tilts his head. Mimic what?*")
        return
    cleaned = text.strip()
    lower = cleaned.lower()
    if any(x in lower for x in ["bad word", "swear", "slur", "nsfw"]):
        await ctx.send("*He hears it, and refuses to repeat it. His ears go flat. **mrr.***")
        return
    if len(cleaned) > 200:
        cleaned = cleaned[:200].rstrip()
    await ctx.send(random.choice([
        f"*He copies the shape of it back in his own way:* **{cleaned}**",
        f"*He repeats it carefully, but only as a soft little echo:* **{cleaned}**",
        f"*He tries to mimic it exactly. It comes out smaller, quieter, and somehow more Yarnaby.* **{cleaned}**",
    ]))


