@bot.command(name="fbxi", aliases=["fblineup", "fbstarters", "fbteams", "fbsquad", "fbelevenxi"])
async def fbxi_cmd(ctx, channel: discord.TextChannel = None):
    """Interactive: collect both teams XI + bench in DM, post to home channel."""
    m = bot.db
    await _add_reactions(ctx, m)

    # Try to get opponent name from schedule / active match
    if opp_override:
        opponent = opp_override.strip()
    else:
        active = m["internal"].get("fb_match")
        schedule = m["internal"].get("fb_schedule") or []
        if active:
            opponent = active.get("opponent", "Opponent")
        elif schedule:
            opponent = schedule[0].get("opponent", "Opponent")
        else:
            opponent = "Opponent"

    def same_author(msg):
        return msg.author == ctx.author and msg.channel == ctx.channel

    #  Step 1: Fenerbahçe XI + bench 
    await ctx.send(
        f"*He sits up straight. Ears forward. He's ready to take this down.*\n"
        f"**Fenerbahçe XI + bench** - type it in your next message.\n"
        f"*(players separated by commas or line breaks, bench after a dash or 'bench:' label)*"
    )
    try:
        fb_msg = await bot.wait_for("message", check=same_author, timeout=180.0)
        fb_xi = fb_msg.content.strip()
    except asyncio.TimeoutError:
        await ctx.send("*He waited. You didn't come back. He'll be here when you are.* **...mrr...**")
        return

    #  Step 2: Opponent XI + bench 
    await ctx.send(
        f"*Got it. Now **{opponent}'s XI + bench**.*"
    )
    try:
        opp_msg = await bot.wait_for("message", check=same_author, timeout=180.0)
        opp_xi = opp_msg.content.strip()
    except asyncio.TimeoutError:
        await ctx.send("*He waited again. He has Fenerbahçe's lineup but not the opponent's. Come back when you have it.* **...mrr...**")
        return

    #  Post to home channel 
    home_id = m["internal"].get("home_channel_id")
    home_ch = _resolve_messageable(bot, home_id) if home_id else None

    announcement = (
        f" **MATCH LINEUPS**\n\n"
        f" **Fenerbahçe**\n{fb_xi}\n\n"
        f" **{opponent}**\n{opp_xi}"
    )

    await ctx.send(
        random.choice([
            "*He has it all. He's posting it now.* **mrr.**",
            "*Noted. He's sending it through.* **prrr.**",
            "*He read every name carefully. He's announcing it now.* **mrr.**",
        ])
    )
    if home_ch:
        # Discord 2000-char limit - split if needed
        if len(announcement) <= 2000:
            await home_ch.send(announcement)
        else:
            fb_block = f" **MATCH LINEUPS**\n\n **Fenerbahçe**\n{fb_xi}"
            opp_block = f" **{opponent}**\n{opp_xi}"
            await home_ch.send(fb_block[:2000])
            await home_ch.send(opp_block[:2000])
    else:
        await ctx.send(
            "*He has the lineups but there's no home channel pinned. Use `!set_home` in the server first.*\n"
            f"**Fenerbahçe:** {fb_xi[:300]}...\n**{opponent}:** {opp_xi[:300]}..."
        )


# ==========================================
# !fbsubs     - substitution announcement
# !fbredcard  - red card announcement
# !fbfulltime - manual full-time result
# ==========================================

def _parse_fb_event(raw: Optional[str]):
    """Parse 'opp? minute? rest' from a raw arg string.
    Returns (is_opponent: bool, minute_str: str, rest: str).
    """
    if not raw:
        return False, "", ""
    import re as _re
    parts = raw.strip()
    is_opp = False
    opp_words = ("opp", "opponent", "other", "them", "enemy")
    first = parts.split()[0].lower() if parts.split() else ""
    if first in opp_words:
        is_opp = True
        parts = parts.split(None, 1)[1] if len(parts.split(None, 1)) > 1 else ""
    # Optional leading minute: digits optionally followed by '
    minute_str = ""
    m = _re.match(r"^(\d{1,3})['\u2019]?\s*", parts)
    if m:
        minute_str = m.group(1)
        parts = parts[m.end():]
    return is_opp, minute_str, parts.strip()


@bot.command(name="fbsubs", aliases=["fbsub", "fbsubstitution", "fbchange", "fbswap"])
async def fbsubs_cmd(ctx, channel: discord.TextChannel = None):
    """Substitution event - announces to home channel.
    Usage: !fbsubs [opp] [minute] [player out] -> [player in]
    """
    m = bot.db
    await _add_reactions(ctx, m)
    if not args:
        await ctx.send(
            "*He tilts his head. Tell him who came on.*\n"
            "Usage: `!fbsubs 65 Dzeko -> Cenk` (Fenerbahçe sub)\n"
            "Or: `!fbsubs opp 70 Icardi -> Zaha` (opponent sub)"
        )
        return

    import re as _re

    is_opp, minute_str, rest = _parse_fb_event(args)

    # Split on ->, ->, >, "for", "comes on for"
    sep_pattern = _re.split(r"\s*(?:->|->|>|(?:\bcomes?\s+on\s+for\b)|(?:\bfor\b))\s*", rest, maxsplit=1)
    if len(sep_pattern) == 2:
        player_out, player_in = sep_pattern[0].strip(), sep_pattern[1].strip()
    else:
        # Fallback: last word is player_in, everything before is player_out
        words = rest.split()
        if len(words) >= 2:
            player_out = " ".join(words[:-1]).strip()
            player_in = words[-1].strip()
        else:
            player_out = rest.strip()
            player_in = "?"

    minute_label = f"{minute_str}' - " if minute_str else ""
    home_id = m["internal"].get("home_channel_id")
    home_ch = _resolve_messageable(bot, home_id) if home_id else None

    # Pick opponent name for label
    active = m["internal"].get("fb_match")
    schedule = m["internal"].get("fb_schedule") or []
    opp_label = (active or {}).get("opponent") or (schedule[0].get("opponent") if schedule else "Opponent")

    if is_opp:
        team_label = opp_label
        dm_line = random.choice([
            f"*He notices the change. **{minute_label}{player_out}** off, **{player_in}** on for {opp_label}. His tail flicks once.* **mrr.**",
            f"*{opp_label} make a change. **{minute_label}{player_out}** -> **{player_in}**. He watches carefully.* **mrr.**",
        ])
        home_line = f" **Sub - {opp_label}:** {minute_label}**{player_out}** -> **{player_in}**"
    else:
        team_label = "Fenerbahçe"
        dm_line = random.choice([
            f"*He watches the number change on the touchline. **{minute_label}{player_out}** off, **{player_in}** on. He approves quietly.* **mrr.**",
            f"*Fenerbahçe bring on **{player_in}** for **{player_out}**. {minute_label}He tracks the movement carefully.* **prrr.**",
        ])
        home_line = f" **Sub - Fenerbahçe:** {minute_label}**{player_out}** -> **{player_in}**"

    await ctx.send(dm_line)
    if home_ch:
        await home_ch.send(home_line)
    else:
        await ctx.send("*No home channel pinned - use `!set_home` in the server first.* **...mrr...**")
    save_db(m)


