# ==========================================
# !fbnews - DM Yarnaby a news item; he announces to home channel
# ==========================================

@bot.command(name="fbnews", aliases=["fbannounce", "fbnewsflash", "fbupdate_news", "fbtransfer", "fbbreaking"])
async def fbnews_cmd(ctx, *, message: str = ""):
    """DM Yarnaby a Fenerbahçe news item - he reacts and posts to home channel.
    Usage: !fbnews Dzeko signed a new contract until 2027
    Or just !fbnews - he'll wait for your next message.
    """
    import re as _re

    m = bot.db
    await _add_reactions(ctx, m)

    # If no inline text, wait for the next message
    if not news_text:
        await ctx.send(
            "*He looks up immediately. His ears are forward. What's the news?*\n"
            "*(Type it in your next message)*"
        )
        def same_author(msg):
            return msg.author == ctx.author and msg.channel == ctx.channel
        try:
            follow = await bot.wait_for("message", check=same_author, timeout=120.0)
            news_text = follow.content.strip()
        except asyncio.TimeoutError:
            await ctx.send("*He waited. Nothing came through.* **...mrr...**")
            return

    if not news_text:
        await ctx.send("*He blinks. There's nothing to announce.* **mrr.**")
        return

    news_lower = news_text.lower()

    # Detect news category for Yarnaby's reaction tone
    is_signing   = any(w in news_lower for w in ("sign", "signed", "joins", "joined", "transfers to", "welcome", "new arrival", "transfer"))
    is_departure = any(w in news_lower for w in ("leaves", "left", "departed", "exit", "sold", "release", "loan", "goodbye", "farewell"))
    is_manager   = any(w in news_lower for w in ("manager", "coach", "head coach", "teknik direktor", "appointed", "sacked", "fired", "resigned"))
    is_injury    = any(w in news_lower for w in ("injur", "ruled out", "surgery", "hospital", "tear", "broken", "muscle", "hamstring", "knee"))
    is_win       = any(w in news_lower for w in ("champion", "title", "trophy", "won", "win", "cup", "league"))

    if is_signing:
        dm_react = random.choice([
            "*He sits up straight. New arrival. He's processing this. His tail flicks with interest.* **mrr.**",
            "*He tilts his head to one side, then the other. A new one. He will form an opinion eventually.* **...prrr...**",
        ])
        home_intro = random.choice([
            " *Yarnaby has news. His ears are up.*",
            " *He looked up from his corner. He has something to say.*",
        ])
    elif is_departure:
        dm_react = random.choice([
            "*He goes quiet for a moment. Someone is leaving. He notes it carefully.* **...mrr...**",
            "*He sits down. He registers the departure. He doesn't elaborate.* **mrr.**",
        ])
        home_intro = random.choice([
            " *Yarnaby has news. He delivered it quietly.*",
            " *He spoke up from the corner. His voice was measured.*",
        ])
    elif is_manager:
        dm_react = random.choice([
            "*He goes very still. A manager change. He is watching this very carefully.* **...mrr...**",
            "*His ears flatten briefly, then rise again. He is paying close attention.* **mrr.**",
        ])
        home_intro = random.choice([
            " *Yarnaby has news about the bench. He looked serious about it.*",
            " *He sat up and announced this one deliberately.*",
        ])
    elif is_injury:
        dm_react = random.choice([
            "*He winces slightly. He doesn't like this kind of news. He relays it anyway.* **...mrr...**",
            "*His tail drops a little. He passes it on.* **prrt.**",
        ])
        home_intro = random.choice([
            " *Yarnaby has an update. He didn't look happy about it.*",
            " *He delivered this one without much ceremony.*",
        ])
    elif is_win:
        dm_react = random.choice([
            "*He is on his feet. He is pacing already. He has news and it is the good kind.* **MRRROW!!**",
            "*His tail is enormous. He cannot contain himself. He is announcing this.* **pRROWW!!**",
        ])
        home_intro = random.choice([
            " *Yarnaby has NEWS. He sprinted to the channel.*",
            " *He burst in with this one. His tail has not calmed down.*",
        ])
    else:
        dm_react = random.choice([
            "*He read it. He noted it. He is passing it along.* **mrr.**",
            "*He listened carefully, then decided you should know.* **mrr.**",
        ])
        home_intro = random.choice([
            " *Yarnaby has a Fenerbahçe update.*",
            " *He came over specifically to say this.*",
        ])

    # Log to news history (last 20)
    news_log = m["internal"].setdefault("fb_news_log", [])
    news_log.append({
        "text": news_text,
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    m["internal"]["fb_news_log"] = news_log[-20:]

    home_id = m["internal"].get("home_channel_id")
    home_ch = _resolve_messageable(bot, home_id) if home_id else None

    await ctx.send(dm_react)
    save_db(m)
    if home_ch:
        await home_ch.send(f"{home_intro}\n\n**{news_text}**")
    else:
        await ctx.send(
            "*He wants to announce it but no home channel is pinned. Use `!set_home` in the server first.* **...mrr...**"
        )
    return


