@bot.command(name="fbchampions", aliases=["fbchamp", "fbwinner", "fbchampion", "leaguewinner", "supertitle"])
async def fbchampions_cmd(ctx):
    """Announce the Süper Lig champion. Creator only.
    !fbchampions Fenerbahçe  ->  Yarnaby loses his mind.
    !fbchampions Galatasaray ->  He has feelings about this.
    !fbchampions             ->  Show who the current champions are.
    """
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Yarnaby tilts his head. This isn't for you.* **mrrp.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)

    # No argument -> show stored champion
    if not team_name:
        stored = m["internal"].get("fb_champions")
        if not stored:
            await ctx.send("*He doesn't have a champion on record yet. Use `!fbchampions [team]` to set one.* **mrr.**")
            return
        champ = stored.get("team", "?")
        since = stored.get("set_at", "?")[:10]
        if stored.get("is_fb"):
            await ctx.send(
                f"*He already knows. He has always known. **{champ}** - champions. He carries it like a warm thing pressed close.* **prrr.**\n*(recorded {since})*"
            )
        else:
            await ctx.send(
                f"*He reads the name: **{champ}**. His ear is still flat about it.* **...mrr.**\n*(recorded {since})*"
            )
        return

    team_lower = team_name.strip().lower()

    # Detect if it's Fenerbahçe
    FB_ALIASES = {
        "fenerbahce", "fenerbahce", "fener", "fb", "sar kanarya",
        "yellow canary", "the canaries", "1907", "fb1907", "fenerbahce sk",
    }
    is_fb = team_lower in FB_ALIASES or "fener" in team_lower

    # Store the record
    m["internal"]["fb_champions"] = {
        "team": team_name.strip(),
        "is_fb": is_fb,
        "set_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }

    home_channel_id = m["internal"].get("home_channel_id")
    home_channel = bot.get_channel(int(home_channel_id)) if home_channel_id else ctx.channel

    if is_fb:
        # Plant the festival dream seed for the next sleep
        m["internal"]["dream_seed"] = "festival"
        save_db(m)

        # Announcement to home channel
        announcement = (
            "** FENERBAHÇE - TRENDYOL SUPER LIG SAMPIYONU **\n\n"
            "*He freezes. He reads the name on the screen one more time. **Fenerbahçe. Champions.** Eleven years. "
            "Something in his chest that has been very quiet for a very long time becomes very loud all at once. "
            "He stands up from his spot - all the way up - and his tail goes vertical and stays there. "
            "He makes a sound that is not quite a chirp and not quite a roar and is entirely him. "
            "He runs one complete circuit of the room at full speed and comes back to exactly where he started. "
            "He sits down. He blinks. He gets up and does it again.* **PRRRRR! CHRRP! CHRRP! MRRROOOWW!**\n\n"
            "*He presses his nose to the screen where the name is. He stays there for a long time. "
            "He is thinking about eleven years and what eleven years feels like from inside a factory "
            "with a yellow and navy heart. He knows. He has always known it would come. "
            "He just didn't know when. Now he knows when.* **...prrr... prrr... prrr...**"
        )
        if home_channel:
            await home_channel.send(announcement)
        if home_channel != ctx.channel:
            await ctx.send(f"*Announced to <#{home_channel_id}>. The dream seed is set - he'll dream the championship tonight.* **prrr.**")

    else:
        save_db(m)

        # Rival team names we can be specific about
        rival_lines = {
            "galatasaray": [
                f"*He reads **{team_name}**. His ear goes flat. He pads to his spot, sits with his back to the screen, and does not make a sound for a long time. He is filing this under things he will remember and not forgive.* **...hff...**",
                f"*The name sits on the screen. He looks at it. He does not look away. Then he turns around very deliberately and lies down facing the wall. He is not going to dignify this.* **...mrr...**",
            ],
            "beAYiktaAY": [
                f"*He reads **{team_name}**. His tail moves once, slowly. He is not devastated. He is not happy. He sits very still and processes this the way he processes bad news - quietly, with his eyes forward.* **mrr.**",
            ],
            "trabzonspor": [
                f"*He reads **{team_name}**. He flicks one ear. His expression is the flat, careful kind that means he has noted it and will not be commenting on it further tonight.* **...mrr...**",
            ],
        }

        team_key = team_lower.replace("s", "s").replace("c", "c").replace("", "i").replace("g", "g")
        matched_rival = next((k for k in rival_lines if k in team_key or team_key in k), None)

        if matched_rival:
            reaction = random.choice(rival_lines[matched_rival])
        else:
            reaction = random.choice([
                f"*He reads **{team_name}** on the screen. His ear flattens. He has nothing further to say about it.* **...mrr...**",
                f"*He stares at the name **{team_name}**. He sits down slowly. He will not be performing this feeling. He just has it.* **mrr.**",
            ])

        announcement = f"**[Trendyol Süper Lig - Sampiyon: {team_name}]**\n\n{reaction}"
        if home_channel:
            await home_channel.send(announcement)
        if home_channel != ctx.channel:
            await ctx.send(f"*Announced to <#{home_channel_id}>.* **mrr.**")


