@bot.command(name="apologize", aliases=["sorry", "apology"])
async def apologize_cmd(ctx):
    """Apologize to Yarnaby. Slowly mends a low relationship."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*You apologize to his sleeping form. He doesn't hear you. The apology counts anyway, you tell yourself.*",
                "*A whispered sorry. He sleeps on. Maybe it'll find him in a dream.*",
            ])
        )
        return

    if is_doctor:
        await ctx.send(
            random.choice([
                "*Yarnaby doesn't understand what you're apologizing for. He just hears your tone and presses his head against your hand. It's fine. It was always fine.*",
                "*You apologize. He chirps softly, climbs into your lap, and tucks his head under your chin. There is nothing to forgive.*",
                "*He listens with his whole face, very serious. Then he licks your wrist once, briefly. Forgiven.*",
            ])
        )
        m["stats"]["affection_crave"] = max(0, m["stats"]["affection_crave"] - 2)
        m["stats"]["integrity"] = min(100, m["stats"].get("integrity", 100) + 1)
        save_db(m)
        return

    # Per-user 30-min cooldown so apologies can't be spammed for free score.
    remaining = _cooldown_remaining(m, f"apologize:{u_id}", 1800)
    if remaining > 0:
        mins = max(1, remaining // 60)
        await ctx.send(
            f"*Yarnaby has heard you the first time. He'll consider it for a while. (try again in ~{mins}m)*"
        )
        return
    _set_cooldown(m, f"apologize:{u_id}")

    score = m["social_matrix"].get(u_id, {}).get("score", 0)

    if score < 0:
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] += 1
        await ctx.send(
            random.choice([
                "*Yarnaby looks at you for a long moment. He doesn't come closer. But he doesn't leave either. That is, for him, a beginning.*",
                "*He sits down a careful distance away and considers you. The set of his ears softens, just slightly. Progress.*",
                "*He listens. He doesn't forgive you, exactly. But he files the apology somewhere.*",
            ])
        )
    elif score == 0:
        await ctx.send(
            random.choice([
                "*Yarnaby tilts his head. He isn't sure what for, but he accepts the apology in spirit.*",
                "*He blinks slowly. Apology received. Apology processed. Apology archived.*",
            ])
        )
    else:
        await ctx.send(
            random.choice([
                "*Yarnaby chirps, confused. He didn't think anything was wrong. He bumps your knee with his head.*",
                "*He doesn't know why you're apologizing, but he leans against your leg in support.*",
            ])
        )
    save_db(m)


