# ==========================================
# Member birthdays (registered by users themselves)
# ==========================================

_MONTH_NAMES = ["", "January", "February", "March", "April", "May", "June",
                "July", "August", "September", "October", "November", "December"]


def _parse_mm_dd(raw):
    """Parse 'MM-DD' / 'MM/DD' / 'M-D' / 'M/D'. Returns (month, day) or None."""
    if not raw:
        return None
    cleaned = raw.strip().replace("/", "-").replace(".", "-")
    parts = cleaned.split("-")
    if len(parts) != 2:
        return None
    try:
        mo = int(parts[0])
        da = int(parts[1])
        # validate against a leap year so Feb 29 is allowed
        datetime(2024, mo, da)
        return (mo, da)
    except (ValueError, TypeError):
        return None


def _days_until(month, day):
    """Days from today (Istanbul) until next occurrence of MM-DD."""
    today = (datetime.now(timezone.utc).replace(tzinfo=None) + ISTANBUL_OFFSET).date()
    try:
        target = datetime(today.year, month, day).date()
    except ValueError:
        # Feb 29 in a non-leap year - slide to Mar 1 for ordering
        target = datetime(today.year, 3, 1).date()
    if target < today:
        try:
            target = datetime(today.year + 1, month, day).date()
        except ValueError:
            target = datetime(today.year + 1, 3, 1).date()
    return (target - today).days


@bot.command(name="my_birthday", aliases=["mybirthday", "setbirthday", "set_birthday", "registerbirthday"])
async def my_birthday_cmd(ctx):
    """Register your own birthday so Yarnaby can mark the day. Format: MM-DD."""
    m = bot.db
    await _add_reactions(ctx, m)
    m.setdefault("member_birthdays", {})
    u_id = str(ctx.author.id)
    name = ctx.author.display_name

    if not date:
        existing = m["member_birthdays"].get(u_id)
        if existing and isinstance(existing, dict):
            mo = existing.get("month")
            da = existing.get("day")
            if mo and da:
                left = _days_until(mo, da)
                month_name = _MONTH_NAMES[mo] if 1 <= mo <= 12 else str(mo)
                if left == 0:
                    await ctx.send(
                        f"*Yarnaby is already watching you closely today. Your birthday is **{month_name} {da:02d}** - that's **today**.*"
                    )
                else:
                    await ctx.send(
                        f"*Yarnaby has it written down somewhere small inside himself: **{month_name} {da:02d}**. That's **{left} day(s)** away. He'll be ready.*\n"
                        f"*To change it, use `!my_birthday MM-DD`. To remove it, use `!unset_birthday`.*"
                    )
                return
        await ctx.send(
            "*Yarnaby tilts his head - he doesn't know your birthday yet.*\n"
            "*Tell him with `!my_birthday MM-DD` (e.g. `!my_birthday 03-14`). On that day, he'll mark it for you, the same way he marks his own.*"
        )
        return

    parsed = _parse_mm_dd(date)
    if not parsed:
        await ctx.send(
            "*Yarnaby blinks. He didn't understand that date.*\n"
            "*Try `!my_birthday MM-DD` - for example `!my_birthday 03-14` or `!my_birthday 12/24`.*"
        )
        return
    mo, da = parsed

    prev = m["member_birthdays"].get(u_id) if isinstance(m["member_birthdays"].get(u_id), dict) else {}
    m["member_birthdays"][u_id] = {
        "month": mo,
        "day": da,
        "name": name,
        "set_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "last_announced_year": prev.get("last_announced_year"),
    }
    save_db(m)

    month_name = _MONTH_NAMES[mo]
    left = _days_until(mo, da)
    if left == 0:
        await ctx.send(
            f"*Yarnaby's ears prick up. **{month_name} {da:02d}** - that's today. He looks at you for a long, soft moment, and chirps.*"
        )
    else:
        await ctx.send(
            random.choice([
                f"*Yarnaby tilts his head. He notes it carefully - **{month_name} {da:02d}**. He'll remember. ({left} day(s) away.)*",
                f"*Filed away, somewhere small and warm inside him: **{month_name} {da:02d}**. He'll mark the day when it comes. ({left} day(s) to go.)*",
                f"*He chirps once in acknowledgment. **{month_name} {da:02d}** is now a day he watches for. ({left} day(s) away.)*",
            ])
        )


@bot.command(name="unset_birthday", aliases=["forget_birthday", "clear_birthday"])
async def unset_birthday_cmd(ctx):
    """Have Yarnaby forget your registered birthday."""
    m = bot.db
    await _add_reactions(ctx, m)
    m.setdefault("member_birthdays", {})
    u_id = str(ctx.author.id)
