@bot.command(name="dream", aliases=["hisdream", "yarndream", "whatdidyoudream"])
async def dream_cmd(ctx):
    """Describe Yarnaby's current dream, or - if he's awake - what he last dreamed about."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
