@bot.command(name="nap")
async def nap_cmd(ctx):
    """Tell Yarnaby to take a quick nap. (Different from the Creator's `!sleep` - this is just a short rest.)"""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*He's already asleep. He doesn't need a nap suggested at him.*",
                "*Already deep under. Wool slowly rising and falling. **prrr.***",
                "*He's out. The nap is in progress. **mrp.***",
            ])
        )
        return

    internal = m["internal"]
    nap_until_iso = internal.get("nap_until")
    now = datetime.now()
    if nap_until_iso:
        try:
            nap_until = datetime.strptime(nap_until_iso, "%Y-%m-%d %H:%M:%S")
            if nap_until > now:
                remaining = int((nap_until - now).total_seconds())
                await ctx.send(
                    random.choice([
                        f"*He's already napping. Curled up tight. **prrr.** Roughly {remaining}s left.*",
                        f"*Ongoing nap, do not disturb. ({remaining}s left.) **...mrr...***",
                        f"*He flicks one ear at the suggestion, but he's already mid-nap. ({remaining}s.) **prrt.***",
                    ])
                )
                return
        except ValueError:
            pass

    if not is_doctor:
        remaining = _cooldown_remaining(m, f"nap:{u_id}", 600)
        if remaining > 0:
            await ctx.send(
                random.choice([
                    f"*He just napped. He's not napping again that fast. Try in {remaining}s.*",
                    f"*Yarnaby blinks at you. He's awake. He intends to stay that way for a bit. ({remaining}s)*",
                    f"*A flat **mrr**. He just got up. Try in {remaining}s.*",
                ])
            )
            return
        _set_cooldown(m, f"nap:{u_id}")

    nap_minutes = random.randint(4, 9)
    nap_until = now + timedelta(minutes=nap_minutes)
    internal["nap_until"] = nap_until.strftime("%Y-%m-%d %H:%M:%S")

    # Mild restorative effects (smaller than full sleep)
    if "tiredness" in m["stats"]:
        m["stats"]["tiredness"] = max(0, m["stats"].get("tiredness", 0) - 3)
    m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 1)

    save_db(m)
    intro = random.choice([
        f"*Yarnaby curls up tight where he was standing. Wool tucked around himself. Eyes shut. **prrr.** A short nap. About {nap_minutes} minutes.*",
        f"*A long stretch, then he folds down into a small loaf. Tail wrapped neatly around his paws. **mrr.** He'll be up in roughly {nap_minutes} minutes.*",
        f"*He pads in a slow circle, finds the spot, and drops onto his side. Glass eyes shut. **prrt.** ~{nap_minutes}m of nap incoming.*",
        f"*Yarnaby tucks his nose under his tail. He is asleep almost immediately. **...prrr...** (~{nap_minutes}m.)*",
        f"*He yawns enormously, blinks slowly at you, and falls into a small wool puddle right there. **chrrp.** ~{nap_minutes}m.*",
    ])
    await ctx.send(intro)


@bot.command(name="bless")
async def bless_cmd(ctx, *, member_text: Optional[str] = None):
    """Have Yarnaby bestow chirpy approval on someone you mention."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    target = None
    if ctx.message.mentions:
        target = ctx.message.mentions[0]
    if target is None:
        await ctx.send("*He waits. He doesn't know who you mean. Try `!bless @user`.*")
        return
    if target.id == ctx.bot.user.id:
        await ctx.send("*Yarnaby blinks at you. He cannot bless himself. He is already blessed by default. **prrt.***")
        return

    if not is_doctor:
        remaining = _cooldown_remaining(m, f"bless:{u_id}", 180)
        if remaining > 0:
            await ctx.send(f"*He's already done a blessing recently. Wait {remaining}s.*")
            return
        _set_cooldown(m, f"bless:{u_id}")

        if m["internal"]["is_sleeping"]:
            await ctx.send("*He's asleep. The blessing is queued. He won't perform it until he wakes.*")
            return

    target_id = str(target.id)
    target_name = target.display_name
    target_score = m["social_matrix"].get(target_id, {}).get("score", 0)

    if target.id == DOCTOR_ID:
        await ctx.send(
            random.choice([
                f"*Yarnaby looks at The Creator. He doesn't even need to bless them - they are the source of all his blessings. He still does it. He pads to them, sits down at their feet, and chirps once, very seriously. **chrrp.***",
                f"*A long, slow blink at The Creator. **prrt.** That is the blessing. There is no greater one he can give.*",
                f"*Yarnaby presses his forehead against The Creator's wrist and stays there. The blessing is the touching. The chirp is just punctuation. **chrrp.***",
            ])
        )
        return

    if target_score >= 5:
        line = random.choice([
            f"*Yarnaby pads up to **{target_name}** without hesitation. He sits in front of them. He chirps, very deliberately - **chrrp!** - then bumps his forehead lightly against their hand. The blessing is given. They have his approval.*",
            f"*A clear, bright **chrrup** in **{target_name}**'s direction. Yarnaby twines briefly around their ankles and pads off again. They have been formally noted as good.*",
            f"*Yarnaby leaps onto whatever **{target_name}** is sitting on, walks across them, and chirps **prrt!** before settling beside them. He approves. He has approved for some time.*",
        ])
        if not is_doctor and _cooldown_remaining(m, f"bless_score:{target_id}", 86400) <= 0:
            entry = m["social_matrix"].setdefault(target_id, {"score": 0})
            entry["score"] = min(10, entry.get("score", 0) + 1)
            _set_cooldown(m, f"bless_score:{target_id}")
    elif target_score >= 0:
        line = random.choice([
            f"*Yarnaby considers **{target_name}** for a long moment. He pads two steps closer. He chirps, briefly - **chrrp.** - then sits at a polite distance. A modest blessing.*",
            f"*A small **prrt** in **{target_name}**'s direction. Yarnaby tips his head once. They are blessed in the lowercase sense. They've been seen.*",
            f"*Yarnaby blinks slowly at **{target_name}**. He doesn't move closer. He chirps, just the once. **chrp.** It will have to do.*",
        ])
    else:
        line = random.choice([
            f"*Yarnaby looks at **{target_name}**. He looks at you. He looks back at **{target_name}**. He turns and walks away. There will be no blessing today. **mrrp.***",
            f"*A flat stare in **{target_name}**'s direction. Wool slightly raised. Yarnaby does not chirp. He does not move closer. The blessing is denied.*",
            f"*Yarnaby pads halfway across the room toward **{target_name}**, stops, sniffs, and turns around. **brrt.** He won't do it.*",
        ])
    save_db(m)
    await ctx.send(line)


