@bot.command(name="weather")
async def weather_cmd(ctx, *, word: Optional[str] = None):
    """Yarnaby reacts to a weather word (or picks one at random)."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send("*He's asleep. The weather is doing what it's doing without him.*")
        return
    keys = list(WEATHER_REACTIONS.keys())
    chosen = None
    if word:
        wl = word.lower()
        for k in keys:
            if k in wl:
                chosen = k
                break
    if chosen is None:
        chosen = random.choice(keys)
    await ctx.send(random.choice(WEATHER_REACTIONS[chosen]))


