@bot.command(name="home", aliases=["gohome", "tohome"])
async def home_cmd(ctx, channel: discord.TextChannel = None):
    """Send Yarnaby to his home (the channel pinned with !set_home)."""
    m = bot.db
    await _add_reactions(ctx, m)
    home_id = m["internal"].get("home_channel_id")
    if not home_id:
        await ctx.send(
            random.choice([
                "*Yarnaby tilts his head. He doesn't have a home channel pinned yet. The Creator can fix that with `!set_home`. **mrr.***",
                "*A small, questioning **chrrp**. He has no home pinned. (`!set_home` in the channel that should be his.)*",
                "*He blinks at you. Home is not yet defined. **prrt.** (Use `!set_home`.)*",
            ])
        )
        return
        if m["internal"]["is_sleeping"]:
            await ctx.send("*He's already asleep - he likely is at home already. **prrr.***")
            return
        here_id = str(ctx.channel.id)
        if here_id == str(home_id):
            await ctx.send(
                random.choice([
                    "*Yarnaby looks around. He's already here. This is home. He sits down, satisfied. **prrr.***",
                    "*A flat **mrr**. He is, in fact, at home. He folds into a loaf to prove it.*",
                "*He blinks at you slowly. He is home. He has been the whole time. **prrt.***",
            ])
        )
        return
    await ctx.send(
        random.choice([
            "*Yarnaby pads off without a word. He is going home. **mrp.***",
            "*A small **chrrp** as he turns and trots in the direction of his home channel. He does not look back.*",
            "*He stretches once, shakes out his wool, and pads away toward home. **prrt.***",
        ])
    )
    await asyncio.sleep(2)
    home_chan = _resolve_messageable(bot, home_id)
    if home_chan:
        await home_chan.send(
            random.choice([
                "*Yarnaby arrives. He circles his spot once, twice - and folds himself down. He is home. **prrr.***",
                "*A soft **chrrp** as he pads in. He sits in his usual place. The wool settles around him. He is home.*",
                "*He pads in quietly, surveys the room, and claims his corner. Home. **mrr.***",
                "*Yarnaby trots in and immediately flops sideways onto his preferred spot. He is, by his own definition, home. **prrt.***",
            ])
        )


