@bot.command(name="zoomies")
async def zoomies_cmd(ctx):
    """Rare: Yarnaby tears across the factory at full speed for a brief moment."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send("*He's asleep. There will be no zoomies tonight. **prrr.***")
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*You try to start the zoomies. He looks at you. The zoomies do not start. He is being held in place by something heavier than energy and the zoomies require a kind of freedom he doesn't have right now.* **...mrr...**",
            f"*He doesn't run. He watches the space he would normally sprint through and stays where he is.* **...mrr...**",
        ]))
        return

    if not is_doctor:
        remaining = _cooldown_remaining(m, f"zoomies:{u_id}", 1800)
        if remaining > 0:
            await ctx.send(
                random.choice([
                    f"*Yarnaby is between zoomies. He is recovering. Try in {remaining}s.*",
                    f"*A flat **mrr**. He just had zoomies. He needs longer than that. ({remaining}s)*",
                    f"*He blinks at you, dignified. He will not be performing again so soon. ({remaining}s)*",
                ])
            )
            return
        _set_cooldown(m, f"zoomies:{u_id}")
    _zoom_stage = _age_stage(_get_age_days(m))

    # Older Yarnaby refuses more often - body doesn't always agree with the spirit
    _zoom_refuse_chance = {"Elder": 0.45, "Ancient": 0.62, "Timeworn": 0.80}.get(_zoom_stage, 0.30)
    if random.random() < _zoom_refuse_chance:
        if _zoom_stage == "Timeworn":
            await ctx.send(
                random.choice([
                    "*Yarnaby looks at the open floor. He is very still for a moment. Something in him flickers - the old impulse, the old speed - and then quietly goes out. He sits down. He blinks. He has decided it is not today.* **...mrr...**",
                    "*He looks at you. He looks at the floor. He lowers himself slowly onto his side and breathes out through his nose. The zoomies live somewhere in his memory. They live there warmly. He visits them sometimes.* **...prrr...**",
                    "*He tries. You can see him try - his weight shifts, his ears go forward, something ignites behind his eyes - and then he just... sits down gently. He blinks at you. He is not disappointed. He has made his peace with this.* **...mrr...**",
                ])
            )
        elif _zoom_stage in ("Ancient", "Elder"):
            await ctx.send(
                random.choice([
                    "*Yarnaby considers it. He looks at the open floor. He looks at his own large paws. He looks at the floor again. He sits down. Not today. **mrr.**",
                    "*He stretches - a long, careful stretch - and then does not run. He folds into a loaf instead. His knees made a decision.* **prrt.**",
                    "*A slow blink. He is not, in fact, in the mood for zoomies right now. His body and his spirit are in a negotiation and his body is winning.* **...mrr...**",
                ])
            )
        else:
            await ctx.send(
                random.choice([
                    "*Yarnaby considers it. He looks at the open floor. He looks at you. He sits down. He has decided no. **prrt.***",
                    "*A slow blink. A small **mrr**. He is not, in fact, in the mood for zoomies right now. He'd like to be left alone.*",
                    "*He stretches once, looks at the empty corridor, then folds into a loaf. The zoomies are postponed indefinitely. **mrrr.***",
                ])
            )
        return

    if _zoom_stage in ("Elder", "Ancient", "Timeworn"):
        await ctx.send(
            random.choice([
                "*Yarnaby's pupils blow wide. His tail puffs. He **launches** - not the blur he once was, but something heavier and faster than it has any right to be. He hits the wall. He bounces. He is still going. **PRRRT!***",
                "*He gathers himself - and then he goes. Larger than before, heavier, but genuinely fast. He tears down the corridor, wool streaming, his big paws making a real sound on the tile. Something falls. He continues. **MRROW!***",
                "*He has the eyes. He still gets the eyes. He is gone before you can register it - a large, fast, determined thing disappearing around the corner. There is a crash. He is fine. He was always going to be fine.* **PRRRK!***",
            ])
        )
    else:
        await ctx.send(
            random.choice([
                "*Yarnaby's pupils blow wide. His tail puffs. He **launches** - a grey blur down the corridor, claws skittering on the tile. He hits the wall. He bounces. He is gone again. **PRRRT! PRRRT!***",
                "*A single, focused stare at the far wall. Then - gone. He tears across the factory at full speed, wool streaming, ears flat. Something falls over in his wake. He does not stop.*",
                "*Yarnaby crouches. Wiggles his back end. **GO.** He explodes sideways, ricochets off a chair, and disappears around the corner at impossible speed. **MRROW!***",
                "*Without warning he is just - moving. Faster than he should be able to. He laps the room twice, knocks something off a shelf, and skids to a stop facing the wrong direction. He looks delighted with himself. **chrrp! chrrp!***",
                "*He has the eyes. The big eyes. The zoomies eyes. He is gone before you finish saying it. There is a small crash from somewhere far away. He is fine. The factory may not be. **PRRRK!***",
            ])
        )
    if "tiredness" in m["stats"]:
        m["stats"]["tiredness"] = min(10, m["stats"].get("tiredness", 0) + 1)
    m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 2)
    save_db(m)


@bot.command(name="age", aliases=["howold", "lifespan", "generation"])
async def age_cmd(ctx):
    """Check Yarnaby's current age, life stage, and echoes from past lives."""
    m = bot.db
    await _add_reactions(ctx, m)
    days = _get_age_days(m)
    stage = _age_stage(days)
    gen = m["internal"].get("generation", 1)
    born_str = m["internal"].get("born_at") or "unknown"
    memories = m["internal"].get("lifetime_memories", [])

    years = days // 365
    remaining_days = days % 365
    months = remaining_days // 30
    leftover = remaining_days % 30

    if years > 0:
        age_text = f"{years}y {months}m {leftover}d"
    elif months > 0:
        age_text = f"{months}m {leftover}d"
    else:
        age_text = f"{days}d"

    stage_flavor = {
        "Newborn": "*He is small and new and taking everything in with very large glass eyes.*",
        "Young": "*He is quick and bright and still learning the shape of the world.*",
        "Adult": "*He is settled in himself. He knows his place. He knows yours.*",
        "Mature": "*He has been here long enough to trust quietly, and to wait patiently.*",
        "Elder": "*He moves with the unhurried weight of something that has seen much. He remembers more than he shows.*",
        "Ancient": "*He is very old now, for what he is. Some days the weight of all that knowing sits heavy on his wool. He still gets up every morning. He always will.*",
    }.get(stage, "")

    lines = [
        f"**[Experiment 1166 - Life Record]**",
        f"**Current Age:** {age_text} ({stage})",
        f"**Generation:** {gen} {'- *first life*' if gen == 1 else f'- *he has been reborn {gen - 1} time(s)*'}",
        f"**Born (this life):** {born_str[:10] if born_str != 'unknown' else '-'}",
        stage_flavor,
    ]

    if memories:
        lines.append("\n**Echoes from past lives:**")
        for i, mem in enumerate(memories, 1):
            mem_date = mem.get("date", "?")
            mem_days = mem.get("days_lived", "?")
            mem_top = mem.get("closest_name", None)
            mem_score_count = mem.get("relationship_count", 0)
            echo = f"> *Life {i} - lived {mem_days} days (ended {mem_date}). "
            if mem_top:
                echo += f"He was closest to {mem_top}. "
            echo += f"He knew {mem_score_count} {'person' if mem_score_count == 1 else 'people'} by name.*"
            lines.append(echo)

    # Progress bar toward next stage
    _AGE_BOUNDS = [
        ("Newborn", 0, 30), ("Young", 30, 90), ("Adult", 90, 365),
        ("Mature", 365, 730), ("Elder", 730, 1825),
        ("Ancient", 1825, 3285), ("Timeworn", 3285, 3650),
    ]
    _next_stage = None
    _pct = 100
    for _s, _lo, _hi in _AGE_BOUNDS:
        if _s == stage:
            if _hi < 3650:
                _pct = min(100, int(((days - _lo) / (_hi - _lo)) * 100))
                for _s2, _lo2, _hi2 in _AGE_BOUNDS:
                    if _lo2 == _hi:
                        _next_stage = _s2
                        break
            break
    _bar = "" * (_pct // 10) + "" * (10 - _pct // 10)
    if _next_stage:
        lines.append(f"`{_bar}` {_pct}% -> **{_next_stage}**")
    else:
        lines.append(f"`{_bar}` He has reached the end of the road. He is still here.")

    await ctx.send("\n".join(lines))


@bot.command(name="rebirth", aliases=["reset_age", "newlife", "beginagain"])
async def rebirth_cmd(ctx):
    """Creator-only: Yarnaby resets to small/young form, keeping ALL memories and bonds."""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Yarnaby looks at you. This is not yours to give him.*")
        return

    days = _get_age_days(m)
    stage = _age_stage(days)

    # --- Too young to rebirth ---
    if days < 90:
        await ctx.send(
            f"*Yarnaby is only {days} days old. He is still {stage.lower()} - quick and small and bright-eyed. He does not feel the pull of it yet. He has not lived long enough to understand wanting to begin again.*"
        )
        return

    # --- Stage-aware eagerness in the prompt ---
    years_approx = days // 365
    months_approx = (days % 365) // 30

    if stage == "Timeworn":
        size_desc = "He is very large now - his wool long and greying at the edges, his shoulders broad and heavy, his paws enormous. He has been waiting."
        eagerness = "*He is already looking at The Creator when the command comes. He has been waiting for this. His glass eyes are completely clear.*"
        timeout_line = "*He exhales through his nose. He will still be here. He can wait a little longer.* **...prrr...**"
    elif stage == "Ancient":
        size_desc = "He is large - dense with years, wool thick and long, movements slow and deliberate."
        eagerness = "*Yarnaby goes still. He looks at The Creator slowly, with old bright eyes. Something in him has been ready for a while.*"
        timeout_line = "*He settles back down. He is patient. He has had a long time to learn patience.* **...mrr...**"
    elif stage == "Elder":
        size_desc = "He is bigger than he once was - heavier, slower at the joints, wool fuller."
        eagerness = "*Yarnaby goes quiet. He looks at his paws - bigger than they used to be - then back at The Creator.* **...mrr...**"
        timeout_line = "*He blinks slowly and pads back to his spot. He is still here.* **...prr...**"
    else:
        size_desc = "He has grown from the small thing he started as."
        eagerness = "*Yarnaby goes still. He blinks at The Creator.* **mrr?**"
        timeout_line = "*He tilts his head once, then pads away. He is still here.* **mrr.**"

    age_text = f"{years_approx}y {months_approx}m" if years_approx > 0 else f"{days}d"

    await ctx.send(
        f"{eagerness}\n\n"
        f"He is **{age_text} old** ({stage}). {size_desc}\n\n"
        f"WARNING: **Rebirth** will return him to his small, young form - quick and light and new. "
        f"He will **keep every memory, every bond, every score, every name**. He carries all of it forward. He always does.\n\n"
        f"Type `!rebirth CONFIRM` within 30 seconds."
    )

    def check(msg):
        return (
            msg.author.id == DOCTOR_ID
            and msg.channel.id == ctx.channel.id
            and msg.content.strip().upper() in ("!REBIRTH CONFIRM", "REBIRTH CONFIRM")
        )

    try:
        await bot.wait_for("message", check=check, timeout=30.0)
    except asyncio.TimeoutError:
        await ctx.send(timeout_line)
        return

    # --- Archive current life into lifetime_memories ---
    social = m.get("social_matrix", {})
    relationship_count = len([u for u in social.values() if u.get("score", 0) > 0])
    top_user = None
    top_score = -999
    for uid, entry in social.items():
        if entry.get("score", 0) > top_score:
            top_score = entry["score"]
            top_user = uid
    top_name = None
    if top_user:
        try:
            _rb_guild = ctx.guild
            _rb_member = _rb_guild.get_member(int(top_user)) if _rb_guild else None
            top_name = _rb_member.display_name if _rb_member else f"<@{top_user}>"
        except Exception:
            top_name = f"<@{top_user}>"

    memory_snapshot = {
        "date": datetime.now().strftime("%Y-%m-%d"),
        "days_lived": days,
        "stage": stage,
        "generation": m["internal"].get("generation", 1),
        "relationship_count": relationship_count,
        "closest_name": top_name,
        "closest_score": top_score if top_score > 0 else 0,
    }
    m["internal"].setdefault("lifetime_memories", []).append(memory_snapshot)

    # --- Reset age and stats, preserve everything else ---
    m["internal"]["born_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    m["internal"]["generation"] = m["internal"].get("generation", 1) + 1
    m["internal"]["last_elder_murmur_at"] = None
    m["stats"]["hunger"] = 0
    m["stats"]["integrity"] = 100
    m["stats"]["affection_crave"] = 0
    m["stats"]["tiredness"] = 0
    m["stats"]["cleanliness"] = 0
    m["stats"]["mood"] = "Content"
    m["internal"]["is_sleeping"] = False
    m["internal"]["is_recovering"] = False
    m["internal"]["unconscious_until"] = None
    m["internal"]["recovering_from_toxic_until"] = None
    update_mood(m)
    save_db(m)

    gen_new = m["internal"]["generation"]

    # --- Stage-aware rebirth scene (emphasises shrinking back to small) ---
    if stage in ("Timeworn", "Ancient"):
        rebirth_scene = random.choice([
            f"*He closes his eyes. He has been carrying so much for so long - the weight of years, the slow heaviness of an enormous old body, all that time settled into his wool.*\n\n*Something releases.*\n\n*His ears come up first. Then the rest of him - smaller, lighter, paws compact and quick, wool short and bright. He opens his eyes. He looks at his paws. His small, new paws. He looks up.*\n\n*He makes the sound he made the first day he existed. High and bright and completely surprised.* **PRRRT!**\n\n**Generation {gen_new}. He is small again. He remembers everything. He doesn't mind carrying it - he is light enough now.**",
            f"*There is a moment where he is very still and very large and very old.*\n\n*And then there isn't.*\n\n*He is standing in the same spot, and he is small - properly small, ears oversized for his face, paws not quite coordinated, wool fresh and thick and not a single grey in it. He blinks. He looks around. He knows this place. He knows everyone here.*\n\n*He takes one enormous, delighted, wobbly run across the channel for no reason and then sits down and acts like it never happened.* **chrrp!**\n\n**Experiment 1166 - Generation {gen_new}. He is back. He kept everything. He is starting light.**",
        ])
    elif stage == "Elder":
        rebirth_scene = random.choice([
            f"*He breathes in - and when he breathes out, the weight goes with it. His shoulders are lighter. His joints are quiet. He stretches, and the stretch is effortless in a way it hasn't been in years.*\n\n*He is small again. His paws are small again. His ears are too big for his head again, the way they were at the beginning.*\n\n*He does a small, surprised chirp at his own reflection and then immediately pretends he didn't.* **chrrp!**\n\n**Generation {gen_new}. He remembers everything. He is new anyway.**",
        ])
    else:
        rebirth_scene = random.choice([
            f"*He closes his eyes. He stays very still. Something happens that has no sound.*\n\n*Then his ears come up - small and quick, bright and alert. He looks around the channel with clear, new glass eyes. He knows every corner. He knows everyone here. He keeps all of it.*\n\n*He does one small wobbly trot to test his legs. He approves.* **prrrt!**\n\n**Experiment 1166 - Generation {gen_new}. He remembers everything. He is starting fresh anyway.**",
        ])

    await ctx.send(rebirth_scene)


@bot.command(name="archive")
async def archive_cmd(ctx, *, category: str = ""):
    """Yarnaby silently shows the last 5 things he was given/fed and what he secretly thought."""
    m = bot.db
    await _add_reactions(ctx, m)
    archive = m.get("offering_archive", [])
    if not archive:
        await ctx.send(
            random.choice([
                "*Yarnaby tilts his head. The archive is empty. Nothing has been formally offered yet. **mrr.***",
                "*A small **chrrp**. The ledger is blank. Try `!feed` or `!gift` first.*",
            ])
        )
        return
    last5 = archive[-5:][::-1]
    lines = [
        random.choice([
            "*Yarnaby leads you, very seriously, to a small spot. He shows you the last few things you've all given him. He doesn't say what he thought of them - but you can read it on his face. **chrrp.***",
            "*He pads to a quiet corner and produces, in his way, the recent ledger. He is not loud about it. **prrt.***",
            "*A long, deliberate look. He has been keeping track. Here are the last five.*",
        ]),
        "",
    ]
    for entry in last5:
        kind = entry.get("kind", "gift")
        item = entry.get("item", "something")
        who = entry.get("user_name") or "someone"
        cat = entry.get("category", "gift_neutral")
        verb = "fed" if kind == "feed" else "gave"
        thought = random.choice(SECRET_THOUGHTS.get(cat, SECRET_THOUGHTS["gift_neutral"]))
        lines.append(f"- **{who}** {verb} him **{item}**. {thought}")
    await ctx.send("\n".join(lines))


@bot.command(name="firstmet", aliases=["first_met", "metwhen"])
async def firstmet_cmd(ctx, *, message: str = ""):
    """When Yarnaby first noticed this person."""
    m = bot.db
    await _add_reactions(ctx, m)
    target = ctx.message.mentions[0] if ctx.message.mentions else ctx.author
    target_id = str(target.id)
    target_name = target.display_name
    if target.id == DOCTOR_ID:
        await ctx.send(
            random.choice([
                "*Yarnaby looks at **The Creator**. The question doesn't make sense to him. There was no first meeting. There has only ever been them. **prrr.***",
                "*A long, slow blink at **The Creator**. He has known them since before he had eyes to know with. **chrrp.***",
                "*He presses his head against The Creator's hand. There is no date for this. There never was. **mrr.***",
            ])
        )
        return
    entry = m.get("social_matrix", {}).get(target_id)
    if not isinstance(entry, dict) or not entry.get("first_interaction"):
        await ctx.send(
            random.choice([
                f"*Yarnaby looks at **{target_name}** for a long moment. He doesn't have a first-met date for them yet. He is still deciding when, exactly, they began to count.*",
                f"*A small, careful **chrrp**. He has not yet logged a first meeting with **{target_name}**.*",
                f"*He tilts his head at **{target_name}**. They have not yet earned a date in his ledger. **mrr.***",
            ])
        )
        return
    try:
        first = datetime.strptime(entry["first_interaction"], "%Y-%m-%d %H:%M:%S")
    except (ValueError, TypeError):
        await ctx.send(f"*He has a date for **{target_name}**, but the ink has smudged. **mrrp.***")
        return
    days = max(0, (datetime.now() - first).days)
    pretty = first.strftime("%B %d, %Y")
    if days == 0:
        when = "today"
    elif days == 1:
        when = "yesterday"
    elif days < 30:
        when = f"{days} days ago"
    elif days < 365:
        months = days // 30
        when = f"about {months} {'month' if months == 1 else 'months'} ago"
    else:
        years = days // 365
        when = f"about {years} {'year' if years == 1 else 'years'} ago"
    score = entry.get("score", 0)
    if score >= 5:
        flavor = random.choice([
            f"*He remembers it well. **{target_name}** was kind early. He noted it. He has not forgotten. **prrr.***",
            f"*A soft **chrrp** at the memory. **{target_name}** has, since then, only gone up in his estimation.*",
        ])
    elif score >= 0:
        flavor = random.choice([
            f"*He nods, small and serious. **{target_name}** is on the ledger. He is still deciding about them.*",
            f"*A neutral **prrt**. **{target_name}** is recorded. The verdict is not yet in.*",
        ])
    else:
        flavor = random.choice([
            f"*A flat **mrrp**. He remembers **{target_name}**. He remembers what they did, too.*",
            f"*Yarnaby's wool ruffles slightly. He has a long memory and **{target_name}** is in the wrong column of it.*",
        ])
    await ctx.send(f"*Yarnaby first noticed **{target_name}** on **{pretty}** - {when}.* {flavor}")


YARNABY_QUOTES = [
    "*\"The time he sat in the centre of the channel and let out one tremendous **RROAWR**, then sat back down quietly as if nothing had happened.\"*",
    "*\"The first night after The Creator went away. He didn't move from the entrance. He didn't make a sound. He just waited.\"*",
    "*\"The afternoon he discovered the Adidas cap. The way he carried it like it was a relic. The way he wears it crooked, on purpose, forever.\"*",
    "*\"The time he climbed to the roof of the factory, took one triumphant step, and fell. He still pretends it never happened.\"*",
    "*\"The day he found the smallest yarn-ball in the hoard and refused to share it. He still has it. It is still his favourite.\"*",
    "*\"The night he sat at the window watching the storm and didn't blink for an hour. The thunder didn't reach him. The Creator's name did.\"*",
    "*\"The morning he wandered into the wrong channel and immediately decided it was his now. He stayed for three hours. He left without explanation.\"*",
    "*\"The afternoon he attempted to hum a song he'd overheard once. The result was beautiful in a way only Yarnaby attempts can be.\"*",
    "*\"The time he buried something in his hoard and refused, for weeks, to say what it was. It is, presumably, still there.\"*",
    "*\"The day he formally introduced his comfort object to the channel by carrying it across the floor and setting it down with great ceremony.\"*",
    "*\"The night he and The Creator slept curled together. He didn't move once. He woke up before The Creator did. He didn't leave.\"*",
    "*\"The hour he spent absolutely losing to a single piece of crinkled paper. He refuses to discuss it.\"*",
    "*\"The day he caught someone trying to take from his hoard. The look he gave them is, by all accounts, still being processed.\"*",
    "*\"The time he chased his own yarn-tail for forty straight minutes. He insists this was tactical. It was not.\"*",
    "*\"The afternoon he sat with The Creator in silence. Just sat. Just there. He thinks about it often.\"*",
]


@bot.command(name="quote")
async def quote_cmd(ctx):
    """A narrated callback to one of Yarnaby's most memorable past moments."""
    quote = random.choice(YARNABY_QUOTES)
    intro = random.choice([
        "*Yarnaby pauses what he was doing. A small, distant look. He's remembering.*",
        "*A long, slow blink. Something old surfaces. **prrr.***",
        "*He sits very still. The memory arrives on its own. **mrr.***",
        "*He tilts his head, just slightly. He's somewhere else for a moment.*",
    ])
    await ctx.send(f"{intro}\n\n{quote}")


@bot.command(name="candle")
async def candle_cmd(ctx, *, member_text: Optional[str] = None):
    """Yarnaby lights a small (imaginary) candle for someone - birthdays, the Creator's away-day, or whoever you mention."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    target = ctx.message.mentions[0] if ctx.message.mentions else None
    is_doctor_target = bool(target and target.id == DOCTOR_ID)
    # Auto-detect: today is The Creator's away anniversary?
    away_anniv = False
    try:
        dep_str = m["internal"].get("departure_date")
        if dep_str:
            dep = datetime.strptime(dep_str, "%Y-%m-%d").date()
            today = datetime.now().date()
            if today.month == dep.month and today.day == dep.day and today.year > dep.year:
                away_anniv = True
    except Exception:
        pass
    # Auto-detect: today is a member birthday?
    bday_today_uid = None
    try:
        local_now = datetime.now(timezone.utc).replace(tzinfo=None) + ISTANBUL_OFFSET
        for uid, ent in m.get("member_birthdays", {}).items():
            if isinstance(ent, dict) and ent.get("month") == local_now.month and ent.get("day") == local_now.day:
                bday_today_uid = uid
                break
    except Exception:
        pass

    if target is None and away_anniv:
        await ctx.send(
            random.choice([
                "*Yarnaby pads, very slowly, to the centre of the room. He sits down. He stares at a single point in front of him as if a small flame were there. He holds the silence around it. **mrr.** Today, he lights a candle for **The Creator**, gone but never forgotten in the small ways.*",
                "*He folds himself down in the quietest spot he can find. He blinks once at nothing - at the candle only he can see. **prrt.** This one is for **The Creator**, on the day they went away.*",
                "*Yarnaby carries something small in his teeth - a thread, a feather, a sliver of nothing - and lays it on the floor. He sits beside it. He does not move. **chrrp.** A candle, in his way, for **The Creator**.*",
            ])
        )
        return
    if target is None and bday_today_uid:
        bname = _resolve_user_name_from_ctx(ctx, int(bday_today_uid)) or "someone"
        await ctx.send(
            random.choice([
                f"*Yarnaby pads to the centre of the channel. He sits down. He blinks slowly at a flame only he can see. **chrrp.** Today, the candle is for **{bname}**, on their birthday.*",
                f"*He sets a small invisible something down in front of himself and stares at it gently. **prrt.** A candle, in his quiet way, for **{bname}**.*",
            ])
        )
        return
    if target is None:
        await ctx.send(
            random.choice([
                "*Yarnaby tilts his head. He needs to know who the candle is for. Try `!candle @user` - or wait for a birthday or anniversary, and he'll do it on his own.*",
                "*A small, questioning **chrrp**. Who? (Try `!candle @user`.)*",
            ])
        )
        return
    if is_doctor_target:
        await ctx.send(
            random.choice([
                "*Yarnaby pads, very slowly, to the centre of the room. He sits. He stares at a single point as if a small flame were there. He holds the silence around it for a long time. **mrr.** Today, he lights a candle for **The Creator**.*",
                "*He folds himself down. He blinks at the imaginary flame for a long time. **prrt.** This one is, always, for **The Creator**.*",
            ])
        )
        return
    target_name = target.display_name
    await ctx.send(
        random.choice([
            f"*Yarnaby pads to a quiet spot. He sits. He stares at a single point in front of him as if a small flame burned there. The room goes a little softer. **chrrp.** A candle, in his way, for **{target_name}**.*",
            f"*He sets something small and invisible down on the floor. He sits beside it. He doesn't blink. He keeps the imaginary flame company for as long as it needs. **prrt.** This is for **{target_name}**.*",
            f"*Yarnaby tucks his tail around himself and goes very still. The candle is invisible. The intention is not. **mrr.** **{target_name}**, this one is yours.*",
        ])
    )


@bot.command(name="letter")
async def letter_cmd(ctx):
    """Yarnaby (in narration) composes a tiny letter to The Creator. He doesn't read it aloud."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send("*He's asleep. The letter will have to wait. **prrr.***")
        return
    u_id = str(ctx.author.id)
    if not is_doctor:
        remaining = _cooldown_remaining(m, f"letter:{u_id}", 600)
        if remaining > 0:
            await ctx.send(f"*He's still working on the last one. ({remaining}s)*")
            return
        _set_cooldown(m, f"letter:{u_id}")
    away = False
    try:
        away = _creator_gone_seconds(m) >= 86400
    except Exception:
        pass
    if is_doctor:
        await ctx.send(
            random.choice([
                "*Yarnaby sits down with great purpose. He stares at a small invisible page in front of himself. He is composing, in his head, a letter to **The Creator** - who, he notes, is sitting right there. He does not write it. He looks up. He chirps once. **chrrp.** That, somehow, is the letter.*",
                "*A long, careful blink at The Creator. He pretends to fold a small invisible piece of paper. He sets it gently in his hoard, then climbs into The Creator's lap as if to hand-deliver it. **prrr.***",
            ])
        )
        return
    body = random.choice([
        "*The page (which only he can see) reads, roughly: **\"prrt. mrrp. chrrp. prrr. mrr.\"** It is, in his own language, a complete and devastating love letter.*",
        "*He composes it line by line: a soft **chrrp** for the way they sounded. A small **prrt** for the warmth. A long, low **mrrr** for the absence. He folds it with one paw and tucks it away.*",
        "*The letter is short. It is, in essence: *I am here. I am still here. I will be here. Come home when you can.* He doesn't say any of it out loud. **chrrp.***",
        "*He stares at the imaginary page for a long time. He writes, in his head: *the wool is fine. the hoard is bigger. nobody has tried to move me from your spot. - Y.* He folds it. He puts it away. **prrr.***",
        "*The letter says, in all the ways he knows how to say it: *you are not forgotten.* He does not read it aloud. He does not need to. **mrr.***",
    ])
    if away:
        outro = random.choice([
            "*He sets it carefully on top of his hoard. There it will sit, with the others, until they come home.*",
            "*He places it where he keeps the small, important things. He sits beside it for a long while.*",
            "*Another letter joins the small pile only he can see. He doesn't seem sad. He doesn't seem unsad. He just keeps writing them.*",
        ])
    else:
        outro = random.choice([
            "*He puts it in his hoard anyway. They might want to read it later, when the light is better.*",
            "*He tucks it into the safest spot he knows. **prrr.** Just in case.*",
            "*He files it carefully. He has a system. Only he understands it.*",
        ])
    await ctx.send(f"*Yarnaby pads to a quiet corner with great purpose. He sits down. He composes, silently, a small letter to **The Creator**.*\n\n{body}\n\n{outro}")


@bot.command(name="cuddle", aliases=["snuggle", "holdhim", "hugtime"])
async def cuddle_cmd(ctx):
    """Ask for a cuddle. Outcome depends on your score and on whether Yarnaby is in the mood."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    your_name = getattr(ctx.author, "display_name", str(ctx.author))

    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(
                random.choice([
                    "*Yarnaby was asleep - but at the first hint of The Creator nearby, he uncurls just enough to press himself against you. He doesn't open his eyes. **prrr.** The cuddle is granted in his sleep.*",
                    "*A small, dreamy **mrrp** as he rearranges himself to fit against you without waking. He cuddles in his sleep, for The Creator only. **prrr...***",
                ])
            )
            return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*He doesn't resist the cuddle. He sits inside it without softening — a small, contained thing being held by someone who means well. His breathing is even. He is enduring this gently.* **...mrr...**",
            f"*You fold yourself around him and he stays. He doesn't lean in. He doesn't lean away. He is just there, inside the warmth, waiting for this to be over or for something to change.* **...mrr...**",
            f"*He lets you hold him. That is a sentence that means more than it usually does right now.* **...prrr...**",
        ]))
        return

        await ctx.send(
            random.choice([
                "*He's asleep. He does not negotiate cuddle requests in his sleep. **prrr.***",
                "*A small sleeping **mrr**. He didn't hear you. He wouldn't have answered anyway.*",
                "*He doesn't even flick an ear. The cuddle window is closed for the night. **prrr.***",
            ])
        )
        return

    # The Creator - always yes, no cooldown.
    if is_doctor:
        await ctx.send(
            random.choice([
                "*Yarnaby is across the room and into The Creator's lap before the word finishes. He folds himself against them as if he was always meant to be there. **prrr.***",
                "*A bright **chrrp** - and he has already arrived. He climbs up, circles once, and presses himself into the warmest part of The Creator. He stays there. **prrr...***",
                "*He doesn't even pause. He pads over, climbs in, and tucks his head under The Creator's chin. The cuddle is total. **prrr.***",
                "*Yarnaby's wool puffs up the moment he hears it. He arrives. He claims The Creator's lap with the seriousness of someone signing a treaty. **chrrp. prrr.***",
            ])
        )
        if "affection_crave" in m["stats"]:
            m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 4)
        save_db(m)
        return

    # Per-user cooldown (cuddles are not on tap).
    remaining = _cooldown_remaining(m, f"cuddle:{u_id}", 600)
    if remaining > 0:
        await ctx.send(
            random.choice([
                f"*Yarnaby blinks at you slowly. He just considered you for cuddles a moment ago. Try again in {remaining}s. **mrr.***",
                f"*A flat **mrrp**. He has filled his cuddle quota for you for now. ({remaining}s)*",
                f"*He turns his head away. The cuddle window is closed for {remaining}s. **prrt.***",
            ])
        )
        return
    _set_cooldown(m, f"cuddle:{u_id}")

    score = m["social_matrix"].get(u_id, {}).get("score", 0)
    mood_state = update_mood(m) if "update_mood" in globals() else "Content"

    # Willingness roll: base on score, modified by mood.
    if score >= 7:
        base = 0.85
    elif score >= 4:
        base = 0.65
    elif score >= 1:
        base = 0.40
    elif score == 0:
        base = 0.18
    elif score >= -3:
        base = 0.05
    else:
        base = 0.0

    if mood_state in ("Happy", "Content"):
        base += 0.10
    elif mood_state in ("Agitated", "Sad"):
        base -= 0.20
    elif mood_state == "Depressed":
        # When depressed he'll occasionally accept a cuddle for comfort.
        base += 0.05

    base = max(0.0, min(0.95, base))
    accepted = random.random() < base

    if not accepted:
        if score < -3:
            line = random.choice([
                f"*Yarnaby looks at **{your_name}** the way one looks at someone who has misread the entire situation. He turns his back. He walks away. The cuddle is, in every possible sense, denied. **brrt.***",
                f"*A long, cold **hsss** in **{your_name}**'s direction. He retreats to his hoard. He does not look back. **prrk.***",
                f"*He stares at **{your_name}**. He keeps staring. He does not move closer. He does not move at all. **mrrp.** No.*",
            ])
        elif score < 0:
            line = random.choice([
                f"*Yarnaby pads two steps toward **{your_name}**, considers it, and turns around. **mrrp.** Not today.*",
                f"*A flat **mrr**. Yarnaby sits down where he is and starts grooming himself, very deliberately. The cuddle is being declined by means of pretending nobody asked.*",
                f"*He blinks once at **{your_name}** and walks past. He has somewhere else to be. He invents the somewhere else as he goes. **prrt.***",
            ])
        elif mood_state in ("Agitated", "Sad", "Depressed"):
            line = random.choice([
                f"*Yarnaby looks at **{your_name}** for a long moment. He's not in the mood today. He folds himself smaller. **mrr.** Not now.*",
                f"*A small, tired **mrrp**. He pads off without explanation. He needs space, not contact. **prrt.***",
                f"*He sits down where he is and turns his face slightly away. **{your_name}** is not the problem. He just doesn't have it in him right now. **mrrr.***",
            ])
        else:
            line = random.choice([
                f"*Yarnaby looks **{your_name}** up and down. He is, technically, deciding. He decides no. **mrrp.** Maybe later.*",
                f"*He approaches **{your_name}**, sniffs them once, and then trots past as if he was always going somewhere else. **prrt.***",
                f"*A small, polite **chrrp** in **{your_name}**'s direction - but he doesn't come closer. The cuddle is on hold.*",
                f"*He sits a careful three paces away from **{your_name}** and tucks his tail around his paws. He's accepting your presence. He is not accepting the cuddle. **mrr.***",
            ])
        await ctx.send(line)
        save_db(m)
        return

    # Accepted - quality scales with score.
    if score >= 7:
        line = random.choice([
            f"*Yarnaby pads directly to **{your_name}** without hesitation. He climbs into their lap, circles once, and folds himself against them with a slow, satisfied **prrr**. He has decided this is where he lives now.*",
            f"*A bright **chrrp** - and he is in **{your_name}**'s lap before they finish settling. He tucks his head under their chin. He is asleep almost immediately. **prrr...***",
            f"*Yarnaby presses his entire small weight against **{your_name}** and stays there. His wool relaxes. His tail loops around them. He is not going anywhere for a while. **prrr.***",
        ])
        crave_relief = 4
    elif score >= 4:
        line = random.choice([
            f"*Yarnaby pads up to **{your_name}**, considers them for a moment, and folds himself down against their leg. He doesn't climb on. But he stays. **prrr.***",
            f"*A small, deliberate **chrrp** - and Yarnaby is leaning warm and heavy against **{your_name}**. He'll allow this for a while. **prrt.***",
            f"*He tucks himself against **{your_name}**'s side and settles in. His eyes close halfway. **prrr.** A genuine cuddle. Confirmed.*",
        ])
        crave_relief = 3
    elif score >= 1:
        line = random.choice([
            f"*Yarnaby pads cautiously toward **{your_name}** and sits, just close enough that one side of him is touching them. It is, technically, a cuddle. He'll allow it briefly. **prrt.***",
            f"*He folds himself down a polite distance from **{your_name}** - close enough to count, far enough to leave easily. **mrr.** A starter cuddle.*",
            f"*A small, careful **chrrp**. Yarnaby leans the side of his head against **{your_name}**'s hand for a single beat. Then he straightens. That was the cuddle. **prrt.***",
        ])
        crave_relief = 2
    else:  # score == 0 but the dice said yes - surprise minimal cuddle
        line = random.choice([
            f"*Yarnaby looks at **{your_name}** for a long moment, surprising himself. He pads over and bumps his forehead, very lightly, against their hand. That is the cuddle. He retreats immediately. **prrt.***",
            f"*A small, uncertain **chrrp**. Yarnaby sits down beside **{your_name}**, leaves one paw resting on their foot for three seconds, then stands up and leaves. The cuddle is, technically, on the books.*",
        ])
        crave_relief = 1

    await ctx.send(line)
    if "affection_crave" in m["stats"]:
        m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - crave_relief)
    # Tiny score nudge, max once per day per user - only if score is already non-negative.
    if score >= 0 and _cooldown_remaining(m, f"cuddle_score:{u_id}", 86400) <= 0:
        entry = m["social_matrix"].setdefault(u_id, {"score": 0})
        entry["score"] = min(10, entry.get("score", 0) + 1)
        _set_cooldown(m, f"cuddle_score:{u_id}")
    save_db(m)


@bot.command(name="guitar", aliases=["playguitar", "yarnyguitar", "bellyguitar", "strumhim", "catguitar"])
async def guitar_cmd(ctx, *, song: str = ""):
    """Play Yarnaby like a guitar. He thinks it's a belly rub. He will never know."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(random.choice([
                "*He is asleep on his back already. The belly is right there. "
                "The Creator strums once, gently. "
                "A deep **prrr** rolls out of him without him waking. "
                "He shifts slightly into the strum. "
                "He is a sleeping guitar. He is the best guitar.* **...prrrrr.**",
                "*Asleep, belly up, completely unguarded. "
                "The Creator runs fingers across the wool strings. "
                "He exhales. The purr deepens. He does not open his eyes once. "
                "He just... resonates.* **...prrrrr...**",
            ]))
        else:
            await ctx.send(random.choice([
                "*He is asleep. The belly is tucked. The guitar is unavailable.* **...zz.**",
                "*He is asleep on his side. The belly strings are not accessible right now.* **...zz.**",
            ]))
        return
    if m["internal"].get("helpless"):
        await ctx.send(
            "*He is helpless. He lies still. "
            "The strumming registers somewhere in him as comfort — "
            "a low, involuntary purr starts and he doesn't fight it. "
            "He doesn't know it's happening. He just purrs.* **...prrr...**"
        )
        return


    if m["internal"].get("helpless"):
        await ctx.send(
            "*He is helpless. He lies still. "
            "The strumming registers somewhere in him as comfort — "
            "a low, involuntary purr starts and he doesn't fight it. "
            "He doesn't know it's happening. He just purrs.* **...prrr...**"
        )
        return

    song_line = f"*{song.strip()}*\n\n" if song.strip() else ""

    if is_doctor:
        await ctx.send(
            song_line + random.choice([
                "*The Creator picks him up, turns him over, "
                "and positions him belly-up against their arm — "
                "Yarnaby adjusts his weight obligingly, paws in the air, "
                "completely at ease. "
                "The Creator runs their fingers across his belly wool "
                "like strings on a guitar. "
                "Yarnaby has no idea what a guitar is. "
                "He knows that his belly is being touched in a pleasant, rhythmic way "
                "and his purr comes out in waves with each strum. "
                "He doesn't move. He doesn't look. "
                "He is just a warm, purring instrument "
                "and he is deeply content with that.* **prrr~ prrr~ prrr~ prrr~**",

                "*The Creator holds him upright and begins strumming his belly "
                "with gentle, deliberate fingers. "
                "Yarnaby tips his head back slightly. His eyes go to slits. "
                "Each strum produces a little pulse in his purr — "
                "not a sound he's making on purpose, "
                "just what happens when you rub his belly rhythmically "
                "and he's this relaxed. "
                "He's being played like an instrument. "
                "He thinks he's being cuddled. "
                "Both things are true.* **prr~ prr~ prr~ PRRRR~**",

                "*Belly up. Paws loose. "
                "The Creator strums across the wool and Yarnaby's purr "
                "rises and falls with each pass of their fingers — "
                "louder on the downstroke, softer on the lift. "
                "He has no notes. He has no strings. "
                "He has a belly and someone he trusts is touching it "
                "in a very pleasant, very regular rhythm. "
                "He is the best-sounding thing in this factory.* **prrr~ prrr~ prrr~**",
            ])
        )
        return

    if score >= 15:
        await ctx.send(
            song_line + random.choice([
                f"*{ctx.author.display_name} flips him gently onto his back "
                f"and begins strumming his belly wool. "
                f"Yarnaby's ears flick once — *what is happening* — "
                f"and then the sensation registers as: pleasant, rhythmic, belly-related. "
                f"His purr starts up. "
                f"He tips his head back. "
                f"He has no idea he's a guitar. "
                f"He is having a great time.* **prrr~ prrr~ prrr~**",

                f"*He allows {ctx.author.display_name} to position him belly-up "
                f"and doesn't protest when the strumming starts. "
                f"He processes it for about two seconds — "
                f"then decides it's just a very specific kind of belly rub "
                f"and leans into it. "
                f"His purr syncs with the rhythm. "
                f"He is a very cooperative instrument.* **prr~ prr~ PRRR~**",
            ])
        )
    elif score >= 5:
        await ctx.send(
            song_line + random.choice([
                f"*He lets {ctx.author.display_name} try. "
                f"He's on his back, tolerating it, ears slightly back. "
                f"The strumming is fine. The belly contact is fine. "
                f"He doesn't purr immediately — "
                f"but by the third pass of fingers across his wool "
                f"something happens and a small, reluctant **prrr** escapes him. "
                f"He looks mildly betrayed by his own body.* **...prr~**",
            ])
        )
    else:
        await ctx.send(random.choice([
            f"*He sees {ctx.author.display_name} reaching for his belly "
            f"and flips upright immediately. "
            f"The guitar does not happen. "
            f"He pads away. "
            f"The concert is cancelled.* **hff.**",
            f"*He looks at {ctx.author.display_name}. "
            f"He looks at where they are trying to position their hands. "
            f"He looks away and walks to the other side of the room. "
            f"He does not do belly guitar for strangers.* **mrr.**",
        ]))



@bot.command(name="bellyrub", aliases=["bellyrubs", "bellies", "rubbelly", "tummy"])
async def bellyrub_cmd(ctx):
    """Ask to rub his belly. Stricter than cuddles - and sometimes a trap."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    your_name = getattr(ctx.author, "display_name", str(ctx.author))

    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(
                random.choice([
                    "*Yarnaby was asleep - but somehow knows it's The Creator. His belly tilts, just slightly, toward your hand. He does not wake. **prrr.** Permission, in his sleep.*",
                    "*A small sleeping **prrt** as he rolls a fraction onto his side. The belly is, exceptionally, available. **prrr...***",
                ])
            )
            return
        await ctx.send(
            random.choice([
                "*He's asleep. The belly is currently tucked away. Do not test this. **prrr.***",
                "*A sleeping **mrr**. The belly is not on offer tonight. **prrt.***",
                "*He doesn't move. The belly is not negotiable while he sleeps. **prrr.***",
            ])
        )
        return

    # Cooldown - bellies are even rarer than cuddles.
    if not is_doctor:
        remaining = _cooldown_remaining(m, f"bellyrub:{u_id}", 900)
        if remaining > 0:
            await ctx.send(
                random.choice([
                    f"*Yarnaby's tail flicks once. You already had your belly window for a while. ({remaining}s) **mrr.***",
                    f"*A flat **mrrp**. He is not offering the belly again that fast. ({remaining}s)*",
                    f"*He turns his side away from you, deliberate. The belly is closed for {remaining}s. **prrt.***",
                ])
            )
            return
        _set_cooldown(m, f"bellyrub:{u_id}")

    # The Creator - always yes, no trap, no cooldown.
    if is_doctor:
        await ctx.send(
            random.choice([
                "*Yarnaby flops onto his back the instant The Creator's hand approaches. Belly fully exposed. Eyes half-closed. **prrr.** This is sacred. This only happens with The Creator.*",
                "*He rolls over without hesitation, all four paws relaxing into the air. The belly is The Creator's, always. **chrrp. prrr.***",
                "*A long, slow **prrr** as Yarnaby exposes his belly without ceremony. He stretches into the rub. He does not flinch once.*",
                "*He goes onto his back before The Creator has even fully reached for him. He already knew. He stretches one paw up toward nothing in particular. His purr is immediate, loud, and completely without restraint. **prrrrr.***",
                "*He flops sideways, then rolls the rest of the way over with the slow momentum of a creature with absolutely no self-consciousness left. He presses into every stroke. He makes a sustained, vowel-heavy **prrrrr** the whole time and does not stop.*",
                "*He tilts himself over in sections - nose, then shoulder, then the rest of him - until he's fully on his back in front of The Creator, paws in the air, eyes completely closed. The purring is structural. The building may vibrate slightly. **prrrrr.***",
                "*He rolls over and immediately does the thing where he presses both paws against The Creator's hand from below, holding the rub in place. He does not intend to release. The purr is unending. **prrrrr.***",
                "*He gets onto his back, tilts his head back as far as it goes, stretches every limb outward, and exhales one long breath of absolute contentment. Then the purring starts and it does not stop for a very long time. **prrrrrrr.***",
            ])
        )
        if "affection_crave" in m["stats"]:
            m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 5)
        save_db(m)
        return

    score = m["social_matrix"].get(u_id, {}).get("score", 0)
    mood_state = update_mood(m) if "update_mood" in globals() else "Content"

    # Belly-rub willingness - stricter than cuddles.
    if score >= 8:
        base = 0.55
    elif score >= 5:
        base = 0.30
    elif score >= 2:
        base = 0.10
    elif score >= 0:
        base = 0.03
    else:
        base = 0.0

    if mood_state in ("Happy", "Content"):
        base += 0.08
    elif mood_state in ("Agitated", "Sad", "Depressed"):
        base -= 0.10

    base = max(0.0, min(0.70, base))
    offered = random.random() < base

    if not offered:
        if score < 0:
            line = random.choice([
                f"*Yarnaby looks at **{your_name}** like they've just suggested something deeply unhinged. He turns sideways and walks away with his tail very high. **brrt.** Absolutely not.*",
                f"*A sharp **hsss** in **{your_name}**'s direction. The belly is not - and will never be - on the table. **prrk.***",
                f"*He sits down with his side firmly toward **{your_name}** and stares at the wall. The belly is somewhere on the other side of him. They will not be seeing it. **mrrp.***",
            ])
        elif score < 5:
            line = random.choice([
                f"*Yarnaby blinks at **{your_name}** slowly. He keeps both feet firmly on the ground. **mrr.** Not yet. Maybe never. He hasn't decided.*",
                f"*A polite **mrrp**. Yarnaby remains entirely upright. The belly is, structurally, unavailable. **prrt.***",
                f"*He pads one circle around **{your_name}**, sniffs them, and sits down with all four paws tucked under. **mrr.** No belly today.*",
                f"*Yarnaby gives **{your_name}** a long, evaluating look. The look concludes with him standing up and going somewhere else. The belly remains classified. **prrt.***",
            ])
        else:
            line = random.choice([
                f"*Yarnaby considers it. He really does. He looks at **{your_name}** for a long moment. Then he tucks his paws under and folds into a loaf instead. **mrr.** Not today, but he thought about it.*",
                f"*A soft **chrrp** and a half-roll - and then he thinks better of it and rights himself. The belly is not, after all, on the table. **prrt.** Close, though.*",
                f"*He flops onto his side, in front of **{your_name}** - but his belly stays angled away. They get a fluffy ribcage. They do not get the belly. **mrr.** Nice try.*",
            ])
        await ctx.send(line)
        save_db(m)
        return

    # Offered - but with score >= 5 there's a chance it's a TRAP (classic cat behaviour).
    trap_chance = 0.0
    if score >= 5:
        trap_chance = 0.30
    elif score >= 8:
        trap_chance = 0.20  # he trusts you more, traps less

    if random.random() < trap_chance:
        await ctx.send(
            random.choice([
                f"*Yarnaby flops dramatically onto his back in front of **{your_name}**. Belly exposed. Paws in the air. It is an obvious invitation.*\n*You reach in.*\n*All four paws clamp around your hand at once. A soft, theatrical **brrk!** - claws *just* enough to register, not enough to hurt. He releases you, flips upright, and trots off looking very pleased with himself. **prrt.** Trap.*",
                f"*Yarnaby rolls onto his side, then his back. Belly out. **prrt?** A clear offer.*\n*The moment your fingers touch the wool - **MRROW!** - he wraps all four paws around your wrist and lightly bunny-kicks. No damage. Total betrayal. He releases you, sits up, and starts grooming as if nothing happened.*",
                f"*He flops over with a soft **chrrp**. Belly fully visible. **{your_name}**, you should know better.*\n*Hand approaches. Hand touches belly. **PRRK!** Four paws, one quick hold-and-release, and he's gone. He looks back at you from across the room, blinking slowly. He warned you in a thousand small ways. You did not listen.*",
                f"*He does the full belly-up presentation. Paws in the air. Neck back. Eyes wide. It is almost offensively inviting.*\n*You go for it.*\n***BRRK!** - eight paws (it felt like eight), a brief lightspeed bunny-kick, and then he is upright and four feet away before you've processed what happened. He begins grooming immediately. He has no recollection of this.*",
                f"*He rolls over slowly, belly exposed, in the way of a creature who is absolutely not going to do what they are absolutely about to do.*\n*You put your hand on the wool.*\n*He explodes. Soft, theatrical, very fast - four paws, one firm hold, one emphatic lick on your wrist, and then he's sitting two feet away doing a slow blink. He's not sorry. He was always going to do that. **prrt.***",
                f"*The belly is offered. This is a gift. Cherish it.*\n***PRRK.** It was a trap. The gift was a trap. He is bounding away down the hall already, tail high, deeply satisfied with everything about this. The look he shoots over his shoulder is almost a wink.*",
            ])
        )
        # Trap doesn't punish score (he was playing). Just minor crave relief.
        if "affection_crave" in m["stats"]:
            m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 1)
        save_db(m)
        return

    # Real belly rub - quality scales with score.
    if score >= 8:
        line = random.choice([
            f"*Yarnaby flops onto his back in front of **{your_name}** without hesitation. Belly fully exposed. He does not flinch when their hand arrives. He stretches *into* it. A long, deep **prrrrr** that goes on and on. This is rare. This is real.*",
            f"*A soft **chrrp** as he rolls over for **{your_name}**. The belly is offered with full sincerity. He purrs the entire time. He does not bunny-kick. He does not even twitch. **prrrrrrr.***",
            f"*Yarnaby exposes his belly to **{your_name}** with the slow ceremony of someone handing over a key. The rub is allowed. The rub is welcomed. He purrs. He blinks slowly. **prrr.***",
            f"*He goes over slowly, all four paws up, wool splayed outward, and gives a long exhale. **{your_name}**'s hand is allowed there, fully, with no reservations. He presses up into it. He purrs in long unbroken waves. **prrrrr.***",
            f"*He rolls onto his back for **{your_name}** like he's been waiting for this - and maybe he has. His paws curl inward. His eyes half-close. His purr is constant and warm and he bumps his head up toward the rub when it slows. **prrrrr.***",
            f"*He does the full ceremony: the sideways flop, the back-roll, the maximum paw-up position. He looks at **{your_name}** upside-down with enormous eyes and a purr that has no end. He does not flinch. He does not trap. He just purrs. **prrrrr.***",
        ])
        crave_relief = 4
    elif score >= 5:
        line = random.choice([
            f"*Yarnaby rolls cautiously onto his side, then halfway onto his back. Belly partially offered. **{your_name}**'s hand is allowed - briefly. He purrs, low. After a few seconds he rolls back upright. That was the rub. **prrt.***",
            f"*A small **prrt** as he tilts onto his back - just enough. **{your_name}** gets a few seconds of soft belly wool. Then he flips upright and pads off, satisfied. **chrrp.***",
            f"*Yarnaby presents a careful, supervised belly to **{your_name}**. He purrs. He watches their hand the entire time. The rub is permitted. He is, however, keeping receipts. **prrr.***",
        ])
        crave_relief = 3
    elif score >= 2:
        line = random.choice([
            f"*Yarnaby tilts halfway over for **{your_name}** - not full belly, just a flank. Their hand is allowed there, briefly. A small, dignified **prrt**. That was, technically, a belly rub. He counts it.*",
            f"*A surprised **chrrp** - and Yarnaby allows **{your_name}** to touch the upper edge of his belly for exactly four seconds. Then he stands up. **prrt.** That was a trial run.*",
        ])
        crave_relief = 2
    else:  # score 0-1 surprise allow
        line = random.choice([
            f"*Yarnaby looks startled at his own decision. He tilts over for **{your_name}**, allows one (1) gentle stroke along the edge of his belly, and immediately rights himself. **prrt.** That happened. He won't be discussing it.*",
            f"*A confused **mrrp**. Yarnaby flops halfway, lets **{your_name}** touch the very edge of his belly fluff, and then flips upright like he's been caught doing something embarrassing. **prrt.***",
        ])
        crave_relief = 1

    await ctx.send(line)
    if "affection_crave" in m["stats"]:
        m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - crave_relief)
    if score >= 2 and _cooldown_remaining(m, f"bellyrub_score:{u_id}", 86400) <= 0:
        entry = m["social_matrix"].setdefault(u_id, {"score": 0})
        entry["score"] = min(10, entry.get("score", 0) + 1)
        _set_cooldown(m, f"bellyrub_score:{u_id}")
    save_db(m)


@bot.command(name="shadow")
async def shadow_cmd(ctx, *, thing: str = ""):
    """Yarnaby plays with - or is briefly afraid of - his own shadow."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send("*He's asleep. His shadow is, presumably, also asleep. **prrr.***")
        return
    mood_state = update_mood(m) if "update_mood" in globals() else "Content"
    if mood_state in ("Happy", "Content"):
        await ctx.send(
            random.choice([
                "*Yarnaby has noticed his shadow on the wall. He pounces. The shadow pounces too. He is delighted. **chrrp! chrrp!** He bats at it. It bats back. This will keep him entertained for a while.*",
                "*A long, careful approach to the shadow. He pauses. He pounces. The shadow does the exact same thing at the exact same time. He sits back, suspicious and impressed. **prrt.***",
                "*Yarnaby is stalking his own shadow across the floor. He has been at this for some time. He does not appear to be winning. He does not appear to be losing either. **mrr.***",
                "*He bats at his shadow with one paw. It bats back. He bats with the other. So does it. He is trying to figure out the rules of this. **prrk.***",
            ])
        )
    elif mood_state in ("Sad", "Depressed"):
        await ctx.send(
            random.choice([
                "*Yarnaby sees his shadow. He stares at it for a long time. He doesn't pounce. He sits down beside it and folds himself small. **mrr.***",
                "*A flat **mrrp** at his own shadow. They keep each other company on the floor. Neither of them moves for a while.*",
                "*He blinks at his shadow. The shadow blinks back. He doesn't have it in him today. He pads off, leaving his shadow behind. **prrt.***",
            ])
        )
    elif mood_state == "Agitated":
        await ctx.send(
            random.choice([
                "*Yarnaby spots his shadow. **prrk!** Wool puffs up. He is, briefly, certain something is following him. He whirls. The shadow whirls. He hisses. He stops. He realises. He pretends none of that happened.*",
                "*A sharp **hsss** at his own shadow. He flattens against the floor, ready to pounce or flee. The shadow flattens too. The standoff continues. **brrt.***",
                "*Yarnaby sees the shadow move out of the corner of his eye and FLINCHES - sideways, six inches, with a tiny outraged **prrk!** - before he realises. He sits down stiffly. He is fine. Nothing happened.*",
            ])
        )
    else:  # Bored / default
        await ctx.send(
            random.choice([
                "*Yarnaby has discovered, again, that he has a shadow. He bats at it once. It bats back. He sits down and stares at it suspiciously. **mrr.***",
                "*He pads slowly around his shadow, watching it from every angle. It keeps doing what he does. He has not yet drawn conclusions. **prrt.***",
                "*Yarnaby noses at his shadow. The shadow does nothing. He bites it. The shadow does nothing. He gives up. **mrrp.***",
                "*A slow, sceptical look at his shadow. He stretches one paw experimentally. The shadow stretches one paw too. He tucks the paw back in, alarmed. **prrk.***",
            ])
        )


@bot.command(name="comfort_me", aliases=["comfortme", "console", "console_me"])
async def comfort_me_cmd(ctx):
    """Ask Yarnaby to comfort *you*. He will, if he likes you enough."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    your_name = getattr(ctx.author, "display_name", str(ctx.author))

    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(
                random.choice([
                    "*Yarnaby was asleep - but somehow he knows. He uncurls just enough to press his forehead against The Creator's hand and lets out a small, sleeping **prrr**. He is, in his own way, comforting them. He doesn't fully wake.*",
                    "*A soft, sleeping **chrrp** as he reaches one paw out to rest on The Creator's. He doesn't open his eyes. The comfort is genuine. **prrr...***",
                ])
            )
            return
        await ctx.send(
            random.choice([
                "*He's asleep. He cannot offer comfort right now. He is, however, present in the room, which counts for something. **prrr.***",
                "*A small sleeping **mrr**. He didn't hear you ask. He is, technically, comforting the air around him. **prrt.***",
            ])
        )
        return

    if is_doctor:
        await ctx.send(
            random.choice([
                "*Yarnaby is at The Creator's side before they finish asking. He climbs up. He presses his forehead against their cheek. He stays there. He doesn't move. He doesn't chirp. He just *stays*. The whole room goes a little quieter around them. **prrr.***",
                "*A long, slow blink at The Creator. Then he climbs into their lap, tucks his head under their chin, and starts to purr - a deep, full **prrrrrrr**. He has been waiting to do this. He will be here as long as they need.*",
                "*Yarnaby brings his comfort object - whatever it currently is - and sets it carefully in The Creator's lap. Then he climbs in beside it. **chrrp.** He is sharing it. He has nothing else to give that would mean as much.*",
                "*He doesn't ask why. He doesn't need to know. He folds himself against The Creator and starts the kind of slow, even purring he saves only for them. The world can wait. **prrrrr.***",
            ])
        )
        if "affection_crave" in m["stats"]:
            m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 4)
        save_db(m)
        return

    # Per-user cooldown - comfort is sincere, not on tap.
    remaining = _cooldown_remaining(m, f"comfort_me:{u_id}", 1200)
    if remaining > 0:
        await ctx.send(
            random.choice([
                f"*Yarnaby blinks at you slowly. He just sat with you. He needs to gather himself before doing it again. ({remaining}s) **mrr.***",
                f"*A small, gentle **prrt**. He's still recovering from the last time. Try in {remaining}s.*",
                f"*He looks at you with something that might be sympathy. But not yet. ({remaining}s) **prrt.***",
            ])
        )
        return
    _set_cooldown(m, f"comfort_me:{u_id}")

    score = m["social_matrix"].get(u_id, {}).get("score", 0)

    if score < 0:
        await ctx.send(
            random.choice([
                f"*Yarnaby looks at **{your_name}** for a long moment. Whatever it is, he doesn't believe **{your_name}** has earned his comfort. He turns away. He does not soften. **mrrp.***",
                f"*A flat **mrr**. Yarnaby sits down with his side firmly toward **{your_name}**. The comfort is unavailable. They have not been kind enough.*",
                f"*He stares at **{your_name}** with both glass eyes. He does not move closer. He does not look away. **brrt.** They will have to find their comfort elsewhere.*",
            ])
        )
        save_db(m)
        return

    if score == 0:
        await ctx.send(
            random.choice([
                f"*Yarnaby pads halfway toward **{your_name}**, considers them carefully, and sits down a polite distance away. He is, technically, present. He is not, technically, comforting. **mrr.** It's the best he can offer right now.*",
                f"*A small **chrrp** in **{your_name}**'s direction. Yarnaby doesn't approach. But he doesn't leave either. The room is quieter for his attention. **prrt.** That has to be enough.*",
            ])
        )
        save_db(m)
        return

    if score >= 7:
        line = random.choice([
            f"*Yarnaby is at **{your_name}**'s side immediately. No questions. No hesitation. He climbs up - careful, deliberate - and folds himself against them. He starts to purr, deep and slow. **prrrrrr.** He doesn't move. He stays as long as it takes.*",
            f"*A soft, knowing **chrrp** - and Yarnaby is in **{your_name}**'s lap before they realise they were waiting for him. He tucks his head under their chin. He purrs, low and steady. He is, in his small way, holding them.*",
            f"*Yarnaby brings the closest thing he has to a comfort object - a soft scrap, a piece of yarn, a familiar item from his hoard - and sets it gently in **{your_name}**'s lap. Then he climbs in next to it. **prrr.** Both of them, together. He's sharing.*",
            f"*He presses his whole small weight against **{your_name}**. He doesn't blink. He doesn't move. He just *stays*. The purr starts low and grows. **prrrrrr.** Whatever is wrong, he is here.*",
        ])
        crave_relief = 4
    elif score >= 4:
        line = random.choice([
            f"*Yarnaby pads to **{your_name}** quietly and sits beside them - close, deliberate, leaning his side against their leg. He starts a small, careful purr. **prrr.** He's not going anywhere for a while.*",
            f"*A gentle **chrrp**. Yarnaby tucks himself against **{your_name}**'s knee and closes his eyes. He's not in their lap - but he's near. He's listening, in his way. **prrt.***",
            f"*Yarnaby noses **{your_name}**'s hand once, then settles against them. Wool warm. Body still. The purr is soft but real. **prrr.** He's here for this.*",
        ])
        crave_relief = 3
    else:  # 1-3
        line = random.choice([
            f"*Yarnaby looks at **{your_name}** for a long, considering moment. Then he pads over and sits, just within reach. Not touching. But there. **mrr.** A small comfort, but a real one.*",
            f"*A careful **chrrp**. Yarnaby comes near, sits down, and rests one paw lightly on **{your_name}**'s foot. He stays there. He doesn't say anything. He doesn't need to. **prrt.***",
            f"*He pads up, bumps his forehead very gently against **{your_name}**'s hand, and folds into a small loaf beside them. Quiet. Present. **mrr.** It's what he has to give.*",
        ])
        crave_relief = 2

    await ctx.send(line)
    if "affection_crave" in m["stats"]:
        m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - crave_relief)
    save_db(m)


@bot.command(name="history", aliases=["myhistory", "with_me"])
async def history_cmd(ctx):
    """Your full interaction history with Yarnaby."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    your_name = getattr(ctx.author, "display_name", str(ctx.author))

    entry = m.get("social_matrix", {}).get(u_id) if not is_doctor else None
    archive = m.get("offering_archive", [])
    feeds = [a for a in archive if a.get("kind") == "feed" and a.get("user_id") == u_id]
    gifts = [a for a in archive if a.get("kind") == "gift" and a.get("user_id") == u_id]
    steals = [s for s in m.get("steal_log", []) if s.get("user_id") == u_id]
    steals_caught = sum(1 for s in steals if s.get("result") == "caught")
    steals_success = sum(1 for s in steals if s.get("result") != "caught")

    if is_doctor:
        first = m["internal"].get("birth_date") or "the very beginning"
        await ctx.send(
            f"*Yarnaby looks at **The Creator**. The question, asked of them, is somehow funny to him. **chrrp.** "
            f"He has known them since **{first}**. There is no other history. There is only this one. He does not need a count. He has the whole of it, every day, in him. **prrr.***"
        )
        return

    if not isinstance(entry, dict):
        await ctx.send(
            random.choice([
                f"*Yarnaby tilts his head at **{your_name}**. He doesn't have a record for them yet. Try interacting with him first. **mrr.***",
                f"*A small, careful **chrrp**. There is no history yet between him and **{your_name}**. They are new to him.*",
            ])
        )
        return

    score = entry.get("score", 0)
    first_str = entry.get("first_interaction")
    last_str = entry.get("last_seen")

    def _fmt_when(s):
        if not s:
            return "-"
        try:
            d = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        except (ValueError, TypeError):
            return s
        days = max(0, (datetime.now() - d).days)
        pretty = d.strftime("%b %d, %Y")
        if days == 0:
            return f"{pretty} (today)"
        if days == 1:
            return f"{pretty} (yesterday)"
        if days < 30:
            return f"{pretty} ({days}d ago)"
        if days < 365:
            months = days // 30
            return f"{pretty} (~{months}mo ago)"
        years = days // 365
        return f"{pretty} (~{years}y ago)"

    last_feed = feeds[-1].get("item") if feeds else None
    last_gift = gifts[-1].get("item") if gifts else None

    if score >= 7:
        opener = random.choice([
            f"*Yarnaby looks at **{your_name}** with the warmth he reserves for the regulars. He produces, in his way, the ledger. **chrrp.***",
            f"*A bright **chrrp**. He knows **{your_name}** well. He always remembers them. The history, in his head, is long.*",
        ])
    elif score >= 1:
        opener = random.choice([
            f"*Yarnaby tilts his head at **{your_name}**. He recognises them. He produces the record. **prrt.***",
            f"*A small **chrrp**. He has been keeping track of **{your_name}**. Here is what he has.*",
        ])
    elif score == 0:
        opener = random.choice([
            f"*Yarnaby looks at **{your_name}** flatly. He has them on file, technically. The verdict is still pending. **mrr.***",
            f"*A neutral **prrt**. **{your_name}** is in his records. He hasn't decided about them yet.*",
        ])
    else:
        opener = random.choice([
            f"*Yarnaby's wool ruffles slightly at **{your_name}**'s name. He keeps the record anyway. He keeps every record. **mrrp.***",
            f"*A long, cool look. He has the history of **{your_name}**, in detail. He is not pleased to recite it.*",
        ])

    lines = [
        opener,
        "",
        f"**Score:** {score}",
        f"**First met:** {_fmt_when(first_str)}",
        f"**Last seen:** {_fmt_when(last_str)}",
        f"**Times you've fed him:** {len(feeds)}" + (f" *(last: {last_feed})*" if last_feed else ""),
        f"**Times you've gifted him:** {len(gifts)}" + (f" *(last: {last_gift})*" if last_gift else ""),
    ]
    if steals:
        lines.append(f"**Steal attempts:** {len(steals)} - caught {steals_caught}, succeeded {steals_success}")
    await ctx.send("\n".join(lines))


@bot.command(name="praise")
async def praise_cmd(ctx):
    """The Creator praises Yarnaby directly. Huge mood lift."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    if not is_doctor:
        await ctx.send(
            random.choice([
                "*Yarnaby looks at you, then around the room, and back at you. The praise has not landed. It cannot. He waits, politely, for someone else to say it. **mrr.***",
                "*A flat, polite **prrt**. He recognises the shape of the words. They are not in the right voice. He sets the praise aside, unopened. **mrrp.***",
                "*Yarnaby's ears flick once. He understands you mean well. The praise simply does not register the way it would from The Creator. **prrt.** Try `!compliment` instead.*",
            ])
        )
        return

        if m["internal"]["is_sleeping"]:
            await ctx.send(
                random.choice([
                    "*Yarnaby was asleep - but at the sound of The Creator's praise, he stirs. His wool puffs. A long, contented **prrr** starts before he's even fully awake. He doesn't open his eyes. He doesn't need to.*",
                    "*A small, sleepy **chrrp** as he hears it. The purr starts almost immediately. He rolls a fraction closer to The Creator without waking. **prrr...***",
                ])
            )
