@bot.command(name="wander", aliases=["wandered", "wheredidhego", "hisdaytrip", "explored", "wherehedwent"])
async def wander_cmd(ctx, *, note: str = ""):
    """Narrate where Yarnaby went today."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    today = (datetime.now(timezone.utc).replace(tzinfo=None) + ISTANBUL_OFFSET).date()
    day_seed = int(today.strftime("%Y%m%d"))
    rng = random.Random(day_seed)
    stops = rng.sample(WANDER_LOCATIONS, k=min(3, len(WANDER_LOCATIONS)))
    intros = [
        "*Today, if you tracked him carefully:*",
        "*He was gone for stretches today. Here is where he went:*",
        "*His movements, reconstructed from evidence:*",
        "*He ranged further than usual today. The itinerary, best as anyone can tell:*",
    ]
    lines = [random.choice(intros), ""]
    for i, (place, note) in enumerate(stops, start=1):
        lines.append(f"**{i}.** He was found at **{place}** - {note}")
    lines.append("")
    lines.append(random.choice([
        "*He is back now. He offers no explanation for any of it.* **mrr.**",
        "*He returned on his own timeline. He always does.* **...prrr...**",
        "*He came back when he was ready. He considers this the correct approach.* **prrt.**",
    ]))
    await ctx.send("\n".join(lines))


