@bot.command(name="boopbattle", aliases=["boop_battle", "counterboop"])
async def boopbattle_cmd(ctx):
    m = bot.db
    await _add_reactions(ctx, m)
    score = 999 if ctx.author.id == DOCTOR_ID else m.get("social_matrix", {}).get(str(ctx.author.id), {}).get("score", 0)
    if m["internal"].get("is_sleeping"):
        await ctx.send("*He is asleep. Your boop lands on wool. One paw rises in his sleep and counter-boops the air.* **...mrr...**")
