@bot.command(name="trusttest", aliases=["trust_test", "trial"])
async def trusttest_cmd(ctx):
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    uid = str(ctx.author.id)
    score = 999 if ctx.author.id == DOCTOR_ID else m.get("social_matrix", {}).get(uid, {}).get("score", 0)
    passed = ctx.author.id == DOCTOR_ID or random.random() < min(0.9, max(0.1, (score + 20) / 100))
    if passed:
        m.setdefault("social_matrix", {}).setdefault(uid, {})["score"] = min(100, score + 1) if score < 999 else score
        save_db(m)
        await ctx.send("*He places one small object in front of you and waits. You do not ruin it. He notes this carefully.* **prrr.**")
    else:
        await ctx.send("*He considers trusting you with a small object. He reconsiders. The test has been postponed by his legal department.* **mrr.**")


