@bot.command(name="bite", aliases=["bitehim", "chomp", "nibble", "nom"])
async def bite_cmd(ctx, *, spot: str = ""):
    """Bite Yarnaby playfully. He may bite back depending on Creator and score."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    score = 999 if is_doctor else m.get("social_matrix", {}).get(u_id, {}).get("score", 0)
    spot_text = (spot or "wool").strip().lower()

    if m["internal"].get("is_sleeping"):
        await ctx.send(random.choice([
            "*You try to bite him while he's asleep. His paw comes up automatically and presses against your face. He does not wake.* **...mrr...**",
            "*He's asleep. The bite lands in wool. He grumbles once and rolls away like a very offended pillow.* **...mrrp...**",
        ]))
        return

    if any(word in spot_text for word in ["butt", "ass", "groin", "crotch", "private", "privates"]):
        await ctx.send("*No. Yarnaby relocates instantly. Keep bites playful and non-NSFW.* **mrr.**")
        return

    if not is_doctor:
        remaining = _cooldown_remaining(m, f"bite:{u_id}", 45)
        if remaining > 0:
            await ctx.send(f"*Yarnaby shows you his teeth in warning. Bite privileges are on cooldown. ({remaining}s)* **mrr.**")
            return
        _set_cooldown(m, f"bite:{u_id}")

    bite_back_chance = 0.95 if is_doctor else 0.15
    if score >= 80:
        bite_back_chance = 0.75
    elif score >= 50:
        bite_back_chance = 0.55
    elif score >= 20:
        bite_back_chance = 0.35
    elif score < 0:
        bite_back_chance = 0.05

    if is_doctor:
        lines = [
            "*The Creator bites him gently. Yarnaby freezes, processes the ancient social contract, then bites back with ceremonial softness. This is law now.* **prrrk.**",
            "*He accepts the bite from The Creator with enormous dignity. Then he leans in and returns one tiny chomp, careful as a promise.* **prrr.**",
        ]
        m["stats"]["affection_crave"] = max(0, m["stats"].get("affection_crave", 0) - 3)
    elif random.random() < bite_back_chance:
        lines = [
            f"*You bite his {spot_text}. Yarnaby stares. Then he leans forward and gives your sleeve one precise revenge-nibble. Fair is fair.* **mrrp.**",
            f"*The bite lands. His ears go forward. He bites back very gently, then sits there looking unbearably pleased with himself.* **prrk.**",
            f"*He allows it for half a second, then answers with a tiny chomp of his own. Not hard. Just legally binding.* **mrr.**",
        ]
        if score >= 20:
            m["social_matrix"].setdefault(u_id, {})["score"] = min(100, score + 1)
    else:
        lines = [
            f"*You bite his {spot_text}. He slowly turns his head and gives you the flattest look he owns. No bite back. Only judgment.* **mrr.**",
            f"*Yarnaby feels the bite, puffs up, and steps exactly one foot away. He is reconsidering your permissions.* **mrrp.**",
            f"*He dodges the bite at the last second and taps your arm with one paw. Denied.* **mrr.**",
        ]
        if score < 5:
            m["social_matrix"].setdefault(u_id, {})["score"] = max(-100, score - 1)

    save_db(m)
    await ctx.send(random.choice(lines))

