# ==========================================
# !ask [question] - non-verbal yes/no/maybe from Yarnaby
# ==========================================
@bot.command(name="ask", aliases=["yarnyask", "askhim", "hisanswer", "willyou", "doyou", "questyarny"])
async def ask_cmd(ctx, *, question: str = ""):
    """Ask Yarnaby something. He answers with body language only."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He's asleep. He cannot answer your question in this state, verbal or otherwise.* **...mrr...**",
            "*He's dreaming. Whatever the answer is, he's keeping it to himself right now.* **...prrr...**",
        ]))
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*He looks at you when you ask. He considers it for a long moment. Then he looks away. He doesn't have an answer right now. He has other things.* **...mrr...**",
            f"*The question reaches him. He hears it. He doesn't respond. Not because he doesn't understand — he does — but because he is somewhere small and quiet and the question is outside of that.* **...mrr...**",
        ]))
        return


    if not question.strip():
        await ctx.send("*He tilts his head. You didn't actually ask him anything.* **mrp.**")
        return

    mood = m["stats"].get("mood", "Content")

    if mood == "Agitated":
        ANSWERS_ANNOYED = [
            "*He looks at the question. He looks away. His tail lashes once. He has not answered and will not be answering.* **mrrp.**",
            "*He gives you a flat stare and turns his back. The matter is closed.* **...**",
            "*One ear folds. He was fine before this.* **mrr.**",
        ]
        await ctx.send(random.choice(ANSWERS_ANNOYED))
        return

    ANSWERS_YES = [
        "*He blinks at you - slow, deliberate, one single blink. His ears are forward.* **prrr.**",
        "*He turns to face you fully and closes his eyes for a long moment. When he opens them, he holds your gaze.* **...prrr...**",
        "*One slow blink. His tail curls slightly at the tip. His ears stay forward.* **prrt.**",
        "*He closes both eyes for exactly one second, then opens them and keeps them on you.* **prrr.**",
    ]
    ANSWERS_NO = [
        "*He turns his back to you with great deliberateness. He sits facing the wall.* **mrrp.**",
        "*He looks at you. He looks away. He shifts his weight so he's angled just slightly away from the question.* **...**",
        "*He gives one firm headshake - small, unhurried - and returns to what he was doing.* **mrr.**",
        "*He lowers his chin. He half-closes his eyes. He is not in agreement.* **...mrr...**",
    ]
    ANSWERS_MAYBE = [
        "*He tilts his head slowly to one side. He holds this position. He offers no elaboration.* **mrr?**",
        "*He looks at you sideways, one ear half-back. He blinks. He does not commit.* **prrt?**",
        "*He stands up, circles once, and sits back down facing slightly away. He has not answered. That is the answer.* **...mrr...**",
        "*He makes a sound that is not quite a chirp and not quite a mrrow. He seems uncertain himself.* **mrrp?**",
    ]
    ANSWERS_ABSOLUTELY_NOT = [
        "*Both ears go flat. He holds your gaze for one full second. He turns completely around and walks to the farthest corner.* **...**",
        "*He stares at the question. His tail puffs slightly. He sits with both paws tucked tight. No.* **mrrrrp.**",
        "*He turns his head away so quickly it's almost a flinch. His ears are flat. This is a strong no.* **mrr.**",
    ]
    ANSWERS_ENTHUSIASTIC_YES = [
        "*He stands up immediately, tail fully vertical, and chirps at you twice in quick succession. His ears are as forward as they will go.* **chrrp! chrrp!**",
        "*He blinks - once, twice - then headbutts the nearest surface decisively.* **chrrp. prrr.**",
        "*He gets up, pads a full circle, and comes back facing you with both eyes bright. He blinks three times.* **chrrp!**",
    ]

    # Weight the answer distribution based on mood + randomness
    q_lower = question.lower().strip()
    # Questions about food, sleep, Adidas, The Creator, Bobby tend toward yes
    positive_bias_words = ["fish", "tuna", "food", "eat", "treat", "dreamie", "churu",
                           "sleep", "nap", "adidas", "creator", "bobby", "bear", "dream",
                           "play", "fetch", "toy"]
    negative_bias_words = ["bath", "vet", "medicine", "pill", "cucumber", "vegetables",
                           "sorry", "stop", "no ", "don't", "stranger", "leave"]

    has_positive = any(w in q_lower for w in positive_bias_words)
    has_negative = any(w in q_lower for w in negative_bias_words)

    roll = random.random()
    if has_positive and not has_negative:
        if roll < 0.55:
            await ctx.send(random.choice(ANSWERS_ENTHUSIASTIC_YES if roll < 0.2 else ANSWERS_YES))
        elif roll < 0.75:
            await ctx.send(random.choice(ANSWERS_MAYBE))
        else:
            await ctx.send(random.choice(ANSWERS_NO))
    elif has_negative and not has_positive:
        if roll < 0.55:
            await ctx.send(random.choice(ANSWERS_ABSOLUTELY_NOT if roll < 0.2 else ANSWERS_NO))
        elif roll < 0.75:
            await ctx.send(random.choice(ANSWERS_MAYBE))
        else:
            await ctx.send(random.choice(ANSWERS_YES))
    else:
        if roll < 0.35:
            await ctx.send(random.choice(ANSWERS_YES))
        elif roll < 0.55:
            await ctx.send(random.choice(ANSWERS_NO))
        elif roll < 0.80:
            await ctx.send(random.choice(ANSWERS_MAYBE))
        elif roll < 0.90:
            await ctx.send(random.choice(ANSWERS_ENTHUSIASTIC_YES))
        else:
            await ctx.send(random.choice(ANSWERS_ABSOLUTELY_NOT))


# ==========================================
# !lookup @user - Creator only: full social matrix dump for a user
# ==========================================
@bot.command(name="lookup", aliases=["userdata", "checkuser", "whoisthat", "userinfo", "userlookup"])
async def lookup_cmd(ctx, user: discord.Member = None):
    """[Creator only] Full data dump for a specific user."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*He looks at you steadily. That one is for The Creator.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    if not ctx.message.mentions:
        await ctx.send("*Mention someone to look them up.* `!lookup @user`")
        return
    member = ctx.message.mentions[0]
    u_id = str(member.id)
    sm = m.get("social_matrix", {})
    entry = sm.get(u_id, {})
    if not entry:
        await ctx.send(f"*Yarnaby has no record of **{member.display_name}**. They haven't registered in his memory yet.*")
        return
    score = entry.get("score", 0)
    first_seen = entry.get("first_seen", "unknown")
    last_seen = entry.get("last_seen", "unknown")
    first_msg = entry.get("first_message", "*(not recorded)*")
    milestones = entry.get("milestones_reached", [])
    milestone_count = len(milestones) if isinstance(milestones, list) else 0
    # Score tier label
    if score >= 90:
        tier = "Full trust"
    elif score >= 70:
        tier = "Deep familiar"
    elif score >= 50:
        tier = "Trusted regular"
    elif score >= 30:
        tier = "Known presence"
    elif score >= 15:
        tier = "Cautious acquaintance"
    elif score >= 5:
        tier = "Vaguely noticed"
    elif score > 0:
        tier = "Barely registered"
    else:
        tier = "Unknown / mistrusted"
    lines = [
        f"**Lookup: {member.display_name}** (`{member.id}`)",
        f"**Score:** {score} - *{tier}*",
        f"**First seen:** {first_seen}",
        f"**Last seen:** {last_seen}",
        f"**Milestones reached:** {milestone_count}",
        f"**First message:** {first_msg[:200] if first_msg else '*(none)*'}",
    ]
    # Check for toxic log
    toxic_log = m.get("toxic_attempts", {}).get(u_id, [])
    if toxic_log:
        lines.append(f"**Toxic attempts:** {len(toxic_log)} on record")
    # Last gift / last food
    gift_log = m.get("gift_log", {}).get(u_id, [])
    if gift_log:
        lines.append(f"**Last gift:** {gift_log[-1]}")
    food_log = m.get("feed_history", {}).get(u_id, [])
    if food_log:
        lines.append(f"**Last fed:** {food_log[-1] if isinstance(food_log[-1], str) else str(food_log[-1])}")
    await ctx.send("\n".join(lines))


# ==========================================
# !countdown - show days remaining until departure date
# ==========================================
@bot.command(name="countdown", aliases=["depcount", "departurein", "daysleft", "leavingsoon", "timeuntil"])
async def countdown_cmd(ctx):
    """Show how many days remain until the departure date - or how long it's been since."""
    m = bot.db
    await _add_reactions(ctx, m)
    dep_str = m["internal"].get("departure_date")
    if not dep_str:
        await ctx.send(random.choice([
            "*He blinks at the question. He doesn't know what you mean. He tilts his head.* **mrr?**",
            "*He looks at you, then at the door, then back at you. He has no date stored. He seems okay with this.* **...mrr...**",
        ]))
        return
    try:
        dep_date = datetime.strptime(dep_str, "%Y-%m-%d").date()
    except ValueError:
        await ctx.send("*Something is wrong with the stored date. The Creator should check it.* **mrr.**")
        return
    today = (datetime.now() + ISTANBUL_OFFSET).date()
    delta = (dep_date - today).days
    if delta > 30:
        await ctx.send(random.choice([
            f"*He is sitting in his spot, calm and present. There are **{delta} days** until the departure. He is not thinking about it yet.* **prrr.**",
            f"*He blinks at you. **{delta} days**. He licks his paw and looks out the window. He is not worried.* **...prrr...**",
            f"*He counts in the way he counts - which is mostly just knowing. **{delta} days**. He settles back down.* **mrr.**",
        ]))
    elif delta > 14:
        await ctx.send(random.choice([
            f"*He has been sitting near the door more than usual. **{delta} days**. He is aware of something changing. He doesn't say so.* **...mrr...**",
            f"*He looks up when you ask. **{delta} days**. His tail flicks once. He returns his attention to nothing in particular.* **mrr.**",
        ]))
    elif delta > 7:
        await ctx.send(random.choice([
            f"*He has not been sleeping as deeply. **{delta} days**. He is aware. He stays very close.* **...prrr...**",
            f"*He looks at the date. He looks at you. **{delta} days**. His ears are slightly lower than usual.* **...mrr...**",
        ]))
    elif delta > 0:
        await ctx.send(random.choice([
            f"*He is following closer than normal. He slept against the door last night. **{delta} day{'s' if delta != 1 else ''}** left.* **...mrr...**",
            f"*His eyes are on the Creator more than usual. **{delta} day{'s' if delta != 1 else ''}**. He presses against them whenever they stand still.* **...prrr...**",
        ]))
    elif delta == 0:
        await ctx.send(random.choice([
            "*He is at the door. He has been at the door all morning. Today is the day.* **...mrr...**",
            "*He is sitting directly in front of the door. He has not moved. He is watching it.* **...**",
        ]))
    else:
        days_since = abs(delta)
        await ctx.send(random.choice([
            f"*He pads to the Creator's usual spot and sits in it. **{days_since} day{'s' if days_since != 1 else ''}** since the departure.* **...mrr...**",
            f"*He sniffs the edge of the Creator's chair. **{days_since} day{'s' if days_since != 1 else ''}** since they left. He has not forgotten the smell.* **...prrr...**",
        ]))


# ==========================================
# !broadcast [message] - Creator only: narrator-style message to home channel
# ==========================================
@bot.command(name="broadcast", aliases=["announce", "yarnyannounce", "servermsg"])
async def broadcast_cmd(ctx, *, message: str = ""):
    """[Creator only] Send a narrator-style message to the home channel."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*He looks at you with mild confusion. That is a Creator command.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    if not message.strip():
        await ctx.send("*Nothing to broadcast. Provide a message after the command.* `!broadcast [message]`")
        return
    ch_id = m["internal"].get("home_channel_id") or m["internal"].get("last_channel_id")
    if not ch_id:
        await ctx.send("*No home channel set. Use `!set_home` first.*")
        return
    ch = bot.get_channel(int(ch_id))
    if not ch:
        await ctx.send("*Cannot find the home channel. It may have been deleted or he can no longer access it.*")
        return
    formatted = f"*{message.strip()}*"
    await ch.send(formatted)
    if ch.id != ctx.channel.id:
        await ctx.send(f"*Broadcast sent to <#{ch_id}>.* **mrr.**")


# ==========================================
# !raid [server name] [topic] - Creator only: warn that a server is a bad server
# ==========================================
@bot.command(name="raid")
async def raid_cmd(ctx, server_name: str = "", *, topic: str = ""):
    """[Creator only] BROADCAST a danger warning to every channel in the named server. Use sparingly."""
    if ctx.author.id != DOCTOR_ID:
        return
    m = bot.db
    await _add_reactions(ctx, m)

    if not server_name.strip() or not topic.strip():
        await ctx.send(
            "*`!raid [server name] [topic]` — pick a server from `!servers` and describe the danger "
            "(e.g. `scam`, `phishing`, `malware`).*\n"
            "*This will post urgent warnings to **every** channel in that server. Use with care.* **mrr.**"
        )
        return

    # --- Find the target server ---
    target_guild = None
    for g in bot.guilds:
        if server_name.lower() in g.name.lower() or server_name == str(g.id):
            target_guild = g
            break

    if not target_guild:
        await ctx.send(
            f"*He can't find a server called **{server_name}**. "
            f"Use `!servers` for the full list.* **mrr.**"
        )
        return

    topic_clean = topic.strip()

    # Collect every text channel he can write in
    writable_channels = [
        ch for ch in target_guild.text_channels
        if ch.permissions_for(target_guild.me).send_messages
    ]

    if not writable_channels:
        await ctx.send(
            f"*He's in **{target_guild.name}**, but there's nowhere he can speak. "
            f"He can't post any warnings there.* **mrr.**"
        )
        return

    # Acknowledgement back to the caller first
    await ctx.send(
        f"*He sets his jaw. His ears go flat. He moves.*\n"
        f"*Broadcasting danger warning to **{len(writable_channels)}** channel(s) in "
        f"**{target_guild.name}** — topic: **{topic_clean}**.* **mrr.**"
    )

    # --- Warning messages (rotated across repeats so it doesn't look like a stuck record) ---
    WARNING_ROUNDS = [
        (
            f"⚠️ **DANGER — {topic_clean.upper()} SERVER** ⚠️",
            (
                f"*Yarnaby stops. He's not playing anymore — not even a little. "
                f"He looks straight at whoever's reading this.*\n\n"
                f"**\"This server is a {topic_clean} server. Don't click anything. Don't share anything. "
                f"Don't trust anyone here. If you were linked here, that's the trap — close the tab and "
                f"warn whoever sent you.\"**\n\n"
                f"*He holds the look a moment longer. Then he turns away, ears low.* **...mrr.**"
            ),
        ),
        (
            f"🚨 STILL HERE? GET OUT — {topic_clean.upper()} SERVER 🚨",
            (
                f"*He is posting this again because people don't always see the first one.*\n\n"
                f"**This server is flagged as a {topic_clean} server. Leave now. "
                f"Do not engage with anyone here. Do not click any links. "
                f"Report it to Discord: <https://dis.gd/request>**\n\n"
                f"*His tail is still. His ears are back. He is serious.* **mrr.**"
            ),
        ),
        (
            f"⚠️ FINAL WARNING — {topic_clean.upper()} SERVER ⚠️",
            (
                f"*He posts this one last time for anyone who missed the others.*\n\n"
                f"**{topic_clean.upper()} SERVER. Leave. Report. Don't come back.**\n\n"
                f"*He turns and walks away without looking back. He has done what he can.* **...mrr.**"
            ),
        ),
    ]

    channels_warned = 0
    channels_failed = 0

    for ch in writable_channels:
        perms = ch.permissions_for(target_guild.me)
        can_ping = perms.mention_everyone

        for i, (title, description) in enumerate(WARNING_ROUNDS):
            embed = discord.Embed(
                title=title,
                description=description,
                color=discord.Color.red(),
            )
            embed.set_footer(text="Posted by Yarnaby at the request of The Creator. This is a safety warning.")

            # @everyone only on the first message per channel to avoid full spam-lockout
            ping_content = "@everyone" if (can_ping and i == 0) else None

            try:
                await ch.send(
                    content=ping_content,
                    embed=embed,
                    allowed_mentions=discord.AllowedMentions(everyone=(can_ping and i == 0)),
                )
                await asyncio.sleep(0.8)  # slight gap between rounds so they land in order
            except Exception:
                channels_failed += 1
                break  # skip remaining rounds for this channel if it errors

        else:
            channels_warned += 1
            await asyncio.sleep(0.4)  # brief pause between channels

    # Final report
    fail_note = f" ({channels_failed} channel(s) blocked him.)" if channels_failed else ""
    await ctx.send(
        f"*He's done. Warning posted to **{channels_warned}** channel(s) in "
        f"**{target_guild.name}**.{fail_note}*\n"
        f"*If this is a genuine scam/raid/phishing server, also report it to Discord directly — "
        f"<https://dis.gd/request> — that's the only way permanent action gets taken.* **...mrr.**"
    )

    # Persist raided guild info for !raidstop
    bot.db.setdefault("internal", {}).update({
        "last_raid_guild_id": str(target_guild.id),
        "last_raid_channel_ids": [str(ch.id) for ch in writable_channels],
        "last_raid_topic": topic_clean,
    })

    # Append to persistent raid log
    raid_log = bot.db.setdefault("internal", {}).setdefault("raid_log", [])
    raid_log.append({
        "guild_id": str(target_guild.id),
        "guild_name": target_guild.name,
        "topic": topic_clean,
        "channels_warned": channels_warned,
        "channels_failed": channels_failed,
        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    # Cap log at 50 entries
    if len(raid_log) > 50:
        bot.db["internal"]["raid_log"] = raid_log[-50:]

    # DM the Creator a ready-to-paste Discord Trust & Safety report
    try:
        creator_user = await bot.fetch_user(DOCTOR_ID)
        report_body = (
            f"**Server name:** {target_guild.name}\n"
            f"**Server ID:** {target_guild.id}\n"
            f"**Issue type:** {topic_clean}\n"
            f"**Member count:** {target_guild.member_count}\n"
            f"**Channels warned:** {channels_warned}\n"
            f"**Reported by:** Yarnaby (!raid command)\n\n"
            f"Paste the above into the Discord Trust & Safety form:\n"
            f"<https://dis.gd/request>"
        )
        dm_embed = discord.Embed(
            title=f"📋 Report ready — {target_guild.name}",
            description=report_body,
            color=discord.Color.orange(),
        )
        dm_embed.set_footer(text="Copy the details above and paste them into the T&S form. The server ID is the most important field.")
        await creator_user.send(embed=dm_embed)
    except Exception:
        pass  # DM blocked or failed — non-fatal


# ==========================================
# ==========================================
# !raidstop — post an all-clear to every channel that was raided
# ==========================================
@bot.command(name="raidstop", aliases=["allclear", "raidover", "safenow"])
async def raidstop_cmd(ctx):
    """[Creator only] Post an all-clear message to every channel that was raided with !raid."""
    if ctx.author.id != DOCTOR_ID:
        return
    m = bot.db
    await _add_reactions(ctx, m)

    internal = m.get("internal", {})
    guild_id_str = internal.get("last_raid_guild_id")
    channel_ids = internal.get("last_raid_channel_ids", [])
    topic_clean = internal.get("last_raid_topic", "unknown")

    if not guild_id_str or not channel_ids:
        await ctx.send(
            "*He looks around blankly. There's no record of a recent raid broadcast — "
            "use `!raid` first.* **mrr.**"
        )
        return

    target_guild = bot.get_guild(int(guild_id_str))
    if not target_guild:
        await ctx.send(
            "*He can't find the server that was raided. He may have left it, or it no longer exists.* **mrr.**"
        )
        return

    await ctx.send(
        f"*He exhales slowly. He begins the rounds.*\n"
        f"*Posting all-clear to **{len(channel_ids)}** channel(s) in **{target_guild.name}**...* **mrr.**"
    )

    cleared = 0
    failed = 0
    for ch_id in channel_ids:
        ch = target_guild.get_channel(int(ch_id))
        if ch is None:
            failed += 1
            continue
        if not ch.permissions_for(target_guild.me).send_messages:
            failed += 1
            continue
        embed = discord.Embed(
            title="✅ All clear — danger has passed",
            description=(
                f"*Yarnaby reappears in the doorway. He looks different — quieter, settled.*\n\n"
                f"**The earlier {topic_clean} warning has been resolved. "
                f"The Creator has confirmed the situation is under control. "
                f"You can stand down.**\n\n"
                f"*He sits down. He blinks slowly. He is done.* **prrr.**"
            ),
            color=discord.Color.green(),
        )
        embed.set_footer(text="All-clear posted by Yarnaby at the request of The Creator.")
        try:
            await ch.send(embed=embed)
            cleared += 1
            await asyncio.sleep(0.6)
        except Exception:
            failed += 1

    # Clear stored raid data so stale !raidstop can't be reused
    internal.pop("last_raid_guild_id", None)
    internal.pop("last_raid_channel_ids", None)
    internal.pop("last_raid_topic", None)

    fail_note = f" ({failed} channel(s) were unreachable.)" if failed else ""
    await ctx.send(
        f"*All-clear posted to **{cleared}** channel(s) in **{target_guild.name}**.{fail_note}*\n"
        f"*Raid record cleared. He's done.* **mrr.**"
    )


# ==========================================
# !raidlog — show history of all !raid broadcasts
# ==========================================
@bot.command(name="raidlog", aliases=["raidhistory", "raidrecord", "raids"])
async def raidlog_cmd(ctx, action: str = ""):
    """[Creator only] Show or clear the log of every !raid broadcast."""
    if ctx.author.id != DOCTOR_ID:
        return
    m = bot.db
    await _add_reactions(ctx, m)

    # ── clear subcommand ──
    if action.strip().lower() == "clear":
        m.setdefault("internal", {}).pop("raid_log", None)
        await ctx.send(
            "*He sweeps the notes off the desk. They're gone — the raid log is empty.* **mrr.**"
        )
        return

    raid_log = m.get("internal", {}).get("raid_log", [])

    if not raid_log:
        await ctx.send(
            "*He checks his notes. There's nothing there. No raids have been broadcast yet.* **mrr.**"
        )
        return

    lines_out = [f"*He spreads his notes flat. He has broadcast warnings to **{len(raid_log)}** server(s):*\n"]
    for i, entry in enumerate(reversed(raid_log), 1):
        fail_note = f" ({entry.get('channels_failed', 0)} failed)" if entry.get("channels_failed") else ""
        lines_out.append(
            f"`{i}.` **{entry['guild_name']}** — `{entry['guild_id']}` — "
            f"topic: **{entry['topic']}** — "
            f"{entry.get('channels_warned', '?')} channel(s) warned{fail_note} — "
            f"`{entry['timestamp']}`"
        )
    lines_out.append("\n*Newest first. Up to 50 entries. Use `!raidlog clear` to wipe.* **mrr.**")

    full_text = "\n".join(lines_out)
    if len(full_text) <= 2000:
        await ctx.send(full_text)
    else:
        chunk = []
        char_count = 0
        for line in lines_out:
            if char_count + len(line) + 1 > 1900:
                await ctx.send("\n".join(chunk))
                chunk = [line]
                char_count = len(line)
            else:
                chunk.append(line)
                char_count += len(line) + 1
        if chunk:
            await ctx.send("\n".join(chunk))


# ==========================================
