@bot.command(name="rate", aliases=["rateme", "rateyou", "ratings"])
async def rate_cmd(ctx, user: discord.Member = None):
    """Rate a user (or yourself) on height/active/affection/etc."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    if target is None:
        target = ctx.author
    u_id = str(target.id)
    score = 99 if (target.id == DOCTOR_ID) else m["social_matrix"].get(u_id, {}).get("score", 0)
    height_cm = m["social_matrix"].get(u_id, {}).get("height_cm", None)
    category = category.lower().strip()

    if not category:
        await ctx.send("*He blinks. Rate what? Try `!rate height/active/affection/kindness/chaos @user`.* **mrr.**")
        return

    if category == "height":
        if height_cm is None:
            await ctx.send(f"*He tilts his head at {target.display_name}. He has no height data on them. Use `!setheight` first.* **mrr?**")
            return
        if height_cm < 150:
            lines = ["*He looks up. Then down. Then up again. He seems very smug about this.* **mrr. 3/10 - he can reach higher shelves than you.**",
                     "*He circles them once, slowly. He says nothing, but his posture says everything.* **mrr. 4/10.**"]
        elif height_cm < 170:
            lines = ["*He evaluates. He nods. He seems satisfied they are a reasonable size.* **6/10. Acceptable.**",
                     "*He looks them up and down with the air of a very small art critic. He approves.* **6/10.**"]
        elif height_cm < 185:
            lines = ["*He cranes his neck slightly. He doesn't mind tall people. They're useful for high shelves.* **7/10. Convenient.**",
                     "*He looks up at them with quiet respect. He does not admit the respect.* **7/10.**"]
        else:
            lines = ["*He stares upward for a long moment. He makes a small impressed chirp. He would rather not need a step stool to reach them.* **8/10. Tall.**",
                     "*He tilts his head all the way back. He nods once, slowly, like he's decided something.* **8/10. He appreciates the view from below.**"]
        await ctx.send(random.choice(lines))

    elif category in ("active", "activity", "activity_level"):
        entries = m["social_matrix"].get(u_id, {})
        msg_count = entries.get("message_count", 0) or 0
        if msg_count == 0:
            await ctx.send(f"*He sniffs the air where {target.display_name} usually sits. He sees very little data. **2/10.** He does not know them well enough to rate.* **mrr.**")
        elif msg_count < 10:
            await ctx.send(f"*He gives {target.display_name} a measured look. They exist. Barely. **4/10.** More effort, please.* **mrr.**")
        elif msg_count < 50:
            await ctx.send(f"*He considers {target.display_name}. They are present a reasonable amount. **6/10.** He notices them.* **mrr.**")
        elif msg_count < 200:
            await ctx.send(f"*He looks at {target.display_name} with something like appreciation. They are reliably here. **8/10.*** **prrr.**")
        else:
            await ctx.send(f"*He blinks at {target.display_name} slowly. He has seen them every single day. **10/10. He would be confused without them.*  **prrr.**")

    elif category in ("affection", "love", "warmth"):
        if score >= 8:
            await ctx.send(f"*He presses his cheek against {target.display_name}'s leg without being asked. **10/10.** He would be devastated if they left.* **prrrrr.**")
        elif score >= 5:
            await ctx.send(f"*He sits near {target.display_name} and watches them with warm glass eyes. **7/10.** He would choose them.* **prrr.**")
        elif score >= 2:
            await ctx.send(f"*He looks at {target.display_name}. He looks away. He looks back. **5/10.** He is still deciding.* **mrr.**")
        elif score >= 0:
            await ctx.send(f"*He gives {target.display_name} a neutral, assessing blink. **3/10.** He tolerates them, for now.* **mrr.**")
        else:
            await ctx.send(f"*He glances at {target.display_name} and immediately looks elsewhere. **1/10.** He has concerns about them.* **mrr.**")

    elif category in ("kindness", "kind", "nice"):
        kind_score = random.randint(max(1, score), 10) if score >= 0 else random.randint(1, max(1, 10 + score))
        await ctx.send(f"*He watches {target.display_name} for a long moment. He has been watching for a while. **{kind_score}/10.** He does not explain his methodology.* **mrr.**")

    elif category in ("chaos", "chaotic", "wild"):
        chaos = random.randint(1, 10)
        if chaos >= 8:
            await ctx.send(f"*He eyes {target.display_name} with something that might be respect. **{chaos}/10.** They have chaotic energy he admires and also fears.* **mrr.**")
        elif chaos >= 5:
            await ctx.send(f"*He tilts his head at {target.display_name}. **{chaos}/10.** Moderately chaotic. He can work with this.* **mrr.**")
        else:
            await ctx.send(f"*He blinks at {target.display_name}. **{chaos}/10.** Predictable. He already knows what they'll do next. He's not offended.* **mrr.**")

    elif category in ("smell", "scent", "sniff"):
        smells = ["clean wool", "warm bread", "something suspicious", "rain", "old books", "Adidas shoe lace", "mystery"]
        picked = random.choice(smells)
        rating = random.randint(3, 10)
        await ctx.send(f"*He sniffs in {target.display_name}'s direction carefully. He picks up: **{picked}**. **{rating}/10.** He files this information away.* **mrr.**")

    else:
        await ctx.send(f"*He tilts his head at the category '**{category}**'. He doesn't know how to rate that. Try: height, active, affection, kindness, chaos, smell.* **mrr?**")


# ==========================================
# !guess - guess his stats
# ==========================================
_pending_guesses = {}  # user_id -> {"stat": ..., "value": ..., "expires": ...}

@bot.command(name="guess", aliases=["guessit", "guessstat"])
async def guess_cmd(ctx, *, stat: str = ""):
    """Guess one of Yarnaby's stats. Confirm with !yes / !no."""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    stat = stat.lower().strip()
    u_id = str(ctx.author.id)

    stat_map = {
        "age": ("age", None),
        "height": ("height", None),
        "hunger": ("hunger", m["stats"].get("hunger", 0)),
        "tiredness": ("tiredness", m["stats"].get("tiredness", 0)),
        "health": ("health", m["stats"].get("health", 100)),
        "mood": ("mood", m["stats"].get("mood", "Content")),
        "integrity": ("integrity", m["stats"].get("integrity", 100)),
        "cleanliness": ("cleanliness", m["stats"].get("cleanliness", 0)),
        "loved": ("loved", None),
        "hated": ("hated", None),
        "active": ("active", None),
    }

    if not stat or stat not in stat_map:
        await ctx.send("*He blinks. Guess what? Try: `!guess age / height / hunger / tiredness / health / mood / loved / hated / active`.* **mrr?**")
        return

    if stat == "age":
        days = _get_age_days(m)
        years = days / 365
        _pending_guesses[u_id] = {"stat": "age", "value": round(years, 1), "expires": datetime.now() + timedelta(seconds=60)}
        await ctx.send(f"*He tilts his head at you. Go on then - guess his age in years. Use `!yes [your guess]` or just guess a number and use `!yes` / `!no` to confirm after.* **mrr?**")

    elif stat == "height":
        height_cm = m["social_matrix"].get(u_id, {}).get("height_cm", None)
        if height_cm is None:
            await ctx.send("*He looks at you blankly. No height is set for you yet. Use `!setheight` first.* **mrr.**")
            return
        _pending_guesses[u_id] = {"stat": "height", "value": height_cm, "expires": datetime.now() + timedelta(seconds=60)}
        await ctx.send(f"*He squares up against the wall with an air of great seriousness. Guess his height in cm. `!yes [cm]` or `!no`.* **mrr?**")

    elif stat in ("loved", "hated"):
        sm = m.get("social_matrix", {})
        if stat == "loved":
            best = max(sm.items(), key=lambda kv: kv[1].get("score", 0) if isinstance(kv[1], dict) else 0, default=(None, {}))
            val_id = best[0]
            hint = "the one he loves most"
        else:
            worst = min(sm.items(), key=lambda kv: kv[1].get("score", 0) if isinstance(kv[1], dict) else 0, default=(None, {}))
            val_id = worst[0]
            hint = "the one he trusts least"
        _pending_guesses[u_id] = {"stat": stat, "value": val_id, "expires": datetime.now() + timedelta(seconds=90)}
        await ctx.send(f"*He sits very still and thinks about {hint}. Name someone. `!yes @user` or `!no`.* **mrr...**")

    elif stat == "active":
        sm = m.get("social_matrix", {})
        most_active = max(sm.items(), key=lambda kv: kv[1].get("message_count", 0) if isinstance(kv[1], dict) else 0, default=(None, {}))
        _pending_guesses[u_id] = {"stat": "active", "value": most_active[0], "expires": datetime.now() + timedelta(seconds=90)}
        await ctx.send("*He paces for a moment, thinking of who is around the most. Name someone. `!yes @user` or `!no`.* **mrr...**")

    else:
        _pending_guesses[u_id] = {"stat": stat, "value": m["stats"].get(stat, 0), "expires": datetime.now() + timedelta(seconds=60)}
        await ctx.send(f"*He makes a small sound and waits. Guess his **{stat}** value (0-100 for numbers, or name the mood). Use `!yes [value]` to guess.* **mrr?**")


@bot.command(name="yes", aliases=["correct", "yep", "yeah"])
async def yes_cmd(ctx):
    """Confirm a pending !guess."""
    m = bot.db
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    pending = _pending_guesses.get(u_id)
    if not pending or datetime.now() > pending["expires"]:
        _pending_guesses.pop(u_id, None)
        await ctx.send("*He blinks. Yes to what? There's no pending guess.* **mrr.**")
        return

    stat = pending["stat"]
    correct_val = pending["value"]
    _pending_guesses.pop(u_id, None)

    # Try to compare
    correct = False
    try:
        if stat in ("loved", "hated", "active"):
            if ctx.message.mentions:
                guessed_id = str(ctx.message.mentions[0].id)
                correct = guessed_id == str(correct_val)
            else:
                correct = False
        elif stat in ("mood",):
            correct = guess_val.lower() in str(correct_val).lower()
        elif stat == "age":
            guessed_years = float(guess_val.replace("years", "").replace("year", "").strip())
            correct = abs(guessed_years - float(correct_val)) < 0.6
        elif stat == "height":
            guessed_cm = int(guess_val.replace("cm", "").strip())
            correct = abs(guessed_cm - int(correct_val)) <= 5
        else:
            guessed_num = float(guess_val.strip())
            correct = abs(guessed_num - float(correct_val)) <= 5
    except (ValueError, TypeError):
        correct = False

    if correct:
        await ctx.send(random.choice([
            f"*He stares at you. You got it. He's not sure how. He narrows his eyes slightly.* **mrr. Yes.**",
            f"*He blinks. Then blinks again. Then does a small, reluctant nod.* **chrrp. Correct.**",
            f"*He tilts his head. You're right. He is mildly unsettled by this.* **prrr. ...yes.**",
        ]))
    else:
        val_str = str(correct_val)
        await ctx.send(random.choice([
            f"*He shakes his head slowly. No. Not even close. The real answer was **{val_str}**. He is slightly disappointed.* **mrr. No.**",
            f"*He makes a flat sound. Wrong. (**{val_str}** was the answer.) He does not elaborate.* **mrr.**",
            f"*He gives you a long, patient look. The answer was **{val_str}**. He forgives you. Barely.* **...mrr...**",
        ]))


@bot.command(name="no", aliases=["wrong", "nope", "nah", "stop"])
async def no_cmd(ctx):
    """Cancel a pending !guess."""
    u_id = str(ctx.author.id)
    if u_id in _pending_guesses:
        _pending_guesses.pop(u_id, None)
        await ctx.send("*He nods once. Guess cancelled.* **mrr.**")
    else:
        await ctx.send("*He tilts his head. There was nothing pending.* **mrr.**")


