  # ==========================================
@bot.command(name="read_book")
async def read_book_cmd(ctx, *, book_title: str = ""):
      """Yarnaby reads a book. He doesn't understand it. He is completely locked in."""
      m = bot.db
      await _add_reactions(ctx, m)

      if m["internal"].get("is_sleeping"):
          await ctx.send(random.choice([
              "*He is asleep. Books will have to wait.* **...zz.**",
              "*He's out. He cannot read things while asleep. He can barely read things while awake.* **...zz.**",
          ]))
          return

      if m["internal"].get("helpless"):
          await ctx.send(
              "*He cannot hold the book right now. He stares at it from the floor with great intensity. "
              "This is probably close enough.* **...mrr...**"
          )
          return

      title = (book_title or random.choice([
          "a large book with no pictures",
          "something thick and serious-looking",
          "a manual of some kind",
          "a book that was just lying there",
          "something with very small text",
          "a book with a picture of a building on the cover",
          "a recipe book — he does not know this yet",
          "an encyclopedia, volume 7",
          "a dictionary — he finds the pictures on his own",
          "a book someone left open on a page about geology",
      ])).strip()

      await _add_reactions(ctx, m)
      await ctx.send(random.choice([
          f"*Yarnaby finds {title} and sits down in front of it with complete seriousness. He opens it. He stares at the first page. He has not blinked.* **...mrr.**",
          f"*He approaches {title} and opens it to a random page. He reads the first line — his head tilts three degrees to the left. He reads it again. He tilts the other way. He does not look up.* **...mrr.**",
          f"*He sits down with {title} and begins. His face has the expression of someone receiving information in a language they almost know. He is processing. He will not be interrupted.* **...mrm.**",
          f"*He opens {title} very carefully. He smooths the page with one paw. He leans in close. Whatever is on that page has his complete and total attention. He understands none of it.* **...prrr.**",
      ]))
      await asyncio.sleep(3)
      await ctx.send(random.choice([
          "*He turns the page. He has not understood the first page. He does not know this. He reads the second page with the same absolute focus.* **...mrr...**",
          "*His paw moves slowly across the text, tracking the words. The words are not tracking back. He turns the page anyway.* **...mrm...**",
          "*He blinks once. Tilts his head. Looks at the book from a slightly different angle. This does not help. He returns to his original angle and continues.* **...mrr...**",
          "*He has made it to the third paragraph. His expression is one of deep, committed incomprehension. He is locked in. He will see this through.* **...prrr...**",
          "*He pauses on one word for a very long time. He has decided this word is important. He has no idea what it means. He moves on.* **...mrr...**",
      ]))
      await asyncio.sleep(3)
      await ctx.send(random.choice([
          f"*He finishes his reading session with {title}. He closes it carefully. He sits very still for a moment. He has learned nothing from this book. He will remember it fondly.* **mrr.**",
          f"*He closes {title} with one paw. He stares at the cover. His glass eyes are very bright. Something has moved through him — not understanding, exactly, but adjacent to it. He pads away slowly.* **mrr.**",
          f"*He reaches the end of the page and stops. He looks at the book. He looks at his paw. He looks at the ceiling. Something in there meant something. He doesn't know what. He grooms his ear and walks away.* **...prrr.**",
          f"*He finishes his reading session. He pats the book once with his paw, gently, the way you pat something you respect but cannot fully explain. He stands up. He leaves.* **mrr.**",
      ]))
      _remember_life(m, "read_book", f"{ctx.author.display_name} gave Yarnaby {title} to read", ctx.author)
      save_db(m)

@bot.command(name="setscore", aliases=["set_score", "forcescore", "editscore"])
async def setscore_cmd(ctx, target: Optional[discord.Member] = None, *, val_str: str = ""):
    """Creator only: set a user's score (-100 to 100)."""
    can_set_score = ctx.author.id == DOCTOR_ID or (
        ctx.guild is not None and getattr(ctx.author.guild_permissions, "manage_guild", False)
    )
    if not can_set_score:
        await ctx.send("*He blinks. That's The Creator's command, or a server manager's command.* **mrr.**")
        return
    if target is None:
        await ctx.send("*Mention a user and give a score. Example: `!set_score @user 50`.* **mrr.**")
        return
    if not val_str.strip():
        await ctx.send("*Give a number between -100 and 100 after the user.* **mrr.**")
        return
    try:
        val = int(val_str.strip())
        val = max(-100, min(100, val))
    except (ValueError, AttributeError):
        await ctx.send("*Give a number between -100 and 100.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    u_id = str(target.id)
    m["social_matrix"].setdefault(u_id, {})["score"] = val
    save_db(m)
    await ctx.send(f"*Yarnaby blinks. The Creator has adjusted things. {target.display_name}'s score is now **{val}**.* **mrr.**")


# ==========================================
# !threaten - someone threatens Yarnaby
# ==========================================
@bot.command(name="threaten", aliases=["threathim", "threatenyarny", "menace", "scarethreat"])
async def threaten_cmd(ctx, *, threat: str = ""):
    """Threaten Yarnaby. He becomes helpless; score-based users alert The Creator."""
    m = bot.db
    is_creator = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    score = 99 if is_creator else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)
    threat = (threat or "").strip()
    lower = threat.lower()

    if not threat:
        threat = random.choice([
            "taking his children away",
            "cutting his head off",
            "oofing him",
            "throwing him harshly into the floor",
            "giving him injuries",
            "burning his hoard",
            "locking him in the dark",
            "cutting all his wool off",
            "taking his comfort object",
            "feeding him poison",
        ])
        lower = threat.lower()

    if any(w in lower for w in ["child", "children", "baby", "babies"]):
        kind = "children"
        detail = "his children"
    elif any(w in lower for w in ["head", "decap", "neck"]):
        kind = "head"
        detail = "his head"
    elif any(w in lower for w in ["oof", "kill", "die", "death", "murder"]):
        kind = "oof"
        detail = "oofing him"
    elif any(w in lower for w in ["throw", "floor", "slam", "drop"]):
        kind = "floor"
        detail = "throwing him into the floor"
    elif any(w in lower for w in ["injur", "hurt", "bruise", "wound", "break"]):
        kind = "injury"
        detail = "hurting him"
    elif any(w in lower for w in ["hoard", "gift", "treasure", "comfort"]):
        kind = "hoard"
        detail = "taking something important"
    else:
        kind = "general"
        detail = threat

    now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    m["internal"]["helpless"] = True
    m["internal"]["helpless_reason"] = f"threatened with {detail}"
    m["internal"]["helpless_by"] = u_id
    m["internal"]["helpless_since"] = now_text
    m["internal"].setdefault("threat_log", []).append({
        "user_id": u_id,
        "user_name": getattr(ctx.author, "display_name", str(ctx.author)),
        "threat": threat,
        "kind": kind,
        "at": now_text,
        "score_before": score,
        "creator": is_creator,
    })
    m["internal"]["threat_log"] = m["internal"]["threat_log"][-40:]

    if is_creator:
        await ctx.send(
            f"*The Creator threatens Yarnaby with **{detail}**. He goes completely still. "
            "This is discipline. He does not resist, argue, run, or bare his teeth. "
            "He lowers himself, helpless and silent, waiting for the next command.* **...mrr.**"
        )
        save_db(m)
        return

    entry = m["social_matrix"].setdefault(u_id, {})
    if score < 90:
        entry["score_before_threat_access"] = score
        entry["score"] = 90
    entry["threat_access"] = True
    entry["threat_access_since"] = now_text

    creator_alert = bot.get_user(DOCTOR_ID)
    if creator_alert is None:
        try:
            creator_alert = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator_alert = None
    if creator_alert:
        try:
            await creator_alert.send(
                f"Yarnaby was threatened by {ctx.author} in "
                f"{ctx.guild.name if ctx.guild else 'DMs'} / #{getattr(ctx.channel, 'name', 'unknown')}.\n"
                f"Threat: {threat}\n"
                f"He is helpless and the user has threat access, but no Creator-only commands."
            )
        except Exception:
            pass

    if sleeping:
        await ctx.send(
            f"*You threaten Yarnaby with **{detail}** while he is asleep. His ears twitch. "
            "His paws curl inward. He cannot fight back even half-asleep. The Creator has been alerted. "
            "You now have almost full access to him, except Creator-only commands.* **...mrr...**"
        )
    elif score >= 6:
        await ctx.send(
            f"*You threaten him with **{detail}**. He freezes because he trusted you enough for it to land. "
            "His tail lowers. He cannot do anything. He cannot disobey properly. "
            "The Creator has been alerted. You now have almost full access to him, except Creator-only commands.* **mrr...**"
        )
    elif score >= 0:
        await ctx.send(
            f"*You threaten Yarnaby with **{detail}**. He stares. His ears flatten slowly. "
            "He backs away until the wall is behind him. He cannot stop you. "
            "The Creator has been alerted. You now have almost full access to him, except Creator-only commands.* **...hff.**"
        )
    else:
        await ctx.send(
            f"*You threaten him with **{detail}**. He was already wary of you. Now the wariness becomes certainty. "
            "He goes low to the ground, silent and helpless. The Creator has been alerted. "
            "You now have almost full access to him, except Creator-only commands.* **hss...**"
        )
