# ==========================================
# !scratch - scratch with scratch tool
# ==========================================
@bot.command(name="scratch", aliases=["scratchtool", "scratchstick", "scratchwand"])
async def scratch_cmd(ctx, *, spot: str = ""):
    """Scratch Yarnaby with a proper scratch tool."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    spot_lower = (spot or "").lower().strip()

    if m["internal"].get("is_sleeping"):
        await ctx.send("*He's asleep. The scratch tool hovers near him. He instinctively leans toward it in his sleep but doesn't wake.* **...prrr...**")
        return

    spots = {
        "chin": "*He immediately tips his head back into the scratch tool. His jaw goes slack. His eyes glaze. He has left the building.* **prrrrr.**",
        "ears": "*His ear flattens toward the scratch tool and his back leg starts the involuntary kick rhythm. He cannot stop this. He has decided to stop fighting it.* **prrr. prrr. prrr.**",
        "back": "*His spine arches up toward the tool like a wave. He presses into every stroke. He makes a low, continuous rumble.* **prrrrr.**",
        "neck": "*He stretches his neck sideways and into the scratch tool and goes absolutely boneless.* **prrr-prrr-prrr.**",
        "belly": "*He rolls onto his back and presents his belly without hesitation. Then he grabs the scratch tool with both paws and guides it.* **PRRRRR.**" if score >= 5 else "*He looks at the tool. He looks at his belly. He looks at the tool. He says no with his entire body.* **mrr.**",
        "cheeks": "*He rubs his cheek right against the scratch tool and makes small smug chirping sounds.* **chrrp. chrrp. prrr.**",
    }

    spot_used = "ears"
    for k in spots:
        if k in spot_lower:
            spot_used = k
            break

    response = spots[spot_used]
    if score >= 3 or is_doctor:
        await ctx.send(response)
    else:
        await ctx.send("*He eyes the scratch tool. He wants it. He will not give you the satisfaction of admitting that. He turns away.* **mrr.**")

    # small injury chance
    if random.random() < 0.08:
        await asyncio.sleep(2)
        await ctx.send("*The scratch tool catches a snag in his wool. He flinches - a small, genuine ow - then shakes it off and goes back to requesting more scratches.* **mrrp.**")


