# !meme - teach him memes
# ==========================================
_KNOWN_MEMES = {}  # stores learned memes per session; also in db["internal"]["known_memes"]

@bot.command(name="meme", aliases=["teachmeme", "showmeme", "memeit"])
async def meme_cmd(ctx, *, meme_name: str = ""):
    """Teach Yarnaby a meme."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    meme_lower = (meme_name or "").lower().strip()
    known = m["internal"].setdefault("known_memes", [])

    HATE_MEMES = ["67", "sixty-seven", "sixty seven", "rule 34", "rule34", "gore", "jumpscare"]
    LOVE_MEMES = ["cat", "nyan cat", "nyan", "bread cat", "keyboard cat", "loaf", "yes chad", "chad"]
    CONFUSED_MEMES = ["shrek", "rickroll", "rick roll", "trollface", "troll", "doge", "dogecoin", "stonks"]

    if not meme_lower:
        if known:
            await ctx.send(f"*He has been shown: **{', '.join(known[-5:])}**. He has opinions about all of them.* **mrr.**")
        else:
            await ctx.send("*He hasn't been shown any memes yet. Try `!meme [meme name]`.* **mrr.**")
        return

    if any(w in meme_lower for w in HATE_MEMES):
        await ctx.send(
            f"*You show him **{meme_name}**. He recoils. He hisses. He pushes the screen away with his paw. "
            f"He is deeply, personally offended. He sits facing the wall.* **HSSSS. mrrow.**"
        )
        m["internal"].setdefault("hated_memes", []).append(meme_name)
        save_db(m)
        return

    if meme_lower in [m.lower() for m in known]:
        await ctx.send(f"*He already knows **{meme_name}**. He tilts his head and makes the sound he always makes when he sees it.* **mrr.**")
        return

    known.append(meme_name)
    if len(known) > 30:
        known.pop(0)

    if any(w in meme_lower for w in LOVE_MEMES):
        await ctx.send(
            f"*You show him **{meme_name}**. His eyes go wide. He leans closer to the screen. He chirps at it. "
            f"He paws the screen gently. He has decided this is his favourite thing.* **chrrp! prrr.**"
        )
    elif any(w in meme_lower for w in CONFUSED_MEMES):
        await ctx.send(
            f"*You show him **{meme_name}**. He stares. He tilts his head left. Then right. Then left again. "
            f"He looks at you for explanation. He receives none. He tilts his head again.* **...mrr?**"
        )
    else:
        await ctx.send(
            f"*You show him **{meme_name}**. He watches. He processes. He makes a small sound that could mean anything. "
            f"He has filed it away somewhere.* **mrr.**"
        )
    save_db(m)


