@bot.command(name="level", aliases=["lvl", "xp", "mylevel", "checklevel"])
async def level_cmd(ctx, user: discord.Member = None):
    """Check a user's level."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    if target is None:
        target = ctx.author
    u_id = str(target.id)
    data = m["social_matrix"].get(u_id, {})
    lvl = data.get("level", 1)
    xp = data.get("xp", 0)
    next_xp = lvl * 100

    await ctx.send(
        f"*Yarnaby glances at **{target.display_name}** and tilts his head. He counts in the way he counts - mostly just knowing.* "
        f"**Level {lvl}** | {xp}/{next_xp} XP **mrr.**"
    )


@bot.command(name="setlevel", aliases=["set_level", "forcelevel", "lvlset"])
async def setlevel_cmd(ctx, target: discord.Member = None):
    """Creator only: set a user's level."""
