# ==========================================
# !joinvc - join a voice channel
# ==========================================
@bot.command(name="joinvc", aliases=["join_vc", "joinvoice", "yarnabyvc", "vcjoin"])
async def joinvc_cmd(ctx, *, name: str = ""):
    """Make Yarnaby join your voice channel."""
    if not ctx.author.voice or not ctx.author.voice.channel:
        await ctx.send("*He tilts his head. You're not in a voice channel. He cannot follow you nowhere.* **mrr.**")
        return
    vc_channel = ctx.author.voice.channel
    try:
        if ctx.voice_client:
            await ctx.voice_client.move_to(vc_channel)
            vc = ctx.voice_client
        else:
            vc = await vc_channel.connect(timeout=30, reconnect=True)
        if hasattr(vc, "timeout"):
            try:
                vc.timeout = None
            except Exception:
                pass
        bot.db.setdefault("internal", {})["stay_in_vc_channel_id"] = str(vc_channel.id)
        save_db(bot.db)
        await ctx.send(
            f"*Yarnaby pads into **{vc_channel.name}** and settles in. He will stay until `!leavevc` or Discord removes him.* **prrr.**"
        )
    except Exception as e:
        await ctx.send(f"*He tries to join the voice channel and fails. He sits outside it, confused.* **mrr.** *(Error: {e})*")


@bot.command(name="leavevc", aliases=["leave_vc", "yarnabyout", "vcleave", "disconnectvc"])
async def leavevc_cmd(ctx, channel: discord.TextChannel = None):
    """Make Yarnaby leave the voice channel."""
    if ctx.voice_client:
        bot.db.setdefault("internal", {}).pop("stay_in_vc_channel_id", None)
        save_db(bot.db)
        await ctx.voice_client.disconnect(force=True)
        await ctx.send("*Yarnaby pads out of the voice channel without looking back. He has done what he came to do.* **mrr.**")
    else:
        await ctx.send("*He's not in a voice channel.* **mrr.**")


