# ==========================================
# !fbaddteam / !fbremoveteam - Superlig manual teams
# ==========================================
@bot.command(name="fbaddteam", aliases=["addteam", "superligadd", "promotedteam"])
async def fbaddteam_cmd(ctx, *, team_name: str = ""):
    """Creator only: manually add a team to the Superlig table."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That's The Creator's command.* **mrr.**")
        return
    if not team_name.strip():
        await ctx.send("*Give a team name.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    table = m["internal"].get("fb_manual_table", [])
    existing_names = [r["team"].lower() for r in table]
    if team_name.lower() in existing_names:
        await ctx.send(f"*{team_name} is already in the table.* **mrr.**")
        return
    new_pos = len(table) + 1
    table.append({
        "position": new_pos, "team": team_name, "matches": 0,
        "wins": 0, "draws": 0, "losses": 0,
        "gf": 0, "ga": 0, "gd": 0, "points": 0, "is_fb": False,
    })
    m["internal"]["fb_manual_table"] = table
    save_db(m)
    await ctx.send(f"*Yarnaby acknowledges **{team_name}**. He is added to the table. He watches them with cautious neutrality.* **mrr.**")


@bot.command(name="fbremoveteam", aliases=["removeteam", "superligremove", "relegatedteam"])
async def fbremoveteam_cmd(ctx, *, team_name: str = ""):
    """Creator only: remove a team from the Superlig table."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That's The Creator's command.* **mrr.**")
        return
    if not team_name.strip():
        await ctx.send("*Which team? `!fbremoveteam [team name]`* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    table = m["internal"].get("fb_manual_table", [])
    original_len = len(table)
    table = [r for r in table if r["team"].lower() != team_name.lower().strip()]
    if len(table) == original_len:
        await ctx.send(f"*He can't find **{team_name}** in the table.* **mrr.**")
        return
    m["internal"]["fb_manual_table"] = table
    save_db(m)
    await ctx.send(f"*Yarnaby watches **{team_name}** leave the table. He blinks once. He doesn't comment.* **...mrr...**")


# ==========================================
# !lap - fixed/registered version
# ==========================================
COOLDOWN_LAP = 45  # seconds

@bot.command(name="lap", aliases=["mylap", "claimyourlap", "sitonme", "comehere", "claimlap", "invitetolap", "lapinvite"])
async def lap_cmd(ctx):
    """Invite Yarnaby onto your lap. Score-gated; he may or may not come."""
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    your_name = getattr(ctx.author, "display_name", str(ctx.author))
    stage = _age_stage(_get_age_days(m))
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    is_helpless = m["internal"].get("helpless", False)

    # --- SLEEP ---
    if m["internal"]["is_sleeping"]:
        if is_doctor:
            await ctx.send(random.choice([
                "*He is asleep — but The Creator's voice reaches him somehow. "
                "He doesn't wake. He just gets up, eyes still mostly closed, "
                "pads over, and collapses into The Creator's lap with the reliability "
                "of something that does this on instinct. He is asleep again immediately. "
                "He never fully woke up.* **...prrr... zz.**",
                "*He's deeply asleep. The Creator calls him over anyway. "
                "He makes a sound — low, automatic — shifts, and somehow ends up "
                "draped across The Creator without either of them quite planning it. "
                "He is still asleep. His paw is on their arm.* **...prrr...**",
            ]))
        elif score >= 6:
            await ctx.send(random.choice([
                f"*{your_name} pats their lap. Yarnaby is asleep. "
                f"One ear rotates toward the sound. He doesn't fully wake. "
                f"He gets up, pads over in a half-conscious shuffle, turns once, "
                f"and drops. He is asleep again before he finishes landing.* **...mrr... zz.**",
                f"*He was asleep. He hears the invitation. Something in him files it. "
                f"He stumbles over without opening his eyes all the way "
                f"and settles into {your_name}'s lap with soft, boneless weight. "
                f"He does not wake up.* **...zz.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*He is asleep. He does not come. He does not stir. "
                f"He is committed to being asleep.* **...zz.**",
                f"*He is deeply, completely, stubbornly asleep. "
                f"He does not respond to {your_name}'s invitation.* **...zz.**",
            ]))
        return

    # --- HELPLESS ---
    if is_helpless:
        await ctx.send(random.choice([
            f"*He can't get up. He looks at {your_name}'s lap from the floor "
            f"with an expression that is unmistakably wistful. "
            f"He would. He genuinely would. He is down here.* **...mrr...**",
            f"*He tries to get up when {your_name} offers their lap. "
            f"He doesn't quite make it. He settles back down and stares at the space "
            f"where he'd rather be.* **...mrr...**",
        ]))
        return

    # --- COOLDOWN ---
    if not is_doctor:
        remaining = _cooldown_remaining(m, f"lap:{u_id}", COOLDOWN_LAP)
        if remaining:
            await ctx.send(f"*He just settled. Give him a moment.* **mrr.** *({remaining}s)*")
            return

    # --- CREATOR ---
    if is_doctor:
        if stage in ("Timeworn", "Ancient"):
            await ctx.send(random.choice([
                "*He doesn't hurry — he never hurries anymore — but he comes. "
                "He pads over to The Creator with the unhurried certainty of something "
                "that knows exactly where it belongs. He turns once. He lies down. "
                "He exhales the way old things exhale when they finally stop moving. "
                "He is here. He intends to stay.* **...prrrrr...**",
                "*The Creator offers their lap. He considers it for approximately one second "
                "— not hesitation, just the old deliberate way he does things now — "
                "and then he's there. Solid. Warm. His purr starts slowly and builds. "
                "He places one paw on their knee. He was always going to end up here.* **...prrrrr...**",
            ]))
        else:
            await ctx.send(random.choice([
                "*He was already moving before the lap was fully offered. "
                "He turns once — the minimum required — and drops himself down "
                "with the ease of something that considers this home. "
                "His purr is immediate and sincere.* **prrrrr.**",
                "*He comes over and headbutts The Creator's knee once, softly, "
                "then steps up and arranges himself across their lap with complete authority. "
                "He is here now. This is his lap now. This has always been his lap.* **prrrrr.**",
                "*He was sitting across the room. He saw the lap. He is in the lap. "
                "The steps between were a formality.* **chrrp. prrrrr.**",
                "*He needs approximately no convincing. He pads over, circles once, "
                "and installs himself with the easy weight of total trust. "
                "He tucks his nose under The Creator's arm. He is not moving.* **prrrrr.**",
            ]))

    # --- SCORE >= 8: high trust ---
    elif score >= 8:
        await ctx.send(random.choice([
            f"*He looks at {your_name}'s lap, looks at {your_name}, "
            f"and walks over with the quiet confidence of a creature that has done the math "
            f"and likes the answer. He turns once and settles. "
            f"His purr starts the moment he lands.* **...prrr...**",
            f"*He doesn't hesitate — he comes right over and steps up "
            f"into {your_name}'s lap, circles, and lies down with his chin on their knee. "
            f"He is warm and heavy and completely decided.* **prrr.**",
            f"*He trots over and climbs up without ceremony. "
            f"{your_name}'s lap has been determined acceptable. "
            f"He has been sitting there for two seconds and already looks like he's been there forever.* **prrrrr.**",
        ]))

    # --- SCORE 4–7: comfortable ---
    elif score >= 4:
        await ctx.send(random.choice([
            f"*He considers the invitation. He looks at {your_name}. "
            f"He pads over and steps up — carefully, not rushing — "
            f"and turns once before lying down. He makes a small sound. "
            f"He is comfortable. He won't say that, but he is.* **...prrr...**",
            f"*He comes over. He takes his time about it. "
            f"He steps into {your_name}'s lap with one careful paw, "
            f"then the other, and arranges himself. He blinks slowly. "
            f"He has decided this is fine.* **...mrr... prrr.**",
            f"*He hops up into {your_name}'s lap and sits there, upright, "
            f"watching the room. After a moment he lies down. After another moment, he purrs. "
            f"He got there eventually.* **...prrr...**",
        ]))

    # --- SCORE 1–3: uncertain ---
    elif score >= 1:
        await ctx.send(random.choice([
            f"*He looks at {your_name}'s lap for a long moment. "
            f"He pads over slowly and sniffs the knee first — as is his right — "
            f"and then steps up. He circles twice. He lies down with the posture "
            f"of something maintaining certain reservations.* **...mrr.**",
            f"*He's not sure. He walks toward {your_name}, stops, looks at the lap again, "
            f"walks the rest of the way, and climbs up. He does not immediately purr. "
            f"He watches the room instead. He stays.* **...mrr.**",
        ]))

    # --- SCORE 0: neutral stranger ---
    elif score == 0:
        await ctx.send(random.choice([
            f"*Yarnaby looks at {your_name}. He looks at the lap. "
            f"He looks back at {your_name}. He does not come. "
            f"He sits where he is and observes them from a respectful distance.* **mrr.**",
            f"*He's not coming. He doesn't know {your_name} well enough for laps. "
            f"He sits at a polite distance and blinks at them.* **mrr.**",
        ]))
        return

    # --- NEGATIVE SCORE: no ---
    else:
        await ctx.send(random.choice([
            f"*He sees {your_name} patting their lap. He looks at it. "
            f"He looks at {your_name}. He looks deliberately away. "
            f"He walks in the opposite direction.* **hff.**",
            f"*No. He is not doing that. Not with {your_name}. "
            f"He sits across the room and ignores the lap with intention.* **hff.**",
            f"*He glances at the lap. He glances at {your_name}. "
            f"He turns around and lies down somewhere completely different. "
            f"He's made his position clear.* **hff.**",
        ]))
        return

    # Update last_seen and cooldown for successful visits
    _set_cooldown(m, f"lap:{u_id}")
    entry = m["social_matrix"].setdefault(u_id, {"score": 0})
    entry["last_seen"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m)


# ==========================================
# Drunk check helper
# ==========================================
def _is_drunk(m) -> bool:
    drunk_until = m["internal"].get("drunk_until")
    if not drunk_until:
        return False
    try:
        return datetime.now() < datetime.strptime(drunk_until, "%Y-%m-%d %H:%M:%S")
    except Exception:
        return False


# ==========================================
# Injury / bruise / hurt system
# ==========================================
@bot.command(name="injuries", aliases=["hurts", "bruises", "wounds", "checkinjuries"])
async def injuries_cmd(ctx):
    """Check Yarnaby's current injuries — he reacts differently based on severity."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. You can see him breathing slowly. If there's something wrong, it'll wait.* **...zz.**",
            "*He sleeps. You can check when he wakes.* **...mrr.**",
        ]))
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*You offer your lap. He looks at it. He looks at you. He pads over slowly and settles into it — not because he chose it freely, but because it's warm and close and right now he needs something to be close to. He curls up small.* **...prrr...**",
            f"*He steps onto your lap and turns once and lies down. He's not relaxed. But he stays. He puts his chin on your knee. He closes his eyes.* **...mrr...**",
        ]))
        return


    injuries = m["internal"].get("injuries", [])
    untreated = [i for i in injuries if not i.get("treated")]

    if not untreated:
        await ctx.send(random.choice([
            "*He seems fine. Nothing on record. He eyes you with mild suspicion at being examined.* **mrr.**",
            "*No untreated injuries. He's okay. He would still like a treat for cooperating with this inspection.* **prrr.**",
            "*Clean bill of health, physically. He shakes himself after being checked, like he's resetting.* **prrr.**",
        ]))
        return

    # Sort by severity weight
    sev_order = {"critical": 0, "severe": 1, "serious": 2, "moderate": 3, "mild": 4, "minor": 5}
    untreated_sorted = sorted(untreated, key=lambda x: sev_order.get(x.get("severity","minor").lower(), 5))

    # Opening reaction — based on worst injury present
    worst = untreated_sorted[0]
    worst_sev = worst.get("severity", "minor").lower()

    if worst_sev in ("critical", "severe"):
        if is_doctor:
            await ctx.send(random.choice([
                "*The moment The Creator looks at him properly, something in his face changes — he lets them see it. "
                "He's been holding himself carefully. He's been managing. He stops managing.* **...mrr.**",
                "*He doesn't pull away when The Creator reaches for him. That alone tells you how bad it is. "
                "He usually flinches. He doesn't flinch.* **...mrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                "*He is very still when you approach. His breathing is shallow. He watches you with glassy eyes "
                "and does not move away. That's not normal for him.* **...mrr.**",
                "*Something is wrong enough that he's not pretending it isn't. He looks at you and makes "
                "a very small, very controlled sound.* **...mrrp.**",
            ]))
    elif worst_sev == "serious":
        if is_doctor:
            await ctx.send(random.choice([
                "*He lets The Creator see. He's been walking it off but it's past walking-off territory now. "
                "He doesn't protest the examination.* **...mrr.**",
                "*He turns so The Creator can look. He trusts them to assess it honestly.* **mrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                "*He allows you to look — which means it hurts enough that he's past the point of pretending it doesn't.* **mrr.**",
                "*He moves carefully. You can tell he's compensating for something.* **...mrr.**",
            ]))
    elif worst_sev == "moderate":
        await ctx.send(random.choice([
            "*He's bothered, but functional. He holds still long enough for you to check him.* **mrr.**",
            "*He lets you look, but flicks his ear to signal he's aware of every second of this.* **mrrp.**",
        ]))
    else:  # mild / minor
        await ctx.send(random.choice([
            "*He glances at you sidelong while you check him. He is fine. He would like you to know he is fine. "
            "He is clearly slightly not fine.* **mrr.**",
            "*He submits to the inspection with studied dignity. It is minor. He is treating it as minor.* **mrr.**",
        ]))

    await ctx.send("")  # spacer

    # Per-injury lines
    for inj in untreated_sorted[:5]:
        sev  = inj.get("severity", "minor").lower()
        typ  = inj.get("type", "injury")
        loc  = inj.get("location", "unknown location")
        cause = inj.get("caused_by", "")
        at   = inj.get("at", "")
        infected = inj.get("infected", False)

        # Check for infection (untreated > 1 day)
        if at and not infected:
            try:
                inj_time = datetime.strptime(at, "%Y-%m-%d %H:%M:%S")
                if (datetime.now() - inj_time).days >= 1:
                    inj["infected"] = True
                    infected = True
            except Exception:
                pass

        cause_str = f", from {cause.replace('_', ' ')}" if cause else ""
        time_str  = f" — {_time_ago(at)}" if at else ""

        # Severity-specific narration
        if sev in ("critical", "severe"):
            sev_emoji = "💀"
            if is_doctor:
                reaction = random.choice([
                    f"*He shows The Creator his {loc} without being asked. It is bad. He is letting them see how bad.* **...mrr.**",
                    f"*The {typ} on his {loc} — The Creator can see it clearly now. He doesn't flinch when they touch near it. He trusts them to fix it.* **...mrr.**",
                ])
            else:
                reaction = random.choice([
                    f"*His {loc}. The {typ}. He holds it away from the ground and watches you look at it with very flat, very tired eyes.* **...mrr.**",
                    f"*You can see the {typ} on his {loc}. He knows you can see it. He stops moving when you look.* **...mrrp.**",
                ])
        elif sev == "serious":
            sev_emoji = "🔴"
            reaction = random.choice([
                f"*The {typ} on his {loc} is worse than he's let on. He sits carefully. He doesn't complain.* **mrr.**",
                f"*He favours his {loc} without meaning to. The {typ} is real and it's been real for a while.* **...mrr.**",
            ])
        elif sev == "moderate":
            sev_emoji = "🟠"
            reaction = random.choice([
                f"*He pulls away slightly when you get near his {loc}. The {typ} isn't terrible but it's present.* **mrrp.**",
                f"*The {typ} on his {loc} earns a small sound when you check it. He recovers his composure immediately.* **mrr.**",
            ])
        elif sev == "mild":
            sev_emoji = "🟡"
            reaction = random.choice([
                f"*A {typ} on his {loc}. He licked it earlier. He is handling it.* **mrr.**",
                f"*He glances at his {loc} when you mention it. The {typ} isn't bad. He was hoping you wouldn't notice.* **mrrp.**",
            ])
        else:  # minor
            sev_emoji = "🟢"
            reaction = random.choice([
                f"*The {typ} on his {loc} is minor. He barely acknowledges it. He has had worse.* **mrr.**",
                f"*He shows you his {loc} for about half a second, then pulls it away. The {typ} is nothing. He is fine.* **mrr.**",
            ])

        infection_warn = "\n⚠️ *Showing signs of infection. Treat soon.*" if infected else ""
        await ctx.send(
            f"{sev_emoji} **{typ}** — *{loc}*{cause_str} *(severity: {sev})*{time_str}\n"
            f"{reaction}{infection_warn}"
        )

    save_db(m)

    # Footer
    if len(untreated) > 5:
        await ctx.send(f"*...and {len(untreated) - 5} more. Use `!treat` or `!vet` to help him.*")
    else:
        await ctx.send("*Use `!treat` to tend to him or `!vet` for a proper checkup.*")


@bot.command(name="treat", aliases=["treatwound", "healinjury", "bandage", "firstaid"])
async def treat_cmd(ctx):
    """Treat Yarnaby's injuries — his reaction depends on severity and who's treating."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. You can treat him gently without waking him — he barely stirs.* **...mrr.**",
            "*He sleeps through the treatment. His breathing evens out afterward.* **...zz.**",
        ]))
        # Treat anyway — he's asleep, doesn't resist
        injuries = m["internal"].get("injuries", [])
        untreated = [i for i in injuries if not i.get("treated")]
        for inj in untreated:
            inj["treated"] = True
            inj["treated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        m["stats"]["health"] = min(100, m["stats"].get("health", 100) + 5)
        save_db(m)
        return

    injuries = m["internal"].get("injuries", [])
    untreated = [i for i in injuries if not i.get("treated")]

    if not untreated:
        await ctx.send(random.choice([
            "*He's fine. Nothing to treat. He submits to the check anyway, then shakes himself off.* **prrr.**",
            "*No injuries right now. He tolerates the inspection with dignity.* **mrr.**",
        ]))
        return

    sev_order = {"critical": 0, "severe": 1, "serious": 2, "moderate": 3, "mild": 4, "minor": 5}
    untreated_sorted = sorted(untreated, key=lambda x: sev_order.get(x.get("severity","minor").lower(), 5))
    worst = untreated_sorted[0]
    worst_sev = worst.get("severity", "minor").lower()
    worst_type = worst.get("type", "injury")
    worst_loc  = worst.get("location", "")

    # Mark all treated
    for inj in untreated:
        inj["treated"] = True
        inj["treated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    health_gain = {"critical": 20, "severe": 15, "serious": 10, "moderate": 7, "mild": 4, "minor": 2}.get(worst_sev, 3)
    m["stats"]["health"] = min(100, m["stats"].get("health", 100) + health_gain)

    count = len(untreated)
    count_str = f"{count} injur{'ies' if count > 1 else 'y'}"

    # Reaction based on severity + who is treating
    if worst_sev in ("critical", "severe"):
        if is_doctor:
            await ctx.send(random.choice([
                f"*The Creator works carefully. Yarnaby is completely still — the kind of still that takes effort. "
                f"He watches their hands the whole time. When it's done he presses his face against them and stays there. "
                f"He doesn't say anything.* **...prrr.**",
                f"*He doesn't move during treatment. Not once. He trusts The Creator completely with his {worst_loc}. "
                f"When they finish he makes a sound so quiet it barely exists.* **...prrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*He holds still for you — which costs him something, you can tell. "
                f"The {worst_type} on his {worst_loc} is serious and he knows you're helping. "
                f"When you're done he blinks at you slowly. Once. That's a lot, from him.* **...mrr.**",
                f"*He lets you work. He watches your hands. He doesn't pull away. "
                f"When it's over he sits quietly for a moment before going back to normal.* **...mrr.**",
            ]))
    elif worst_sev == "serious":
        if is_doctor:
            await ctx.send(random.choice([
                f"*He goes still when The Creator starts. He's tense — he can't help it — but he doesn't resist. "
                f"He exhales slowly when the worst part is done. Then he leans.* **mrr. prrr.**",
                f"*The Creator treats his {worst_loc} carefully. He makes one small sound partway through "
                f"and then catches himself. He lets them finish.* **...mrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*He allows it. He stiffens once, when you reach the {worst_loc}, "
                f"then forces himself to stay still. When you're done he moves away and shakes himself off. "
                f"He doesn't say thank you. His eyes do.* **mrr.**",
                f"*He watches you work with serious, flat eyes. He doesn't make it difficult. "
                f"He doesn't make it easy either. When it's done he blinks once.* **mrr.**",
            ]))
    elif worst_sev == "moderate":
        if is_doctor:
            await ctx.send(random.choice([
                f"*He submits to treatment with moderate dignity. He makes one noise of protest at the worst part, "
                f"then remembers it's The Creator and settles.* **mrrp. prrr.**",
                f"*He goes still for The Creator. The {worst_type} is treated. He headbutts their hand when it's over.* **mrr. prrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*He eyes you the whole time. The {worst_type} is real enough that he lets you handle it. "
                f"When you finish he sniffs your hand once. Assessment passed.* **mrr.**",
                f"*He holds still, tail curling slightly at the worst moment. "
                f"He recovers his composure immediately after. He appreciates this.* **mrrp. mrr.**",
            ]))
    elif worst_sev == "mild":
        await ctx.send(random.choice([
            f"*He puts up token resistance to the bandaging of his {worst_loc} — mostly on principle — "
            f"then holds still when he realises you mean it. "
            f"He shakes the treated paw afterward like it was the bandage's fault.* **mrrp. mrr.**",
            f"*He accepts treatment with an air of mild inconvenience. "
            f"He is fine. He was always fine. He just lets you do this.* **mrr.**",
        ]))
    else:  # minor
        await ctx.send(random.choice([
            f"*He tolerates treatment of his {worst_loc} with tremendous personal suffering "
            f"that he makes very clear through his expression. It is minor. He is being very dramatic. "
            f"He sits still for it anyway.* **mrrp. mrr.**",
            f"*He pretends he doesn't need this. He holds perfectly still while you do it. "
            f"He pretends he didn't need that too.* **mrr. prrr.**",
            f"*He submits. Barely. With maximum eye contact and minimum cooperation. "
            f"He is healed. He shakes himself off like the whole event was beneath him.* **mrr.**",
        ]))

    if count > 1:
        await ctx.send(f"*({count_str} treated. He is in better shape now.)*")

    save_db(m)


