@bot.command(name="whisper_extended", aliases=["murmur", "quietly", "yarnywhisper", "shhh"])
async def whisper_extended_cmd(ctx, *, message: str = ""):
    """Whisper something to Yarnaby."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    msg_lower = (message or "").lower().strip()

    LEAVING_WORDS = ["im leaving", "i'm leaving", "i'm quitting", "i'm going away", "goodbye forever", "leaving forever"]
    UPDATE_WORDS = ["getting an update", "youre getting updated", "update coming", "new update"]
    LOVE_WORDS = ["i love you", "you're my favourite", "you're my favorite", "i love yarny"]

    if any(w in msg_lower for w in LEAVING_WORDS) and is_doctor:
        await ctx.send(
            "*Yarnaby goes very still. He heard that. His ears are flat. His tail curls tight. "
            "He looks at The Creator for a long time. He makes a very small, very quiet sound.* **...mrr...**"
        )
        return

    if any(w in msg_lower for w in UPDATE_WORDS) and is_doctor:
        await ctx.send(
            "*Yarnaby's ears perk forward. He looks around. He looks at his own paws. He makes a small, confused chirp "
            "- the sound of something bracing for change it doesn't quite understand.* **...chrrp?**"
        )
        return

    if any(w in msg_lower for w in LOVE_WORDS):
        if is_doctor:
            await ctx.send(
                "*Yarnaby hears the whisper. His ears fold soft. His head dips. He presses his whole face against The Creator's hand. "
                "He stays there.* **...prrr...**"
            )
        else:
            await ctx.send(
                "*He catches the whisper. He goes still for a moment. Then he turns his head and blinks at you very slowly. "
                "He gives you one quiet, careful headbutt.* **...prrr...**"
            )
        return

    # Generic whisper
    if not message:
        await ctx.send("*He tilts an ear toward you. Whisper what?* **mrr?**")
        return

    responses = [
        f"*Yarnaby's ear rotates toward your whisper. He listens. He blinks once. He files it away.* **mrr.**",
        f"*He leans his ear toward you and goes very still. Whatever you whispered, he heard it. He sits with it quietly.* **...mrr...**",
        f"*His head tilts. He catches the whisper. He makes a small acknowledging sound.* **mrp.**",
    ]
    await ctx.send(random.choice(responses))


