import threading as _threading, http.server as _http_server, io as _io_mod

def _start_status_server(port: int = 8080):
    """Serve a minimal status page for Replit preview, with port fallback."""
    html_bytes = _BOT_STATUS_HTML.encode("utf-8")

    class _Handler(_http_server.BaseHTTPRequestHandler):
        def do_GET(self):
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(html_bytes)))
            self.end_headers()
            self.wfile.write(html_bytes)

        def log_message(self, format: str, *args: Any) -> None:  # noqa: A002
            pass

    preferred = int(os.environ.get("PORT", port))
    ports = [preferred] + [p for p in range(preferred + 1, preferred + 6)]
    for candidate in ports:
        try:
            srv = _http_server.HTTPServer(("0.0.0.0", candidate), _Handler)
            t = _threading.Thread(target=srv.serve_forever, daemon=True)
            t.start()
            print(f"[status page] listening on :{candidate}")
            return
        except OSError as e:
            print(f"[status page] port {candidate} unavailable: {e}")
        except Exception as e:
            print(f"[status page] could not start on {candidate}: {e}")
            return

    print("[status page] no preview port available; bot will continue without it")

_start_status_server(port=8089)


