@bot.command(name="watch", aliases=["showvideo", "watchthis", "watchit", "makehimwatch"])
async def watch_cmd(ctx, *, content: str = ""):
    """Make Yarnaby watch something."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    content_lower = (content or "").lower().strip()

    if not content_lower:
        await ctx.send("*He tilts his head. Watch what?* **mrr?**")
        return

    # Log if it's a URL (treat as image if image-like)
    if content_lower.startswith("http"):
        _log_image(m, str(ctx.author.id), ctx.author.display_name, content, f"video/watch: {content[:60]}")
        save_db(m)

    # Pick reaction bucket
    bucket = "default"
    for key in WATCH_REACTIONS:
        if key in content_lower:
            bucket = key
            break

    response = random.choice(WATCH_REACTIONS[bucket])

    # Special nyan cat + creator combo
    if "nyan cat" in content_lower and is_doctor:
        response += "\n*The Creator is watching too. He presses against The Creator to share the screen. He is very close to the screen. He chirps once more at the Nyan Cat.* **CHRRP.**"

    await ctx.send(response)

    # Play roar SFX if watching horror in VC
    if "horror" in content_lower and ctx.guild:
        vc = _get_guild_vc(ctx.guild)
        await _play_sfx(vc, "roar")


