# !suggest - suggest a command; !answer_suggest - creator replies
# ==========================================
_pending_suggestions = {}  # suggestion_id -> {user_id, user_name, text}
_suggestion_counter = [0]

@bot.command(name="suggest", aliases=["suggestcommand", "suggestion", "ideafor"])
async def suggest_cmd(ctx):
    """Suggest a new command or feature. It gets sent to the Creator."""
    if not suggestion.strip():
        await ctx.send("*He tilts his head. Suggest what? Write your idea after `!suggest`.* **mrr?**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    store = m.setdefault("internal", {}).setdefault("pending_suggestions", {})
    _suggestion_counter[0] = max(_suggestion_counter[0], *(int(k) for k in store.keys())) if store else _suggestion_counter[0]
    _suggestion_counter[0] += 1
    s_id = _suggestion_counter[0]
    _pending_suggestions[s_id] = {
        "user_id": ctx.author.id,
        "user_name": ctx.author.display_name,
        "text": suggestion.strip(),
        "channel_id": ctx.channel.id,
        "guild_id": ctx.guild.id if ctx.guild else None,
    }
    store[str(s_id)] = _pending_suggestions[s_id]
    save_db(m)
    # Notify creator
    creator = bot.get_user(DOCTOR_ID)
    if creator is None:
        try:
            creator = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator = None
    if creator:
        try:
            await creator.send(
                f" **New suggestion #{s_id} from {ctx.author.display_name} ({ctx.author.id}):**\n"
                f"> {suggestion.strip()}\n\n"
                f"Reply with: `!answer_suggest {s_id} [your answer]`"
            )
        except Exception as e:
            print(f"[suggest] failed to DM creator: {e}")
    await ctx.send(
        f"*Yarnaby picks up your suggestion - carefully, like it might be important - and carries it off somewhere. "
        f"The Creator will see it. Suggestion ID: **#{s_id}**.* **mrr.**"
    )

@bot.command(name="answer_suggest", aliases=["answersuggest", "replysuggestion", "suggestion_reply"])
async def answer_suggest_cmd(ctx):
    """Creator only: reply to a suggestion and it gets DM'd to the suggester."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That's The Creator's command.* **mrr.**")
        return
    store = bot.db.setdefault("internal", {}).setdefault("pending_suggestions", {})
    if suggestion_id not in _pending_suggestions and str(suggestion_id) in store:
        _pending_suggestions[suggestion_id] = store[str(suggestion_id)]
    if suggestion_id not in _pending_suggestions:
        await ctx.send(f"*He searches his memory. Suggestion #{suggestion_id} not found. It may have already been answered or the bot restarted.* **mrr.**")
        return
    if not reply.strip():
        await ctx.send("*Write a reply after the suggestion ID.* **mrr.**")
        return
    entry = _pending_suggestions.pop(suggestion_id)
    store.pop(str(suggestion_id), None)
    save_db(bot.db)
    user = bot.get_user(entry["user_id"])
    if user is None:
        try:
            user = await bot.fetch_user(entry["user_id"])
        except Exception:
            user = None
    if user:
        try:
            await user.send(
                f"*Yarnaby arrives with something in his mouth. He drops it at your feet carefully. "
                f"It is a reply to your suggestion (#{suggestion_id}):*\n\n"
                f"**The Creator says:** {reply.strip()}\n\n"
                f"*He tilts his head, blinks once, and walks away.* **mrr.**"
            )
            await ctx.send(f"*Reply to suggestion #{suggestion_id} sent to {entry['user_name']}.* **mrr.**")
        except Exception:
            await ctx.send(f"*He tried to deliver the reply to {entry['user_name']} but couldn't reach them.* **mrr.**")
    else:
        await ctx.send(f"*He couldn't find {entry['user_name']} to deliver the reply.* **mrr.**")


