# ==========================================
# Feeding improvements - back-to-back same food tolerance
# ==========================================
# Track last food fed; if same food sent back to back, no complaint until 6+ times.

_last_fed = {}  # guild_id+user_id -> {"food": str, "count": int}

def _feed_repetition_check(guild_id: str, u_id: str, food: str) -> int:
    """Track repetition. Returns count of times same food given in a row."""
    key = f"{guild_id}:{u_id}"
    entry = _last_fed.get(key, {"food": "", "count": 0})
    if entry["food"].lower() == food.lower():
        entry["count"] += 1
    else:
        entry["count"] = 1
        entry["food"] = food
    _last_fed[key] = entry
    return entry["count"]


