# ==========================================
# !bump - bump command (Yarnaby bumps someone)
# ==========================================
@bot.command(name="bump", aliases=["headbump", "bumpinto", "bumphim", "headbutt"])
async def bump_cmd(ctx, target: Optional[discord.Member] = None):
    """Yarnaby bumps into someone (or you bump him)."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if target is None or target.id == bot.user.id:
        # Bump Yarnaby himself
        if is_doctor:
            await ctx.send(
                "*The Creator bumps Yarnaby gently. He tips sideways by about two inches. "
                "He rights himself. He bumps The Creator back immediately, harder.* **mrr.**"
            )
        elif score >= 6:
            await ctx.send(random.choice([
                "*You bump him. He bumps you back. This is apparently how this works now.* **mrr.**",
                "*He accepts the bump with dignity and returns a slow, deliberate headbutt.* **prrr.**",
                "*He bumps back. He sits. He considers this a successful interaction.* **mrr.**",
            ]))
        elif score >= 2:
            await ctx.send(random.choice([
                "*You bump him. He sways slightly. He gives you a measured look.* **mrr.**",
                "*He tolerates the bump. He does not return it. Yet.* **mrr.**",
            ]))
        else:
            await ctx.send("*He sidesteps before you reach him. He saw it coming.* **mrr.**")
        return

    # Bump Yarnaby into someone else
    t_score = 99 if target.id == DOCTOR_ID else m["social_matrix"].get(str(target.id), {}).get("score", 0)
    if t_score >= 5:
        await ctx.send(
            f"*Yarnaby pads over to {target.display_name} and bumps them with the side of his head - "
            f"firm, deliberate, warm. He stays leaning for a moment.* **prrr.**"
        )
    elif t_score >= 0:
        await ctx.send(
            f"*He approaches {target.display_name}, pauses, and gives them a very small bump. "
            f"He retreats immediately to evaluate their reaction.* **mrr.**"
        )
    else:
        await ctx.send(
            f"*He looks at {target.display_name}. He looks at you. He declines to bump them.* **mrr.**"
        )


# ==========================================
# !drag - drag him into/out of things
# ==========================================
@bot.command(name="drag", aliases=["draghim", "dragyarny", "pull", "pullyarny"])
async def drag_cmd(ctx, *, action: str = ""):
    """Drag Yarnaby somewhere or into something. Options: cuddle/snuggle, sleep, out."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    action_lower = (action or "").lower().strip()
    sleeping = m["internal"].get("is_sleeping", False)

    # Common drag sound - he always meows/makes noise
    async def _drag_noise():
        sounds = [
            "**MRRROW!**", "**mrrow! mrrow!**", "**MRROW. mrr.**",
            "**mrrp! mrrp!**", "**RROAWR!**", "**mrrow... mrr...**",
            "**mrrrow! prrr.**", "**mrrow! chrrp!**",
        ]
        return random.choice(sounds)

    noise = await _drag_noise()

    # --- Drag out of sleep ---
    if any(w in action_lower for w in ["sleep", "wake", "out of sleep", "wake up", "bed"]):
        if not sleeping:
            await ctx.send("*He's already awake. There's nothing to drag him out of.* **mrr.**")
            return
        if is_doctor:
            await ctx.send(
                f"*The Creator gently takes hold of Yarnaby and slides him across the floor. {noise} "
                f"He opens one eye. He sees The Creator. He makes a small, betrayed sound - then stands up. "
                f"He headbutts The Creator's hand once. Fine. He is awake.* **...mrr. prrr.**"
            )
        elif score >= 6:
            await ctx.send(
                f"*You drag him gently by his scruff - carefully. {noise} "
                f"He wakes, protests loudly, and then sees it's you. He blinks. He decides he was going to wake up anyway.* **mrrow! ...mrr.**"
            )
        elif score >= 2:
            await ctx.send(
                f"*You grab him carefully and slide him off his spot. {noise} "
                f"He scrambles upright and glares at you for a solid five seconds.* **MRROW! mrr.**"
            )
        else:
            await ctx.send(
                f"*You try to drag him out of sleep. {noise} "
                f"He wakes up, bites the air near your hand, and turns his back on you.* **MRRROW! HSSSS.**"
            )
        m["internal"]["is_sleeping"] = False
        save_db(m)
        return

    # --- Drag into cuddle/snuggle ---
    if any(w in action_lower for w in ["cuddle", "snuggle", "hug", "hold"]):
        if is_doctor:
            await ctx.send(
                f"*The Creator pulls Yarnaby in - there is a brief {noise} of protest - "
                f"then he goes completely limp. He curls against The Creator. He pretends he was already doing this.* **prrr. prrr.**"
            )
        elif score >= 7:
            await ctx.send(
                f"*You pull him into a cuddle. {noise} - and then he settles. "
                f"He goes boneless. He stays.* **prrr. prrr.**"
            )
        elif score >= 3:
            await ctx.send(
                f"*You drag him over. {noise} He's not fully against it. "
                f"He allows the cuddle but maintains a formal posture for about thirty seconds before slowly melting.* **...mrr. prrr.**"
            )
        elif score >= 0:
            await ctx.send(
                f"*You try to drag him into a cuddle. {noise} "
                f"He tolerates it for exactly four seconds before extracting himself with dignity.* **mrrow. mrr.**"
            )
        else:
            await ctx.send(
                f"*You reach for him. {noise} He is already three feet away. He does not come back.* **MRROW.**"
            )
        return

    # --- Generic drag (no specific target) ---
    if is_doctor:
        await ctx.send(
            f"*The Creator drags Yarnaby somewhere. {noise} "
            f"He goes, making his feelings known the entire way, but he goes. He trusts the destination.* **mrrow... mrr. prrr.**"
        )
    elif score >= 5:
        await ctx.send(
            f"*You drag Yarnaby. {noise} He complains loudly and continuously but does not actually resist that hard. "
            f"He ends up wherever you wanted him and acts like it was his idea.* **mrrow! mrr.**"
        )
    elif score >= 0:
        await ctx.send(
            f"*You try to drag him. {noise} He plants all four paws. You get him about two feet. "
            f"He glares at you from his new position.* **MRROW. mrr.**"
        )
    else:
        await ctx.send(
            f"*He sees you reaching. {noise} He leaves before you get there.* **MRRROW.**"
        )


