# ==========================================
# Keyword listener - "yarny" name response fix
# ==========================================
# Already in the existing keyword system (line 5112 confirms it).
# The on_message keyword handler already catches "yarny"/"yarnaby"/"naby".
# No additional patch needed - confirmed working.


# ==========================================
# Feed: air, inedibles, couch gift patches
# ==========================================
# These are added as constants to supplement the existing feed/gift systems.

_INEDIBLE_FEED_ITEMS = [
    "air", "nothing", "void", "wind", "oxygen", "nitrogen", "gas",
    "book", "books", "paper", "cardboard", "plastic", "metal", "rock", "stone",
    "glass", "wood", "fabric", "phone", "keyboard", "screen",
]

_COUCH_GIFT_ITEMS = [
    "couch", "sofa", "loveseat", "settee", "armchair", "beanbag",
    "cushion", "pillow", "blanket fort",
]

async def _handle_inedible_feed(ctx, item: str) -> bool:
    """Returns True if the item is inedible and we handled it."""
    item_lower = item.lower().strip()
    if any(w in item_lower for w in _INEDIBLE_FEED_ITEMS):
        responses = [
            f"*He sniffs the **{item}**. He looks at you. He looks at the **{item}**. "
            f"He is not going to eat that. He blinks once, slowly, and walks away.* **mrr.**",
            f"*You offer **{item}**. He approaches. He sniffs. His ear twitches. "
            f"He sits back down. He will not be eating **{item}** today. Or any day.* **mrr.**",
            f"*He stares at the **{item}** for a long moment. He stares at you. "
            f"He would like something edible, please.* **mrr.**",
        ]
        if "air" in item_lower or "oxygen" in item_lower or "wind" in item_lower:
            responses = [
                "*He opens his mouth. He breathes. He closes his mouth. He looks at you. "
                "He has consumed the air. This changes nothing. He is still hungry.* **mrr.**",
                "*He sniffs the air you've offered. He always sniffs the air. "
                "He doesn't know why you're acting like this is special.* **mrr.**",
            ]
        await ctx.send(random.choice(responses))
        return True
    return False

async def _handle_couch_gift(ctx, item: str) -> bool:
    """Returns True if item is furniture and we handled it as a gift."""
    item_lower = item.lower().strip()
    if any(w in item_lower for w in _COUCH_GIFT_ITEMS):
        responses = [
            f"*You present Yarnaby with a **{item}**. He approaches it cautiously. "
            f"He sniffs every corner. He kneads it twice. He turns three circles. He lies down. "
            f"He has accepted the **{item}**. It is his now.* **prrr.**",
            f"*He sees the **{item}**. He walks around it once. He sits on top of it immediately. "
            f"He does not look at you but his tail tip is moving. He is pleased.* **prrr.**",
            f"*He jumps onto the **{item}** before you've even finished offering it. "
            f"He kneads it three times. He lies down. He blinks slowly.* **prrr. prrr.**",
        ]
        await ctx.send(random.choice(responses))
        m = bot.db
        u_id = str(ctx.author.id)
        m["social_matrix"].setdefault(u_id, {})["score"] = min(
            100, m["social_matrix"].get(u_id, {}).get("score", 0) + 1
        )
        save_db(m)
        return True
    return False


# ==========================================
# !while_you_were_gone - enhanced version
# ==========================================
@bot.command(name="while_you_were_gone_v2",
             aliases=["whatidhappen", "whatimiss", "summarise", "summary_gone", "wyg2"])
async def while_you_were_gone_v2_cmd(ctx):
    """Enhanced: full summary of what happened while creator was away."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That's The Creator's command.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot respond right now.*",
                "*He is sleeping. He will hear you when he wakes.*",
                "*He is asleep. The words reach him as a distant murmur.*",
            ])
        )
        return
    log = m["internal"].get("away_log", [])
    if not log:
        await ctx.send("*He tilts his head. The log is empty - nothing was recorded while you were away, or he was offline.* **mrr.**")
        return

    joins = [e for e in log if e["type"] == "join"]
    leaves = [e for e in log if e["type"] == "leave"]
    bans = [e for e in log if e["type"] == "ban"]
    mentions = [e for e in log if e["type"] in ("mention", "creator_mention")]
    feed_events = [e for e in log if e["type"] == "feed"]
    injury_events = [e for e in log if e["type"] == "injury"]

    lines = ["*Yarnaby sits very still and thinks carefully. He tells you what he remembers, in his way:*\n"]
    if joins:
        lines.append(f"**Joins:** {len(joins)} - {', '.join(e['author_name'] for e in joins[-5:])}{' ...' if len(joins) > 5 else ''}")
    if leaves:
        lines.append(f"**Left/removed:** {len(leaves)} - {', '.join(e['author_name'] for e in leaves[-5:])}{' ...' if len(leaves) > 5 else ''}")
    if bans:
        lines.append(f"**Bans:** {len(bans)} - {', '.join(e['author_name'] for e in bans[-5:])}{' ...' if len(bans) > 5 else ''}")
    if mentions:
        lines.append(f"**Times your name was mentioned:** {len(mentions)}")
        for e in mentions[-3:]:
            lines.append(f"  - {e['author_name']}: \"{e['excerpt'][:80]}\"")
    if injury_events:
        lines.append(f"**He got hurt {len(injury_events)} time(s) while you were gone.**")
    if feed_events:
        lines.append(f"**He was fed {len(feed_events)} time(s).**")
    if not any([joins, leaves, bans, mentions, injury_events, feed_events]):
        lines.append("*It was quiet. Very quiet. He waited.*")

    lines.append("\n*He blinks at you. He is glad you are back.* **...prrr...**")
    await ctx.send("\n".join(lines))
    # Clear log after reading
    m["internal"]["away_log"] = []
    save_db(m)


# ==========================================
# Mischievous ambient - periodic random pestering
# ==========================================
# This fires randomly from the existing wander/ambient tick
# when his mood is "mischievous" or "playful"

async def _maybe_mischief_ambient(bot_instance):
    """Called from the ambient tick - random chance to pester someone."""
    m = bot_instance.db
    if m["internal"].get("is_sleeping"):
        return
    mood = m["stats"].get("mood", "Content")
    if mood not in ("Playful", "Mischievous", "Energetic"):
        return
    if random.random() > 0.12:  # 12% chance per ambient tick
        return

    # Pick a random user from social matrix
    sm = m.get("social_matrix", {})
    candidates = [uid for uid, data in sm.items()
                  if isinstance(data, dict) and data.get("score", 0) >= 2]
    if not candidates:
        return

    target_id = random.choice(candidates)
    target_name = sm[target_id].get("display_name", "someone")

    ch_id = m["internal"].get("home_channel_id") or m["internal"].get("original_home_channel_id")
    if not ch_id:
        return
    try:
        ch = bot_instance.get_channel(int(ch_id))
        if ch:
            lines = [
                f"*Yarnaby has decided that {target_name} needs attending to right now. "
                f"He pads over and pats them twice. He meows once. He waits.* **mrrow.**",
                f"*Without warning, Yarnaby sits directly in front of {target_name} and stares. "
                f"He pats their arm once. He meows.* **mrrow.**",
                f"*He finds {target_name} and knocks something small off the nearest surface near them. "
                f"He watches it fall. He looks at them. He walks away.* **mrr.**",
            ]
            await ch.send(random.choice(lines))
    except Exception:
        pass


