    """Called from wandering_instincts - 8% chance per tick to make a random sound."""
    if random.random() > 0.08:
        return
    m = bot_instance.db
    if m["internal"].get("is_sleeping"):
        return
    text, sfx_key = random.choice(_RANDOM_SOUND_EVENTS)
