@bot.command(name="teachdoor", aliases=["doorlesson", "teacopen", "learnopen"])
async def teachdoor_cmd(ctx):
    """Teach Yarnaby a step of door-opening."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    if not is_doctor:
        await ctx.send("*He tilts his head. He learns door lessons from The Creator.* **mrr.**")
        return

    lessons_done = m["internal"].setdefault("door_lessons", [])
    remaining = [l for l in _DOOR_LESSONS if l[0] not in lessons_done]

    if not remaining:
        await ctx.send(
            "*He already knows everything. He opens doors now. He opens them confidently. "
            "He opens them when you want him to and also when you don't.* **chrrp.**"
        )
