# ==========================================
# !jealous - he gets jealous of attention
# ==========================================
@bot.command(name="jealous", aliases=["jealousy", "envious", "jelly", "yarnjealous"])
async def jealous_cmd(ctx, target: Optional[discord.Member] = None):
    """Yarnaby gets jealous of someone getting too much attention."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return

    target_name = target.display_name if target else "someone"

    if is_doctor:
        await ctx.send(random.choice([
            f"*The Creator is giving {target_name} attention. Yarnaby watches this for approximately four seconds before walking directly between them and sitting down. He faces The Creator. He does not acknowledge {target_name}.* **mrr.**",
            f"*Yarnaby sees The Creator looking at {target_name}. He walks over and places one paw on The Creator's knee. Just one paw. A reminder. He is here.* **...mrr.**",
            f"*He watches The Creator interact with {target_name}. He approaches slowly. He sits on The Creator's feet. He begins to purr at maximum volume. This is not subtle.* **PRRRRR.**",
        ]))
    elif score >= 6:
        await ctx.send(random.choice([
            f"*Yarnaby notices {target_name} getting a lot of attention. His tail flicks once. He walks over and inserts himself into the situation completely.* **mrr.**",
            f"*He watches {target_name} for a moment. Then he walks over to you and bumps your hand with his head. He was here first.* **mrr.**",
            f"*He sees what's happening with {target_name}. He sits between you and them. He stares forward. He is not jealous. He is simply sitting here. In this spot. Right here.* **...mrr.**",
        ]))
    elif score >= 2:
        await ctx.send(random.choice([
            f"*He glances at {target_name}. He glances at you. He looks away. His tail tip moves. He is fine. He is completely fine.* **mrr.**",
            f"*He watches {target_name} receive attention. He sits very upright. He looks at a completely different direction. He is unbothered.* **...mrr...**",
        ]))
    else:
        await ctx.send(f"*He looks at {target_name} getting attention. He looks away. He was not interested anyway.* **mrr.**")


# ==========================================
# !showoff - he does something impressive
# ==========================================
@bot.command(name="showoff", aliases=["showhimoff", "impressive", "yarnshowoff", "trick"])
async def showoff_cmd(ctx):
    """Yarnaby does something impressive then pretends he wasn't trying."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return

    tricks = [
        ("jumps from a standing position onto a surface twice his height", "lands perfectly, four paws together"),
        ("balances on the narrow edge of something for exactly seven seconds", "steps off like it was nothing"),
        ("catches something mid-air with one paw", "sets it down carefully and walks away"),
        ("opens a door, walks through, and closes it behind him", "does not look back"),
        ("does a perfect silent landing from a significant height", "shakes one ear and continues"),
        ("solves a puzzle toy in under thirty seconds", "pushes it aside and acts like he was just passing through"),
        ("performs an immaculate grooming sequence without stopping once", "finishes and stares at the wall"),
    ]

    trick, landing = random.choice(tricks)

    if is_doctor:
        await ctx.send(
            f"*Yarnaby {trick}. He {landing}. He does not look at The Creator. "
            f"He absolutely looked at The Creator for exactly one moment. He will not confirm this.* **...mrr.**"
        )
    elif score >= 6:
        await ctx.send(
            f"*He {trick}. He {landing}. He sits down and begins grooming his ear. "
            f"He definitely knew you were watching. He definitely did that on purpose.* **mrr.**"
        )
    elif score >= 2:
        await ctx.send(
            f"*He {trick}. He {landing}. He glances in your direction for half a second. "
            f"He looks away. That was not for you. That was just something he does.* **mrr.**"
        )
    else:
        await ctx.send(
            f"*He {trick}. He {landing}. He does not look at you at all. "
            f"You were not supposed to see that.* **mrr.**"
        )


# ==========================================
# !mirror - he sees his reflection
# ==========================================
@bot.command(name="mirror", aliases=["reflection", "seehimself", "yarnyreflection", "lookingglass"])
async def mirror_cmd(ctx):
    """Yarnaby encounters his own reflection."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)
    helpless = m["internal"].get("helpless", False)
    await _add_reactions(ctx, m)

    # --- SLEEP ---
    if sleeping:
        await ctx.send(random.choice([
            "*You hold the mirror in front of him while he sleeps. His nose twitches once. "
            "His ear rotates toward the glass. One eye slits open, registers his own reflection, "
            "and closes again. He will think about this later.* **...zz.**",
            "*He is asleep. The mirror reflects a small, curled creature. He doesn't stir. "
            "The other Yarnaby in the glass doesn't stir either.* **...zz.**",
        ]))
        return

    # --- HELPLESS ---
    if helpless:
        await ctx.send(random.choice([
            "*You hold the mirror in front of him and he cannot look away. "
            "He stares at his own reflection. It stares back. "
            "Something moves behind his eyes — something old and unsettled. "
            "He makes a small, involuntary sound.* **...mrr?**",
            "*He is forced to look at himself. He looks for longer than he'd choose to. "
            "The other Yarnaby in the glass looks just as trapped. "
            "He does not find this comforting.* **...mrr...**",
        ]))
        return

    stage = m["internal"].get("mirror_stage", 0)
    m["internal"]["mirror_stage"] = (stage + 1) % 5
    save_db(m)

    if stage == 0:
        await ctx.send(
            "*Yarnaby sees something in the mirror. He freezes. His ears go fully forward. "
            "He leans closer. There is another Yarnaby in there. "
            "He does not know what to do with this information.* **...mrr?**"
        )
    elif stage == 1:
        await ctx.send(
            "*He approaches the mirror again. He raises one paw. The other Yarnaby raises one paw. "
            "He raises the other paw. The other Yarnaby raises the other paw. "
            "He stares at it for a long time.* **...mrr...**"
        )
    elif stage == 2:
        await ctx.send(
            "*He sniffs the mirror. The other Yarnaby sniffs back. He sniffs harder. "
            "He presses his nose against the glass. He does not understand why it smells like nothing.* **mrr?**"
        )
    elif stage == 3:
        if score >= 5:
            await ctx.send(
                "*He sits in front of the mirror for a while. He looks at himself. He looks for a long time. "
                "Something passes behind his glass eyes — recognition, or a question he doesn't have words for. "
                "He blinks. He glances at you. He walks away.* **...mrr...**"
            )
        else:
            await ctx.send(
                "*He sits in front of the mirror and stares at himself for an uncomfortably long time. "
                "His tail lashes once. He gets up and leaves.* **...mrr.**"
            )
    else:
        if is_doctor:
            await ctx.send(
                "*He walks past the mirror and glances at it. He stops. He looks at The Creator's reflection. "
                "He looks at his own. He looks at The Creator's again. "
                "He pads away, satisfied with something he cannot explain.* **...prrr...**"
            )
        elif score >= 6:
            await ctx.send(
                "*He catches his own eye in the mirror and pauses. He blinks at his reflection — "
                "the slow, deliberate kind. Then he glances at you sideways, as if checking you saw that.* **...mrr.**"
            )
        elif score >= 2:
            await ctx.send(
                "*He passes the mirror and catches his own eye. He stops. Holds his gaze for a moment. "
                "Then he blinks slowly at his own reflection and walks on.* **...mrr...**"
            )
        else:
            await ctx.send(
                "*He sees himself in the mirror and hisses. He hisses at his own reflection. "
                "He hisses again for good measure. He does not understand why it keeps doing that back.* **HSS. HSS.**"
            )


