@bot.command(name="chiropractor", aliases=["adjust", "crackback", "backcrack", "spinepop", "chiro"])
async def chiropractor_cmd(ctx):
    """Give Yarnaby a chiropractic adjustment."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He doesn't stir.*",
                "*He is deeply asleep. His wool rises and falls slowly.*",
                "*He doesn't respond. He's somewhere far away in sleep.*",
            ])
        )
        return

    if is_doctor:
        await ctx.send(
            "*The Creator carefully positions Yarnaby. He goes completely still — he trusts this entirely. "
            "A gentle, precise adjustment along his spine. Something pops. His eyes go wide. "
            "Then he exhales very slowly and his entire body softens. He presses against The Creator.* **...prrr...**"
        )
    elif score >= 7:
        await ctx.send(random.choice([
            "*You position yourself carefully. Yarnaby allows it — he goes limp and cooperative. The adjustment happens. Something pops satisfyingly. His whole body relaxes.* **...mrrrmmm...**",
            "*He lets you work on his spine. A click, a shift, a release. He blinks very slowly afterward and sits with the energy of something deeply sorted out.* **prrr.**",
        ]))
    elif score >= 3:
        await ctx.send("*He tolerates the adjustment with dignity. Something clicks. He twitches. He shakes it off. He seems lighter.* **mrr.**")
    else:
        await ctx.send("*He sees you approaching with intent and walks away. His spine is fine. He is leaving.* **mrr.**")

    injuries = m["internal"].get("injuries", [])
    back_injuries = [i for i in injuries if "back" in i.get("location", "") or "spine" in i.get("location", "")]
