# !opinion — he gives his opinion on anything
@bot.command(name="opinion", aliases=["whatdoyouthink", "yarnyopinion", "hisopinion", "askopinion"])
async def opinion_cmd(ctx, *, thing: str = ""):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He doesn't stir.*",
                "*He is deeply asleep. His wool rises and falls slowly.*",
                "*He doesn't respond. He's somewhere far away in sleep.*",
            ])
        )
        return
    thing = (thing or "that").strip()
    thing_lower = thing.lower()

    STRONG_LIKES = ["fish", "salmon", "tuna", "chicken", "steak", "warm", "wool", "sleep", "nap", "creator", "adidas"]
    STRONG_DISLIKES = ["water", "bath", "dog", "loud", "alarm", "vacuum", "monday"]
    CONFUSED = ["math", "philosophy", "politics", "economy", "taxes", "wifi", "internet"]

    if any(w in thing_lower for w in STRONG_LIKES):
        await ctx.send(random.choice([
            f"*He considers **{thing}** very seriously. He sits up straighter. His tail rises. His opinion is: yes. Strongly yes.* **prrr.**",
            f"*He hears **{thing}** and his ears go fully forward. He has always had positive feelings about this. He stands by them.* **chrrp. prrr.**",
        ]))
    elif any(w in thing_lower for w in STRONG_DISLIKES):
        await ctx.send(random.choice([
            f"*He hears **{thing}**. His ears go back. His tail flicks once. His opinion is no. Firmly no. He does not elaborate.* **mrr.**",
            f"*He thinks about **{thing}** for a moment. He has thought about it. He does not like it. He is done thinking about it.* **hff.**",
        ]))
    elif any(w in thing_lower for w in CONFUSED):
        await ctx.send(random.choice([
            f"*He tilts his head at **{thing}**. He tilts it the other way. He makes a small uncertain sound. He does not have a formed opinion on this yet.* **...mrr?**",
            f"*He stares into the middle distance when **{thing}** is mentioned. Something is processing. It takes a while. No conclusion is reached.* **...mrr...**",
        ]))
    elif is_doctor:
        await ctx.send(f"*He looks at The Creator when **{thing}** is mentioned. He blinks once. Whatever The Creator thinks, he probably thinks too. He is not saying that out loud.* **...prrr...**")
    else:
        opinions = [
            f"*He sniffs in the direction of **{thing}**. He tilts his head. His tail moves once. He seems cautiously neutral.* **mrr.**",
            f"*He listens to **{thing}** being said. He thinks about it. He blinks. Opinion filed somewhere internal. He is not sharing it.* **mrr.**",
            f"*He has thoughts about **{thing}**. He keeps them to himself. His ear flick says everything.* **mrr.**",
        ]
        await ctx.send(random.choice(opinions))


