# !map — show explored rooms
@bot.command(name="map", aliases=["factorymap", "exploredrooms", "yarnymap", "showmap"])
async def map_cmd(ctx):
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    explored = m["internal"].get("explored_rooms", [])
    total = 10
    if not explored:
        await ctx.send(f"*He hasn't explored any hidden rooms yet. Use `!explore` to start.* **mrr.**\n*(0/{total} rooms found)*")
        return
    lines = [f"*Yarnaby's explored rooms ({len(explored)}/{total}):*"]
    for room in explored:
        lines.append(f"• {room}")
    remaining = total - len(explored)
    if remaining > 0:
        lines.append(f"\n*{remaining} room(s) still undiscovered.*")
    else:
        lines.append("\n*He has found everything. The factory holds no more secrets from him.*")
    await ctx.send("\n".join(lines))


