# !seek — find him when hiding
@bot.command(name="seekyarny", aliases=["findyarny", "wheresyarny", "lookhim", "seekout_yarny"])
async def seekyarny_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    # Check both hiding systems: yarnaby_hiding flag AND hideandseek minigame state
    minigame_hide = m["internal"].get("minigame_state", {}).get("hideandseek")
    if not m["internal"].get("yarnaby_hiding") and not minigame_hide:
        await ctx.send("*He is not hiding right now. He is right here. He has always been right here.* **mrr.**")
        return

    # Prefer minigame spot if that's what triggered the hide
    if minigame_hide:
        spot = minigame_hide.get("spot", "somewhere")
    else:
        spot = m["internal"].get("yarnaby_hiding_spot", "somewhere")

    if is_doctor:
        m["internal"]["yarnaby_hiding"] = False
        m["internal"]["yarnaby_hiding_spot"] = None
        if minigame_hide:
            m["internal"]["minigame_state"]["hideandseek"] = None
        save_db(m)
        await ctx.send(
            f"*The Creator finds him immediately — or maybe he let himself be found. "
            f"He was **{spot}**. He emerges and presses against The Creator's leg.* **prrr.**"
        )
    elif score >= 5:
        m["internal"]["yarnaby_hiding"] = False
        m["internal"]["yarnaby_hiding_spot"] = None
        if minigame_hide:
            m["internal"]["minigame_state"]["hideandseek"] = None
        save_db(m)
        await ctx.send(
            f"*After some searching, you find him. He was **{spot}**. "
            f"He looks at you as if to say he was not hiding, he was simply there. "
            f"He was definitely hiding.* **mrr.**"
        )
    else:
        await ctx.send(
            f"*You search. You don't find him. He is somewhere in this factory and he is not coming out for you.* **...mrr...**"
        )


