# !bestfriend — shows his current best friend
@bot.command(name="bestfriend", aliases=["hisbestfriend", "topfriend", "whohedoeshelike_most", "favperson"])
async def bestfriend_cmd(ctx):
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    sm = m.get("social_matrix", {})
    if not sm:
        await ctx.send("*He tilts his head. He hasn't met enough people yet to decide.* **mrr.**")
        return
    best = max(sm.items(), key=lambda kv: kv[1].get("score", 0) if isinstance(kv[1], dict) else 0, default=(None, {}))
    if not best[0]:
        await ctx.send("*He hasn't decided on a best friend yet.* **mrr.**")
        return
    best_id = best[0]
    best_name = best[1].get("display_name", "someone") if isinstance(best[1], dict) else "someone"
    best_score = best[1].get("score", 0) if isinstance(best[1], dict) else 0
    if int(best_id) == DOCTOR_ID:
        await ctx.send(f"*Without hesitation: The Creator. It has always been The Creator. It will always be The Creator.* **prrr.**")
    elif best_score >= 7:
        await ctx.send(f"*He thinks about it for exactly zero seconds. **{best_name}**. He doesn't need to think about it.* **prrr.**")
    elif best_score >= 4:
        await ctx.send(f"*He considers. He thinks about who has been around. He thinks about who has been kind. **{best_name}**.* **mrr.**")
    else:
        await ctx.send(f"*He tilts his head. The best he has right now is **{best_name}**. He is still deciding how he feels about that.* **mrr.**")


# !family — Creator designates family members
@bot.command(name="family", aliases=["setfamily", "familymember", "addfamily", "hisfamily"])
async def family_cmd(ctx, action: str = "", target: Optional[discord.Member] = None):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    action_lower = action.lower().strip()

    if action_lower == "list" or not action_lower:
        family = m["internal"].get("family_members", [])
        if not family:
            await ctx.send("*No family members set yet. Creator can use `!family add @user`.* **mrr.**")
            return
        names = []
        for fid in family:
            member = ctx.guild.get_member(int(fid)) if ctx.guild else None
            names.append(member.display_name if member else f"user {fid}")
        await ctx.send(f"*Yarnaby's family: **{', '.join(names)}**. He treats them with extra warmth.* **prrr.**")
        return

    if not is_doctor:
        await ctx.send("*Only The Creator can set family members.* **mrr.**")
        return

    if not target:
        await ctx.send("*Mention someone. `!family add @user` or `!family remove @user`.* **mrr.**")
        return

    family = m["internal"].setdefault("family_members", [])
    t_id = str(target.id)

    if action_lower == "add":
        if t_id not in family:
            family.append(t_id)
            save_db(m)
            await ctx.send(f"*Yarnaby looks at {target.display_name}. Something settles. They are family now. He presses against them briefly.* **prrr.**")
        else:
            await ctx.send(f"*{target.display_name} is already family.* **mrr.**")
    elif action_lower == "remove":
        if t_id in family:
            family.remove(t_id)
            save_db(m)
            await ctx.send(f"*Yarnaby blinks. The Creator has adjusted something. He processes this quietly.* **...mrr...**")
        else:
            await ctx.send(f"*{target.display_name} isn't in the family list.* **mrr.**")


# !checkup — full health report
@bot.command(name="checkup", aliases=["fullcheckup", "healthreport", "yarnycheck", "medcheck"])
async def checkup_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    stats = m["stats"]
    health = stats.get("health", 100)
    hunger = stats.get("hunger", 0)
    tiredness = stats.get("tiredness", 0)
    mood = stats.get("mood", "Content")
    cleanliness = stats.get("cleanliness", 0)
    injuries = [i for i in m["internal"].get("injuries", []) if not i.get("treated")]
    infected = any(i.get("infected") for i in injuries)
    drunk = _is_drunk(m)
    tape = m["internal"].get("tape_on_head", False)
    cone = m["internal"].get("wearing_cone", False)

    lines = ["*Full checkup on Yarnaby — Experiment 1166:*\n"]
    lines.append(f"❤️ **Health:** {health}/100 {'⚠️' if health < 50 else '✅'}")
    lines.append(f"🍖 **Hunger:** {hunger}/10 {'⚠️' if hunger >= 7 else '✅'}")
    lines.append(f"😴 **Tiredness:** {tiredness}/10 {'⚠️' if tiredness >= 8 else '✅'}")
    lines.append(f"🧼 **Cleanliness:** {'Dirty' if cleanliness >= 5 else 'Clean'} ({cleanliness}/10)")
    lines.append(f"🧠 **Mood:** {mood}")
    if injuries:
        lines.append(f"🩹 **Injuries:** {len(injuries)} untreated {'⚠️ (infected!)' if infected else ''}")
    if drunk:
        lines.append("🍺 **Currently drunk** — wobbling around")
    if tape:
        lines.append("📼 **Has tape on head** — still trying to remove it")
    if cone:
        lines.append("🔵 **Wearing cone** — walking into walls")

    await ctx.send("\n".join(lines))


