# !copycat — he copies what the last person said in mrows
@bot.command(name="copycat", aliases=["mimicspeak", "yarncopy", "mrowcopy", "copywhat"])
async def copycat_cmd(ctx):
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    # Get last message content from channel history
    last_msg = None
    try:
        async for msg in ctx.channel.history(limit=5):
            if msg.author.id != bot.user.id and msg.id != ctx.message.id and msg.content:
                last_msg = msg.content
                break
    except Exception:
        pass

    if not last_msg:
        await ctx.send("*He tilts his head. There is nothing recent to copy.* **mrr.**")
        return

    # Convert to mrows
    words = last_msg.split()
    mrow_words = []
    for word in words[:8]:  # limit length
        length = len(word)
        if length <= 2:
            mrow_words.append("mrr")
        elif length <= 4:
            mrow_words.append("mrow")
        elif length <= 6:
            mrow_words.append("mrrow")
        else:
            mrow_words.append("mrrrrow")
    mrow_sentence = " ".join(mrow_words)

    await ctx.send(
        f"*Yarnaby listens carefully. He opens his mouth. He makes a sound that is clearly meant to be what was just said:*\n"
        f"**{mrow_sentence}.**\n"
        f"*He looks very pleased with this. He nailed it.*  **mrr.**"
    )


