# !translate — he tries to say something in English, fails completely
@bot.command(name="translate", aliases=["translatehim", "speakEnglish", "whatdidyousay", "yarntranslate"])
async def translate_cmd(ctx, *, phrase: str = ""):
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    phrase = (phrase or "hello").strip()
    words = phrase.lower().split()

    # He tries each word but butchers them
    attempts = []
    for word in words[:6]:
        roll = random.random()
        if roll < 0.15:
            # Actually gets it right somehow
            attempts.append(f"**{word}**")
        elif roll < 0.4:
            # Gets the first letter right
            garbled = word[0] + "".join(random.choice(["mr", "rr", "ow", "mh", "rr"]) for _ in range(len(word)-1))
            attempts.append(f"**{garbled[:len(word)+2]}**")
        else:
            # Full mrow
            attempts.append(f"**{'mrr' if len(word) < 4 else 'mrrrow' if len(word) < 7 else 'mrrrrow'}**")

    attempt_str = " ".join(attempts)
    await ctx.send(
        f"*You ask Yarnaby to say \"**{phrase}**\". He listens carefully. He takes a breath. He tries:*\n"
        f"{attempt_str}\n"
        f"*He looks at you expectantly. He believes he got it.* **mrr.**"
    )

