@bot.command(name="set_gender", aliases=["setgender", "genderset", "yarngender", "changesex"])
async def set_gender_cmd(ctx):
    """Creator only: set Yarnaby's gender for this server."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That is The Creator's command.* **mrr.**")
        return
    gender = gender.lower().strip()
    if gender not in ("male", "female", "m", "f"):
        await ctx.send("*Set it to `male` or `female`.* **mrr.**")
        return
    gender_clean = "male" if gender in ("male", "m") else "female"
    m = bot.db
    await _add_reactions(ctx, m)
    guild_id = str(ctx.guild.id) if ctx.guild else "dm"
    m["internal"].setdefault("guild_states", {}).setdefault(guild_id, {})["gender"] = gender_clean
    save_db(m)
    await ctx.send(f"*The Creator has decided. Yarnaby is **{gender_clean}** in this server. He looks down at himself. He looks up. He continues with his day.* **mrr.**")


