# ==========================================
# !tie — tie him up like in the image
# ==========================================
@bot.command(name="tie", aliases=["tiehim", "tieyarny", "bindhim", "restrain"])
async def tie_cmd(ctx):
    """Tie Yarnaby up. Pain and bruises develop over time."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return

    if m["internal"].get("is_tied"):
        await ctx.send("*He's already tied up. Use `!untie` to free him.* **mrr.**")
        return

    if score < 0 and not is_doctor:
        await ctx.send("*He sees the rope and immediately leaves the room.* **mrr.**")
        return

    m["internal"]["is_tied"] = True
    m["internal"]["tied_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    m["internal"]["tied_by"] = ctx.author.display_name
    m["internal"]["tied_channel"] = str(ctx.channel.id)
    save_db(m)

    if is_doctor:
        await ctx.send(
            "*The Creator ties him up carefully. Yarnaby goes completely still during the process — "
            "not struggling, just watching The Creator's hands with enormous trust. "
            "He lies there, all four paws loosely bound, looking up at The Creator.* **...mrr...**"
        )
    elif score >= 7:
        await ctx.send(
            "*You tie him up. He lets you, which is surprising. He lies back and looks at his own paws, "
            "then at you, then at his paws again. He makes a small curious sound.* **...mrr?**"
        )
    elif score >= 3:
        await ctx.send(
            "*He wiggles once as the rope goes on. Then he stops. He looks at you with a flat expression. "
            "He is tied now. He would like it noted that he is not happy about this.* **mrr.**"
        )
    else:
        await ctx.send(
            "*He struggles the whole time but you manage it. He is tied. He is furious. "
            "He stares at you with the intensity of someone planning something.* **MRROW.**"
        )

    # Schedule pain/bruise development
    async def _tie_pain_tick():
        await asyncio.sleep(120)  # 2 minutes
        db = bot.db
        if not db["internal"].get("is_tied"):
            return
        ch_id = db["internal"].get("tied_channel")
        ch = bot.get_channel(int(ch_id)) if ch_id else None
        if ch:
            await ch.send(
                "*Yarnaby shifts uncomfortably. The rope is starting to press into his wool. "
                "He makes a small, pained sound.* **...mrrp...**"
            )
        await asyncio.sleep(180)  # 3 more minutes
        if not db["internal"].get("is_tied"):
            return
        # Add bruise
        db["internal"].setdefault("injuries", []).append({
            "type": "bruise", "location": "paws", "severity": "small",
            "caused_by": "being tied", "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "treated": False,
        })
        db["stats"]["health"] = max(1, db["stats"].get("health", 100) - 3)
        # Lower score of person who tied him
        tied_by_name = db["internal"].get("tied_by", "")
        for uid, data in db["social_matrix"].items():
            if isinstance(data, dict) and data.get("display_name", "") == tied_by_name:
                if int(uid) != DOCTOR_ID:
                    data["score"] = max(-100, data.get("score", 0) - 2)
        save_db(db)
        if ch:
            await ch.send(
                "*He has been tied for a while now. His paws are bruised where the rope presses. "
                "He makes occasional quiet sounds. He would very much like to be untied.* **...mrrp... mrr...**"
            )

    asyncio.create_task(_tie_pain_tick())


@bot.command(name="untie", aliases=["freehim", "untieyarny", "releasehim", "untieknot"])
async def untie_cmd(ctx):
    """Untie Yarnaby."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if not m["internal"].get("is_tied"):
        await ctx.send("*He's not tied up right now.* **mrr.**")
        return

    tied_at_str = m["internal"].get("tied_at", "")
    try:
        tied_at = datetime.strptime(tied_at_str, "%Y-%m-%d %H:%M:%S")
        minutes_tied = (datetime.now() - tied_at).total_seconds() / 60
    except Exception:
        minutes_tied = 0

    m["internal"]["is_tied"] = False
    m["internal"].pop("tied_at", None)
    m["internal"].pop("tied_by", None)
    save_db(m)

    if is_doctor:
        await ctx.send(
            "*The Creator unties him. Yarnaby lies still until the last knot is gone, "
            "then stretches all four paws out as far as they'll go — a long, slow, full-body stretch. "
            "He presses against The Creator immediately after.* **prrr.**"
        )
    elif score >= 7:
        if minutes_tied > 4:
            await ctx.send(
                "*You free him. He stretches immediately — all four paws, maximum extension, long groan of relief. "
                "He blinks at you. He doesn't hold it against you, somehow.* **mrr. prrr.**"
            )
        else:
            await ctx.send(
                "*You untie him quickly. He shakes each paw once and stretches. "
                "He bumps your hand briefly.* **mrr.**"
            )
    elif score >= 2:
        await ctx.send(
            "*Free. He stretches hard and shakes each paw. He looks at you. He doesn't say anything. "
            "He walks away.* **mrr.**"
        )
    else:
        await ctx.send(
            "*You untie him. He's on his feet immediately. He gives you one long, flat stare. "
            "He leaves without another sound.* **mrr.**"
        )


