@bot.command(name="pov", aliases=["hispov", "yarnyview", "hiseyes", "viewpov", "camerapov"])
async def pov_cmd(ctx, *, scene: str = ""):
    """Generate an image of Yarnaby's point of view."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    sleeping = m["internal"].get("is_sleeping", False)
    scene_lower = (scene or "").lower().strip()

    # Build the prompt based on scene/current state
    if not scene or scene_lower in ("current", "now", "what"):
        if sleeping:
            prompt = "A cat's point of view while sleeping, looking down at fluffy wool paws tucked under a warm body, soft dim factory light, cozy and peaceful, slightly blurry dreamy quality"
        else:
            mood = m["stats"].get("mood", "Content")
            prompt = f"A cat's first-person point of view inside an abandoned factory, looking at a concrete floor with soft light coming through high windows, fluffy white-grey paws visible at the bottom of the frame, mood: {mood.lower()}"
    elif "dream" in scene_lower:
        prompt = "A dreamlike cat's point of view, surreal soft colours, floating yarn balls, warm golden light, fluffy paws reaching out, soft edges and glowing atmosphere"
    elif "yarn" in scene_lower or "ball" in scene_lower or "chase" in scene_lower:
        prompt = "A cat's first-person point of view chasing a yarn ball, the ball just ahead on a factory floor, fluffy grey-white paws extended in a pounce, motion blur, excited energy"
    elif "sleep" in scene_lower or "nap" in scene_lower:
        prompt = "A cat's sleepy point of view, eyes half closed, looking at fluffy wool paws tucked underneath, warm and dim lighting, peaceful blurry edges"
    elif "creator" in scene_lower or "doctor" in scene_lower:
        prompt = "A cat's loving point of view looking up at a person's hand reaching down to pet, warm soft lighting, fluffy grey-white paws visible, trust and warmth in the perspective"
    elif "window" in scene_lower:
        prompt = "A cat's point of view looking through a dirty factory window at the outside world, fluffy paws on the windowsill, soft natural light, curious perspective"
    elif "food" in scene_lower or "eat" in scene_lower:
        prompt = "A cat's hungry point of view looking down at a food bowl, fluffy grey-white paws on each side, close up perspective, anticipation"
    else:
        prompt = f"A cat's first-person point of view, {scene}, fluffy grey-white wool paws visible at the bottom, inside an old factory, cinematic lighting"

    await ctx.send("*He blinks. You see what he sees for a moment...*")
    await _send_visual_result(ctx, prompt, "pov")



