# FEED/GIFT: can't eat users, python, toxic stuff
# ==========================================
_INEDIBLE_USERS = []  # handled in on_message check
_CANT_EAT = [
    "python", "javascript", "typescript", "java", "c++", "c#", "html", "css",
    "code", "script", "program", "bug", "stack trace", "keyboard", "computer",
    "laptop", "monitor", "phone", "charger", "usb", "mouse", "controller",
    "rock", "stone", "brick", "metal", "glass", "plastic", "rubber", "wire",
    "cable", "coin", "battery", "socket", "knife", "needle", "nail", "screw",
    "shoe", "boot", "sock", "shirt", "pants", "hat", "paperclip",
    "bleach", "poison", "acid", "toxic", "chemicals", "chemical", "detergent",
    "soap", "cleaner", "petrol", "gasoline", "diesel", "paint", "glue",
    "fire", "lava", "electricity", "spark", "flame",
    "dirt", "sand", "cement", "concrete", "dust", "trash", "garbage",
]

def _resolve_offered_member(ctx, item: str):
    mentions = getattr(getattr(ctx, "message", None), "mentions", None) or []
    if mentions:
        return mentions[0]
    guild = getattr(ctx, "guild", None)
    if not guild:
        return None
    wanted = item.lower().strip()
    if not wanted:
        return None
    wanted = wanted.lstrip("@")
    for member in getattr(guild, "members", []):
        names = {
            getattr(member, "display_name", "").lower(),
            getattr(member, "name", "").lower(),
        }
        if wanted in names:
            return member
    return None

async def _handle_user_feed(ctx, target_member, is_doctor, score) -> bool:
    """Returns True if trying to feed him a user."""
    if not target_member:
        return False
    t_name = target_member.display_name
    if is_doctor:
        await ctx.send(
            f"*The Creator offers {t_name} to Yarnaby as food. He approaches. He sniffs {t_name}. "
            f"He sits back. He looks at The Creator with enormous patience. He will not be eating {t_name}. "
            f"He would like something else.* **mrr.**"
        )
    elif score >= 5:
        await ctx.send(
            f"*You offer {t_name} to Yarnaby. He walks up to them. He sniffs their hand. "
            f"He licks it once — just to check. He backs up. He is not eating {t_name}. "
            f"He blinks at you slowly.* **mrr.**"
        )
    else:
        await ctx.send(
            f"*You try to feed him {t_name}. He looks at {t_name}. He looks at you. "
            f"He walks away. Nobody in this scenario comes out well.* **mrr.**"
        )
    return True

async def _handle_inedible_item_extended(ctx, item: str, is_doctor: bool, score: int) -> bool:
    """Returns True and responds if item is inedible."""
    item_lower = item.lower().strip()
    if not any(w in item_lower for w in _CANT_EAT):
        return False
    if "toxic" in item_lower or "poison" in item_lower or "bleach" in item_lower or "acid" in item_lower:
        if is_doctor:
            await ctx.send(
                f"*The Creator offers **{item}**. Yarnaby sniffs once, recoils, and carefully pushes it away from both of them. "
                f"He looks more worried than angry.* **mrr...**"
            )
        else:
            await ctx.send(
                f"*He sniffs the **{item}**. His nose wrinkles. He recoils hard. He bats it away with his paw "
                f"and backs up three full steps. He stares at you.* **HSSSS.**"
            )
            m = bot.db
            u_id = str(ctx.author.id)
            m["social_matrix"].setdefault(u_id, {})["score"] = min(score, -10)
            save_db(m)
    elif "python" in item_lower or "code" in item_lower or "javascript" in item_lower:
        if is_doctor:
            await ctx.send(
                f"*The Creator offers him **{item}**. He sniffs it, gives The Creator a long patient look, and refuses to eat it. "
                f"He will supervise debugging from a distance.* **mrr.**"
            )
        elif score >= 5:
            await ctx.send(
                f"*You offer him **{item}**. He sniffs it. He gives it one deeply suspicious test bite and spits it out. "
                f"He still likes you, but he is not eating code.* **mrrp.**"
            )
        else:
            await ctx.send(
                f"*You offer him **{item}**. He sniffs it, immediately walks away, and looks back once with pure disappointment. "
                f"He will not be debugging your code by eating it.* **mrr.**"
            )
    elif any(w in item_lower for w in ["rock", "stone", "brick", "metal", "glass", "concrete"]):
        await ctx.send(
            f"*He examines the **{item}** very seriously. He bites it. His face says everything. "
            f"He sits back and stares at you. He has questions.* **mrr.**"
        )
    else:
        await ctx.send(
            f"*He sniffs the **{item}** and gives it a careful look. He bats it once. "
            f"He walks away. That is not food. He knows what food is.* **mrr.**"
        )
    return True


