@bot.command(name="taste_test", aliases=["tastetest", "taste", "licktest", "trytaste"])
async def taste_test_cmd(ctx, *, item: str = ""):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)
    item = (item or "something").strip()

    if sleeping:
        await ctx.send(f"*He is asleep. He cannot taste **{item}** right now.* **...prrr...**")
        return

    LOVE_TASTE = ["fish", "chicken", "tuna", "salmon", "steak", "meat", "milk", "broth"]
    HATE_TASTE = ["lemon", "citrus", "orange", "tangerine", "lime", "bitter", "spicy", "hot sauce"]
    WEIRD_TASTE = ["plastic", "cardboard", "paper", "rubber", "metal"]

    item_lower = item.lower()

    if any(w in item_lower for w in LOVE_TASTE):
        reaction = random.choice([
            f"*He licks the **{item}** carefully. His eyes close slightly. He licks again. He is very serious about this.* **prrr.**",
            f"*One lick. Two licks. He has made his assessment: excellent. He wants more.* **prrr. mrr.**",
        ])
    elif any(w in item_lower for w in HATE_TASTE):
        reaction = random.choice([
            f"*He licks the **{item}**. His face does something extraordinary. He shakes his head. He licks his own paw to remove the taste. He stares at you.* **mrrow.**",
            f"*The **{item}** gets one lick. His entire face contracts. He backs up three steps. He is disgusted in a way that is deeply personal.* **MRROW. hff.**",
        ])
    elif any(w in item_lower for w in WEIRD_TASTE):
        reaction = random.choice([
            f"*He licks the **{item}**. He processes this. He licks again. He does not know what to do with this information.* **...mrr?**",
            f"*One slow lick of the **{item}**. His head tilts. He licks once more. He walks away, still thinking.* **mrr.**",
        ])
    else:
        reaction = random.choice([
            f"*He approaches the **{item}** and licks it carefully. He considers. He licks again. Verdict: neutral. He walks away.* **mrr.**",
            f"*One test lick of the **{item}**. He blinks. He has filed this under 'edible but not exciting'.* **mrr.**",
            f"*He licks the **{item}** and immediately looks suspicious. He licks again. Suspicion remains.* **...mrr?**",
        ])

    if is_doctor:
        reaction = reaction.replace("* **mrr.**", "* *He looks at The Creator for their opinion.* **mrr.**")

    await ctx.send(reaction)


