# Trap ambient — he can get trapped occasionally
async def _maybe_get_trapped(channel, m, bot_instance):
    """Small chance he gets himself trapped in something."""
    if random.random() > 0.02:
        return
    if m["internal"].get("is_sleeping") or m["internal"].get("is_trapped"):
        return

    m["internal"]["is_trapped"] = True
    m["internal"]["trapped_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m)

    try:
        await channel.send(
            "*Yarnaby has gotten himself into something and cannot get back out. "
            "His back half is visible, tail lashing. His front half is stuck. "
            "He makes muffled, urgent sounds.* **...mrrp! mrrp!**\n"
            "*Use `!untrap` to free him before he runs out of energy!*"
        )
    except Exception:
        pass

    # Schedule unconsciousness if not rescued
    async def _trap_timeout():
        await asyncio.sleep(300)  # 5 minutes
        db = bot_instance.db
        if not db["internal"].get("is_trapped"):
            return
        # Nobody came — he passes out
        db["internal"]["is_trapped"] = False
        db["internal"]["is_unconscious"] = True
        db["internal"]["unconscious_until"] = (datetime.now() + timedelta(minutes=10)).strftime("%Y-%m-%d %H:%M:%S")
        db["stats"]["health"] = max(1, db["stats"].get("health", 100) - 15)
        save_db(db)
        try:
            await channel.send(
                "*Nobody came. The sounds stopped. Yarnaby has gone quiet inside whatever he's trapped in. "
                "After a while he tumbles out on his own — limp, exhausted, unconscious. "
                "He's breathing. He's out, but not gone. He just needs time.* **...mrr...**"
            )
        except Exception:
            pass

    asyncio.create_task(_trap_timeout())


