# ==========================================
# Overheating / steaming ambient
# ==========================================
async def _maybe_overheating(channel, m):
    """If it's summer and he's been active, he might steam."""
    if random.random() > 0.05:
        return
    if m["internal"].get("is_sleeping"):
        return
    try:
        now = datetime.now() + ISTANBUL_OFFSET
        month = now.month
    except Exception:
        month = datetime.now().month

    if month not in [6, 7, 8]:
        return

    lines = [
        "*Yarnaby is emitting a visible heat shimmer. He is too warm. He is lying flat on the coolest surface he can find, not moving.* **...mrr...**",
        "*He is... steaming slightly. Just slightly. He has found the coldest spot in the factory and melted into it.* **...mrr...**",
        "*He is warm. Very warm. The kind of warm that makes him lie spread-eagle on the floor with all four paws out.* **...mrr...**",
    ]
    try:
        await channel.send(random.choice(lines))
    except Exception:
        pass


# ==========================================
# !cutwool — cut his wool
# ==========================================
@bot.command(name="cutwool", aliases=["cutfur", "woolcut", "trimwool", "shearyarny"])
async def cutwool_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)
    wool_cut = m["internal"].get("wool_cut", False)

    if wool_cut:
        await ctx.send("*His wool is already cut. It will grow back in about a week.* **mrr.**")
        return

    if sleeping:
        await ctx.send("*You carefully cut some of his wool while he sleeps. He doesn't wake up. He will notice later.* **...prrr...**")
        m["internal"]["wool_cut"] = True
        m["internal"]["wool_cut_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        save_db(m)
        await asyncio.sleep(5)
        await ctx.send("*He wakes up. He begins grooming. He stops. He looks at where his wool was. He stares at the floor. He stares at his side. He stares at the floor.* **...mrr...**")
        return

    if is_doctor:
        await ctx.send(
            "*The Creator approaches with scissors. Yarnaby eyes them. He sits very still — completely trusting, "
            "even as his beloved wool gets snipped. He watches each piece fall. When it's done he looks at himself. "
            "He looks at The Creator. He makes a very small, very betrayed sound.* **...mrrp...**"
        )
    elif score >= 6:
        await ctx.send(
            "*He tolerates the woolcut with the dignity of someone who has accepted their fate. "
            "Each snip makes him twitch slightly. When it's done he looks at the pile of his wool on the floor. "
            "He sits in it. It's still his.* **mrr.**"
        )
    else:
        await ctx.send(
            "*He wiggles and protests the whole time but you get enough done. "
            "He looks at his reduced wool situation. He is not okay with this. "
            "He stares at his own side.* **mrrow. mrr.**"
        )
        m["social_matrix"].setdefault(u_id, {})["score"] = max(-100, score - 1)
        save_db(m)

    m["internal"]["wool_cut"] = True
    m["internal"]["wool_cut_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m)
    await asyncio.sleep(4)
    await ctx.send(
        "*He finds the pile of cut wool on the floor and sits next to it. "
        "He sniffs it. It smells like him. He curls around it protectively. "
        "His wool is gon. He is watching over what remains.* **...mrr...**"
    )


# Wool grows back after a week
@tasks.loop(hours=1)
async def _wool_regrowth_tick():
    """Check if wool has grown back."""
    await bot.wait_until_ready()
    m = bot.db
    if not m["internal"].get("wool_cut"):
        return
    cut_at_str = m["internal"].get("wool_cut_at", "")
    try:
        cut_at = datetime.strptime(cut_at_str, "%Y-%m-%d %H:%M:%S")
        days_since = (datetime.now() - cut_at).days
        if days_since >= 7:
            m["internal"]["wool_cut"] = False
            m["internal"].pop("wool_cut_at", None)
            save_db(m)
            ch_id = m["internal"].get("home_channel_id") or m["internal"].get("original_home_channel_id")
            if ch_id:
                ch = bot.get_channel(int(ch_id))
                if ch:
                    await ch.send(
                        "*Yarnaby's wool has grown back. He notices while grooming. "
                        "He looks down at himself. He looks up. Everything is as it should be. "
                        "He makes a small, satisfied sound.* **prrr.**"
                    )
    except Exception:
        pass

