# !run — helps him lose weight when overweight
# ==========================================
@bot.command(name="run", aliases=["runyarny", "exercise", "yarnyrun", "sprint"])
async def run_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    sleeping = m["internal"].get("is_sleeping", False)

    if sleeping:
        await ctx.send("*He is asleep. He cannot run right now.* **...prrr...**")
        return

    hunger = m["stats"].get("hunger", 0)
    # Weight based on hunger
    weight = 4.2 + (hunger * 0.05)

    if weight < 4.5:
        await ctx.send("*He's not overweight. He doesn't need to run. He runs anyway, because he wants to.* **chrrp!**")
    else:
        await ctx.send(
            f"*Yarnaby begins running laps of the factory. His wool bounces. His paws slap the concrete. "
            f"He is committed to this.* **prrr.**"
        )
        await asyncio.sleep(4)
        weight_lost = round(random.uniform(0.05, 0.15), 2)
        m["stats"]["hunger"] = max(0, hunger - 1)
        m["stats"]["tiredness"] = min(10, m["stats"].get("tiredness", 0) + 2)
        save_db(m)
        await ctx.send(
            f"*He finishes his laps and collapses dramatically. He is panting. He is tired. "
            f"He feels lighter. He lost approximately **{weight_lost}kg**.* **...mrr...**"
        )

    # Play run SFX
    if ctx.guild:
        vc = _get_guild_vc(ctx.guild)
        await _play_sfx(vc, "run")


