# !shake — shake dirt off without a bath
# ==========================================
@bot.command(name="shake", aliases=["shakeitoff", "yarnyshake", "shakeoff", "dustoff"])
async def shake_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    sleeping = m["internal"].get("is_sleeping", False)
    dirt = m["stats"].get("cleanliness", 0)

    if sleeping:
        await ctx.send("*He is asleep. He can't shake right now.* **...prrr...**")
        return

    if dirt <= 1:
        await ctx.send("*He's already pretty clean. He shakes anyway — a quick, full-body shimmy — and continues.* **mrr.**")
        return

    await ctx.send("*Yarnaby shakes. He shakes HARD. His wool goes in all directions. Dust and debris fly off him in a visible cloud.* **brrr!**")
    await asyncio.sleep(2)

    dirt_removed = min(dirt, random.randint(2, 4))
    m["stats"]["cleanliness"] = max(0, dirt - dirt_removed)
    save_db(m)

    new_dirt = m["stats"]["cleanliness"]
    if new_dirt <= 1:
        await ctx.send("*He shakes a final time and settles. He's much cleaner. Not bath-clean, but significantly less dusty.* **prrr.**")
    else:
        await ctx.send(
            f"*He shakes off a good amount of dust. He's cleaner than he was — "
            f"but a proper `!bath` or `!bubblebath` is still needed for a full clean.* **mrr.**"
        )

    # Play furmovement SFX
    if ctx.guild:
        vc = _get_guild_vc(ctx.guild)
        await _play_sfx(vc, "furmovement")


