# Wire all new ambients into the random_sound_tick
# ==========================================
@tasks.loop(minutes=15)
async def _ambient_behaviour_tick():
    """Fires every 15 minutes for ambient behaviour events."""
    await bot.wait_until_ready()
    m = bot.db
    ch_id = m["internal"].get("home_channel_id") or m["internal"].get("original_home_channel_id")
    if not ch_id:
        return
    try:
        ch = bot.get_channel(int(ch_id))
        if not ch:
            return
        await _maybe_tail_face_ambient(ch, m)
        await _maybe_steal_toilet_paper(ch, m)
        await _maybe_orange_cat_ambient(ch, m)
        await _maybe_overheating(ch, m)
        await _maybe_get_trapped(ch, m, bot)
        if callable(globals().get("_maybe_back_pain_ambient")):
            await _maybe_back_pain_ambient(ch, m)
        if callable(globals().get("_maybe_squeeze_ambient")):
            await _maybe_squeeze_ambient(ch, m)
        await _maybe_random_sound(ch, bot)
        await _maybe_breathing_sfx(bot)
    except Exception as e:
        print(f"[ambient tick] {e}")

