@bot.command(name="takeout", aliases=["takehimout", "freeheadstuck", "unstickhead", "pullout"])
async def takeout_cmd(ctx):
    """Free Yarnaby from whatever he's stuck in — box, head stuck, wearing box."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
        ]))
        return
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    # --- WEARING BOX ---
    if m["internal"].get("wearing_box"):
        m["internal"]["wearing_box"] = False
        save_db(m)
        if is_doctor:
            await ctx.send(random.choice([
                "*The Creator lifts the box off him. He shakes himself once, "
                "thoroughly, from nose to tail. He looks at The Creator. "
                "He looks at the box. He walks away from the box with purpose.* **prrr.**",
                "*The Creator takes the box away. He stands there for a moment "
                "in the sudden absence of cardboard and breathes. "
                "He grooms his shoulder where it was rough. He is fine.* **prrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*You lift the box off him. He emerges looking ruffled and dignified simultaneously. "
                f"He shakes himself. He does not thank you. "
                f"He does step slightly toward you afterward.* **mrr.**",
                f"*Box removed. He stands blinking for a second. "
                f"He grooms the spot on his side where the cardboard was rough. "
                f"He glances at you once.* **...mrr.**",
            ]))
        m["social_matrix"].setdefault(u_id, {})["score"] = min(100, score + 1)
        return

    # --- STUCK IN BOX (head, tail, body, paw) ---
    if m["internal"].get("head_stuck"):
        stuck_part = m["internal"].get("stuck_part", "head")
        stuck_at_str = m["internal"].get("head_stuck_at", "")
        try:
            stuck_at = datetime.strptime(stuck_at_str, "%Y-%m-%d %H:%M:%S")
            mins_stuck = (datetime.now() - stuck_at).total_seconds() / 60
        except Exception:
            mins_stuck = 0

        m["internal"]["head_stuck"] = False
        m["internal"].pop("head_stuck_at", None)
        m["internal"].pop("stuck_part", None)
        m["social_matrix"].setdefault(u_id, {})["score"] = min(100, score + 2)
        save_db(m)

        if is_doctor:
            await ctx.send(random.choice([
                f"*The Creator carefully works his **{stuck_part}** free. "
                f"There's a soft pop and he's loose. He shakes himself vigorously. "
                f"He looks at The Creator with slightly dazed eyes "
                f"and presses against them.* **...prrr...**",
                f"*A gentle pull, a wiggle, and his **{stuck_part}** comes free. "
                f"He stands there for a moment recalibrating. "
                f"Then he looks at The Creator and headbutts their hand.* **prrr.**",
            ]))
        elif score >= 5:
            await ctx.send(
                f"*You work his **{stuck_part}** loose carefully. "
                f"He comes free with a wiggle. He shakes himself. "
                f"He blinks at you. He licks his nose. He bumps your hand.* **mrr. prrr.**"
            )
        else:
            await ctx.send(
                f"*You free his **{stuck_part}**. He comes out in a rush, stumbles, recovers. "
                f"He shakes his head several times. He blinks at you. "
                f"Something in his expression shifted slightly.* **...mrr.**"
            )

        if mins_stuck > 5:
            await asyncio.sleep(2)
            await ctx.send(
                f"*He was in there a while. He grooms his **{stuck_part}** thoroughly "
                f"to restore his dignity.* **mrr.**"
            )
        return

    # --- NOTHING TO FREE ---
    await ctx.send("*He's not stuck in anything right now.* **mrr.**")



# ==========================================
# POWER SOCKET electrocution
# ==========================================
async def _maybe_socket_incident(channel, m, bot_instance):
    """He sticks his paw in a power socket."""
    if random.random() > 0.015:
        return
    if m["internal"].get("is_sleeping") or m["internal"].get("paw_in_socket"):
        return

    m["internal"]["paw_in_socket"] = True
    m["internal"]["socket_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m)

    try:
        await channel.send(
            "*Yarnaby has found a power socket. He sniffs it. He sniffs it again. "
            "He reaches out one paw and inserts it - too deep.* **...mrr?**\n"
            "**ZAP.**\n"
            "*He is frozen. He is vibrating slightly. His fur is standing up.* **mrrRRRRR-**\n"
            "*Use `!push` to knock him free! The faster you do it, the less serious the injury.*"
        )
    except Exception:
        pass

    # Auto-rescue after delay — worse injury the longer it takes
    async def _socket_timeout():
        for wait_mins, severity in [(1, "small"), (3, "moderate"), (5, "serious")]:
            await asyncio.sleep(wait_mins * 60)
            db = bot_instance.db
            if not db["internal"].get("paw_in_socket"):
                return  # Already rescued

        # Nobody saved him — he gets out himself but badly hurt
        db = bot_instance.db
        if not db["internal"].get("paw_in_socket"):
            return
        db["internal"]["paw_in_socket"] = False
        db["internal"].pop("socket_at", None)
        db["internal"].setdefault("injuries", []).append({
            "type": "electric burn",
            "location": "paw",
            "severity": "serious",
            "caused_by": "power socket",
            "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "treated": False,
        })
        db["stats"]["health"] = max(1, db["stats"].get("health", 100) - 20)
        save_db(db)
        try:
            await channel.send(
                "*Nobody came. After a long, awful moment, Yarnaby wrenches himself free on his own. "
                "He stumbles backward and lands hard. His fur is still standing. His paw is badly burned. "
                "He sits very still, shaking.* **...mrr...**\n"
                "*He has a serious electric burn on his paw. Use `!treat` to help him.*"
            )
        except Exception:
            pass

    asyncio.create_task(_socket_timeout())


# Patch !push to rescue from socket
_original_push_check = None

@bot.listen("on_command_completion")
async def on_push_socket_rescue(ctx):
    """When !push is used, check if it rescues from socket."""
    if not ctx.command or ctx.command.name != "push":
        return
    m = bot.db
    if not m["internal"].get("paw_in_socket"):
        return

    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    socket_at_str = m["internal"].get("socket_at", "")
    try:
        socket_at = datetime.strptime(socket_at_str, "%Y-%m-%d %H:%M:%S")
        secs_elapsed = (datetime.now() - socket_at).total_seconds()
    except Exception:
        secs_elapsed = 999

    # Severity based on how fast they rescued
    if secs_elapsed < 30:
        severity = "bruise"
        severity_desc = "just a small bruise on his paw"
    elif secs_elapsed < 120:
        severity = "minor burn"
        severity_desc = "a minor burn on his paw — will heal quickly"
    elif secs_elapsed < 300:
        severity = "burn"
        severity_desc = "a moderate burn on his paw"
    else:
        severity = "serious burn"
        severity_desc = "a serious burn — needs treatment soon"

    m["internal"]["paw_in_socket"] = False
    m["internal"].pop("socket_at", None)
    m["internal"].setdefault("injuries", []).append({
        "type": severity,
        "location": "paw",
        "severity": "small" if secs_elapsed < 30 else "moderate" if secs_elapsed < 180 else "serious",
        "caused_by": "power socket",
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "treated": False,
    })
    m["social_matrix"].setdefault(u_id, {})["score"] = min(100, score + 1)
    save_db(m)

    if is_doctor:
        await ctx.send(
            f"*The Creator shoves Yarnaby free from the socket. He goes flying sideways and lands in a heap. "
            f"He sits up, fur completely on end. He blinks. He looks at his paw. He looks at The Creator. "
            f"He presses against them immediately.* **...prrr...**\n"
            f"*Injury: {severity_desc}. Use `!treat` when ready.*"
        )
    elif score >= 5:
        await ctx.send(
            f"*You knock him free. He tumbles, recovers, sits up with his fur standing in all directions. "
            f"He blinks at his own paw. He blinks at you. Something has changed slightly in his expression.* **...mrr. prrr.**\n"
            f"*Injury: {severity_desc}.*"
        )
    else:
        await ctx.send(
            f"*You push him free. He goes sideways, lands, gets up immediately. "
            f"He shakes himself hard. He blinks at you.* **mrr.**\n"
            f"*Injury: {severity_desc}.*"
        )


