async def _trigger_forgetting(m, ch):
    """
    Start a forgetting sequence: announce the task, forget mid-way,
    then remember after a delay (5-20 min).
    Only fires if Yarnaby is awake and ~8% chance per ambient tick.
    """
    if m["internal"].get("is_sleeping"):
        return
    if m["internal"].get("currently_forgetting"):
        return  # already mid-forget
    if random.random() > 0.08:
        return

    # Pick a task — prefer child tasks if children exist
    guild_id = str(ch.guild.id) if hasattr(ch, "guild") and ch.guild else "dm"
    children = _get_children(m, guild_id)

    child_tasks = ["feed_child", "groom_child", "watch_child"]
    non_child_tasks = ["carry_toy", "fetch_something"]

    task_pool = []
    if children:
        task_pool += child_tasks * 3  # weight child tasks higher when children exist
    task_pool += non_child_tasks * 2

    chosen_key = random.choice(task_pool)

    # Get detail
    if chosen_key in child_tasks and children:
        detail = random.choice(children)["name"]
    elif chosen_key == "carry_toy":
        inv = m["internal"].get("hoard", [])
        detail = random.choice(inv)["name"] if inv else random.choice([
            "a small felt mouse", "a crinkle ball", "a piece of wool",
            "a bottle cap", "something shiny", "a cork"
        ])
    else:
        detail = random.choice([
            "something he smelled earlier", "a toy from the back room",
            "something he hid last week", "a particular bottle cap",
            "a thing he left somewhere", "his favourite bit of wool",
        ])

    # Find the task definition
    task_def = next((t for t in _FORGETTABLE_TASKS if t[0] == chosen_key), None)
    if not task_def:
        return

    _, start_fn, forgot_fn, remember_fn = task_def

    # Mark as in-progress
    m["internal"]["currently_forgetting"] = {
        "task": chosen_key,
        "detail": detail,
        "started_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "channel_id": ch.id,
    }
    save_db(m)

    try:
        await ch.send(start_fn(detail))
    except Exception:
        return

    # Forget after 1-4 minutes
    forget_delay = random.randint(60, 240)
    await asyncio.sleep(forget_delay)

    m2 = bot.db
    if not m2["internal"].get("currently_forgetting"):
        return  # was cleared by something else
    if m2["internal"]["is_sleeping"]:
        m2["internal"]["currently_forgetting"] = None
        save_db(m2)
        return

    try:
        await ch.send(forgot_fn(detail))
    except Exception:
        return

    m2["internal"]["currently_forgetting"]["forgot_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m2)

    # Remember after 5-20 more minutes
    remember_delay = random.randint(300, 1200)
    await asyncio.sleep(remember_delay)

    m3 = bot.db
    if not m3["internal"].get("currently_forgetting"):
        return
    if m3["internal"]["is_sleeping"]:
        m3["internal"]["currently_forgetting"] = None
        save_db(m3)
        return

    try:
        await ch.send(remember_fn(detail))
    except Exception:
        pass

    m3["internal"]["currently_forgetting"] = None
    save_db(m3)


@tasks.loop(minutes=18)
async def _forgetting_tick():
    """Tick that may trigger a mid-task forgetting sequence."""
    await bot.wait_until_ready()
    m = bot.db
    if m["internal"].get("is_sleeping"):
        return
    ch_id = m["internal"].get("home_channel_id") or m["internal"].get("original_home_channel_id")
    if not ch_id:
        return
    ch = bot.get_channel(int(ch_id))
    if not ch:
        return
    try:
        await _trigger_forgetting(m, ch)
    except Exception as e:
        print(f"[forgetting tick] {e}")



# Started in on_ready so discord.py has a running event loop.


# ==========================================
# ===== v2.7 LIFE + VISUAL SYSTEMS =====
# ==========================================

def _ensure_life_defaults(m):
    internal = m.setdefault("internal", {})
    internal.setdefault("life_memories", [])
    internal.setdefault("visual_log", [])
    internal.setdefault("crime_log", [])
    internal.setdefault("factory_rooms", ["main floor"])
    internal.setdefault("trained_tricks", {})
    internal.setdefault("nicknames", {})
    internal.setdefault("daily_habits", {})
    internal.setdefault("visual_style", "warm cinematic factory realism")
    internal.setdefault("last_vibe", None)


def _remember_life(m, kind: str, text: str, user=None):
    _ensure_life_defaults(m)
    entry = {
        "kind": kind,
        "text": text[:260],
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }
    if user is not None:
        entry["user_id"] = str(getattr(user, "id", ""))
        entry["user_name"] = getattr(user, "display_name", str(user))
    log = m["internal"]["life_memories"]
    log.append(entry)
    m["internal"]["life_memories"] = log[-160:]


def _log_crime(m, crime: str):
    _ensure_life_defaults(m)
    log = m["internal"]["crime_log"]
    log.append({"crime": crime[:180], "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")})
    m["internal"]["crime_log"] = log[-50:]


def _visual_prompt(scene: str, m, ctx=None) -> str:
    scene = (scene or "current").strip()
    stats = m.get("stats", {})
    internal = m.get("internal", {})
    mood = stats.get("mood", "Content")
    cleanliness = _cleanliness_label(stats.get("cleanliness", 0))
    temp = stats.get("temperature", "warm")
    outfit_bits = []
    if internal.get("wearing_tophat"):
        outfit_bits.append("a tiny top hat")
    if internal.get("wearing_banana"):
        outfit_bits.append("a banana outfit")
    if internal.get("wearing_cone"):
        outfit_bits.append("a medical cone")
    outfit = ", wearing " + ", ".join(outfit_bits) if outfit_bits else ""
    comfort_object = internal.get("comfort_object")
    comfort = f" His comfort object, {comfort_object}, is nearby." if comfort_object else ""
    recent_room = (internal.get("factory_rooms") or ["main floor"])[-1]
    base = (
        "First-person POV from Yarnaby, a small creature made entirely of soft grey-white wool and yarn. "
        "His body is visibly yarn-textured throughout \u2014 like a knitted or felted stuffed animal that came to life. "
        "He has round glass button eyes (NOT real cat eyes \u2014 smooth, dark, glassy buttons sewn on), "
        "small rounded woolly ears made of looped yarn, a fluffy yarn tail, "
        "and chunky paws made of bundled grey-white wool threads. "
        "He looks like a living handmade yarn toy \u2014 wool fibres visible, stuffed-animal aesthetic \u2014 NOT a real cat. "
        f"Fluffy yarn paws visible at the bottom edge, old abandoned factory setting, room: {recent_room}. "
        f"Mood is {mood.lower()}, cleanliness is {cleanliness.lower()}, body temperature feels {temp}{outfit}. "
        f"Scene: {scene}.{comfort} Warm cinematic lighting, tactile concrete, dust motes, intimate low-to-the-ground perspective, no text, no watermark."
    )
    if ctx and ctx.author.id == DOCTOR_ID:
        base += " The Creator is sensed nearby, so the image should feel safer and more trusting."
    return base


async def _try_generate_visual(prompt: str, filename_prefix: str = "pov"):
    """Generate an image via Pollinations.ai — free, no API key required."""
    try:
        import urllib.parse, io
        encoded = urllib.parse.quote(prompt[:400])  # keep URL manageable
        seed = random.randint(1, 2147483647)
        url = f"https://image.pollinations.ai/prompt/{encoded}?width=1024&height=1024&nologo=true&model=flux&seed={seed}"

        if aiohttp is None:
            return ("url", url)

        timeout = aiohttp.ClientTimeout(total=60)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.get(url) as resp:
                if resp.status == 200:
                    data = await resp.read()
                    return ("bytes", data)
        return ("url", url)
    except Exception:
        return None


async def _send_visual_result(ctx, prompt: str, label: str):
    m = bot.db
    _ensure_life_defaults(m)
    result = await _try_generate_visual(prompt, label)

    result_str = "prompt-only"
    if result:
        result_str = result[1] if isinstance(result, tuple) else str(result)

    entry = {
        "label": label,
        "prompt": prompt,
        "result": result_str if isinstance(result_str, str) else "image",
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "user_id": str(ctx.author.id),
        "user_name": ctx.author.display_name,
    }
    m["internal"]["visual_log"].append(entry)
    m["internal"]["visual_log"] = m["internal"]["visual_log"][-40:]
    save_db(m)

    if result is None:
        await ctx.send(
            "*Yarnaby blinks. The image couldn't be generated right now — here's the prompt instead:*\n"
            f"```text\n{prompt[:500]}\n```"
        )
        return

    kind, data = result

    if kind == "bytes":
        import io
        await ctx.send(
            "*Yarnaby blinks. The image resolves:*",
            file=discord.File(io.BytesIO(data), filename=f"{label}.png"),
        )
    else:
        # URL fallback — try embed
        try:
            embed = discord.Embed()
            embed.set_image(url=data)
            await ctx.send("*Yarnaby blinks. The image resolves:*", embed=embed)
        except Exception:
            await ctx.send(f"*Yarnaby blinks. The image resolves:*\n{data}")


