@bot.command(name="train", aliases=["teachtrick", "tricktrain", "practice"])
async def train_cmd(ctx, *, trick: str = ""):
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send(
            random.choice([
                "*Yarnaby is asleep. He cannot do that right now.*",
                "*He is curled up tight. That will have to wait.*",
                "*He is napping. He'll be ready when he wakes up.*",
            ])
        )
        return
    _ensure_life_defaults(m)
    trick = (trick or "").strip().lower()
    if not trick:
        known = m["internal"]["trained_tricks"]
        if not known:
            await ctx.send("*Train what? Try `!train paw`, `!train sit`, `!train roll`, or something cursed like `!train taxes`.* **mrr?**")
            return
        await ctx.send("*Known tricks:*\n" + "\n".join(f"- **{k}**: level {v}" for k, v in sorted(known.items())))
        return
    score = 99 if ctx.author.id == DOCTOR_ID else m["social_matrix"].get(str(ctx.author.id), {}).get("score", 0)
    gain = 2 if ctx.author.id == DOCTOR_ID else 1 if score >= 3 else 0
    tricks = m["internal"]["trained_tricks"]
    tricks[trick] = min(10, tricks.get(trick, 0) + gain)
    _remember_life(m, "training", f"{ctx.author.display_name} trained him to {trick}", ctx.author)
    save_db(m)
    if gain == 0:
        await ctx.send(f"*You try to teach him **{trick}**. He listens, then performs a completely different action with confidence.* **mrr.**")
    elif tricks[trick] >= 7:
        await ctx.send(f"*He practices **{trick}** and almost gets it right. Almost. His confidence is flawless, which is not the same as accuracy.* **prrr.**")
    else:
        await ctx.send(f"*He practices **{trick}**. He learns one small piece of it and forgets one unrelated thing for three seconds.* **mrrp.**")


