# ==========================================
# ===== v2.8 EPISODES + DEEPER LIFE SYSTEMS =====
# ==========================================

def _ensure_v28_defaults(m):
    _ensure_life_defaults(m)
    internal = m.setdefault("internal", {})
    internal.setdefault("active_episode", None)
    internal.setdefault("episode_log", [])
    internal.setdefault("relationship_titles", {})
    internal.setdefault("hazard_log", [])
    internal.setdefault("health_notes", [])
    internal.setdefault("hoard_trades", [])
    internal.setdefault("minigame_state", {})
    internal.setdefault("camera_roll_reactions", [])
    internal.setdefault("visual_diary", [])


def _relationship_title_for(m, member) -> str:
    if member.id == DOCTOR_ID:
        return "The Creator"
    entry = m.get("social_matrix", {}).get(str(member.id), {})
    score = entry.get("score", 0)
    if entry.get("toxic_attempts"):
        return "Unsafe Offering Person"
    if score >= 12:
        return "Heart-Safe Human"
    if score >= 7:
        return "Trusted Warmth"
    if score >= 3:
        return "Food-Bringer"
    if score < -5:
        return "Deeply Suspicious Shape"
    if score < 0:
        return "Questionable Shoes"
    return "Known Person"


def _episode_summary(ep: dict) -> str:
    if not ep:
        return "none"
    started = ep.get("started_at", "?")
    kind = ep.get("kind", "episode")
    stage = ep.get("stage", "active")
    actions = ", ".join(ep.get("actions", [])[-5:]) or "no help yet"
    return f"{kind} / {stage} / started `{started}` / actions: {actions}"


def _start_episode(m, kind: str, ctx=None):
    _ensure_v28_defaults(m)
    ep = {
        "kind": kind,
        "stage": "active",
        "started_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "actions": [],
    }
    if ctx is not None:
        ep["started_by"] = getattr(ctx.author, "display_name", str(ctx.author))
    m["internal"]["active_episode"] = ep
    return ep


def _finish_episode(m, outcome: str):
    _ensure_v28_defaults(m)
    ep = m["internal"].get("active_episode")
    if not ep:
        return None
    ep["stage"] = "finished"
    ep["outcome"] = outcome
    ep["finished_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    m["internal"]["episode_log"].append(ep)
    m["internal"]["episode_log"] = m["internal"]["episode_log"][-30:]
    m["internal"]["active_episode"] = None
    return ep


def _record_hazard(m, hazard: str, severity: str = "minor"):
    _ensure_v28_defaults(m)
    entry = {"hazard": hazard, "severity": severity, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
    m["internal"]["hazard_log"].append(entry)
    m["internal"]["hazard_log"] = m["internal"]["hazard_log"][-40:]
    return entry


def _health_note(m, text: str):
    _ensure_v28_defaults(m)
    m["internal"]["health_notes"].append({"text": text[:180], "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")})
    m["internal"]["health_notes"] = m["internal"]["health_notes"][-40:]


def _v28_visual_preset_prompt(preset: str, m, ctx=None) -> str:
    preset = (preset or "current").lower().strip()
    preset_map = {
        "dream": "dreamlike memory haze, floating yarn, impossible factory doors, soft glowing paws",
        "danger": "low angle urgent view, power socket sparks, deep shadows, tense body language",
        "creator": "looking up at The Creator's hand, warm safe light, trust, tiny paws at the bottom",
        "tinyspace": "cramped tight space, whiskers close to metal and cardboard, stuck head perspective",
        "memory": "half-remembered factory scene, old gifts and blurred people, nostalgic warm dust",
        "crime": "toilet paper trail through factory, guilty paws visible, cinematic evidence photo",
        "snow": "cold outside factory doorway, snow flying toward the viewer, wool fluffed up",
        "sink": "inside a sink basin, faucet looming above, wet reflections, suspicious paws",
    }
    scene = preset_map.get(preset, preset)
    return _visual_prompt(scene, m, ctx)


