@bot.listen("on_message")
async def on_v28_image_reaction(message):
    if getattr(message.author, "bot", False):
        return
    if not getattr(message, "attachments", None):
        return
    if random.random() > 0.12:
        return
    try:
        if not any(att.filename.lower().endswith((".png", ".jpg", ".jpeg", ".gif", ".webp")) for att in message.attachments):
            return
        m = bot.db
        _ensure_v28_defaults(m)
        reaction = random.choice([
            "*Yarnaby notices the image. He leans closer until his nose almost touches the screen.* **mrr?**",
            "*He studies the picture with one ear tilted back. He has formed an opinion and will not explain it.* **mrr.**",
            "*He pats at the image once, very gently. He expected texture. There is no texture. Troubling.* **mrrp.**",
        ])
        m["internal"]["camera_roll_reactions"].append({"url": message.attachments[0].url, "reaction": reaction, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")})
        m["internal"]["camera_roll_reactions"] = m["internal"]["camera_roll_reactions"][-40:]
        save_db(m)
        await message.channel.send(reaction)
    except Exception:
        pass


