@bot.command(name="stretch", aliases=["stretchhim", "stretchyarny", "dostretch", "bigstretch"])
async def stretch_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)

    if sleeping:
        await ctx.send("*He stretches in his sleep — all four paws extend fully, one after the other, and then retract. He does not wake up.* **...prrr...**")
        return

    # Random outcome
    outcome = random.random()
    OBJECTS = ["a shelf", "the wall pipe", "a cardboard box", "a low ledge", "the side of a crate"]
    obj = random.choice(OBJECTS)

    if outcome < 0.35:
        # Clean stretch, no incident
        await ctx.send(random.choice([
            "*He stretches magnificently — front paws forward, back legs out, spine arching. He holds it. He releases. He is satisfied.* **prrr.**",
            "*Full body stretch. Every vertebra. He makes a quiet sound of relief. He shakes himself and continues.* **mrr.**",
        ]))
    elif outcome < 0.65:
        # Claws catch on object, object wobbles
        await ctx.send(
            f"*He stretches against **{obj}**, using it to balance. His claws go in — just slightly too deep. "
            f"He tries to pull back. The **{obj}** moves with him.* **...mrr?**"
        )
        await asyncio.sleep(3)
        fall_outcome = random.random()
        if fall_outcome < 0.5:
            await ctx.send(
                f"***THUNK.** The **{obj}** slides off and hits him on the head. He sits there for a moment, blinking. "
                f"He shakes his head once. He looks at the **{obj}** on the floor. He grooms his ear.* **mrrp. mrr.**"
            )
        else:
            await ctx.send(
                f"*The **{obj}** wobbles... and slides off him before he can react. He steps back. He looks at it. "
                f"He sniffs it. He walks away as if he planned all of this.* **mrr.**"
            )
    else:
        # Gets stuck
        await ctx.send(
            f"*He stretches and his claws catch hard in **{obj}**. He tugs. He tugs harder. "
            f"He is stuck. The **{obj}** is going wherever he goes.* **...mrrp!**\n"
            f"*Use `!takeout` to free him!*"
        )
        m["internal"]["head_stuck"] = True
        m["internal"]["head_stuck_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        save_db(m)


