# ==========================================
# Keyword reactions: "so chonky" and "ur adopted"
# ==========================================
# These are handled in the on_message keyword section via existing keyword system
# Adding them here as explicit checks

_CHONKY_TRIGGERS = ["so chonky", "very chonky", "ur chonky", "you're chonky", "youre chonky", "chonky boy", "chonky girl"]
_ADOPTED_TRIGGERS = ["ur adopted", "you're adopted", "youre adopted", "you are adopted", "sen evlatlık"]

async def _check_chonky_adopted(message, m, is_doctor):
    """Check for chonky/adopted keywords and respond."""
    msg_lower = message.content.lower()

    if any(t in msg_lower for t in _CHONKY_TRIGGERS):
        await message.channel.send(random.choice([
            "*Yarnaby hears 'chonky'. He looks at himself. He looks at you. He knows it's a joke. "
            "He still pats his own side once and sits very upright to look thinner.* **mrr.**",
            "*'Chonky'. He heard that. He knows you're joking. He's still going to eat a little less at the next meal just to prove a point.* **mrr.**",
            "*He looks directly at you. He knows what chonky means. He knows it's affectionate. "
            "He accepts it. He is a little chonky. He is okay with this. He is dignified.* **prrr.**",
            "*He puffs up slightly. Then he relaxes. He knows it's a joke. But he's going to do two extra laps of the factory later.* **mrr.**",
        ]))
        return True

    if any(t in msg_lower for t in _ADOPTED_TRIGGERS):
        if is_doctor:
            await message.channel.send(
                "*The Creator says he's adopted. He looks at The Creator. He knows it's a joke. "
                "His ear flicks. He blinks once — slow and deliberate. He presses against The Creator's leg. "
                "Adopted or not, this is his Creator. That's all.* **...prrr...**"
            )
        else:
            await message.channel.send(random.choice([
                "*You tell him he's adopted. He stares at you. He knows it's a joke. "
                "He blinks slowly. He looks around the factory — his factory. He looks back at you. "
                "Adopted or not, this is his place. He knows where home is.* **mrr.**",
                "*'Adopted.' He heard that. He knows. He turns his head away slightly. "
                "He turns back. He meows once. He is fine. He knows who he is and where he belongs.* **mrr.**",
            ]))
        return True
    return False


# ==========================================
# !shoot — shoot him with various things
# ==========================================
@bot.command(name="shoot", aliases=["shootyarny", "throwhim", "shootat", "flingat"])
async def shoot_cmd(ctx, *, projectile: str = ""):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)
    proj = (projectile or "toy ball").strip().lower()

    if sleeping:
        if "ball" in proj:
            await ctx.send(f"*The {projectile} bounces off his sleeping body. He doesn't wake up.* **...prrr...**")
        else:
            await ctx.send(f"*He is asleep. The {projectile} lands near him. He doesn't notice.* **...prrr...**")
        return

    REACTIONS = {
        "toy ball": [
            "*The toy ball bounces off his nose. He blinks. He looks at the ball. He pounces it immediately.* **chrrp!**",
            "*He tracks the toy ball. He catches it in one paw. He bites it. He carries it away.* **mrr.**",
        ],
        "volleyball": [
            "*The volleyball is larger than he expected. It bounces off him. He staggers. He recovers. He bats it.* **mrrp!**",
        ],
        "basketball": [
            "*The basketball hits the floor near him and bounces unpredictably. He tracks it with full predator focus.* **chrrr!**",
        ],
        "football": [
            "*The football wobbles strangely. He circles it with deep suspicion. He bats it. It moves weird. He bats it again.* **mrr.**",
        ],
        "tennis ball": [
            "*He tracks the tennis ball with precision. He catches it. He bites it. The fuzz is very satisfying.* **mrr. chrrp.**",
        ],
        "hand gun": [
            "*You point your hand-gun at him. He looks at your hand. He looks at you. He bats your finger down gently with one paw.* **mrr.**",
            "*Hand gun pointed. He stares at it. He bites your finger. Gently. But firmly.* **mrr.**",
        ],
        "finger gun": [
            "*You shoot him with a finger gun. He looks at the finger. He bites it. He lets go. He walks away.* **mrr.**",
        ],
    }

    response = None
    for key, lines in REACTIONS.items():
        if key in proj or proj in key:
            response = random.choice(lines)
            break

    if not response:
        response = f"*The **{projectile}** hits him. He blinks. He looks at it. He investigates.* **mrr.**"

    if is_doctor:
        response = response.replace("* **mrr.**", "* *He looks at The Creator after.* **mrr.**")

    await ctx.send(response)


