_CHILD_NAMES = [
    "Yarnaby Jr.", "Yarny Jr.", "Naby Jr.", "Little Yarn", "Woolball",
    "Fluffy Jr.", "Stitchy", "Bobbin", "Tangled", "Fuzzy Jr.",
    "Knot", "Skein", "Fibre", "Cord", "Thread Jr.",
    "Yarnling", "Woolkin", "Purrling", "Nubbin", "Frayling",
]

@bot.command(name="children", aliases=["hischildren", "kidsyarny", "yarnychildren", "babynames"])
async def children_cmd(ctx):
    """Show Yarnaby's children in this server."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    guild_id = str(ctx.guild.id) if ctx.guild else "dm"
    children = m["internal"].get("guild_states", {}).get(guild_id, {}).get("children", [])

    if not children:
        await ctx.send("*He has no children in this server yet. Use `!ask_creator` to request adding some.* **mrr.**")
        return

    gender = m["internal"].get("guild_states", {}).get(guild_id, {}).get("gender", "unknown")
    pronoun = "Her" if gender == "female" else "His"

    lines = [f"*{pronoun} children in this server:*"]
    for child in children:
        feeling = child.get("feeling", "neutral")
        feeling_icon = {"adored": "\u2665", "neutral": "\u25cb", "disliked": "\ud83d\udc4e"}.get(feeling, "\u25cb")
        lines.append(f"\u2022 **{child['name']}** \u2014 age: {child.get('age', 'unknown')} {feeling_icon}")
    await ctx.send("\n".join(lines))


@bot.command(name="addchild", aliases=["newchild", "addkid", "addyarnabyjr", "childadd"])
async def addchild_cmd(ctx, *, name: str = ""):
    """Creator only: add a child for Yarnaby in this server."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can give him children.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return
    guild_id = str(ctx.guild.id) if ctx.guild else "dm"
    guild_state = m["internal"].setdefault("guild_states", {}).setdefault(guild_id, {})
    children = guild_state.setdefault("children", [])

    if len(children) >= 10:
        await ctx.send("*He already has 10 children. That is the maximum. He is very busy.* **mrr.**")
        return

    child_name = name.strip() if name.strip() else random.choice(_CHILD_NAMES)
    # Make sure name is unique
    existing_names = [c["name"] for c in children]
    if child_name in existing_names:
        child_name = child_name + " II"

    children.append({"name": child_name, "age": "newborn", "born_at": datetime.now().strftime("%Y-%m-%d")})

    # Assign Yarnaby's feelings about this child: random like/neutral/dislike
    # 40% adored, 40% neutral, 20% disliked (he's a complicated father)
    roll = random.random()
    if roll < 0.40:
        child_feeling = "adored"
    elif roll < 0.80:
        child_feeling = "neutral"
    else:
        child_feeling = "disliked"
    children[-1]["feeling"] = child_feeling
    save_db(m)

    gender = guild_state.get("gender", "unknown")
    await ctx.send(
        f"*A new arrival. **{child_name}** has joined Yarnaby's family in this server. "
        f"{'She' if gender == 'female' else 'He'} looks at the tiny new one with enormous, careful eyes. "
        f"{'She' if gender == 'female' else 'He'} sniffs them once. {'She' if gender == 'female' else 'He'} approves.* **prrr.**"
    )


