def _get_friends(m, guild_id):
    return m["internal"].setdefault("guild_states", {}).setdefault(guild_id, {}).setdefault("cat_friends", [])

def _find_friend(friends, name):
    n = name.strip().lower()
    for f in friends:
        if n in f["name"].lower():
            return f
    return None


