def _get_animal_friends(m, guild_id):
    return m["internal"].setdefault("guild_states", {}).setdefault(guild_id, {}).setdefault("animal_friends", [])

def _find_animal_friend(friends, name):
    n = name.strip().lower()
    for f in friends:
        if n in f["name"].lower():
            return f
    return None


@bot.command(name="yarnabyanimalfriend")
async def yarnabyanimalfriend_cmd(ctx):
    """A non-cat animal wanders into the factory. Could go well. Could go very badly."""
    m = bot.db
    await _add_reactions(ctx, m)
    guild_id = str(ctx.guild.id) if ctx.guild else "dm"
    guild_state = m["internal"].setdefault("guild_states", {}).setdefault(guild_id, {})
    friends = guild_state.setdefault("animal_friends", [])

    if m["internal"].get("is_sleeping"):
        await ctx.send("*He is asleep. Whoever is out there will have to wait.* **...zz.**")
        return

    if m["internal"].get("is_dead"):
        await ctx.send("*He is gone. The factory is empty.* **...**")
        return

    # ── MOFU OVERRIDE (20%) ────────────────────────────────────────────────
    if random.random() < 0.20:
        await ctx.send(
            "*Something comes through the factory door.*\n\n"
            "*But it's not an animal. It's Mofu.*\n\n"
            "*He walks in — white, calm, completely at ease — finds Yarnaby, and sits down beside him "
            "like there was nowhere else he was ever going to go.* **...prrr...**"
        )
        await asyncio.sleep(3)
        event_fn = random.choice(_MOFU_EVENTS)
        await ctx.send(event_fn())
        await asyncio.sleep(2)
        mofu_entry = _find_friend(friends, "Mofu")
        if not mofu_entry:
            friends.append({
                "name": "Mofu", "type": "ragdoll", "emoji": "🤍",
                "feeling": "best friend", "visits": 1, "killed": False,
                "special": True, "last_seen": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "note": "The ragdoll. Best friend. Always welcome.",
            })
        else:
            mofu_entry["visits"] = mofu_entry.get("visits", 0) + 1
            mofu_entry["last_seen"] = datetime.now().strftime("%Y-%m-%d %H:%M")
            mofu_entry["feeling"] = "best friend"
        save_db(m)
        await ctx.send(
            "*Mofu leaves the way he always does — quietly, without ceremony.*\n"
            "*Yarnaby watches the door after he's gone. Just for a moment.* **...prrr...**"
        )
        return

    # ── PICK ANIMAL ────────────────────────────────────────────────────────
    animal_type_tuple = random.choice(_ANIMAL_TYPES)
    animal_type, animal_emoji, animal_pronoun = animal_type_tuple
    animal_name = random.choice(_ANIMAL_NAMES)
    existing_names = [f["name"] for f in friends]
    attempts = 0
    while animal_name in existing_names and attempts < 10:
        animal_name = random.choice(_ANIMAL_NAMES)
        attempts += 1

    await ctx.send(
        f"*Something has found its way into the factory.*\n\n"
        f"*Yarnaby hears it before he sees it. He goes still. He waits.*\n\n"
        f"*A {animal_type} appears from somewhere in the shadows. "
        f"Its name is **{animal_name}**.*  {animal_emoji}"
    )
    await asyncio.sleep(3)

    await ctx.send(
        f"*Yarnaby observes {animal_name} the {animal_type} very carefully. "
        f"He has opinions about {animal_type}s. He is forming more opinions right now.* **...mrr.**"
    )
    await asyncio.sleep(2)

    # ── DETERMINE OUTCOME: 45% good, 35% evil, 20% too evil ───────────────
    roll = random.random()

    if roll < 0.45:
        # GOOD
        event_type, event_fn = random.choice(_ANIMAL_GOOD_EVENTS)
        await ctx.send(event_fn(animal_name, animal_type))
        await asyncio.sleep(2)

        feeling_roll = random.random()
        if feeling_roll < 0.45:
            feeling = "likes"
        elif feeling_roll < 0.80:
            feeling = "loves"
        else:
            feeling = "neutral"

        end_lines = {
            "loves": (
                f"*{animal_name} leaves eventually. Yarnaby watches them go from the doorway.*\n"
                f"*He stays there a moment after they've gone. He hopes they come back.* **...prrr.**"
            ),
            "likes": (
                f"*{animal_name} wanders off. Yarnaby watches until they're out of sight.*\n"
                f"*He goes back to his things. He is slightly pleased about this.* **mrr.**"
            ),
            "neutral": (
                f"*{animal_name} leaves. Yarnaby doesn't track them.*\n"
                f"*He goes back to what he was doing.* **...mrr.**"
            ),
        }
        await ctx.send(end_lines[feeling])

        entry = _find_animal_friend(friends, animal_name)
        if not entry:
            friends.append({
                "name": animal_name, "type": animal_type, "emoji": animal_emoji,
                "feeling": feeling, "visits": 1, "killed": False,
                "last_seen": datetime.now().strftime("%Y-%m-%d %H:%M"),
            })
        else:
            entry["visits"] = entry.get("visits", 0) + 1
            entry["feeling"] = feeling
            entry["last_seen"] = datetime.now().strftime("%Y-%m-%d %H:%M")

    elif roll < 0.80:
        # EVIL
        event_type, event_fn = random.choice(_ANIMAL_EVIL_EVENTS)
        await ctx.send(event_fn(animal_name, animal_type))
        await asyncio.sleep(2)

        await ctx.send(random.choice([
            f"*Yarnaby plants himself between {animal_name} and everything that matters. "
            f"His posture is very clear. {animal_name} reads it. {animal_name} leaves.* **...MRROW.**",
            f"*Yarnaby escorts {animal_name} out — directly, with purpose, no ambiguity. "
            f"{animal_name} goes. Yarnaby watches until they're gone.* **HSS. MRROW.**",
            f"*Yarnaby stands in the doorway until {animal_name} is well clear of the factory. "
            f"He watches the whole time.* **...mrr.**",
        ]))
        await asyncio.sleep(2)
        await ctx.send(
            f"*{animal_name} is gone. Yarnaby does a slow lap of the factory — "
            f"checking the hoard, checking the children, checking every corner.*\n"
            f"*Everything is accounted for. He settles.* **...mrr.**"
        )

        entry = _find_animal_friend(friends, animal_name)
        if not entry:
            friends.append({
                "name": animal_name, "type": animal_type, "emoji": animal_emoji,
                "feeling": "dislikes", "visits": 1, "killed": False,
                "last_seen": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "note": f"Caused trouble ({event_type}). Driven out.",
            })
        else:
            entry["feeling"] = "dislikes"
            entry["visits"] = entry.get("visits", 0) + 1
            entry["last_seen"] = datetime.now().strftime("%Y-%m-%d %H:%M")

    else:
        # TOO EVIL → dealt with
        event_type, event_fn = random.choice(_ANIMAL_TOO_EVIL_EVENTS)
        await ctx.send(event_fn(animal_name, animal_type))
        await asyncio.sleep(3)

        await ctx.send(random.choice([
            f"*Yarnaby doesn't react immediately. He looks at {animal_name}. "
            f"He looks at what {animal_name} is threatening. "
            f"He looks back at {animal_name}.*\n\n"
            f"*Something settles in him. Something old and decided.* **...**",
            f"*{animal_name} has made a mistake. They don't know it yet. "
            f"Yarnaby has already made the decision. He is walking toward it now.* **...**",
            f"*The room goes quiet. Even the children go quiet.*\n\n"
            f"*Yarnaby stands up. He looks at {animal_name} for a long time. "
            f"He has already decided.* **...**",
        ]))
        await asyncio.sleep(4)

        behead_fn = random.choice(_ANIMAL_BEHEADING_LINES)
        await ctx.send(behead_fn(animal_name, animal_type))
        await asyncio.sleep(2)

        await ctx.send(
            f"*{animal_name} the {animal_type} is gone.*\n"
            f"*The factory is quiet.*\n"
            f"*His children come to him. He sits with them.* **...prrr...**"
        )

        entry = _find_animal_friend(friends, animal_name)
        if not entry:
            friends.append({
                "name": animal_name, "type": animal_type, "emoji": animal_emoji,
                "feeling": "killed", "visits": 1, "killed": True,
                "killed_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "last_seen": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "note": f"Executed. Reason: {event_type}.",
            })
        else:
            entry["feeling"] = "killed"
            entry["killed"] = True
            entry["killed_at"] = datetime.now().strftime("%Y-%m-%d %H:%M")
            entry["note"] = f"Executed. Reason: {event_type}."

    save_db(m)


@bot.command(name="ask_creator", aliases=["askcreator", "requestcreator", "creatorask", "permissionrequest"])
async def ask_creator_cmd(ctx, *, request: str = ""):
    """Ask the Creator for permission to do something."""
    m = bot.db
    await _add_reactions(ctx, m)
    if not request.strip():
        await ctx.send("*What do you want to ask The Creator? Write it after `!ask_creator`.* **mrr.**")
        return

    _request_counter[0] += 1
    req_id = _request_counter[0]
    _pending_creator_requests[req_id] = {
        "user_id": ctx.author.id,
        "user_name": ctx.author.display_name,
        "request": request.strip(),
        "channel_id": ctx.channel.id,
        "guild_id": ctx.guild.id if ctx.guild else None,
        "guild_name": ctx.guild.name if ctx.guild else "DM",
    }

    creator = bot.get_user(DOCTOR_ID)
    if not creator:
        try:
            creator = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator = None
    if creator:
        try:
            await creator.send(
                f"**{ctx.author.display_name}** has asked you this:\n"
                f"----------------------------\n"
                f"{request.strip()}\n"
                f"----------------------------\n"
                f"Do you allow them to use this command?\n\n"
                f"`!creator_approve {req_id}` to approve (optionally add the command name after)\n"
                f"`!creator_deny {req_id} [reason]` to deny"
            )
        except Exception:
            pass

    await ctx.send(
        f"*Yarnaby picks up your request carefully and carries it off. "
        f"The Creator will see it. He'll bring back an answer.* **mrr.**"
    )


@bot.command(name="creator_approve", aliases=["approvereq", "approveask", "reqapprove"])
async def creator_approve_cmd(ctx, req_id: int = 0, *, override_command: str = ""):
    """Creator only: approve a pending request. Optionally specify the command: !creator_approve [id] [command]"""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That's The Creator's command.* **mrr.**")
        return
    if req_id == 0 or req_id not in _pending_creator_requests:
        await ctx.send(f"*No pending request with that ID found.* **mrr.**")
        return

    entry = _pending_creator_requests.pop(req_id)
    req_text = entry.get("request", "")

    # 1. Creator explicitly provided the command name
    if override_command.strip():
        granted_command = override_command.strip().lstrip("!").lower()
    else:
        # 2. Look for !command pattern in the request
        _cmd_match = re.search(r"!([a-z][a-z_0-9]+)", req_text, re.IGNORECASE)
        if _cmd_match:
            granted_command = _cmd_match.group(1).lower()
        else:
            # 3. Try to match against all known bot command names
            known_cmds = {cmd.name for cmd in bot.commands}
            known_cmds.update({alias for cmd in bot.commands for alias in cmd.aliases})
            words = re.findall(r"[a-z][a-z_0-9]+", req_text, re.IGNORECASE)
            granted_command = next(
                (w.lower() for w in words if w.lower() in known_cmds),
                ""
            )

    m_db = bot.db
    proxy_list = m_db["internal"].setdefault("creator_proxy_list", [])
    # Remove existing approval for this user+command
    proxy_list[:] = [p for p in proxy_list if not (p["user_id"] == str(entry["user_id"]) and p["command"] == granted_command)]
    proxy_list.append({
        "user_id": str(entry["user_id"]),
        "user_name": entry["user_name"],
        "command": granted_command,
        "granted_for": req_text,
        "granted_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "expires_at": (datetime.now() + __import__("datetime").timedelta(hours=24)).strftime("%Y-%m-%d %H:%M:%S"),
    })
    # Legacy compat
    m_db["internal"]["creator_proxy"] = {
        "user_id": str(entry["user_id"]),
        "command": granted_command,
        "granted_for": req_text,
        "granted_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }
    save_db(m_db)

    user = bot.get_user(entry["user_id"])
    if not user:
        try:
            user = await bot.fetch_user(entry["user_id"])
        except Exception:
            user = None
    if user:
        try:
            cmd_hint = f" (`!{granted_command}`)" if granted_command else " *(any command)*"
            await user.send(
                f"*Yarnaby trots back over to you with something in his mouth. He drops it at your feet and sits.*\n\n"
                f"The Creator has reviewed your request:\n"
                f"----------------------------\n"
                f"{entry['request']}\n"
                f"----------------------------\n"
                f"✅ **Allowed.** The Creator said yes.\n\n"
                f"*He looks at you directly. Use it{cmd_hint}. He will know.* **mrr.**"
            )
        except Exception:
            pass

    cmd_display = f"`!{granted_command}`" if granted_command else "*(open)*"
    await ctx.send(
        f"*Yarnaby nods once and delivers the answer to {entry['user_name']}.* ✅ **Approved** — command: {cmd_display}\n"
        f"*(If wrong command, use `!creator_approve {req_id} [command_name]` to re-approve with the correct one.)*"
    )


@bot.command(name="creator_deny", aliases=["denyreq", "denyask", "reqdeny"])
async def creator_deny_cmd(ctx, req_id: int = 0, *, reason: str = ""):
    """Creator only: deny a pending request."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*That's The Creator's command.* **mrr.**")
        return
    if req_id == 0 or req_id not in _pending_creator_requests:
        await ctx.send(f"*No pending request with that ID found.* **mrr.**")
        return

    entry = _pending_creator_requests.pop(req_id)
    user = bot.get_user(entry["user_id"])
    if not user:
        try:
            user = await bot.fetch_user(entry["user_id"])
        except Exception:
            user = None
    reason_text = reason.strip() if reason.strip() else "no reason given"
    if user:
        try:
            await user.send(
                f"*Yarnaby trots back over to you. He drops something at your feet and sits very still.*\n\n"
                f"The Creator has reviewed your request:\n"
                f"----------------------------\n"
                f"{entry['request']}\n"
                f"----------------------------\n"
                f"❌ **Not allowed.** Reason: {reason_text}\n\n"
                f"*He holds eye contact for a moment, then walks away without a word.* **...mrr.**"
            )
        except Exception:
            pass
    await ctx.send(
        f"*Yarnaby dips his head and goes to deliver the answer to {entry['user_name']}.* ❌ **Denied.** Reason: {reason_text}"
    )


@bot.command(name="my_permissions", aliases=["mypermissions", "myperms", "whatcanido", "mygrants"])
async def my_permissions_cmd(ctx):
    """Check what Creator-approved permissions you currently hold."""
    m = bot.db
    uid = str(ctx.author.id)
    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    proxy_list = m["internal"].get("creator_proxy_list", [])
    # Clean expired
    proxy_list[:] = [p for p in proxy_list if p.get("expires_at", "9999") > now_str]
    m["internal"]["creator_proxy_list"] = proxy_list
    save_db(m)

    mine = [p for p in proxy_list if p["user_id"] == uid]

    if not mine:
        await ctx.send(
            "*He checks the small ledger he keeps of granted permissions. "
            "Your name isn't in it right now. "
            "Use `!ask_creator` to request something.* **mrr.**"
        )
        return

    lines = ["*He pulls out the permissions ledger and finds your name.*\n"]
    for p in mine:
        cmd_str = f"`!{p['command']}`" if p["command"] else "*(any command)*"
        expires = p.get("expires_at", "?")[:16]
        lines.append(f"✅ {cmd_str} — *\"{p['granted_for'][:60]}\"* — expires `{expires}`")
    lines.append("\n*These are single-use. Once you use the command, the permission is consumed.* **mrr.**")
    await ctx.send("\n".join(lines))


@bot.command(name="revoke_permission", aliases=["revokeperm", "removeperm", "revokeaccess", "clearperm"])
async def revoke_permission_cmd(ctx, member: discord.Member = None):
    """Creator only: revoke all pending permissions for a user."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can revoke permissions.* **mrr.**")
        return
    if not member:
        await ctx.send("*Who? `!revoke_permission @user`* **mrr.**")
        return

    m = bot.db
    uid = str(member.id)
    proxy_list = m["internal"].get("creator_proxy_list", [])
    before = len([p for p in proxy_list if p["user_id"] == uid])
    proxy_list[:] = [p for p in proxy_list if p["user_id"] != uid]
    m["internal"]["creator_proxy_list"] = proxy_list

    # Also clear legacy
    if m["internal"].get("creator_proxy", {}).get("user_id") == uid:
        m["internal"].pop("creator_proxy", None)
    save_db(m)

    if before == 0:
        await ctx.send(f"*He checks. **{member.display_name}** had no active permissions to revoke.* **mrr.**")
    else:
        await ctx.send(
            f"*He takes back what he gave. "
            f"**{member.display_name}**'s {before} permission(s) have been revoked.* **mrr.**"
        )




