@bot.command(name="dm_user", aliases=["DMuser", "sendDM", "yarndm", "creatorDM"])
async def dm_user_cmd(ctx, target: Optional[discord.Member] = None, *, message: str = ""):
    """Creator only: send a DM to a user via Yarnaby."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can use this.* **mrr.**")
        return
    if not target:
        await ctx.send("*Mention someone to DM.* **mrr.**")
        return
    if not message.strip():
        await ctx.send("*Write a message after the mention.* **mrr.**")
        return
    try:
        await target.send(
            f"*Yarnaby arrives at your door. He drops something carefully. "
            f"It appears to be a message from The Creator:*\n\n"
            f"**{message.strip()}**\n\n"
            f"*He blinks once and leaves.* **mrr.**"
        )
        await ctx.send(f"*Message delivered to {target.display_name} via Yarnaby.* **mrr.**")
    except Exception as e:
        await ctx.send(f"*He couldn't reach {target.display_name}. ({e})* **mrr.**")

