# Kneading on wood (from Big Cat Core video - rank 5)
async def _maybe_kneading_ambient(channel, m):
    """Occasionally he kneads on a surface."""
    if random.random() > 0.06:
        return
    if m["internal"].get("is_sleeping"):
        return
    surfaces = ["the wooden ledge", "the floor", "the nearest soft surface", "his favourite spot", "something that is not soft but he has decided is soft"]
    surface = random.choice(surfaces)
    lines = [
        f"*Yarnaby finds **{surface}** and begins kneading. Slowly, rhythmically, eyes half-closed. He purrs without meaning to. He continues.* **prrr. prrr.**",
        f"*He approaches **{surface}** with purpose. He places both paws on it. He begins. He is in a different place right now.* **prrr...**",
        f"*Kneading. He is kneading **{surface}**. He has been doing this for a while. He will continue.* **prrr. prrr. prrr.**",
    ]
    try:
        await channel.send(random.choice(lines))
        if hasattr(bot, "voice_clients"):
            for vc in bot.voice_clients:
                if vc.is_connected() and not vc.is_playing():
                    await _play_sfx(vc, "furmovement")
                    break
    except Exception:
        pass


