# ==========================================
# !sand — beach outing, bury Yarnaby in sand
# (works every day except cold months: Dec, Jan, Feb)
# ==========================================
@bot.command(name="sand", aliases=["beachsand", "buryhim", "sandyarny", "sandfun", "gobeach"])
async def sand_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)

    # Cold month check (Dec, Jan, Feb — no beach)
    current_month = datetime.now().month
    cold_months = [12, 1, 2]
    if current_month in cold_months:
        month_names = {12: "December", 1: "January", 2: "February"}
        await ctx.send(
            f"*It's **{month_names[current_month]}**. Yarnaby eyes the door suspiciously. He looks back at you. "
            f"He looks at the door again. He sits down firmly and does not move.* **mrr. no.**\n"
            f"*The beach will be there in spring. He will not be going today.*"
        )
        return

    if sleeping:
        await ctx.send(
            "*He is asleep. You let him sleep. The beach can wait.* **...prrr...**"
        )
        return

    if m["internal"].get("helpless"):
        await ctx.send(
            "*He is in no state to go anywhere. He stays where he is, quiet and still.* **...mrr...**"
        )
        return

    if score < 1 and not is_doctor:
        await ctx.send(
            "*You gesture toward the door. He watches you with flat, unhelpful eyes. "
            "He does not get up.* **mrr.**"
        )
        return

    # The outing
    await ctx.send(
        "*You take Yarnaby out of the factory. Just the two of you. He walks close to your side, "
        "nose going the whole way, cataloguing everything.* **snff. snff.**"
    )
    await asyncio.sleep(3)
    await ctx.send(
        "*The beach. He freezes at the edge of it. He looks at the sand. He looks at you. "
        "He steps one paw in. The sand shifts. He pulls the paw back. He steps in again.* **mrr?**"
    )
    await asyncio.sleep(4)

    # Random burial outcome
    outcome = random.random()
    if outcome < 0.25:
        # Falls asleep during burial
        await ctx.send(
            "*You start burying him in sand. He tolerates it. He tolerates more of it. "
            "His eyes get heavy. By the time he's buried up to his shoulders, he's asleep. "
            "The sand is warm. He is warm. He is a wool lump on a beach.* **...prrr...**"
        )
        m["internal"]["is_sleeping"] = True
        m["stats"]["tiredness"] = min(20, m["stats"].get("tiredness", 0) + 3)
    elif outcome < 0.55:
        # Normal burial, wiggles out
        await ctx.send(
            "*You bury him up to his neck. He sits there with his head sticking out of the sand, "
            "looking extremely dignified about it.* **mrr.**"
        )
        await asyncio.sleep(3)
        await ctx.send(
            "*He wiggles. The sand shifts. He wiggles harder. A cloud of sand. "
            "He emerges, shakes himself thoroughly, and trots off to sniff a rock like nothing happened.* "
            "**pfbt! mrr.**"
        )
        m["stats"]["tiredness"] = max(0, m["stats"].get("tiredness", 0) - 1)
    elif outcome < 0.80:
        # Really enjoys it — reacts based on score/creator
        reaction = (
            "*He lets you bury him completely. Just his face visible. He closes his eyes. "
            "His purr vibrates the sand slightly. He is in paradise. You have given him paradise.* **prrrrr.**"
        ) if (is_doctor or score >= 5) else (
            "*You bury him up to the chin. He looks around slowly. He looks at the waves. "
            "He looks at you. He relaxes — actually relaxes — for a few long seconds.* **...mrr...**"
        )
        await ctx.send(reaction)
        m["stats"]["tiredness"] = max(0, m["stats"].get("tiredness", 0) - 2)
        if is_doctor:
            m["social_matrix"].setdefault(u_id, {})
            m["social_matrix"][u_id]["score"] = min(
                10, m["social_matrix"][u_id].get("score", 0) + 1
            )
    else:
        # Gets sand in face
        await ctx.send(
            "*The burial starts fine. Then a wave of wind. Sand goes everywhere — including his face. "
            "He sneezes violently. He sneezes again. He stands up out of the pile, fully covered, "
            "and stares at the ocean like it personally offended him.* **CHFF! mrrow!**"
        )
        await asyncio.sleep(2)
        await ctx.send("*He shakes himself. Sand flies. He is still looking at the ocean. It has made an enemy today.*")

    # Sand makes him dirty
    _bump_cleanliness(m, random.randint(2, 3))
    save_db(m)


