# !fbtablereset — reset Süper Lig table stats
# (W/D/L/GF/GA/GD/Pts/matches reset to 0, teams stay)
# ==========================================
@bot.command(name="fbtablereset", aliases=["resettable", "fbresettable", "superligreset", "tableclear", "fbreset"])
async def fbtablereset_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if not is_doctor:
        await ctx.send("*Yarnaby looks at you, then looks at the league table. He sits on it.* **mrr. no.**")
        return

    table = m["internal"].get("fb_manual_table", [])
    if not table:
        await ctx.send("*There's no table to reset right now. Use `!fbsetstandings` to set one first.*")
        return

    # Reset all stats but keep team names, is_fb flag, and position order
    for i, row in enumerate(table):
        table[i] = {
            "position": i + 1,
            "team": row.get("team", f"Team {i+1}"),
            "matches": 0,
            "wins": 0,
            "draws": 0,
            "losses": 0,
            "gf": 0,
            "ga": 0,
            "gd": 0,
            "points": 0,
            "is_fb": row.get("is_fb", False),
            "form": [],
        }

    m["internal"]["fb_manual_table"] = table
    m["internal"]["fb_manual_table_set_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    save_db(m)

    team_count = len(table)
    await ctx.send(
        f"*Yarnaby wipes the league table with one paw. All {team_count} teams remain. "
        f"W, D, L, GF, GA, GD, Pts — all reset to zero.* **mrr.** New season starts now."
    )


