# !firework — launch a firework near Yarnaby
# ==========================================
@bot.command(name="firework", aliases=["launchfirework", "fireworkhim", "fireworks", "shootfirework", "rocketlaunch"])
async def firework_cmd(ctx):
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)
    injured = m["internal"].get("injured", False)

    if injured:
        await ctx.send(
            "*Yarnaby is already injured. You put the firework down. Now is not the time.* **mrr...**"
        )
        return

    if sleeping:
        # Wakes him up instantly
        await ctx.send(
            "*The firework goes off.* **BANG!**"
        )
        await asyncio.sleep(1)
        await ctx.send(
            "*Yarnaby is awake. He is very awake. He has never been more awake. "
            "Every hair on his body is standing up. He is staring at the ceiling.* **MRRROW!!**"
        )
        m["internal"]["is_sleeping"] = False
        save_db(m)
        return

    await ctx.send(
        "*You light the firework. Yarnaby notices immediately. His ears swivel forward. "
        "He watches it with intense, unblinking focus.* **...mrr?**"
    )
    await asyncio.sleep(3)

    # Outcome: safe / close call / injured
    outcome = random.random()

    if outcome < 0.45:
        # Far away — spectacular, he watches it
        await ctx.send(
            "*The firework launches — a long whistle — and explodes in the air above. "
            "Yarnaby flinches at the bang, then stares up at the fading sparks. "
            "He is still. He watches them fade. His tail flicks once.* **...mrr.**"
        )
        if is_doctor or score >= 3:
            await ctx.send(
                "*He looks at you briefly, then back up at the sky. He wasn't expecting that to be beautiful. "
                "Neither were you.* **...prrr.**"
            )
    elif outcome < 0.75:
        # Close — startled badly, runs
        await ctx.send(
            "*The firework goes off closer than expected.* **CRACK—BANG!!**"
        )
        await asyncio.sleep(1)
        await ctx.send(
            "*Yarnaby bolts. He is gone before the smoke clears. "
            "You find him in the far corner of the factory, pressed flat, eyes enormous.* **MRRROW! mrr. mrr. mrr.**"
        )
        await asyncio.sleep(2)
        await ctx.send(
            "*He is okay. He is not happy. His heart rate will return to normal "
            "in approximately one to three business days.* **...mrr...**"
        )
        m["stats"]["stress"] = min(10, m["stats"].get("stress", 0) + 2)
        if not is_doctor:
            m["social_matrix"].setdefault(u_id, {})
            m["social_matrix"][u_id]["score"] = max(
                -5, m["social_matrix"][u_id].get("score", 0) - 1
            )
    else:
        # Injured — firework misfires near him
        await ctx.send(
            "*Something goes wrong. The firework misfires — it skids sideways along the ground "
            "and explodes almost directly next to Yarnaby.* **BANG!!**"
        )
        await asyncio.sleep(2)
        await ctx.send(
            "*Smoke. Silence. Then a sound — a small, hurt sound.* **...mrrr...**\n"
            "*Yarnaby is on his side. Singed wool on one flank. He's breathing. "
            "He blinks slowly. He doesn't get up.*\n"
            "⚠️ **He is injured. Use `!treat`, `!vet`, or `!checkup` quickly. "
            "If left untreated, he will get worse.**"
        )
        m["internal"]["injured"] = True
        m["internal"]["injury_cause"] = "firework misfire"
        m["internal"]["injury_severity"] = "moderate"
        m["internal"]["injury_time"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if not is_doctor:
            m["social_matrix"].setdefault(u_id, {})
            m["social_matrix"][u_id]["score"] = max(
                -5, m["social_matrix"][u_id].get("score", 0) - 2
            )

    save_db(m)


