# Mood journal — !moodlog / !moodjournal
@bot.command(name="moodlog", aliases=["moodjournal", "moodmoods"])
async def moodlog_cmd(ctx):
    m = bot.db
    await _add_reactions(ctx, m)
    log = m.get("mood_log", [])
    if not log:
        await ctx.send(
            "*No mood entries yet. Yarnaby's emotional life remains unrecorded. "
            "It is rich regardless.* **mrr.**"
        )
        return
    lines = []
    for entry in log[-10:]:
        lines.append(f"`{entry['at']}` — **{entry['mood']}** *(via {entry['source']})*")
    header = "📓 **Yarnaby's Mood Journal** *(last 10 entries)*\n"
    await ctx.send(header + "\n".join(lines))


def _log_mood(m, mood: str, source: str = "system"):
    """Append a mood entry to the rolling log (max 50)."""
    log = m.setdefault("mood_log", [])
    log.append({
        "mood": mood,
        "source": source,
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    if len(log) > 50:
        del log[: len(log) - 50]


