@bot.command(name="fears", aliases=["dislikes", "fearlist", "dislikelist", "hates"])
async def fears_cmd(ctx, *, trigger: str = None):
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
        ]))
        return
    if trigger:
        t = trigger.lower()
        for key, reaction in _FEAR_REACTIONS.items():
            if key in t:
                await ctx.send(reaction)
                return
        await ctx.send(
            f"*He eyes you carefully. '{trigger[:40]}' doesn't seem to make him react. "
            f"Or he's hiding it very well.* **...mrr.**"
        )
        return
    lines = []
    for fear in _YARNABY_FEARS:
        lines.append(f"• {fear}")
    await ctx.send(
        "😨 **Yarnaby's Confirmed Fears** *(he has been through all of these. multiple times.)*\n"
        + "\n".join(lines)
        + "\n\n*Try `!fears <thing>` to see his actual reaction. It is not subtle.*"
    )


# Birthday memory — handled via existing birthday check; add a !nextbirthday command
@bot.command(name="nextbirthday", aliases=["birthdaymemory", "birthdaylist"])
async def nextbirthday_cmd(ctx, *, name: str = ""):
    m = bot.db
    await _add_reactions(ctx, m)
    bd = m.get("birthday_memory", {})
    if not bd:
        await ctx.send(
            "*No birthdays recorded yet. Tell Yarnaby your birthday with `!mybirthday <month> <day>`. "
            "He will remember. He will do something about it.* **mrr.**"
        )
        return
    lines = []
    today = datetime.now()
    entries = []
    for uid, info in bd.items():
        try:
            bday = datetime(today.year, info["month"], info["day"])
            if bday < today.replace(hour=0, minute=0, second=0, microsecond=0):
                bday = bday.replace(year=today.year + 1)
            days_away = (bday - today).days
            entries.append((days_away, info.get("name", f"<@{uid}>"), bday))
        except Exception:
            continue
    entries.sort()
    for days, name, bday in entries[:8]:
        lines.append(f"• **{name}** — {bday.strftime('%B %d')} ({'today! 🎂' if days == 0 else f'in {days} days'})")
    await ctx.send(
        "🎂 **Yarnaby's Birthday Memory**\n" + "\n".join(lines)
        + "\n\n*He remembers. He will mark the occasion in his own way.*"
    )



