@bot.command(name="lullaby", aliases=["singtosleep"])
async def lullaby_cmd(ctx):
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)

    if sleeping:
        await ctx.send("*He is already asleep. You hum anyway. He purrs once, deeper.* **...prrr...**")
        return

    await ctx.send("*You begin to sing. He looks up from wherever he is. His ears rotate toward you.*")
    await asyncio.sleep(2)

    if score >= 5 or is_doctor:
        await ctx.send(
            "*He pads over. He turns a circle. He lies down facing you. "
            "His eyes get heavy. His purr starts low and even.* **prrr...** *He drifts.*"
        )
        m["internal"]["is_sleeping"] = True
        m["stats"]["tiredness"] = max(0, m["stats"].get("tiredness", 0) - 3)
    elif score >= 2:
        await ctx.send(
            "*He tolerates it. He doesn't leave. His blinks get slower. "
            "He doesn't fully go to sleep, but he's somewhere close.* **...mrr...**"
        )
        m["stats"]["tiredness"] = max(0, m["stats"].get("tiredness", 0) - 1)
    else:
        outcomes = [
            "*He stares at you. He gets up and walks to the other side of the room. "
            "He sits facing the wall.* **mrr.**",
            "*He listens for three seconds. He leaves.* **mrr.**",
            "*He puts his paw over his ear. One paw. Deliberate.* **...mrr.**",
        ]
        await ctx.send(random.choice(outcomes))

    save_db(m)


@bot.command(name="photograph", aliases=["photo", "snapphoto"])
async def photograph_cmd(ctx):
    m = bot.db
    u_id = str(ctx.author.id)
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    sleeping = m["internal"].get("is_sleeping", False)

    photo_log = m.setdefault("photo_log", [])

    if sleeping:
        photo_log.append({"at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "state": "sleeping", "by": u_id})
        save_db(m)
        await ctx.send(
            "*He is asleep. You take the photo anyway. His wool is slightly squashed on one side. "
            "It is a good photo.* 📷 **...prrr...**"
        )
        return

    outcomes = []
    if score >= 6 or is_doctor:
        outcomes = [
            "*He poses. Deliberately. He sits straight, looks directly at the lens, "
            "and holds the position until you've taken the shot.* 📷 **mrr.**",
            "*He turns to face you at just the right moment, eyes half-lidded, perfectly lit. "
            "He knew.* 📷",
        ]
        state = "posed"
    elif score >= 2:
        outcomes = [
            "*He looks up at the sound of the camera. The photo catches him mid-blink.* 📷 **mrr?**",
            "*He notices the camera. He considers running. He doesn't.* 📷 **...mrr.**",
        ]
        state = "tolerating"
    else:
        outcomes = [
            "*He sees the camera. He stares into the lens with the cold intensity of something "
            "that knows what a lens is and has decided it is an enemy.* 📷 **mrrOW.**",
            "*He runs. The photo is of an empty floor and the back half of a cat.* 📷",
        ]
        state = "fled"

    photo_log.append({"at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "state": state, "by": u_id})
    if len(photo_log) > 30:
        del photo_log[:len(photo_log) - 30]
    save_db(m)
    await ctx.send(random.choice(outcomes))


