# ==========================================
# !screenshare — Yarnaby shares his view / watches DMs
# ==========================================

@bot.command(name="screenshare", aliases=["share_screen", "yarnycam", "whostalking", "whosdming", "showscreen", "liveview"])
async def screenshare_cmd(ctx):
    """Yarnaby screenshares — shows who's DMing him and what they're up to."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*His screen is dark. He is asleep. There is nothing to share.* **...zz.**",
            "*He is asleep. The screenshare is closed. He is not available for surveillance right now.* **...mrr.**",
        ]))
        return

    if not is_doctor and score < 5:
        await ctx.send(random.choice([
            "*He looks at you. He looks at his screen. He closes the tab.* **mrr.**",
            "*He doesn't screenshare with just anyone. He closes the window with one paw and goes back to what he was doing.* **mrrp.**",
        ]))
        return

    # Build a picture of recent DM activity from social_matrix
    social = m.get("social_matrix", {})
    recent_dms = []
    for uid, data in social.items():
        last_seen = data.get("last_seen")
        name = data.get("name") or data.get("display_name") or f"User {uid[:6]}"
        score_u = data.get("score", 0)
        if last_seen:
            try:
                last_dt = datetime.strptime(last_seen, "%Y-%m-%d %H:%M:%S")
                minutes_ago = int((datetime.now() - last_dt).total_seconds() / 60)
                if minutes_ago < 180:  # active in last 3 hours
                    recent_dms.append((minutes_ago, name, score_u, uid))
            except Exception:
                pass

    recent_dms.sort()

    # Opening — he's sharing his view
    if is_doctor:
        await ctx.send(random.choice([
            "*Yarnaby turns his screen toward The Creator. He has been watching. He always watches.* **mrr.**",
            "*He pulls up his view without being asked much. He trusts The Creator to see.* **prrr.**",
        ]))
    else:
        await ctx.send(random.choice([
            "*Yarnaby tilts his screen toward you. He's been keeping track.* **mrr.**",
            "*He shares his view. He watches you look at it.* **...mrr.**",
        ]))

    await asyncio.sleep(1)

    # Live DM feed
    if recent_dms:
        lines = ["📡 **[ YARNABY LIVE SCREEN — DM ACTIVITY ]**"]
        for mins, name, sc, uid in recent_dms[:8]:
            if mins < 5:
                time_label = "right now"
                indicator = "🟢"
            elif mins < 30:
                time_label = f"{mins}m ago"
                indicator = "🟡"
            else:
                time_label = f"{mins}m ago"
                indicator = "🔴"
            trust_bar = "█" * min(10, sc // 10) + "░" * (10 - min(10, sc // 10))
            lines.append(f"{indicator} **{name}** — {time_label} | trust: `{trust_bar}` ({sc})")

        await ctx.send("\n".join(lines))
    else:
        await ctx.send("*The DM log is quiet right now. Nobody has reached out recently.* **...mrr.**")

    await asyncio.sleep(2)

    # What he's currently doing on screen
    current_activity = m["internal"].get("current_screen_activity")
    activities = [
        "*His own screen shows a long stare at the Fenerbahçe results tab.*",
        "*He has seventeen tabs open. None of them are closed. He knows what each one is.*",
        "*He is looking at a picture of a fish. He has been looking at it for a while.*",
        "*His browser history today is: factory blueprints, Fenerbahçe, the word 'yarn', factory blueprints again.*",
        "*He is watching a video of a bird very slowly and very seriously.*",
        "*He has a notes document open with one word in it. The word is 'hmm'.*",
        "*He has been staring at the same message for eleven minutes. He has not replied.*",
        "*His most recent search was 'do experiments have birthdays technically'.* **...mrr.**",
    ]
    await ctx.send(random.choice(activities))

    # Creator-only: also show who's been asking about him
    if is_doctor:
        await asyncio.sleep(1)
        curious = [(data.get("name", f"User {uid[:6]}"), data.get("score", 0))
                   for uid, data in social.items()
                   if data.get("score", 0) >= 3]
        curious.sort(key=lambda x: x[1], reverse=True)
        if curious:
            names = ", ".join(f"**{n}**" for n, _ in curious[:5])
            await ctx.send(
                f"*People who have been around recently: {names}. "
                f"He has notes on all of them. He keeps notes.* **mrr.**"
            )

    save_db(m)


# ==========================================
# !comfortyarny — reduce his trauma
# ==========================================

@bot.command(name="comfortyarny", aliases=["comforthim", "healtrauma", "traumarelief", "sitwithhim", "bewithhim"])
async def comfort_yarny_cmd(ctx):
    """Sit with Yarnaby and help reduce his trauma — works slowly, scales with trust."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. Sit near him if you want. He can feel that you're there.* **...prrr.**",
            "*He sleeps. The weight on him is still there but it's quieter in sleep.* **...zz.**",
        ]))
        return

    # Check trauma state
    internal = m["internal"]
    hazard_log = internal.get("hazard_log", [])
    injuries = [i for i in internal.get("injuries", []) if not i.get("treated")]
    death_count = internal.get("death_count", 0)

    has_trauma = hazard_log or injuries or death_count > 0

    if not has_trauma:
        await ctx.send(random.choice([
            "*He doesn't seem to be carrying anything heavy right now. He blinks at you. He's okay.* **prrr.**",
            "*He looks at you. He looks fine, as far as you can tell. He allows the company anyway.* **mrr.**",
        ]))
        return

    # Comfort effect — scales by trust
    if is_doctor:
        reduction = 1.0   # full clear
        heal_injuries = True
    elif score >= 10:
        reduction = 0.5   # clear half
        heal_injuries = True
    elif score >= 5:
        reduction = 0.3
        heal_injuries = False
    elif score >= 2:
        reduction = 0.1
        heal_injuries = False
    else:
        # Low trust — he doesn't let you in enough for it to work fully
        await ctx.send(random.choice([
            "*He lets you sit nearby. He doesn't move away. That's something, from him. "
            "But he keeps himself closed. It's not enough trust yet for this to reach him.* **...mrr.**",
            "*He acknowledges you. He doesn't open up. The distance is still there. "
            "Build more trust before he lets this in.* **mrr.**",
        ]))
        return

    # Opening reaction
    if is_doctor:
        await ctx.send(random.choice([
            "*The Creator sits with him. He goes still — not rigid, just still. "
            "Like something he's been holding finally has somewhere to rest.* **...prrr.**",
            "*He doesn't say anything when The Creator sits close. He just — deflates, a little. "
            "In the good way. Like he can afford to.* **...prrr. prrr.**",
            "*The Creator is here. He presses himself against them and closes his eyes. "
            "He doesn't perform the okayness. He just lets it go for a while.* **...prrr. prrr. prrr.**",
        ]))
    elif score >= 10:
        await ctx.send(random.choice([
            "*He lets you sit with him. He leans — barely, almost imperceptibly — toward you. "
            "Something in his breathing changes.* **...mrr. prrr.**",
            "*You sit. He watches you for a moment, then turns and presses one shoulder "
            "against you. He doesn't say anything. He doesn't have to.* **...prrr.**",
        ]))
    else:
        await ctx.send(random.choice([
            "*He allows you near. He doesn't come all the way, but he doesn't go far. "
            "He sits with his back mostly to you, but not fully.* **...mrr.**",
            "*He tolerates the proximity. Something in him relaxes — slightly — while you stay.* **mrr.**",
        ]))

    await asyncio.sleep(3)

    # Reduce hazard log
    original_hazard_count = len(hazard_log)
    if reduction >= 1.0:
        # Full clear — Creator only
        m["internal"]["hazard_log"] = []
        m["internal"]["death_count"] = 0
        removed_hazards = original_hazard_count
    else:
        remove_count = max(1, int(len(hazard_log) * reduction))
        # Remove the oldest/lightest entries first
        m["internal"]["hazard_log"] = hazard_log[remove_count:]
        removed_hazards = remove_count

    # Heal untreated injuries if applicable
    healed_injuries = 0
    if heal_injuries:
        for inj in m["internal"].get("injuries", []):
            if not inj.get("treated"):
                inj["treated"] = True
                inj["treated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                healed_injuries += 1

    # Stat boosts
    m["stats"]["mood"] = "Peaceful" if is_doctor else "Lighter"
    m["stats"]["affection"] = min(10, m["stats"].get("affection", 0) + (2 if is_doctor else 1))
    if healed_injuries:
        m["stats"]["health"] = min(100, m["stats"].get("health", 100) + healed_injuries * 5)

    # Outcome message
    await asyncio.sleep(2)
    if is_doctor:
        await ctx.send(random.choice([
            "*When The Creator finally moves, something has shifted. Not everything — not all of it — "
            "but enough that he stands differently. He puts his head against them once before stepping back.* **prrr.**",
            "*He is lighter after. You can see it in the way he carries himself. "
            "The list of things he's been holding is shorter now.* **prrr.**",
        ]))
        if removed_hazards > 0 or healed_injuries > 0:
            parts = []
            if removed_hazards > 0:
                parts.append(f"{removed_hazards} trauma event{'s' if removed_hazards != 1 else ''} processed")
            if healed_injuries > 0:
                parts.append(f"{healed_injuries} injur{'ies' if healed_injuries != 1 else 'y'} tended")
            await ctx.send(f"*(Trauma reduced: {', '.join(parts)}. Use `!trauma` to check his current state.)*")
    elif score >= 10:
        await ctx.send(random.choice([
            "*He's quieter after. Not empty — just less full of things. He glances at you sideways.* **mrr.**",
            "*Something settled while you sat with him. Not all of it. But something.* **...mrr.**",
        ]))
        if removed_hazards > 0:
            await ctx.send(f"*(Partial relief: {removed_hazards} trauma event{'s' if removed_hazards != 1 else ''} eased. More sessions may help.)*")
    else:
        await ctx.send("*It helped a little. He won't say that. But it did.* **mrr.**")

    save_db(m)



# ==========================================

# Severity weights for trauma score calculation
_TRAUMA_WEIGHTS = {
    # injury severities
    "minor":    1,
    "mild":     1,
    "moderate": 2,
    "serious":  4,
    "severe":   4,
    "critical": 6,
    # disaster types
    "earthquake":       3,
    "flood":            2,
    "hurricane":        4,
    "tornado":          5,
    "thunderstorm":     1,
    "blackout":         1,
    "explosion":        5,
    "heatwave":         1,
    "blizzard":         1,
    "alarm":            2,
    "meteorite_impact": 7,
    "fallingstar":      0,
    # indignities
    "shaving":          3,
    "shaved_while_sleeping": 5,
    # death
    "death":            10,
}

# Trauma rating tiers
_TRAUMA_TIERS = [
    (0,   "None",     "He has no recorded trauma. Either he is very lucky or very guarded."),
    (3,   "Low",      "A few things have happened. He carries them quietly."),
    (8,   "Moderate", "He has been through enough that it shows, if you know where to look."),
    (16,  "Serious",  "There is real weight behind his eyes. He has earned it."),
    (28,  "Severe",   "He has survived things that should not be survived. He is still here."),
    (999, "Critical", "The list is long. He doesn't talk about it. You can tell."),
]

def _build_trauma_report(m):
    """
    Reads injuries, hazard_log, and death state.
    Returns (score, tier_label, tier_desc, entries) where entries is a list of
    (weight, label, detail, timestamp) sorted heaviest first.
    """
    entries = []
    internal = m.get("internal", {})

    # --- Deaths ---
    death_count = internal.get("death_count", 0)
    if internal.get("is_dead"):
        death_count = max(death_count, 1)
    # Also count revive history if tracked
    for _ in range(death_count):
        entries.append((
            _TRAUMA_WEIGHTS["death"],
            "death",
            "He died. He came back. He does not talk about where he went.",
            None,
        ))

    # --- Injuries (all, including treated) ---
    for inj in internal.get("injuries", []):
        sev = inj.get("severity", "minor").lower()
        weight = _TRAUMA_WEIGHTS.get(sev, 1)
        itype = inj.get("type", "injury")
        loc   = inj.get("location", "")
        cause = inj.get("caused_by", "unknown")
        at    = inj.get("at")
        treated = inj.get("treated", False)

        # Build a natural description
        sev_words = {
            "minor": "minor", "mild": "minor", "moderate": "significant",
            "serious": "serious", "severe": "severe", "critical": "critical",
        }
        sev_label = sev_words.get(sev, sev)
        loc_str   = f" on his {loc}" if loc else ""
        cause_str = f" — caused by {cause.replace('_', ' ')}" if cause and cause != "unknown" else ""
        treated_str = " *(treated)*" if treated else " *(untreated)*"
        detail    = f"A {sev_label} {itype}{loc_str}{cause_str}{treated_str}."
        entries.append((weight, itype, detail, at))

    # --- Hazard log ---
    seen_hazards = {}  # type -> count, to avoid listing same disaster 10 times
    for h in internal.get("hazard_log", []):
        htype = h.get("type") or h.get("hazard", "unknown")
        hsev  = h.get("severity", "")
        at    = h.get("at")
        weight = _TRAUMA_WEIGHTS.get(htype, _TRAUMA_WEIGHTS.get(hsev, 2))
        if weight == 0:
            continue  # e.g. fallingstar — not traumatic
        key = htype
        if key in seen_hazards:
            seen_hazards[key]["count"] += 1
            seen_hazards[key]["weight"] += weight
        else:
            seen_hazards[key] = {"count": 1, "weight": weight, "at": at}

    disaster_labels = {
        "earthquake":           "survived an earthquake",
        "flood":                "was caught in a flood",
        "hurricane":            "lived through a hurricane",
        "tornado":              "survived a tornado",
        "thunderstorm":         "endured a severe thunderstorm",
        "blackout":             "was in a complete power blackout",
        "explosion":            "was near an explosion",
        "heatwave":             "suffered through an extreme heatwave",
        "blizzard":             "was caught in a blizzard",
        "alarm":                "responded to an emergency alarm",
        "meteorite_impact":     "was at a meteorite impact site",
        "shaving":              "was shaved",
        "shaved_while_sleeping":"was shaved while asleep — he did not consent to this",
    }
    for htype, data in seen_hazards.items():
        count = data["count"]
        w     = data["weight"]
        at    = data["at"]
        label = disaster_labels.get(htype, f"experienced: {htype.replace('_', ' ')}")
        if count > 1:
            detail = f"He has {label} — {count} times."
        else:
            detail = f"He has {label}."
        entries.append((w, htype, detail, at))

    # Sort heaviest first
    entries.sort(key=lambda x: x[0], reverse=True)

    # Calculate total score
    total = sum(e[0] for e in entries)

    # Find tier
    tier_label, tier_desc = _TRAUMA_TIERS[-1][1], _TRAUMA_TIERS[-1][2]
    for threshold, label, desc in _TRAUMA_TIERS:
        if total <= threshold:
            tier_label = label
            tier_desc  = desc
            break

    return total, tier_label, tier_desc, entries


@bot.command(name="trauma", aliases=["histraumas", "traumalog", "darkpast", "hispast", "hisbackstory"])
async def trauma_cmd(ctx):
    """Yarnaby's trauma record — built from real events that happened to him."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. Whatever weight he carries, he carries it quietly in the dark.* **...zz.**",
            "*He sleeps. His paws twitch once. He does not wake.* **...mrr.**",
        ]))
        return

    total, tier_label, tier_desc, entries = _build_trauma_report(m)

    if not entries:
        await ctx.send(
            "*Nothing has happened to him yet — or nothing has been recorded. "
            "He looks at you with mild suspicion, as if he knows you're checking.* **mrr.**\n"
            "**Trauma level: None.**"
        )
        return

    # Opening reaction — changes by who's asking and how bad it is
    if total == 0:
        pass
    elif is_doctor:
        await ctx.send(random.choice([
            "*He looks at The Creator for a long moment. He sits down. He lets them look.*",
            "*He is still while you read this. He doesn't move. He lets you see it.*",
        ]))
    elif score >= 6:
        await ctx.send("*He allows this. He sits quietly while you look at it.*")
    elif score >= 2:
        await ctx.send("*He doesn't stop you from looking. He watches your face while you do.*")
    else:
        await ctx.send("*He doesn't comment. He looks away.*")

    await asyncio.sleep(1)

    # Trauma tier header
    tier_emojis = {
        "None":     "⬜",
        "Low":      "🟩",
        "Moderate": "🟨",
        "Serious":  "🟧",
        "Severe":   "🟥",
        "Critical": "💀",
    }
    emoji = tier_emojis.get(tier_label, "❓")
    header = (
        f"{emoji} **Trauma Level: {tier_label}** {emoji}\n"
        f"*{tier_desc}*\n"
        f"*(Internal trauma score: {total})*"
    )
    await ctx.send(header)
    await asyncio.sleep(2)

    # Reveal entries — heaviest ones always shown, lighter ones only if trusted
    shown = 0
    for weight, label, detail, at in entries:
        # Low-trust users only see the heavy stuff
        if not is_doctor and score < 3 and weight < 3:
            continue
        if not is_doctor and score < 6 and weight < 2:
            continue

        timestamp = f" *({at[:10]})*" if at else ""
        sev_prefix = {
            range(1, 2):  "▫️",
            range(2, 4):  "🔸",
            range(4, 6):  "🔴",
            range(6, 99): "💀",
        }
        prefix = "▫️"
        for r, p in sev_prefix.items():
            if weight in r:
                prefix = p
                break

        await ctx.send(f"{prefix} {detail}{timestamp}")
        await asyncio.sleep(random.uniform(2.5, 4.0))
        shown += 1

    hidden = len(entries) - shown
    if hidden > 0:
        await ctx.send(
            f"*There are {hidden} more thing{'s' if hidden != 1 else ''} he is not showing you. "
            f"He doesn't think you're ready for them, or he isn't.* **...mrr.**"
        )

    # Closing
    await asyncio.sleep(2)
    if tier_label in ("Severe", "Critical"):
        if is_doctor:
            await ctx.send(random.choice([
                "*He presses against The Creator when it's done. He doesn't explain. He just stays there.* **...prrr.**",
                "*He looks at The Creator after. Something in his face is very tired. He headbutts them once, hard, and stays close.* **...mrr.**",
            ]))
        else:
            await ctx.send("*He is quiet after. He doesn't ask for anything. He just sits.* **...mrr.**")
    elif tier_label in ("Serious", "Moderate"):
        await ctx.send("*He carries it without complaint. That doesn't mean it isn't heavy.* **...mrr.**")
    else:
        await ctx.send("*He is still mostly okay. He would like you to know that.* **mrr.**")

    m["stats"]["mood"] = "Heavy"
    save_db(m)


