# ---------------------------------------------------------------------------
# !race — Yarnaby races someone across the factory floor
# ---------------------------------------------------------------------------
@bot.command(name="race", aliases=["raceagainst", "raceme", "factoryrace", "sprintrace"])
async def race_cmd(ctx):
    """Race Yarnaby across the factory floor. Outcome depends on his tiredness and zoomies state."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep. He cannot race. He is, in fact, the opposite of racing.* **...zz.**")
        return
    if m["internal"].get("helpless"):
        await ctx.send(random.choice([
            f"*He doesn't race. He stands at the start position and looks at the finish line and doesn't move. The race is not something he can do right now. He just stands there.* **...mrr...**",
            f"*You set up the race. He watches. He stays where he is. Not because he can't — because something is holding him in place and it isn't your command.* **...mrr...**",
        ]))
        return


    tiredness = m["stats"].get("tiredness", 0)
    has_zoomies = m["internal"].get("zoomies_active", False)
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    # Low trust — he won't race a stranger
    if score < -5 and not is_doctor:
        await ctx.send(random.choice([
            "*He looks at you. He looks at the imaginary starting line. He looks back at you. He goes and sits somewhere else. He is not racing this person.* **...mrr.**",
            "*His ear flattens. He pads away before the race even starts. He does not race people he doesn't trust.* **hff.**",
        ]))
        return

    # Creator gets a special warm start
    if is_doctor:
        await ctx.send("*He sees The Creator take a stance and something in him absolutely lights up. He gets into position so fast he nearly trips over his own paws.* **prrk!**")
        await asyncio.sleep(1.5)

    # Determine outcome
    # Zoomies = almost always wins. High tiredness = likely loses. Creator gets a slight edge.
    if has_zoomies:
        outcome = "win"
    elif tiredness >= 15:
        outcome = "lose"
    elif tiredness >= 8:
        outcome = random.choice(["win", "lose", "lose"])
    else:
        outcome = random.choice(["win", "win", "lose", "tie"])

    await ctx.send(random.choice([
        f"*Yarnaby squares up beside {ctx.author.display_name}. He gets very low. His hindquarters wiggle. He is taking this extremely seriously.* **...prrk.**",
        f"*He glances at {ctx.author.display_name} sideways. He adjusts his stance. His tail lashes once. He is ready. He has always been ready for this.* **mrrt.**",
        f"*He gets into position with a focus that is slightly alarming for a creature his size. His ears are forward. His paws are set. Something in his expression says he will not accept second place.* **...prrk.**",
    ]))
    await asyncio.sleep(3)

    # Build the race narration
    checkpoints = [
        "past the boiler room",
        "through the corridor with the broken lights",
        "around the stacked crates",
        "under the low pipe",
        "through the main floor stretch",
    ]
    random.shuffle(checkpoints)
    for cp in checkpoints[:2]:
        if outcome == "win":
            line = random.choice([
                f"*He pulls ahead {cp} — low, fast, silent.*",
                f"*{cp}, he's already there. He doesn't look back.*",
            ])
        elif outcome == "lose":
            line = random.choice([
                f"*He stumbles slightly {cp}. He recalibrates.*",
                f"*{cp} — he's half a step behind and knows it.*",
            ])
        else:
            line = random.choice([
                f"*Neck and neck {cp}.*",
                f"*{cp} — neither of them giving an inch.*",
            ])
        await ctx.send(line)
        await asyncio.sleep(random.uniform(1.5, 2.5))

    # Final result
    if outcome == "win":
        m["stats"]["tiredness"] = min(30, m["stats"].get("tiredness", 0) + 2)
        if is_doctor:
            await ctx.send(random.choice([
                f"*He wins — then immediately presses himself against The Creator's leg, breathing hard, purring harder. The victory is secondary. They ran together. That's the part he'll remember.* **prrr.**",
                f"*He crosses first and spins around to look at The Creator. His tail is straight up. He chirps once. He is so pleased he can barely contain it.* **prrrt! prrr.**",
            ]))
        elif score >= 6:
            await ctx.send(random.choice([
                f"*Yarnaby crosses first. He glances back at {ctx.author.display_name} with something that might, briefly, be satisfaction. He chirps once. That counted.* **prrrt.**",
                f"*He wins by a clean margin and sits at the finish looking quietly delighted. He acknowledges {ctx.author.display_name} with one slow ear-swivel. Good race.* **mrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*Yarnaby crosses first. He doesn't celebrate — he just turns around and sits down, breathing slightly harder than usual, with the expression of someone who expected nothing less.* **prrrt.**",
                f"*He gets there first and immediately begins grooming himself as if the whole thing was unremarkable. His ear flicks once.* **mrr.**",
            ]))
    elif outcome == "lose":
        m["stats"]["tiredness"] = min(30, m["stats"].get("tiredness", 0) + 3)
        if is_doctor:
            await ctx.send(random.choice([
                f"*He loses — and doesn't seem to mind. He pads directly to The Creator and headbutts their hand. He got to run with them. That's the better part.* **...prrr.**",
                f"*{ctx.author.display_name} crosses first. He arrives a moment later, slightly rumpled, and leans against them without comment.* **...prrr.**",
            ]))
        elif score >= 6:
            await ctx.send(random.choice([
                f"*He comes in second. He gives {ctx.author.display_name} a long look — not resentful, just noting. He pads back to his spot with quiet dignity.* **...mrr.**",
                f"*He loses by a stride. He sits at the finish and processes it. His tail is very still. He does not sulk. He simply files it.* **...mrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*He comes in second. He looks at his paws. He pads away at a measured pace that is not, he would like to clarify, a sulk.* **mrr.**",
                f"*{ctx.author.display_name} crosses first. He arrives after, sits with great dignity, grooms his ear. Nothing significant has occurred.* **...mrr.**",
            ]))
    else:
        m["stats"]["tiredness"] = min(30, m["stats"].get("tiredness", 0) + 2)
        if is_doctor:
            await ctx.send(random.choice([
                f"*A dead tie. He and The Creator cross at the exact same instant. He stares up at them. He makes a small, private **mrp**. He is satisfied with this. More than satisfied.* **prrr.**",
                f"*They hit the line together. He looks at The Creator for a long moment, then headbutts their knee. A tie with The Creator is not nothing.* **...prrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*Dead heat. He and {ctx.author.display_name} cross at the same instant. He stares at them for a long moment. He is not satisfied with this. He is also not going to ask for a rematch. Out loud.* **...prrk.**",
                f"*A tie. He sits down. He looks at {ctx.author.display_name}. He looks away. His tail flicks once. He files this under 'unresolved business'.* **mrr.**",
            ]))

    save_db(m)


