# !letter_to — Yarnaby writes a letter to someone; Creator gets DM'd a copy
# ---------------------------------------------------------------------------
@bot.command(name="letter_to", aliases=["writeto", "letterto", "yarnyletterfor", "writefor"])
async def letter_to_cmd(ctx, *, target: str = ""):
    """Yarnaby writes a private letter to someone. The Creator is notified via DM."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep. He cannot write letters right now. He will find the paper later.* **...zz.**")
        return

    if not target:
        await ctx.send("*`!letter_to [name or @mention]` — who should he write to?*")
        return

    # Resolve mention or name
    recipient_name = target
    recipient_id = None
    if ctx.message.mentions:
        recipient_name = ctx.message.mentions[0].display_name
        recipient_id = str(ctx.message.mentions[0].id)

    # Score relative to recipient (if known)
    rel_score = 0
    if recipient_id and recipient_id in m["social_matrix"]:
        rel_score = m["social_matrix"][recipient_id].get("score", 0)
    elif recipient_id == str(DOCTOR_ID):
        rel_score = 99

    # Build a letter based on relationship
    if recipient_id == str(DOCTOR_ID) or recipient_name.lower() in ["creator", "the creator", "doctor"]:
        letter_lines = random.choice([
            [
                f"Dear Creator,",
                f"",
                f"I have been thinking about the factory. It is the same as always.",
                f"The pipe near the back still makes the sound. I have not fixed it.",
                f"I don't think I am supposed to fix it.",
                f"",
                f"I think about you when it is quiet.",
                f"It is often quiet.",
                f"",
                f"— Yarnaby",
            ],
            [
                f"Creator,",
                f"",
                f"Today someone gave me something. I have added it to the hoard.",
                f"It is not as good as the things you give me.",
                f"I did not say that to them.",
                f"",
                f"I am fine. The factory is fine.",
                f"I would like you to come back soon.",
                f"I am not asking. I am noting.",
                f"",
                f"— Y",
            ],
        ])
    elif rel_score >= 8:
        letter_lines = [
            f"To {recipient_name},",
            f"",
            f"You have been here enough times that I know the sound of your footsteps.",
            f"I do not always look up, but I hear you.",
            f"",
            f"I have noted that you are one of the acceptable ones.",
            f"This is not nothing.",
            f"",
            f"— Yarnaby",
        ]
    elif rel_score >= 2:
        letter_lines = [
            f"To {recipient_name},",
            f"",
            f"You have been around.",
            f"I have seen you.",
            f"I have not decided what I think yet.",
            f"",
            f"That is not an insult. That is just where we are.",
            f"",
            f"— Yarnaby",
        ]
    elif rel_score < 0:
        letter_lines = [
            f"To {recipient_name},",
            f"",
            f"I remember what you did.",
            f"I am not writing this letter to forgive you.",
            f"I am writing it so that you know I remember.",
            f"",
            f"— Yarnaby",
        ]
    else:
        letter_lines = [
            f"To {recipient_name},",
            f"",
            f"I am not sure why I am writing this.",
            f"You exist. I have noticed.",
            f"",
            f"That is all I have so far.",
            f"",
            f"— Yarnaby",
        ]

    letter_text = "\n".join(letter_lines)
    formatted = f"```\n{letter_text}\n```"

    await ctx.send(
        f"*He finds a scrap of paper. He sits with it for a long time before writing anything. When he is done, he folds it carefully and does not look at it again.*\n{formatted}"
    )

    # DM the Creator a copy
    if ctx.author.id != DOCTOR_ID:
        creator = bot.get_user(DOCTOR_ID)
        if creator:
            try:
                await creator.send(
                    f"📜 **Yarnaby wrote a letter to {recipient_name}** (requested by {ctx.author.display_name}):\n{formatted}"
                )
            except Exception:
                pass

    _remember_life(m, "letter_to", f"wrote a letter to {recipient_name}", ctx.author)
    save_db(m)


