@bot.command(name="forgiven_history", aliases=["forgivenlog", "pardonlog", "whohesforgiven", "forgivenlist"])
async def forgiven_history_cmd(ctx):
    """Show the log of users Yarnaby has formally forgiven."""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep. The forgiveness ledger will keep until he wakes.* **...zz.**")
        return

    log = m["internal"].get("forgiven_log", [])
    if not log:
        await ctx.send(
            "*He searches the drawer where he keeps the forgiveness records. It is empty — either no one has needed it yet, or no one has asked him to clear it.* **mrr.**"
        )
        return

    lines = ["*He opens the forgiveness ledger. He keeps one. Of course he keeps one.*\n"]
    for entry in reversed(log[-15:]):
        name = entry.get("name", "Unknown")
        date = entry.get("at", "?")[:10]
        offense = entry.get("offense", "unspecified")
        forgiver = entry.get("forgiven_by", "unknown")
        lines.append(f"▫️ **{name}** — `{date}` — *{offense}* *(cleared by {forgiver})*")

    lines.append(f"\n*{len(log)} total entries. He has not forgotten — he has simply chosen to move forward.* **...mrr.**")
    await ctx.send("\n".join(lines))


# Patch the existing !forgive command to also log to forgiven_log
_original_forgive_cmd = forgive_cmd.callback

async def _patched_forgive(ctx):
    m = bot.db
    if ctx.message.mentions:
        user = ctx.message.mentions[0]
        uid = str(user.id)
        entry = m["social_matrix"].get(uid, {})
        had_offense = (
            bool(entry.get("toxic_attempts"))
            or entry.get("score", 0) < 0
        )
        # Run original
        await _original_forgive_cmd(ctx)
        # Log it if something was actually cleared
        if had_offense:
            fh_raw = m["internal"].get("feed_history", {}).get(uid, [])
            bad_feeds = [fi for fi in fh_raw if fi.get("item") and any(w in fi["item"] for w in FEED_HATES)]
            toxic = entry.get("toxic_attempts", [])
            if toxic:
                offense = f"toxic attempt ({toxic[-1].get('item', '?')})"
            elif bad_feeds:
                offense = f"bad food ({bad_feeds[-1].get('item', '?')})"
            else:
                offense = f"score was {entry.get('score', 0)}"
            log = m["internal"].setdefault("forgiven_log", [])
            log.append({
                "user_id": uid,
                "name": user.display_name,
                "offense": offense,
                "forgiven_by": ctx.author.display_name,
                "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            })
            if len(log) > 100:
                del log[:len(log) - 100]
            save_db(m)
    else:
        await _original_forgive_cmd(ctx)

forgive_cmd.callback = _patched_forgive


