@bot.command(name="weight_log", aliases=["weightlog", "weighthistory", "weighttrack", "scalehistory"])
async def weight_log_cmd(ctx):
    """Show Yarnaby's weight log over time — affected by feeding habits."""
    m = bot.db
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep on the scale, probably. The reading is unreliable right now.* **...zz.**")
        return

    # Record current weight into log
    hunger = m["stats"].get("hunger", 0)
    overfeeding = m["internal"].get("overfed_count", 0)
    base_kg = 4.2
    current_weight = round(base_kg + (hunger * 0.05) + (overfeeding * 0.03), 2)
    current_weight = max(2.8, min(8.5, current_weight))

    wlog = m["internal"].setdefault("weight_log", [])
    wlog.append({
        "weight": current_weight,
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    if len(wlog) > 30:
        del wlog[:len(wlog) - 30]
    save_db(m)

    if len(wlog) < 2:
        await ctx.send(
            f"*He steps onto the scale. **{current_weight} kg**. There's only one reading so far — check back after more feeding sessions to see the trend.* **mrr.**"
        )
        return

    # Build trend
    first = wlog[0]["weight"]
    diff = round(current_weight - first, 2)
    trend_str = f"+{diff} kg" if diff > 0 else f"{diff} kg" if diff < 0 else "stable"

    lines = [f"*He eyes the scale with suspicion but steps on anyway. His weight log:*\n"]
    for entry in wlog[-8:]:
        date = entry["at"][:10]
        w = entry["weight"]
        bar = "█" * int(w) + ("▌" if (w % 1) >= 0.5 else "")
        lines.append(f"`{date}` **{w} kg** {bar}")

    if diff > 0.5:
        comment = "*He has been eating well. Perhaps very well. He does not acknowledge the scale's opinion.* **mrr.**"
    elif diff < -0.3:
        comment = "*He is lighter than before. He has been eating less, or more carefully, or both.* **mrr.**"
    else:
        comment = "*Stable. He is consistent. He respects this about himself.* **mrr.**"

    lines.append(f"\n*Trend since first reading: **{trend_str}***")
    lines.append(comment)
    await ctx.send("\n".join(lines))


# ---------------------------------------------------------------------------
# !dental — check tooth health; degrades with sugary food
# ---------------------------------------------------------------------------

DENTAL_SUGAR_WORDS = [
    "candy", "sweets", "sugar", "lollipop", "gummy", "jelly bean", "cotton candy",
    "cake", "cupcake", "brownie", "muffin", "donut", "doughnut", "fudge", "toffee",
    "caramel", "taffy", "chocolate", "skittles", "starburst", "sour candy", "nerds",
    "marshmallow", "sweetbread", "frosting", "icing", "syrup", "honey", "jam",
]

def _get_dental_score(m):
    """0 = perfect, higher = worse. Max 100."""
    return m["internal"].get("dental_score", 0)

def _degrade_dental(m, item: str):
    """Called after feeding — bump dental score if item is sugary."""
    item_lower = (item or "").lower()
    if any(w in item_lower for w in DENTAL_SUGAR_WORDS):
        current = m["internal"].get("dental_score", 0)
        m["internal"]["dental_score"] = min(100, current + random.randint(3, 8))

@bot.command(name="dental", aliases=["checkteeth", "teethhim", "yarnyteeth", "toothcheck", "brushteeth"])
async def dental_cmd(ctx):
    """Check Yarnaby's dental health. Degrades with sugary food."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep. His teeth are closed. You cannot check them right now.* **...zz.**")
        return

    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    content_lower = ctx.message.content.lower()
    cleaning = any(w in content_lower for w in ["brush", "clean"])

    # Low trust — he won't let strangers near his mouth unless brushing (and even then, barely)
    if score < 0 and not is_doctor and not cleaning:
        await ctx.send(random.choice([
            "*He covers his mouth with one paw and looks at you sideways. He's not letting you check his teeth.* **mrr.**",
            "*He turns his head away when you lean in. He doesn't trust you near his face.* **hff.**",
        ]))
        return

    score_var = _get_dental_score(m)
    cooldown_key = "dental_clean"

    if score_var == 0:
        desc = "Perfect. His teeth are immaculate. He is smug about this."
        emoji = "🦷"
        tip = ""
    elif score_var < 20:
        desc = "Good. Minor plaque building up — nothing serious yet."
        emoji = "🦷"
        tip = "*A light brush wouldn't hurt. `!dental brush` to clean them.*"
    elif score_var < 45:
        desc = "Moderate buildup. His breath is getting noticeable. He doesn't appreciate you noticing."
        emoji = "⚠️"
        tip = "*He needs his teeth brushed. Use `!dental brush` to clean them.*"
    elif score_var < 70:
        desc = "Poor. He has visible tartar. He winces slightly when eating hard things."
        emoji = "🔴"
        tip = "*He needs a dental clean urgently. `!dental brush` or `!vet`.*"
        m["stats"]["hunger"] = max(0, m["stats"].get("hunger", 0) - 1)
    else:
        desc = "Critical. He needs a vet. He is pretending everything is fine. He is not fine."
        emoji = "💀"
        tip = "*Dental score this high causes eating pain. Use `!vet` or `!dental brush`.*"
        m["stats"]["hunger"] = max(0, m["stats"].get("hunger", 0) - 2)

    # Handle brush subcommand
    if cleaning:
        rem = _cooldown_remaining(m, cooldown_key, 3600)
        if rem > 0 and not is_doctor:
            await ctx.send(f"*He has already had his teeth done recently. Give him an hour. (~{rem}s)* **mrr.**")
            return
        reduction = random.randint(15, 30) if not is_doctor else score_var
        m["internal"]["dental_score"] = max(0, score_var - reduction)
        _set_cooldown(m, cooldown_key)
        save_db(m)
        if score_var == 0:
            await ctx.send("*His teeth are already perfect. He allows the brushing anyway with an expression of regal tolerance.* **mrr.**")
        else:
            new = m["internal"]["dental_score"]
            if is_doctor:
                await ctx.send(random.choice([
                    f"*He lets The Creator brush his teeth without a single protest. His eyes are closed. He is completely still. Dental score: **{score_var} → {new}**.* **...prrr.**",
                    f"*He opens his mouth cooperatively the moment The Creator reaches for the brush. He has never done this for anyone else. Score: **{score_var} → {new}**.* **prrr.**",
                ]))
            else:
                await ctx.send(random.choice([
                    f"*He submits to the tooth-brushing with the dignity of a creature who deeply resents it but understands the necessity. Dental score: **{score_var} → {new}**. He spits. He glares. He is cleaner.* **mrr.**",
                    f"*He holds still — barely — and lets you brush. His ears are fully back. He is being very cooperative and he would like acknowledgement of that. Score: **{score_var} → {new}**.* **mrr.**",
                ]))
        return

    await ctx.send(
        f"{emoji} *You check Yarnaby's teeth carefully. He does not love this.*\n"
        f"**Dental health:** {desc}\n"
        f"**Score:** {score_var}/100\n"
        f"{tip}"
    )
    save_db(m)


# Hook dental degradation into the feed command by patching save_db isn't clean;
# instead we add a post-feed hook via the offering log. We patch _log_offering:
_original_log_offering = _log_offering

def _patched_log_offering(m, kind: str, item: str, user_id: str, user_name: str) -> None:
    _original_log_offering(m, kind, item, user_id, user_name)
    if kind == "feed":
        _degrade_dental(m, item)
        # Also track overfeeding for weight
        hunger = m["stats"].get("hunger", 0)
        if hunger >= 8:
            m["internal"]["overfed_count"] = m["internal"].get("overfed_count", 0) + 1

_log_offering = _patched_log_offering


# ---------------------------------------------------------------------------
# !shedding — seasonal wool buildup; debuffs if ignored
# ---------------------------------------------------------------------------

SHEDDING_SEASONS = ["spring", "autumn", "fall"]

def _is_shedding_season():
    month = datetime.now().month
    return month in (3, 4, 5, 9, 10, 11)  # spring + autumn

@bot.command(name="shedding", aliases=["woolshed", "sheddingcheck", "woolbuild", "deshedcheck", "fluff"])
async def shedding_cmd(ctx):
    """Check Yarnaby's wool shedding status. Buildup causes debuffs if ignored."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep. His wool is visibly doing its thing right now. Check back when he wakes.* **...zz.**")
        return

    shed_level = m["internal"].get("shedding_level", 0)
    in_season = _is_shedding_season()
    content_lower = ctx.message.content.lower()
    cleaning = any(w in content_lower for w in ["clean", "brush", "groom", "deshed", "clear", "remove"])

    # Passive buildup if in season and hasn't been cleaned
    if in_season:
        last_clean_str = m["internal"].get("last_deshed_at")
        days_since = 999
        if last_clean_str:
            try:
                last_clean = datetime.strptime(last_clean_str, "%Y-%m-%d %H:%M:%S")
                days_since = (datetime.now() - last_clean).total_seconds() / 86400
            except Exception:
                pass
        if days_since > 3:
            gain = int(days_since * 2)
            m["internal"]["shedding_level"] = min(100, shed_level + gain)
            shed_level = m["internal"]["shedding_level"]

    # Apply debuffs if level is high
    if shed_level >= 70:
        m["stats"]["tiredness"] = min(30, m["stats"].get("tiredness", 0) + 1)
    if shed_level >= 90:
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - 2)

    if cleaning:
        if shed_level == 0:
            await ctx.send("*His wool is already clean and tidy. He endures the brushing anyway with a look of mild sufferance.* **mrr.**")
            return
        cleaned = min(shed_level, random.randint(30, 60) if not is_doctor else shed_level)
        m["internal"]["shedding_level"] = max(0, shed_level - cleaned)
        m["internal"]["last_deshed_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        new_level = m["internal"]["shedding_level"]
        save_db(m)
        if is_doctor:
            await ctx.send(random.choice([
                f"*He goes completely still the moment The Creator starts brushing. His eyes half-close. A deep, steady purr starts up. He leans into it. He leans into it so hard he nearly tips over. Shedding: **{shed_level} → {new_level}**.* **...prrrrr.**",
                f"*He presents his back to The Creator without being asked — a gesture he makes for no one else. He stays there for the entire session, eyes closed, purring. Shedding: **{shed_level} → {new_level}**.* **prrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*You brush him thoroughly. Wool comes off in small, satisfying clouds. He leans into it — very slightly — before resuming his composed expression. Shedding: **{shed_level} → {new_level}**.* **...prrr.**",
                f"*He submits to the deshedding with the air of someone accepting a necessary inconvenience. The wool pile grows. He looks tidier. He does not thank you. Shedding: **{shed_level} → {new_level}**.* **mrr.**",
            ]))
        return

    # Status display
    season_note = "*(shedding season — buildup is accelerating)*" if in_season else "*(not shedding season — buildup is slow)*"
    if shed_level == 0:
        desc = "Immaculate. His wool is clean, smooth, and under control."
        emoji = "✨"
        tip = ""
    elif shed_level < 25:
        desc = "Light buildup. A few loose tufts. Manageable."
        emoji = "🐑"
        tip = "*Use `!shedding clean` to brush him out.*"
    elif shed_level < 55:
        desc = "Moderate. His wool is visibly fluffier than usual in the wrong way. He keeps pulling at it with his teeth."
        emoji = "⚠️"
        tip = "*He needs brushing — `!shedding clean` or `!groom`.*"
    elif shed_level < 80:
        desc = "Heavy. He looks like he's wearing two of himself. He is tired. It's affecting his energy."
        emoji = "🔴"
        tip = "*Heavy buildup is causing tiredness debuffs. `!shedding clean` urgently.*"
    else:
        desc = "Critical. He is a wool emergency. He is visibly uncomfortable and his health is starting to suffer."
        emoji = "💀"
        tip = "*At this level he takes health damage. `!shedding clean` or `!vet`.*"

    await ctx.send(
        f"{emoji} *You examine Yarnaby's wool carefully.*\n"
        f"**Shedding level:** {shed_level}/100 — {desc}\n"
        f"{season_note}\n"
        f"{tip}"
    )
    save_db(m)


