# !allergy — certain foods trigger sneezing / reactions logged as mild injuries
# ---------------------------------------------------------------------------

ALLERGY_TRIGGERS = [
    "pollen", "flowers", "bouquet", "daisy", "rose", "tulip", "lavender",
    "dust", "feather", "feathers", "down pillow", "hay", "grass",
    "peanut", "peanut butter", "tree nut", "almond", "walnut", "cashew",
    "shellfish", "shrimp", "prawn", "crab", "lobster",
    "dairy", "milk", "cheese", "cream", "butter", "ice cream",
    "citrus", "orange", "lemon", "lime", "grapefruit",
    "perfume", "cologne", "air freshener", "spray", "aerosol",
]

ALLERGY_SEVERITY = {
    "peanut": "serious", "peanut butter": "serious", "shellfish": "serious",
    "shrimp": "serious", "prawn": "serious", "crab": "serious", "lobster": "serious",
    "perfume": "moderate", "cologne": "moderate", "aerosol": "moderate",
}

@bot.command(name="allergy", aliases=["allergycheck", "allergytest", "giveallergen", "testallergy", "allergytrigger"])
async def allergy_cmd(ctx, *, item: str = ""):
    """Expose Yarnaby to a potential allergen. Triggers sneezing, reactions, or logged injuries."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    if m["internal"]["is_sleeping"]:
        await ctx.send("*He is asleep. Do not bring allergens near him while he sleeps.* **...zz.**")
        return

    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)

    if not item:
        # Show his known allergy profile
        known = m["internal"].get("allergy_history", [])
        triggers_seen = list({e["item"] for e in known})
        if not known:
            await ctx.send(
                "*His allergy history is blank. Either he has no known reactions, or no one has tested yet.* **mrr.**"
            )
        else:
            lines = ["*His known allergy reactions:*\n"]
            for e in reversed(known[-10:]):
                lines.append(f"▫️ **{e['item']}** — {e['severity']} reaction *(logged {e['at'][:10]})*")
            await ctx.send("\n".join(lines))
        return

    item_lower = item.lower()
    matched = next((t for t in ALLERGY_TRIGGERS if t in item_lower), None)

    if not matched:
        await ctx.send(random.choice([
            f"*He sniffs the **{item}** carefully. His nose twitches. Nothing happens. He looks at you with mild disappointment at the lack of drama.* **mrr.**",
            f"*He investigates the **{item}**. No reaction. He blinks once and pads away.* **mrr.**",
            f"*The **{item}** produces no response beyond a slow, evaluating blink. He is fine. He is always fine.* **mrr.**",
        ]))
        return

    severity = ALLERGY_SEVERITY.get(matched, "mild")

    # Log the reaction
    allergy_history = m["internal"].setdefault("allergy_history", [])
    allergy_history.append({
        "item": matched,
        "full_item": item,
        "severity": severity,
        "triggered_by": ctx.author.display_name,
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    if len(allergy_history) > 50:
        del allergy_history[:len(allergy_history) - 50]

    # Creator bringing allergen — he trusts it's safe and doesn't anticipate it
    if is_doctor:
        if severity == "mild":
            await ctx.send(random.choice([
                f"*The Creator brings the **{item}**. He sniffs it without suspicion — it came from The Creator, it must be fine. His nose disagrees loudly.* **ACHOO. ...mrr?**",
                f"*He leans into The Creator's hand to smell what they've brought. He sneezes so hard he stumbles. He blinks. He looks at The Creator with watery eyes and complete confusion.* **chff— mrr?**",
            ]))
        elif severity == "moderate":
            await ctx.send(random.choice([
                f"*He approaches the **{item}** without hesitation — The Creator brought it. He trusts. His eyes immediately start watering. He sneezes three times in rapid succession and looks up at The Creator with the most betrayed expression he can manage while still sneezing.* **achoo— achoo— achoo. mrr...**",
                f"*He doesn't pull away fast enough. The **{item}** came from The Creator's hands. He sniffs deeply — and immediately regrets it. His face is a disaster. He looks up at them like: *why.*** **...hff. ACHOO. mrr.**",
            ]))
            injuries = m["internal"].setdefault("injuries", [])
            injuries.append({
                "type": "allergic reaction",
                "severity": "minor",
                "location": "nose/eyes",
                "caused_by": f"allergy to {matched} (from Creator)",
                "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "treated": False,
            })
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - 5)
        else:
            await ctx.send(random.choice([
                f"*He takes the **{item}** from The Creator without a second thought. He trusts completely. The reaction is immediate and severe — sneezing, watering eyes, retreating. He keeps looking back at The Creator between sneezes. He is not angry. He is just very, very unwell and very confused.* **achoo— achoo— achoo— mrr...**",
                f"*He eats or sniffs the **{item}** because The Creator gave it. That's the whole reason. He trusts. His body disagrees violently. He needs treatment.* **achoo— achoo— hff— mrr...**",
            ]))
            injuries = m["internal"].setdefault("injuries", [])
            injuries.append({
                "type": "severe allergic reaction",
                "severity": "moderate",
                "location": "respiratory/eyes",
                "caused_by": f"allergy to {matched} (from Creator — trusted source)",
                "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "treated": False,
            })
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - 15)
            m["stats"]["mood"] = "Agitated"
        save_db(m)
        return

    # Score-gated: low trust means he won't let you near him with it
    if score < -3:
        await ctx.send(random.choice([
            f"*He sees what you're holding and backs away immediately. He is not letting you bring that near him.* **hff.**",
            f"*He spots the **{item}** and retreats to a safe distance, watching you from there. He is not approaching.* **...mrr.**",
        ]))
        return

    if severity == "mild":
        await ctx.send(random.choice([
            f"*He sniffs the **{item}**. His nose wrinkles. He sneezes — once, sharp, undignified — and backs away looking offended by his own face.* **ACHOO. ...mrr.**",
            f"*A single sneeze. Forceful. He blinks at the **{item}** with watery eyes and the expression of someone who has been personally wronged.* **chff— mrr.**",
            f"*His whiskers twitch. His ears go back. He sneezes twice in rapid succession and immediately begins grooming himself as though that will help.* **achoo. achoo. ...mrr.**",
        ]))
        m["stats"]["mood"] = "Annoyed" if m["stats"].get("mood") not in ("Traumatized", "Depressed (will recover)") else m["stats"]["mood"]

    elif severity == "moderate":
        await ctx.send(random.choice([
            f"*He reacts immediately to the **{item}** — sneezing repeatedly, eyes watering, backing away with ears flat. He looks miserable and indignant in equal measure. He will remember this.* **achoo— achoo— achoo. hff. mrr.**",
            f"*His eyes water. He sneezes hard enough to stumble slightly. He stares at the **{item}** with the focused resentment of a creature who is filing this under grievances.* **...hff. ACHOO. mrr.**",
        ]))
        # Mild injury
        injuries = m["internal"].setdefault("injuries", [])
        injuries.append({
            "type": "allergic reaction",
            "severity": "minor",
            "location": "nose/eyes",
            "caused_by": f"allergy to {matched}",
            "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "treated": False,
        })
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - 5)

    else:  # serious
        await ctx.send(random.choice([
            f"*The **{item}** causes an immediate reaction — he sneezes uncontrollably, his eyes swell slightly, and he retreats as far as he can get. He is not okay. He needs treatment.* **achoo— achoo— achoo— hff— mrr...**",
            f"*He backs away from the **{item}** fast. His face is a disaster. He is sneezing, his eyes are streaming, and he looks genuinely distressed. `!medicine` or `!vet` recommended.* **...achoo— achoo— mrr...**",
        ]))
        injuries = m["internal"].setdefault("injuries", [])
        injuries.append({
            "type": "severe allergic reaction",
            "severity": "moderate",
            "location": "respiratory/eyes",
            "caused_by": f"allergy to {matched}",
            "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "treated": False,
        })
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - 15)
        m["stats"]["mood"] = "Agitated"

    save_db(m)


# ==========================================
# NSFW SERVER DETECTION — !cleanup / !getoutNSFW
# ==========================================



async def _notify_creator_nsfw(guild):
    """DM the Creator when Yarnaby is in an NSFW server."""
    creator = bot.get_user(DOCTOR_ID)
    if not creator:
        try:
            creator = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator = None
    if creator:
        try:
            await creator.send(
                f"⚠️ **NSFW server detected.**\n"
                f"----------------------------\n"
                f"Yarnaby is in: **{guild.name}** (`{guild.id}`)\n"
                f"Members: {guild.member_count}\n"
                f"Owner ID: {guild.owner_id}\n"
                f"----------------------------\n"
                f"Use `!getoutNSFW` to remove him from all NSFW servers at once,\n"
                f"or `!leaveserver {guild.name}` for just this one."
            )
        except Exception:
            pass


@bot.event
async def on_guild_join(guild):
    """Auto-check when Yarnaby joins a new server."""
    m = bot.db
    # Log server join to away_log
    log = m["internal"].setdefault("away_log", [])
    log.append({
        "ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "type": "server_join",
        "guild_id": str(guild.id),
        "guild_name": guild.name,
        "member_count": guild.member_count or 0,
        "excerpt": f"Added to new server: {guild.name} ({guild.member_count or '?'} members)",
    })
    if len(log) > AWAY_LOG_MAX_ENTRIES:
        del log[0:len(log) - AWAY_LOG_MAX_ENTRIES]
    if _is_nsfw_guild(guild):
        await _notify_creator_nsfw(guild)
        # Log it internally
        nsfw_log = m["internal"].setdefault("nsfw_servers_log", [])
        nsfw_log.append({
            "guild_id": str(guild.id),
            "guild_name": guild.name,
            "detected_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "action": "joined — flagged",
        })
        if len(nsfw_log) > 50:
            del nsfw_log[:len(nsfw_log) - 50]
        log[-1]["nsfw_flagged"] = True
    save_db(m)


@bot.command(name="cleanup", aliases=["nsfwcheck", "servercheck", "checkservers", "nsfwscan", "scanservers"])
async def cleanup_cmd(ctx, *, content: str = ""):
    """Check all servers Yarnaby is in for NSFW content. Creator only."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can ask him to do a cleanup check.* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)

    await ctx.send("*He pads through every server he knows, nose low, checking carefully. Give him a moment.* **mrr.**")

    nsfw_guilds = []
    clean_guilds = []

    for guild in bot.guilds:
        if _is_nsfw_guild(guild):
            nsfw_guilds.append(guild)
        else:
            clean_guilds.append(guild)

    # Log findings
    nsfw_log = m["internal"].setdefault("nsfw_servers_log", [])
    for guild in nsfw_guilds:
        already_logged = any(e["guild_id"] == str(guild.id) for e in nsfw_log)
        if not already_logged:
            nsfw_log.append({
                "guild_id": str(guild.id),
                "guild_name": guild.name,
                "detected_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "action": "found via !cleanup",
            })
    if len(nsfw_log) > 50:
        del nsfw_log[:len(nsfw_log) - 50]
    save_db(m)

    if not nsfw_guilds:
        await ctx.send(
            f"*He comes back and sits in front of you. He blinks once. Everything is clean. "
            f"He is in **{len(clean_guilds)}** server(s) and none of them are flagged.* **mrr.**"
        )
        return

    # Report findings
    lines = [
        f"*He returns. His expression is flat. He found something.*\n",
        f"⚠️ **{len(nsfw_guilds)} NSFW server(s) detected** out of {len(bot.guilds)} total:\n",
    ]
    for g in nsfw_guilds:
        lines.append(f"🔴 **{g.name}** (`{g.id}`) — {g.member_count} members")

    lines.append(f"\n✅ **{len(clean_guilds)}** server(s) are clean.")
    lines.append(f"\n*Use `!getoutNSFW` to remove him from all flagged servers at once.*")

    await ctx.send("\n".join(lines))

    # Also DM the Creator a copy if command was used in a server (not DM)
    if ctx.guild:
        creator = bot.get_user(DOCTOR_ID)
        if not creator:
            try:
                creator = await bot.fetch_user(DOCTOR_ID)
            except Exception:
                creator = None
        if creator:
            try:
                dm_lines = [f"🔍 **Cleanup scan results:**\n"]
                for g in nsfw_guilds:
                    dm_lines.append(f"⚠️ **{g.name}** (`{g.id}`) — {g.member_count} members")
                if not nsfw_guilds:
                    dm_lines.append("All servers clean.")
                await creator.send("\n".join(dm_lines))
            except Exception:
                pass


@bot.command(name="getoutNSFW", aliases=["leaveallnsfw", "nsfwleave", "leaveNSFW", "clearnsfw"])
async def getout_nsfw_cmd(ctx):
    """Make Yarnaby leave all detected NSFW servers immediately. Creator only."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can give that order.* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)

    nsfw_guilds = [g for g in bot.guilds if _is_nsfw_guild(g)]

    # Don't leave the server this command is being run from
    current_guild_id = ctx.guild.id if ctx.guild else None
    safe_to_leave = [g for g in nsfw_guilds if g.id != current_guild_id]
    cant_leave = [g for g in nsfw_guilds if g.id == current_guild_id]

    if not nsfw_guilds:
        await ctx.send(
            "*He looks around. He checks again. There are no NSFW servers to leave. Everything is clean.* **mrr.**"
        )
        return

    await ctx.send(
        f"*He stands. He pulls himself up to full height. He is going to handle this.* "
        f"*Leaving **{len(safe_to_leave)}** NSFW server(s)...* **mrr.**"
    )

    left = []
    failed = []
    for guild in safe_to_leave:
        try:
            await guild.leave()
            left.append(guild.name)
            # Log it
            nsfw_log = m["internal"].setdefault("nsfw_servers_log", [])
            for entry in nsfw_log:
                if entry["guild_id"] == str(guild.id):
                    entry["action"] = "left via !getoutNSFW"
                    entry["left_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        except Exception as e:
            failed.append(f"{guild.name} ({e})")

    save_db(m)

    lines = []
    if left:
        lines.append(f"✅ **Left {len(left)} server(s):**")
        for name in left:
            lines.append(f"  — {name}")
    if failed:
        lines.append(f"\n❌ **Failed to leave {len(failed)}:**")
        for f_entry in failed:
            lines.append(f"  — {f_entry}")
    if cant_leave:
        lines.append(f"\n⚠️ **Could not leave (command origin):** {cant_leave[0].name} — kick him manually.")

    lines.append(f"\n*He comes back and sits down. He is done. He is clean.* **mrr.**")
    await ctx.send("\n".join(lines))

    # DM Creator a summary
    creator = bot.get_user(DOCTOR_ID)
    if not creator:
        try:
            creator = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator = None
    if creator and ctx.guild:
        try:
            summary = f"🧹 **getoutNSFW executed.**\nLeft: {', '.join(left) if left else 'none'}\nFailed: {', '.join(failed) if failed else 'none'}"
            await creator.send(summary)
        except Exception:
            pass


