async def _send_log(guild_id: int, embed):
    """Send a log embed to the configured log channel for this guild — fire and forget."""
    m = bot.db
    ch_id = m["internal"].get("log_channels", {}).get(str(guild_id))
    if not ch_id:
        return
    ch = bot.get_channel(int(ch_id))
    if not ch:
        return
    try:
        await ch.send(embed=embed)
    except Exception:
        pass


def _log_embed(title: str, description: str = "", color: int = 0x7289da, fields: list = None):
    """Build a clean log embed with timestamp."""
    e = discord.Embed(title=title, description=description, color=color, timestamp=datetime.now(timezone.utc).replace(tzinfo=None))
    e.set_footer(text="Yarnaby Logs")
    if fields:
        for name, value, inline in fields:
            e.add_field(name=name, value=str(value)[:1024] or "—", inline=inline)
    return e


def _uid(user) -> str:
    return f"`{user.id}`"


async def _audit(guild, action, *, limit=3):
    """Quick audit log fetch — returns first matching entry or None."""
    try:
        async for entry in guild.audit_logs(limit=limit, action=action):
            age = (datetime.now(timezone.utc).replace(tzinfo=None) - entry.created_at.replace(tzinfo=None)).total_seconds()
            if age < 8:
                return entry
    except Exception:
        pass
    return None


