@bot.event
async def on_member_update(before, after):
    if not after.guild:
        return

    # Nickname
    if before.nick != after.nick:
        entry = await _audit(after.guild, discord.AuditLogAction.member_update)
        mod = f"{entry.user.mention}" if entry and entry.user != after else "*(self)*"
        e = _log_embed("📝 Nickname Changed", color=0x5865f2, fields=[
            ("User", f"{after.mention} {_uid(after)}", True),
            ("Changed by", mod, True),
            ("Before", before.nick or "*(none)*", True),
            ("After", after.nick or "*(none)*", True),
        ])
        e.set_thumbnail(url=after.display_avatar.url)
        await _send_log(after.guild.id, e)

    # Roles
    added = [r for r in after.roles if r not in before.roles]
    removed = [r for r in before.roles if r not in after.roles]
    if added:
        entry = await _audit(after.guild, discord.AuditLogAction.member_role_update)
        mod = f"{entry.user.mention}" if entry else "*(unknown)*"
        e = _log_embed("➕ Role Added", color=0x57f287, fields=[
            ("User", f"{after.mention} {_uid(after)}", True),
            ("By", mod, True),
            ("Role(s)", " ".join(r.mention for r in added), False),
        ])
        e.set_thumbnail(url=after.display_avatar.url)
        await _send_log(after.guild.id, e)
    if removed:
        entry = await _audit(after.guild, discord.AuditLogAction.member_role_update)
        mod = f"{entry.user.mention}" if entry else "*(unknown)*"
        e = _log_embed("➖ Role Removed", color=0xed4245, fields=[
            ("User", f"{after.mention} {_uid(after)}", True),
            ("By", mod, True),
            ("Role(s)", " ".join(r.mention for r in removed), False),
        ])
        e.set_thumbnail(url=after.display_avatar.url)
        await _send_log(after.guild.id, e)

    # Timeout
    if before.timed_out_until != after.timed_out_until:
        entry = await _audit(after.guild, discord.AuditLogAction.member_update)
        mod = f"{entry.user.mention}" if entry else "*(unknown)*"
        if after.timed_out_until:
            e = _log_embed("🔇 Member Timed Out", color=0xfee75c, fields=[
                ("User", f"{after.mention} {_uid(after)}", True),
                ("By", mod, True),
                ("Until", f"<t:{int(after.timed_out_until.timestamp())}:F>", False),
            ])
        else:
            e = _log_embed("🔈 Timeout Removed", color=0x57f287, fields=[
                ("User", f"{after.mention} {_uid(after)}", True),
                ("By", mod, True),
            ])
        e.set_thumbnail(url=after.display_avatar.url)
        await _send_log(after.guild.id, e)


@bot.event
async def on_member_ban(guild, user):
    entry = await _audit(guild, discord.AuditLogAction.ban)
    mod = f"{entry.user.mention} {_uid(entry.user)}" if entry else "*(unknown)*"
    reason = entry.reason or "*(no reason)*" if entry else "*(unknown)*"
    e = _log_embed("🔨 Member Banned", color=0xed4245, fields=[
        ("User", f"{user.mention} {_uid(user)}", True),
        ("By", mod, True),
        ("Reason", reason, False),
    ])
    e.set_thumbnail(url=user.display_avatar.url)
    await _send_log(guild.id, e)
    # Away log
    try:
        m = bot.db
        log = m["internal"].setdefault("away_log", [])
        _mod_name = entry.user.display_name if entry and entry.user else "unknown"
        log.append({
            "ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "type": "ban",
            "author_id": str(user.id),
            "author_name": getattr(user, "display_name", str(user)),
            "guild_name": guild.name,
            "banned_by": _mod_name,
            "reason": entry.reason or "no reason" if entry else "unknown",
            "excerpt": f"{getattr(user, 'display_name', str(user))} was banned from {guild.name} by {_mod_name}.",
        })
        if len(log) > AWAY_LOG_MAX_ENTRIES:
            del log[0:len(log) - AWAY_LOG_MAX_ENTRIES]
        save_db(m)
    except Exception:
        pass


