# ==========================================
# !kickNSFW — scan members for NSFW servers
# ==========================================

@bot.command(name="kickNSFW", aliases=["nsfwkick", "scankick", "memberscan"])
async def kick_nsfw_cmd(ctx):
    """Scan all members for NSFW server membership and kick those found. Creator only."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can give that order.* **mrr.**")
        return
    if not ctx.guild:
        await ctx.send("*Use this in a server.* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)
    await ctx.send("*He begins going through every member in the server, nose low, checking carefully. This may take a moment.* **mrr.**")

    flagged = []
    protected = []
    not_found = []   # members not sharing any guild with Yarnaby beyond this one
    clean = 0

    for member in ctx.guild.members:
        if member.bot:
            continue
        if member.id == DOCTOR_ID:
            continue

        # Safety: never kick admins or server owner
        is_protected = (
            member.id == ctx.guild.owner_id or
            member.guild_permissions.administrator
        )

        # Find all guilds this member shares with Yarnaby (excluding current)
        shared = [
            g for g in bot.guilds
            if g.id != ctx.guild.id and g.get_member(member.id)
        ]

        if not shared:
            not_found.append(member)
            continue

        nsfw_shared = [g for g in shared if _is_nsfw_guild(g)]
        if nsfw_shared:
            if is_protected:
                protected.append((member, nsfw_shared))
            else:
                flagged.append((member, nsfw_shared))
        else:
            clean += 1

    # Report — protected first (warnings)
    lines = []
    if protected:
        lines.append(f"⚠️ **{len(protected)} protected member(s) flagged — NOT kicked (admin/owner):**")
        for mem, guilds in protected[:10]:
            gnames = ", ".join(f"**{g.name}**" for g in guilds[:3])
            role = "Owner" if mem.id == ctx.guild.owner_id else "Admin"
            lines.append(f"  🛡️ **{mem.display_name}** ({role}) — found in: {gnames}")
        if len(protected) > 10:
            lines.append(f"  *...and {len(protected) - 10} more.*")
        lines.append("")

    if not flagged:
        lines.append(f"✅ No kickable members found in NSFW servers.")
        lines.append(f"🧹 Clean: **{clean}** | 🔍 Not in shared servers: **{len(not_found)}**")
        await ctx.send("\n".join(lines))
        return

    lines.append(f"🔴 **{len(flagged)} member(s) found in NSFW servers. Kicking...**\n")
    await ctx.send("\n".join(lines))

    kicked = []
    failed_kick = []

    for member, nsfw_guilds in flagged:
        gnames = ", ".join(g.name for g in nsfw_guilds[:3])
        try:
            try:
                await member.send(
                    f"*Yarnaby drops something at your feet and takes a step back.*\n\n"
                    f"You have been removed from **{ctx.guild.name}**.\n"
                    f"Reason: found in NSFW server(s): {gnames}\n\n"
                    f"*He blinks once. He walks away.* **...mrr.**"
                )
            except Exception:
                pass
            await member.kick(reason=f"Found in NSFW server(s): {gnames}")
            kicked.append((member, gnames))
        except Exception as ex:
            failed_kick.append((member, str(ex)))

    # Final report
    result_lines = []
    if kicked:
        result_lines.append(f"✅ **Kicked {len(kicked)} member(s):**")
        for mem, gnames in kicked[:15]:
            result_lines.append(f"  — **{mem.display_name}** (was in: {gnames})")
        if len(kicked) > 15:
            result_lines.append(f"  *...and {len(kicked) - 15} more.*")
    if failed_kick:
        result_lines.append(f"\n❌ **Failed to kick {len(failed_kick)}:**")
        for mem, err in failed_kick[:5]:
            result_lines.append(f"  — **{mem.display_name}**: {err}")
    result_lines.append(f"\n🧹 Clean: **{clean}** | 🔍 Not in shared servers: **{len(not_found)}** | 🛡️ Protected: **{len(protected)}**")
    result_lines.append(f"\n*He comes back and sits down. He is done.* **mrr.**")

    await ctx.send("\n".join(result_lines))

    # DM Creator a summary if used in server
    creator = bot.get_user(DOCTOR_ID)
    if not creator:
        try:
            creator = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator = None
    if creator and ctx.guild:
        try:
            summary_lines = [f"👢 **!kickNSFW results in {ctx.guild.name}:**"]
            summary_lines.append(f"Kicked: {len(kicked)} | Failed: {len(failed_kick)} | Protected (warned): {len(protected)} | Clean: {clean}")
            if protected:
                summary_lines.append("\n⚠️ **Protected (admin/owner) flagged members:**")
                for mem, guilds in protected:
                    summary_lines.append(f"  🛡️ {mem.display_name} ({mem.id}) — {', '.join(g.name for g in guilds[:3])}")
            await creator.send("\n".join(summary_lines))
        except Exception:
            pass





