# ── Patrol ─────────────────────────────────────────────────────────────────────

@bot.command(name="serverscan", aliases=["serverpatrol", "scansuspects", "checksuspect", "scanmembers"])
async def serverscan_cmd(ctx):
    """Creator only: Yarnaby scans the server for suspicious members."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can send him on a server scan.* **mrr.**")
        return
    if not ctx.guild:
        await ctx.send("*Use this in a server.* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)
    await ctx.send("*He stands, ears forward, and begins a slow, deliberate walk through every corner of the server. Give him a moment.* **mrr.**")
    await _asyncio.sleep(2)

    findings = []

    for member in ctx.guild.members:
        if member.bot:
            continue

        flags = []

        # New account
        age_days = (datetime.now(timezone.utc).replace(tzinfo=None) - member.created_at.replace(tzinfo=None)).days
        if age_days < 7:
            flags.append(f"⚠️ new account ({age_days}d old)")

        # No roles (besides @everyone)
        if len(member.roles) <= 1:
            flags.append("🔍 no roles")

        # In NSFW servers
        nsfw_shared = [g for g in bot.guilds if g.id != ctx.guild.id and g.get_member(member.id) and _is_nsfw_guild(g)]
        if nsfw_shared:
            flags.append(f"🔴 in NSFW server(s): {', '.join(g.name for g in nsfw_shared[:2])}")

        # Warning history
        warns = m["internal"].get("warnings", {}).get(str(member.id), [])
        if warns:
            flags.append(f"📋 {len(warns)} warning(s) on record")

        # Blacklisted
        if str(member.id) in m["internal"].get("blacklist", {}):
            flags.append("⛔ blacklisted")

        if flags:
            findings.append((member, flags))

    if not findings:
        await ctx.send(
            "*He completes the full circuit and returns. He sits down in front of you. "
            "He blinks once. Everything is clean. Nothing flagged.* **mrr.**"
        )
        return

    lines = [f"*He returns and drops a report at your feet.*\n\n🔍 **{len(findings)} member(s) flagged:**\n"]
    for mem, flags in findings[:20]:
        lines.append(f"▫️ **{mem.display_name}** (`{mem.id}`) — {' | '.join(flags)}")
    if len(findings) > 20:
        lines.append(f"\n*...and {len(findings) - 20} more. Full list DM'd to The Creator.*")

    lines.append(f"\n*He sits back down. He has noted everything.* **mrr.**")
    await ctx.send("\n".join(lines))

    # DM full list if truncated
    if len(findings) > 20:
        creator = bot.get_user(DOCTOR_ID)
        if not creator:
            try:
                creator = await bot.fetch_user(DOCTOR_ID)
            except Exception:
                creator = None
        if creator:
            full_lines = [f"🔍 **Full patrol report — {ctx.guild.name}:**\n"]
            for mem, flags in findings:
                full_lines.append(f"• {mem.display_name} ({mem.id}): {' | '.join(flags)}")
            try:
                await creator.send("\n".join(full_lines)[:4000])
            except Exception:
                pass


