@bot.command(name="blacklist", aliases=["blockuser", "ignoreuser", "yarnblacklist", "addblacklist"])
async def blacklist_cmd(ctx, member: discord.Member = None, *, reason: str = ""):
    """Creator only: permanently block a user from interacting with Yarnaby."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can do that.* **mrr.**")
        return
    if not member:
        await ctx.send("*Who? `!blacklist @user [reason]`* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)

    uid = str(member.id)
    bl = m["internal"].setdefault("blacklist", {})

    if uid in bl:
        await ctx.send(
            f"*He already has **{member.display_name}** in the blacklist. "
            f"Use `!unblacklist @user` to remove them.* **mrr.**"
        )
        return

    bl[uid] = {
        "name": member.display_name,
        "reason": reason.strip() or "no reason given",
        "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }
    # Set trust score to floor
    m["social_matrix"].setdefault(uid, {})["score"] = -100
    m["social_matrix"][uid]["trust_frozen"] = True
    save_db(m)

    await ctx.send(
        f"*He looks at **{member.display_name}**'s entry, closes the ledger, and turns it face-down. "
        f"They no longer exist to him.* ⛔ **Blacklisted.**"
    )

    embed = _log_embed("⛔ User Blacklisted", color=0xed4245, fields=[
        ("User", f"{member.mention} `{member.id}`", True),
        ("By", ctx.author.mention, True),
        ("Reason", reason or "No reason given", False),
    ])
    if ctx.guild:
        await _send_log(ctx.guild.id, embed)


@bot.command(name="unblacklist", aliases=["removeblacklist", "unblockuser", "unignoreuser", "clearblacklist"])
async def unblacklist_cmd(ctx, member: discord.Member = None):
    """Creator only: remove a user from the blacklist."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can do that.* **mrr.**")
        return
    if not member:
        await ctx.send("*Who? `!unblacklist @user`* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)

    uid = str(member.id)
    bl = m["internal"].get("blacklist", {})

    if uid not in bl:
        await ctx.send(f"*He checks. **{member.display_name}** isn't on the blacklist.* **mrr.**")
