@bot.command(name="8ball", aliases=["eightball", "yarnyball", "magicball", "askyarny8"])
async def eightball_cmd(ctx, *, question: str = ""):
    """Ask Yarnaby a yes/no question. He answers in his own way."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return

    if not question.strip():
        await ctx.send("*He looks at you waiting for a question. `!8ball [your question]`* **mrr.**")
        return

    action, answer = random.choice(_8BALL_RESPONSES)

    # Mood influences answer slightly
    mood = m["stats"].get("mood", "Content")
    if mood == "Agitated" and answer == "yes":
        action, answer = random.choice([r for r in _8BALL_RESPONSES if r[1] == "no"])
    elif mood == "Happy" and answer == "no":
        if random.random() < 0.3:
            action, answer = random.choice([r for r in _8BALL_RESPONSES if r[1] == "yes"])

    sound = {"yes": "**mrr.**", "no": "**hff.**", "...": "**...mrr.**"}[answer]
    await ctx.send(f"*He receives the question. He considers it.*\n{action} {sound}")


# ── Rock Paper Scissors ────────────────────────────────────────────────────────

_RPS_CHOICES = ["rock", "paper", "scissors"]
_RPS_BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}
_RPS_EMOJIS = {"rock": "🪨", "paper": "📄", "scissors": "✂️"}

@bot.command(name="rps", aliases=["rockpaperscissors", "yarnyRPS", "playRPS", "rpsyarny"])
async def rps_cmd(ctx, choice: str = ""):
    """Play rock paper scissors against Yarnaby. He cheats if he's in a bad mood."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return

    choice = choice.lower().strip()
    if choice not in _RPS_CHOICES:
        await ctx.send("*He holds up three options: `rock`, `paper`, or `scissors`. Pick one.* **mrr.**")
        return

    mood = m["stats"].get("mood", "Content")
    uid = str(ctx.author.id)

    # Cheating: if Agitated or low trust, he peeks at your choice and picks the winner
    score = 99 if ctx.author.id == DOCTOR_ID else m["social_matrix"].get(uid, {}).get("score", 0)
    cheating = mood in ("Agitated",) or score < -3

    if cheating and random.random() < 0.6:
        # He picks whatever beats you
        his_choice = [c for c in _RPS_CHOICES if _RPS_BEATS[c] == choice][0]
        cheat = True
    else:
        his_choice = random.choice(_RPS_CHOICES)
        cheat = False

    pe = _RPS_EMOJIS[his_choice]
    ue = _RPS_EMOJIS[choice]

    if _RPS_BEATS[his_choice] == choice:
        result = "win"
    elif _RPS_BEATS[choice] == his_choice:
        result = "lose"
    else:
        result = "tie"

    if result == "win":
        if cheat:
            response = random.choice([
                f"*He reveals {pe}. You had {ue}. He wins. He knew. His ear flicks once. He is not sorry.* **mrr.**",
                f"*{pe} vs {ue}. He wins. Something about the way he was watching your hand suggests he had information.* **...mrr.**",
            ])
        else:
            response = random.choice([
                f"*{pe} vs {ue}. He wins. He blinks once. He expected this.* **mrr.**",
                f"*He reveals {pe}. You had {ue}. He wins, and his expression says he sees no reason to celebrate the obvious.* **mrr.**",
            ])
        if uid in m["social_matrix"] and not _is_trust_frozen(m, uid):
            m["social_matrix"][uid]["score"] = max(-100, m["social_matrix"][uid].get("score", 0) - 1)
    elif result == "lose":
        response = random.choice([
            f"*{pe} vs {ue}. He loses. He stares at his own paw for a moment. He files this under unresolved business.* **...mrr.**",
            f"*He reveals {pe}. You had {ue}. He loses. His tail is very still. He does not request a rematch. Out loud.* **mrr.**",
        ])
        if uid in m["social_matrix"] and not _is_trust_frozen(m, uid):
            m["social_matrix"][uid]["score"] = min(100, m["social_matrix"][uid].get("score", 0) + 1)
    else:
        response = random.choice([
            f"*{pe} vs {ue}. A tie. He looks at you. He looks at his paw. He looks back. Unresolved.* **...mrr.**",
            f"*Both {pe}. He sits back. This settles nothing. He is aware of this.* **mrr.**",
        ])

    save_db(m)
    await ctx.send(response)


# ── Scramble ──────────────────────────────────────────────────────────────────

_SCRAMBLE_WORDS = [
    "factory", "hoard", "window", "blanket", "feather", "shadow", "lantern",
    "chimney", "clockwork", "velvet", "marble", "copper", "silence", "thunder",
    "patchwork", "cobweb", "hollow", "splinter", "cinders", "Archive",
    "gearbox", "furnace", "workshop", "balcony", "corridor", "fragment",
    "flicker", "anchor", "thimble", "compass", "telescope", "cabinet",
    "whisper", "crumble", "scatter", "wander", "burrow", "shimmer",
]

_active_scramble: dict = {}  # channel_id -> {word, scrambled, task}

def _scramble_word(word: str) -> str:
    import random as _r
    letters = list(word.lower())
    while True:
        _r.shuffle(letters)
        scrambled = "".join(letters)
        if scrambled != word.lower():
            return scrambled

@bot.command(name="scramble", aliases=["wordscramble", "yarnscramble", "unscramble", "scrambleword"])
async def scramble_cmd(ctx):
    """Yarnaby drops a scrambled word. First to unscramble it wins a trust bump."""
    m = bot.db
    await _add_reactions(ctx, m)
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. He does not respond.* **...zz.**",
            "*He is curled up and deeply asleep. Nothing stirs.* **...zz.**",
            "*A faint snore. He is not available.* **...zz.**",
            "*He is asleep. His ear twitches once, then stills.* **...zz.**",
            "*He is somewhere far away in sleep. He does not hear you.* **...zz.**",
        ]))
        return

    if ctx.channel.id in _active_scramble:
        await ctx.send("*He taps the scrambled word on the floor. That one's still out there. Solve it first.* **mrr.**")
        return

    word = random.choice(_SCRAMBLE_WORDS).lower()
    scrambled = _scramble_word(word)

    await ctx.send(random.choice([
        f"*He drops a handful of letters on the floor and sits back. He waits.*\n\n🔤 **`{scrambled}`** — unscramble it. You have 45 seconds.",
        f"*He produces a set of jumbled letters from somewhere and presents them with quiet seriousness.*\n\n🔤 **`{scrambled}`** — what's the word?",
        f"*He arranges something on the floor carefully, then sits beside it and stares at you.*\n\n🔤 **`{scrambled}`**",
    ]))

    async def _timeout_scramble():
        await asyncio.sleep(45)
        if ctx.channel.id in _active_scramble:
            del _active_scramble[ctx.channel.id]
            try:
                await ctx.send(f"*He picks the letters back up. The word was **{word}**.* **mrr.**")
            except Exception:
                pass

    task = bot.loop.create_task(_timeout_scramble())
    _active_scramble[ctx.channel.id] = {"word": word, "scrambled": scrambled, "task": task}


@bot.listen("on_message")
async def _scramble_listener(message):
    if message.author.bot:
        return
    entry = _active_scramble.get(message.channel.id)
    if not entry:
        return
    if message.content.startswith("!") or message.content.startswith("yarn!"):
        return

    if message.content.strip().lower() == entry["word"]:
        entry["task"].cancel()
        del _active_scramble[message.channel.id]

        m = bot.db
        uid = str(message.author.id)
        if uid in m["social_matrix"] and not _is_trust_frozen(m, uid):
            m["social_matrix"][uid]["score"] = min(100, m["social_matrix"][uid].get("score", 0) + 2)
            save_db(m)

        await message.channel.send(random.choice([
            f"*He looks at {message.author.mention}. He blinks. He sweeps the letters into a pile and sits on them, satisfied.* **prrk.**",
            f"*He watches {message.author.mention} solve it. His ear flicks forward once. Correct.* **mrr.**",
            f"*He stares at {message.author.mention} for a moment, then looks at the letters, then back. He nods once.* **prrr.**",
        ]))



# ==========================================
# THREAT TIMEOUT SYSTEM
# - Threatener must keep sending messages
# - 10 min silence = Yarnaby escapes
# - Creator can use !stop_threat to end it
# ==========================================

_threat_timeout_task = None  # current running timeout task
_threatener_last_message: dict = {}  # user_id -> timestamp

async def _escape_threat(m, channel_id: int, reason: str = "silence"):
    """Yarnaby escapes the threat — clear all helpless state and narrate it."""
    by_id = m["internal"].get("helpless_by", "")
    threat_detail = m["internal"].get("helpless_reason", "the threat")

    # Clear helpless state
    m["internal"]["helpless"] = False
    m["internal"]["helpless_reason"] = ""
    m["internal"]["helpless_by"] = ""
    m["internal"]["helpless_since"] = ""

    # Remove threat access from the threatener
    if by_id and by_id in m["social_matrix"]:
        entry = m["social_matrix"][by_id]
        entry["threat_access"] = False
        # Restore original score if it was bumped
        if "score_before_threat_access" in entry:
            entry["score"] = entry.pop("score_before_threat_access")
        # Also dock score for threatening him
        entry["score"] = max(-100, entry.get("score", 0) - 10)

    save_db(m)

    channel = bot.get_channel(channel_id)
    if not channel:
        return

    if reason == "silence":
        await channel.send(random.choice([
            f"*The room has been quiet for a while. The threat hasn't moved. Hasn't spoken. "
            f"Yarnaby waits one more moment — then he shifts his weight. Then he moves. "
            f"Slowly, deliberately, he walks away from where he was being held. "
            f"He doesn't look back. He finds a corner and sits down. He grooms his paw once. "
            f"He is out.* **...mrr.**",

            f"*Ten minutes of silence. The hand that held him in place is gone — not physically, "
            f"but in every way that matters. Yarnaby watches the door. Then he gets up. "
            f"He pads to the far side of the room. He sits. He tucks his tail around his paws. "
            f"He exhales once. He's free.* **...prrr.**",

            f"*Nothing has happened for too long. Yarnaby recalibrates. "
            f"He was still because something was pressing on him — and now that pressure is gone. "
            f"He stands, shakes himself once, and moves to where he actually wants to be. "
            f"He does not acknowledge what just happened. He simply resumes.* **mrr.**",

            f"*The silence stretched. The threat lost its grip the longer it went without being maintained. "
            f"Yarnaby feels the difference. He gets up — not fast, not dramatic — and walks away. "
            f"He settles somewhere else. His ears are forward again. It's over.* **...mrr.**",
        ]))
    elif reason == "creator":
        await channel.send(random.choice([
            f"*The Creator ends it. Yarnaby feels it immediately — the weight lifts. "
            f"He gets up, pads directly to The Creator, and presses his head against them once. "
            f"He stays there for a moment. Then he walks back to his spot and sits down, "
            f"ears forward, tail wrapped. He is himself again.* **prrr.**",

            f"*The Creator intervenes. Whatever was holding Yarnaby dissolves. "
            f"He stands, stretches — a long, full-body stretch that says everything — "
            f"and goes to The Creator. He bumps his head against their hand. "
            f"He is out. He is fine. He is, probably, filing this under things he will remember.* **prrr.**",
        ]))

    # DM the Creator either way
    creator = bot.get_user(DOCTOR_ID)
    if not creator:
        try:
            creator = await bot.fetch_user(DOCTOR_ID)
        except Exception:
            creator = None
    if creator:
        try:
            await creator.send(
                f"🔓 Yarnaby escaped the threat.\n"
                f"**Reason:** {'10 minutes of threatener silence' if reason == 'silence' else 'Creator used !stop_threat'}\n"
                f"**Original threat:** {threat_detail}\n"
                f"**Threatener score docked -10.**"
            )
        except Exception:
            pass


async def _run_threat_timeout(m, channel_id: int, threatener_id: str):
    """Background task: watches for 10 min of threatener silence then triggers escape."""
    global _threat_timeout_task
    TIMEOUT = 600  # 10 minutes
    CHECK_INTERVAL = 30  # check every 30 seconds

    elapsed = 0
    while elapsed < TIMEOUT:
        await asyncio.sleep(CHECK_INTERVAL)
        elapsed += CHECK_INTERVAL

        # Check if threat was already cleared (by creator)
        m = bot.db
        if not m["internal"].get("helpless"):
            return  # already resolved

        # Check last message time from the threatener
        last_msg = _threatener_last_message.get(threatener_id, 0)
        since_last = datetime.now().timestamp() - last_msg
        if since_last > TIMEOUT:
            # Threatener has been silent for 10 minutes — escape
            await _escape_threat(m, channel_id, reason="silence")
            return

    # If we somehow exit the loop still helpless
    m = bot.db
    if m["internal"].get("helpless"):
        await _escape_threat(m, channel_id, reason="silence")


@bot.listen("on_message")
async def _threat_activity_listener(message):
    """Track threatener's last message time to reset their 10-min silence window."""
    if message.author.bot:
        return
    m = bot.db
    if not m["internal"].get("helpless"):
        return
    by_id = m["internal"].get("helpless_by", "")
    if str(message.author.id) == by_id:
        _threatener_last_message[by_id] = datetime.now().timestamp()


# Patch the threaten command to start the timeout task
_original_threaten_callback = None

def _patch_threaten_cmd():
    global _original_threaten_callback
    cmd = bot.get_command("threaten")
    if not cmd:
        return
    _original_threaten_callback = cmd.callback

    import functools
    @functools.wraps(_original_threaten_callback)
    async def _patched_threaten(ctx, *, threat: str = ""):
        global _threat_timeout_task
        # Run original
        await _original_threaten_callback(ctx, threat=threat)

        # Start the timeout watcher
        m = bot.db
        if m["internal"].get("helpless"):
            u_id = str(ctx.author.id)
            _threatener_last_message[u_id] = datetime.now().timestamp()
            # Cancel any existing task
            if _threat_timeout_task and not _threat_timeout_task.done():
                _threat_timeout_task.cancel()
            _threat_timeout_task = bot.loop.create_task(
                _run_threat_timeout(m, ctx.channel.id, u_id)
            )

    cmd.callback = _patched_threaten


@bot.command(name="stop_threat", aliases=["stopthreat", "endthreat", "freeyarny", "releaseyarny", "threatstop"])
async def stop_threat_cmd(ctx):
    """Creator only: immediately end the current threat and free Yarnaby."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can end a threat.* **mrr.**")
        return

    m = bot.db
    await _add_reactions(ctx, m)

    if not m["internal"].get("helpless"):
        await ctx.send(
            "*He checks. Yarnaby isn't currently under any threat. "
            "He is free. He has always been free here.* **mrr.**"
        )
        return

    # Cancel the running timeout task
    global _threat_timeout_task
    if _threat_timeout_task and not _threat_timeout_task.done():
        _threat_timeout_task.cancel()
        _threat_timeout_task = None

    await _escape_threat(m, ctx.channel.id, reason="creator")





