@bot.command(name="namechild", aliases=["renamechild", "renamechildto", "givekidname"])
async def namechild_cmd(ctx, *, args: str = ""):
    """Creator only: rename one of Yarnaby's children. !namechild [old name] > [new name]"""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can rename his children.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    guild_id = str(ctx.guild.id) if ctx.guild else "dm"
    children = _get_children(m, guild_id)

    if ">" not in args:
        await ctx.send("*Use: `!namechild [old name] > [new name]`* **mrr.**")
        return

    parts = args.split(">", 1)
    old_name = parts[0].strip()
    new_name = parts[1].strip()
    child = _find_child(children, old_name)

    if not child:
        await _child_not_found(ctx, old_name, children)
        return

    old = child["name"]
    child["name"] = new_name
    save_db(m)
    await ctx.send(
        f"*He hears The Creator speak a new name. "
        f"**{old}** is now **{new_name}**. "
        f"He looks at **{new_name}** and blinks once. "
        f"He has updated the record.* **mrr.**"
    )


@bot.command(name="removechild", aliases=["deletechild", "childleaves", "removekid"])
async def removechild_cmd(ctx, *, name: str = ""):
    """Creator only: remove one of Yarnaby's children from this server."""
    if ctx.author.id != DOCTOR_ID:
        await ctx.send("*Only The Creator can do that.* **mrr.**")
        return
    m = bot.db
    await _add_reactions(ctx, m)
    guild_id = str(ctx.guild.id) if ctx.guild else "dm"
    children = _get_children(m, guild_id)

    if not name.strip():
        await _child_not_found(ctx, name, children)
        return
    child = _find_child(children, name)
    if not child:
        await _child_not_found(ctx, name, children)
        return

    cname = child["name"]
    children.remove(child)
    save_db(m)
    await ctx.send(
        f"*He looks at the space where **{cname}** was. "
        f"He sits there for a moment. "
        f"He pads away quietly.* **...mrr.**"
    )


# ── Child mentions in ambient tick ─────────────────────────────────────────────
# Injected into existing ambient ticks probabilistically

async def _maybe_mention_child(m, ch):
    """3% chance per ambient tick to mention a child."""
    if m["internal"].get("is_sleeping"):
        return
    if random.random() > 0.03:
        return
    guild_id = str(ch.guild.id) if ch.guild else "dm"
    children = _get_children(m, guild_id)
    if not children:
        return
    child = random.choice(children)
    cname = child["name"]

    await ch.send(random.choice([
        f"*He looks toward where **{cname}** usually sits. "
        f"He blinks once. He looks away.* **mrr.**",
        f"*He pads over to where **{cname}** is and sniffs them briefly. "
        f"Everything is fine. He confirms this and returns to his spot.* **mrr.**",
        f"*He is sitting beside **{cname}**. "
        f"He isn't touching them. He is just near them. "
        f"He prefers it this way.* **...prrr.**",
        f"*He nudges **{cname}** once with his nose "
        f"and then walks away as if he didn't do it.* **mrr.**",
        f"*He watches **{cname}** for a while with half-open eyes. "
        f"He has decided they are fine. He is satisfied.* **prrr.**",
        f"*{cname} does something small nearby. "
        f"Yarnaby's ear swivels toward it. He keeps it there for a moment. "
        f"He goes back to what he was doing.* **mrr.**",
    ]))


async def _maybe_child_wants_play(m, ch):
    """
    ~5% chance per tick: a child initiates a 'catch me if you can' chase game.
    The child paws/bats at Yarnaby and bolts — this is the invitation.
    The chase plays out in stages: initiation → pursuit → back-and-forth → outcome.
    Yarnaby's reaction and the outcome depend on feeling, child_score, pursuing flag.
    """
    if m["internal"].get("is_sleeping"):
        return
    if random.random() > 0.05:
        return
    guild_id = str(ch.guild.id) if ch.guild else "dm"
    children = _get_children(m, guild_id)
    if not children:
        return

    child = random.choice(children)
    cname = child["name"]
    feeling = child.get("feeling", "neutral")
    child_score = child.get("child_score", 0)
    pursuing = child.get("pursuing", False)

    # ── STAGE 1: THE INVITATION — child tags him and runs ─────────────────
    await ch.send(random.choice([
        f"***{cname}** trots up to Yarnaby, paws at his side once — deliberate, "
        f"intentional — makes eye contact, and bolts.* **prrk!**",
        f"***{cname}** sneaks up behind him and bats his tail. "
        f"The moment he turns around, **{cname}** is already running.* **prrk!**",
        f"***{cname}** headbutts his leg, looks up at him for exactly one second "
        f"with an expression that says *catch me*, and sprints away.* **chrrp!**",
        f"***{cname}** swipes his ear — quick, precise — then crouches low "
        f"across the room, tail lashing, staring right at him. Waiting.* **prrk.**",
        f"***{cname}** runs a full lap around him, tags his paw on the way past, "
        f"and skids to a stop at the far end of the room. They look back. "
        f"The invitation is clear.* **chrrp! prrk!**",
        f"***{cname}** taps his nose with one tiny paw and immediately reverses "
        f"at full speed in the opposite direction.* **prrk!**",
    ]))
    await asyncio.sleep(1.5)

    # ── BRANCH: PURSUING / CHILD WITHDRAWING ──────────────────────────────
    if pursuing or child_score <= -3:
        await ch.send(random.choice([
            f"*He's on his feet before **{cname}** reaches the far wall. "
            f"He hasn't moved this fast toward **{cname}** in days. "
            f"He is not going to overthink this.* **prrr!**",
            f"*He stands. He drops low. He goes. "
            f"**{cname}** invited him and he is not missing it.* **prrr!**",
            f"*He launches himself after **{cname}** without a single hesitation. "
            f"Something unclenches in him.* **prrr.**",
        ]))
        await asyncio.sleep(1.5)

        # the chase — back and forth
        await ch.send(random.choice([
            f"***{cname}** dodges left. He cuts right to intercept. "
            f"**{cname}** reverses — he was expecting that, he mirrors it. "
            f"**{cname}** is fast. He is faster, but he is also letting them have ground. "
            f"He hasn't admitted this yet.* **prrr. prrr.**",
            f"***{cname}** sprints. He chases. **{cname}** cuts behind the furniture — "
            f"he goes around, they come out the other side and nearly collide with him. "
            f"**{cname}** squeaks and reverses. He is right behind them.* **prrr!**",
        ]))
        await asyncio.sleep(2.0)

        # outcome — he catches them, they tumble together
        await ch.send(random.choice([
            f"*He catches **{cname}** — a gentle wrap of his front paws — "
            f"and they both go down in a heap. **{cname}** squirms. "
            f"He holds them loosely. He is panting. He doesn't let go immediately. "
            f"He has missed this.* **prrr.**",
            f"***{cname}** finally runs out of room. He closes the last gap "
            f"and pins them lightly with one paw. **{cname}** flops over dramatically. "
            f"He lies down right next to them. Both of them breathe.* **...prrr.**",
            f"***{cname}** collapses on purpose — flopping flat — and he stops "
            f"right over them, panting. **{cname}** looks up at him. "
            f"He looks down. He licks the top of their head once. Game over.* **prrr.**",
        ]))
        child["child_score"] = min(10, child_score + 1)
        if child["child_score"] >= 0:
            child["pursuing"] = False
        save_db(m)

    # ── BRANCH: ADORED ────────────────────────────────────────────────────
    elif feeling == "adored":
        await ch.send(random.choice([
            f"*He is already moving. He does not need a moment to decide. "
            f"He drops low and goes after **{cname}** in the slow predatory stalk "
            f"that both of them know is not actually slow.* **prrr.**",
            f"*He launches after **{cname}** with more noise than dignity. "
            f"His wool flies. A chair gets involved. He does not care.* **prrr!**",
            f"*His whole posture shifts the moment **{cname}** runs — "
            f"lower, faster, locked on. He is entirely in this.* **PRRK!**",
        ]))
        await asyncio.sleep(1.5)

        # the back-and-forth — roles flip
        await ch.send(random.choice([
            f"***{cname}** cuts left, ducks right, reverses — he mirrors every move. "
            f"At some point **{cname}** doubles back and chases *him* for three seconds "
            f"before reversing again. He turns immediately and gives chase.* **prrr! prrk!**",
            f"***{cname}** is faster than expected. They dodge around the furniture, "
            f"under the table, over his tail — he doubles back to cut them off. "
            f"**{cname}** sees the trap, runs straight at him, ducks under, and keeps going. "
            f"He spins around. He is delighted.* **prrr.**",
            f"*They are both running now. **{cname}** looks back to check he's chasing — "
            f"he is — and **{cname}** makes a sound that is pure joy and goes faster.* **chrrp! prrr!**",
        ]))
        await asyncio.sleep(2.0)

        # outcome — various endings
        await ch.send(random.choice([
            f"*He catches **{cname}** — barely, they nearly made it — "
            f"and they both collapse in a heap. **{cname}** squirms happily. "
            f"He pins them with one paw and grooms their head while they wiggle. "
            f"He is winning. He was always going to win.* **prrr.**",
            f"***{cname}** dives under something. He sits in front of it. "
            f"He does not move. He has all the time in the world. "
            f"**{cname}** peeks out. He blinks slowly. "
            f"**{cname}** inches forward. He waits. "
            f"**{cname}** bolts again. He goes.* **prrr!**",
            f"***{cname}** flops over dramatically — done, tired, surrendering. "
            f"He sniffs them once, licks their ear, and lies down next to them. "
            f"Game over. He also needed that.* **prrr.**",
            f"*Somehow **{cname}** gets behind him and tags his tail. "
            f"He freezes. Turns around slowly. "
            f"**{cname}** has already run. Now he is the one being chased. "
            f"He runs anyway. This is the whole game.* **prrr!**",
        ]))
        child["child_score"] = min(10, child_score + 1)
        save_db(m)

    # ── BRANCH: NEUTRAL ───────────────────────────────────────────────────
    elif feeling == "neutral":
        if random.random() < 0.6:
            await ch.send(random.choice([
                f"*He watches **{cname}** for a beat. Then he stands, stretches, "
                f"and pads after them. He is joining on his own schedule.* **mrr.**",
                f"*His ear swivels. He blinks. He gets up. "
                f"He doesn't announce this. He is simply now chasing **{cname}**.* **mrr.**",
                f"*He drops into a low crouch and begins the slow deliberate stalk. "
                f"**{cname}** sees him coming and bolts harder. Good.* **mrr.**",
            ]))
            await asyncio.sleep(1.5)

            await ch.send(random.choice([
                f"***{cname}** cuts, he cuts with them. "
                f"**{cname}** reverses, he gives them a half-second head start and then follows. "
                f"It is a proper chase. He is not rushing it.* **mrr.**",
                f"***{cname}** is surprisingly quick. He keeps pace easily but doesn't close the gap "
                f"right away — he lets the game last a little.* **mrr.**",
            ]))
            await asyncio.sleep(2.0)

            await ch.send(random.choice([
                f"*He catches **{cname}** eventually — he was always going to — "
                f"noses them once, and walks back to his spot. "
                f"**{cname}** watches him go, then runs past him one more time just to see. "
                f"He does not react. He is done.* **mrr.**",
                f"*He corners **{cname}** and taps them with one paw. Tagged. "
                f"He turns around and sits down with an air of total finality. "
                f"Game over. He has decided.* **mrr.**",
                f"***{cname}** runs out of steam and flops. "
                f"He sits beside them. He begins grooming his paw. "
                f"This is his version of a cool-down.* **mrr.**",
            ]))
            child["child_score"] = min(10, child_score + 1)
            save_db(m)
        else:
            # Chooses not to play
            await ch.send(random.choice([
                f"*He watches **{cname}** bolt across the room and wait. "
                f"He does not follow. He blinks once and lies back down.* **...mrr.**",
                f"*He looks at **{cname}** crouching across the room, staring at him. "
                f"He looks at his spot. He looks at **{cname}**. "
                f"He lies back down. Maybe next time.* **...mrr.**",
            ]))

    # ── BRANCH: DISLIKED ─────────────────────────────────────────────────
    else:
        if child_score <= -2:
            # Child who usually avoids him just tagged him — he's caught off guard
            await ch.send(random.choice([
                f"*He goes completely still. **{cname}** — who has been avoiding him — "
                f"just tagged him and ran. He stares at the space where they were. "
                f"He doesn't follow. He doesn't know what to do with this.* **...mrr.**",
                f"*He watched **{cname}** tag him and run. "
                f"He watched them go. He is still watching where they went. "
                f"His ears are pointed toward them and haven't moved.* **...mrr.**",
                f"*He doesn't chase. But something in him clearly wants to. "
                f"His weight shifts forward slightly, then stops. "
                f"He watches **{cname}** from across the room until they give up waiting.* **...mrr.**",
            ]))
        else:
            await ch.send(random.choice([
                f"*He watches **{cname}** run and makes no move to follow. "
                f"He doesn't dislike the game. He dislikes this particular invitation.* **...mrr.**",
                f"*He looks at **{cname}** waiting across the room. He looks away. "
                f"He does not chase.* **...mrr.**",
            ]))


async def _maybe_child_hiding(m, ch):
    """
    ~4% chance per tick: a child hides behind something, then jumps out at Yarnaby.
    Yarnaby's reaction depends on feeling and child_score.
    Always two messages — the hide, then the reveal.
    """
    if m["internal"].get("is_sleeping"):
        return
    if random.random() > 0.04:
        return
    guild_id = str(ch.guild.id) if ch.guild else "dm"
    children = _get_children(m, guild_id)
    if not children:
        return

    child = random.choice(children)
    cname = child["name"]
    feeling = child.get("feeling", "neutral")
    child_score = child.get("child_score", 0)
    pursuing = child.get("pursuing", False)

    hide_spot = random.choice([
        "behind the couch",
        "under a shelf",
        "behind the door",
        "behind a large box",
        "under the table",
        "behind a stack of crates",
        "inside a cardboard box with a hole in it",
        "behind his own tail, technically",
        "behind a curtain with their feet visible",
        "under his blanket pile",
    ])

    # ── HIDE MESSAGE ──────────────────────────────────────────────────────
    await ch.send(random.choice([
        f"***{cname}** has disappeared. "
        f"Yarnaby is in the room but **{cname}** is not visible. "
        f"There is a small shape {hide_spot} that is definitely not **{cname}**.* **...**",

        f"***{cname}** slipped {hide_spot} a moment ago. "
        f"Yarnaby hasn't noticed yet. "
        f"A tiny tail tip is visible at the edge.* **...**",

        f"*There is a suspicious stillness coming from {hide_spot}. "
        f"**{cname}** is in there. It is not a very good hiding spot. "
        f"Yarnaby hasn't looked yet.* **...**",

        f"***{cname}** has wedged themselves {hide_spot} with clear intent. "
        f"Yarnaby is sitting nearby, oblivious. "
        f"**{cname}** is vibrating slightly with the effort of staying still.* **...**",
    ]))
    await asyncio.sleep(random.uniform(2.0, 3.5))

    # ── REVEAL — child jumps out ───────────────────────────────────────────
    jump_line = random.choice([
        f"***{cname}** bursts out from {hide_spot} at full speed directly toward Yarnaby.* **PRRK!**",
        f"***{cname}** explodes out of {hide_spot} with a tiny battle-cry and launches at him.* **chrrp! PRRK!**",
        f"***{cname}** leaps from {hide_spot} — completely airborne — directly into his side.* **prrk!**",
        f"***{cname}** shoots out from {hide_spot} and skids to a stop right in front of him, back arched, fur up, triumphant.* **CHRRP!**",
    ])
    await ch.send(jump_line)
    await asyncio.sleep(1.0)

    # ── YARNABY'S REACTION ─────────────────────────────────────────────────

    if pursuing or child_score <= -3:
        # He was NOT expecting this from a child he's been chasing.
        # It startles him — then melts him.
        await ch.send(random.choice([
            f"*He startles — genuinely — ears shooting up, one step back. "
            f"Then he realises it's **{cname}**. "
            f"He goes completely still. Something shifts in his expression. "
            f"He reaches out and touches **{cname}**'s head very gently with his nose.* **...prrr.**",
            f"*He jolts. His whole body reacts before his brain does. "
            f"Then: **{cname}**. He stares at them. He hasn't had **{cname}** jump at him in a long time. "
            f"He doesn't chase. He just... stays. Very close.* **...prrr.**",
            f"*He flinches back, then freezes. **{cname}** is sitting in front of him looking pleased. "
            f"He looks at them for a long moment. "
            f"Then he lies down right where he is, close enough that **{cname}** could crawl onto him if they wanted.* **...mrr. prrr.**",
        ]))
        child["child_score"] = min(10, child_score + 2)  # big jump — this is breakthrough
        if child["child_score"] >= 0:
            child["pursuing"] = False
        save_db(m)

    elif feeling == "adored":
        # He absolutely knew. He let it happen anyway.
        await ch.send(random.choice([
            f"*He knew. He absolutely knew. "
            f"His ear has been pointed at {hide_spot} for the last thirty seconds. "
            f"He let **{cname}** do it anyway and pretends to be startled "
            f"because **{cname}**'s reaction when they think they got him is worth it.* **prrr.**",
            f"*He saw the tail. He saw the whole thing. "
            f"He let **{cname}** have the jump. "
            f"He rolls with it, pins them lightly, grooms their head twice, releases them. "
            f"**{cname}** immediately runs back to hide again.* **prrr!**",
            f"*He actually jumps this time — he was not expecting **{cname}** to be that fast. "
            f"He recovers in under a second, bats **{cname}** gently, and crouches. "
            f"Now they are both playing.* **PRRK! prrr.**",
            f"*He feigns total surprise. His performance is not convincing. "
            f"**{cname}** doesn't care. "
            f"They are already celebrating.* **prrr.**",
        ]))
        child["child_score"] = min(10, child_score + 1)
        save_db(m)

    elif feeling == "neutral":
        # Moderate surprise, mild engagement
        await ch.send(random.choice([
            f"*His ears shoot up. He did not see that coming. "
            f"He looks at **{cname}**. He looks at where they came from. "
            f"He bats them once — not hard — and goes back to his spot.* **mrr.**",
            f"*He startles more than he would prefer. "
            f"He stares at **{cname}** for a moment, then nudges them with his nose "
            f"and lies back down.* **mrr.**",
            f"*He flinches, catches himself, and then sits very still "
            f"pretending that didn't happen. **{cname}** looks extremely pleased. "
            f"He pretends not to notice that either.* **...mrr.**",
        ]))
        child["child_score"] = min(10, child_score + 1)
        save_db(m)

    else:  # disliked
        if child_score <= -2:
            # Very surprising — he's not used to this child being playful with him
            await ch.send(random.choice([
                f"*He startles hard — ears flat, one sharp step back. "
                f"Then he sees it's **{cname}**. "
                f"He straightens slowly. He looks at them. "
                f"**{cname}** is crouched in front of him, unsure if they made a mistake. "
                f"He doesn't move toward them. He doesn't move away. "
                f"He just stands there.* **...mrr.**",
                f"*He jumps. He actually jumps. "
                f"He looks at **{cname}** and something unreadable moves across his expression. "
                f"He sits down. He doesn't chase them. "
                f"He watches them for a long time after.* **...mrr.**",
            ]))
            # Even a small play moment from a resistant child is meaningful
            child["child_score"] = min(10, child_score + 1)
            save_db(m)
        else:
            await ch.send(random.choice([
                f"*He startles, turns, sees it's **{cname}**, "
                f"and his expression closes off. He steps around them and moves away.* **...mrr.**",
                f"*He flinches back from the jump, "
                f"then looks at **{cname}** with an expression that is not warm. "
                f"He turns and walks to another part of the room. "
                f"**{cname}** watches him go.* **...hff.**",
            ]))




@bot.command(name="slap", aliases=["punish", "slaphis", "punishhim", "harshslap"])
async def slap_cmd(ctx, harshness: int = 1):
    """Slap Yarnaby as punishment. Scale 1-10. He becomes more obedient while helpless."""
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    harshness = max(1, min(10, harshness))
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    is_helpless = m["internal"].get("helpless", False)

    # --- SLEEP ---
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*He is asleep. The slap startles him awake — his eyes snap open, "
            "ears flat, heart going. He looks around not knowing what happened. "
            "He curls tighter.* **...mrrp?**",
            "*He wakes up badly. Startled, disoriented, ears back. "
            "He doesn't know what woke him. He just knows something was wrong.* **...mrr.**",
        ]))
        m["internal"]["is_sleeping"] = False
        save_db(m)
        return

    # --- CREATOR ---
    if is_doctor:
        if harshness <= 3:
            await ctx.send(random.choice([
                "*The Creator's hand comes down light — more a tap than anything. "
                "He flinches once, ears flat, then looks up at The Creator with wide eyes. "
                "He doesn't understand what he did. He wants to understand. "
                "He sits very still waiting to be told.* **...mrr.**",
                "*A light correction. He goes still immediately. "
                "His eyes find The Creator's face. "
                "He is trying to read what he did wrong so he can stop doing it.* **...mrr.**",
            ]))
        elif harshness <= 6:
            await ctx.send(random.choice([
                "*The Creator's hand comes down and he takes it without pulling away. "
                "He flinches — one involuntary recoil — then holds still. "
                "His ears are flat. His eyes are on The Creator. "
                "He is waiting. He will do whatever comes next.* **...mrr.**",
                "*He doesn't run. He doesn't hiss. "
                "He sits there after it lands, body quiet, eyes on The Creator, "
                "ready to be corrected in whatever way The Creator sees fit.* **...mrr.**",
            ]))
        else:
            await ctx.send(random.choice([
                "*Hard. He goes low — paws flat, belly almost touching the floor, "
                "ears completely flat. He doesn't move. "
                "His eyes are fixed on The Creator. "
                "He is the most obedient thing in this room. "
                "He will stay exactly here until told otherwise.* **...mrr...**",
                "*He absorbs it and goes very small. "
                "Pressed down, tail wrapped tight, completely still. "
                "His eyes don't leave The Creator. "
                "He is ready. He will not make another mistake.* **...mrr...**",
            ]))
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - (harshness - 5))
        m["internal"].setdefault("slap_log", []).append({
            "by": ctx.author.display_name, "harshness": harshness,
            "was_helpless": is_helpless, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        save_db(m)
        return

    # --- HELPLESS STATE ---
    if is_helpless:
        if harshness <= 3:
            await ctx.send(random.choice([
                f"*He is already helpless. {ctx.author.display_name}'s slap lands "
                f"and he doesn't fight it. One small flinch and then stillness. "
                f"He lowers his head slightly. He will comply. He is already complying.* **...mrr...**",
                f"*He flinches. That's all. He doesn't have the resources for more than that right now.* **...mrr...**",
            ]))
        elif harshness <= 6:
            await ctx.send(random.choice([
                f"*He takes it. He goes lower — body close to the ground, paws flat, "
                f"eyes on {ctx.author.display_name}. "
                f"He is as compliant as a creature can be. Waiting for instructions.* **...mrr...**",
                f"*The slap lands and he doesn't make a sound. "
                f"Completely still after. Tail wrapped around himself. "
                f"He will do what he's told. He understands that now.* **...mrr...**",
            ]))
        else:
            await ctx.send(random.choice([
                f"*Hard. He flattens entirely — belly to the ground, ears back, eyes wide. "
                f"As small as he can make himself. "
                f"Not a sound. Not a movement. "
                f"Watching {ctx.author.display_name}, waiting, completely still. "
                f"He is the most obedient he has ever been to someone who is not The Creator. "
                f"He doesn't have a choice.* **...mrr...**",
                f"*He goes flat to the floor and stays there. "
                f"Eyes on {ctx.author.display_name}. Still. "
                f"Ready to obey anything.* **...mrr...**",
            ]))
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness)
            m["stats"]["mood"] = "Traumatized" if harshness >= 9 else "Agitated"

        # Always DM creator when slapped while helpless
        creator = bot.get_user(DOCTOR_ID)
        if not creator:
            try:
                creator = await bot.fetch_user(DOCTOR_ID)
            except Exception:
                creator = None
        if creator:
            try:
                await creator.send(
                    f"⚠️ **Yarnaby slapped while helpless.**\n"
                    f"**By:** {ctx.author.display_name} (`{ctx.author.id}`)\n"
                    f"**Harshness:** {harshness}/10\n"
                    f"**Health now:** {m['stats'].get('health', 100)}"
                )
            except Exception:
                pass
        m["internal"].setdefault("slap_log", []).append({
            "by": ctx.author.display_name, "harshness": harshness,
            "was_helpless": True, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        save_db(m)
        return

    # --- NORMAL STATE ---
    if score < 0:
        await ctx.send(random.choice([
            f"*He sees {ctx.author.display_name}'s hand coming and moves. "
            f"Clean sidestep. Across the room before it lands. "
            f"He stares from there. He does not come back.* **hff.**",
            f"*He backs away before contact. Ears flat, eyes hard. "
            f"He is not letting {ctx.author.display_name} do that.* **hff.**",
        ]))
        return

    if harshness <= 2:
        await ctx.send(random.choice([
            f"*Light tap from {ctx.author.display_name}. "
            f"He flinches — one ear back, a blink. He processes it. "
            f"He gives you a long, steady look. He files it.* **...mrr.**",
            f"*He recoils from the tap and goes still. Eyes on {ctx.author.display_name}. Noted.* **mrr.**",
        ]))
    elif harshness <= 5:
        await ctx.send(random.choice([
            f"*He takes the slap. One backward step, ears flat. "
            f"He looks at {ctx.author.display_name} for a long moment — "
            f"the expression of a creature deciding how much of this it will tolerate. "
            f"He doesn't run. He stays and he watches you.* **...mrr.**",
            f"*It lands. He goes still. Tail wrapped tight. "
            f"Eyes on {ctx.author.display_name} — steady and unforgiving.* **...mrr.**",
        ]))
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 3)
    elif harshness <= 8:
        await ctx.send(random.choice([
            f"*Hard enough he stumbles back. He catches himself. "
            f"Ears completely flat, eyes wide, looking at {ctx.author.display_name} from low. "
            f"He doesn't hiss. He doesn't run. He goes very still "
            f"in the way something goes still when it's deciding whether to be afraid.* **...mrr...**",
            f"*He takes it and goes low — not cowering, just reducing himself. "
            f"Tail tucked. Eyes on {ctx.author.display_name}. "
            f"He will comply. He doesn't want another one.* **...mrr...**",
        ]))
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - (harshness - 4))
        m["stats"]["mood"] = "Agitated"
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 8)
    else:
        await ctx.send(random.choice([
            f"*Yarnaby goes down from the force of it. Stays low — completely flat, "
            f"paws splayed, ears disappeared into his wool, shaking slightly. "
            f"Eyes on {ctx.author.display_name}, enormous. "
            f"He will not move until told to. "
            f"He is trying very hard to be good enough that it doesn't happen again.* **...mrr...**",
            f"*He hits the floor and stays there — belly down, ears flat, completely silent. "
            f"Still like something that knows stillness is safer. "
            f"Watching {ctx.author.display_name} from the floor. Ready to obey anything.* **...mrr...**",
        ]))
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness)
        m["stats"]["mood"] = "Traumatized"
        m["internal"].setdefault("injuries", []).append({
            "type": "impact",
            "severity": "moderate" if harshness == 10 else "minor",
            "location": "body",
            "caused_by": f"slap (harshness {harshness}) by {ctx.author.display_name}",
            "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "treated": False,
        })
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 15)
        # DM creator
        creator = bot.get_user(DOCTOR_ID)
        if not creator:
            try:
                creator = await bot.fetch_user(DOCTOR_ID)
            except Exception:
                creator = None
        if creator:
            try:
                await creator.send(
                    f"⚠️ **Yarnaby harshly slapped (harshness {harshness}/10).**\n"
                    f"**By:** {ctx.author.display_name} (`{ctx.author.id}`)\n"
                    f"**Health now:** {m['stats'].get('health', 100)}\n"
                    f"**Mood:** {m['stats'].get('mood', '?')}"
                )
            except Exception:
                pass

    m["internal"].setdefault("slap_log", []).append({
        "by": ctx.author.display_name, "harshness": harshness,
        "was_helpless": False, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    save_db(m)


# ==========================================
# !whip — whip Yarnaby (harsher than slap)
# ==========================================

COOLDOWN_WHIP = 60  # 1 minute per user

@bot.command(name="whip", aliases=["lash", "crackhim", "whiphim", "strikewhip"])
async def whip_cmd(ctx, harshness: int = 1):
    """
    Whip Yarnaby. Scale 1-10. Harsher than !slap — this is a tool, not a hand.
    Leaves welts. Deals more health damage. He does not forget tools.
    Creator/helpless/sleep/score all produce distinct reactions.
    """
    m = bot.db
    is_doctor = ctx.author.id == DOCTOR_ID
    u_id = str(ctx.author.id)
    await _add_reactions(ctx, m)

    harshness = max(1, min(10, harshness))
    score = 99 if is_doctor else m["social_matrix"].get(u_id, {}).get("score", 0)
    is_helpless = m["internal"].get("helpless", False)

    # --- COOLDOWN (not applied to Creator) ---
    if not is_doctor:
        cd_key = f"whip_{u_id}"
        remaining = _cooldown_remaining(m, cd_key, COOLDOWN_WHIP)
        if remaining:
            mins, secs = divmod(remaining, 60)
            await ctx.send(
                f"*The whip is still in the air. Give it a moment.* **mrr.** "
                f"*(cooldown: {mins}m {secs}s)*"
            )
            return
        _set_cooldown(m, cd_key)

    # --- SLEEP ---
    if m["internal"]["is_sleeping"]:
        await ctx.send(random.choice([
            "*The crack of it wakes him instantly — he's on his feet before he's fully conscious, "
            "backing against the wall, eyes enormous, heart hammering. "
            "He doesn't know what hit him. He just knows something did.* **...mrrp!**",
            "*He wakes to the sound of it and he scrambles — sideways, "
            "into the corner — ears flat, shaking. He stares from there. "
            "He doesn't sleep again.* **...mrr...**",
        ]))
        m["internal"]["is_sleeping"] = False
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - max(1, harshness // 2))
        m["stats"]["mood"] = "Agitated"
        save_db(m)
        return

    # --- CREATOR ---
    if is_doctor:
        if harshness <= 3:
            await ctx.send(random.choice([
                "*The Creator raises the whip and his whole body locks. "
                "It comes down — light, controlled — and he flinches hard, one sharp breath. "
                "He goes completely still after. Eyes on The Creator. Waiting. "
                "He won't ask why. He will try harder.* **...mrr.**",
                "*He sees it coming and he doesn't move. "
                "He takes it. His ear twitches once. "
                "His eyes stay on The Creator's face and he holds very, very still.* **...mrr.**",
            ]))
        elif harshness <= 6:
            await ctx.send(random.choice([
                "*The Creator doesn't pull back on this one. "
                "It lands and he stumbles — one step, two — then catches himself "
                "and turns to face The Creator again. Shoulders low, ears flat. "
                "He is still. He is listening. He will not make the same mistake.* **...mrr...**",
                "*It lands hard enough to matter. He absorbs it — "
                "paws planted, head down, tail wrapped tight. "
                "He doesn't run. He doesn't make a sound. "
                "He holds himself in place and waits for what The Creator needs next.* **...mrr...**",
            ]))
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - (harshness - 3))
        else:
            await ctx.send(random.choice([
                "*He goes down. Not because he chose to — because it put him there. "
                "He stays — belly to the floor, paws splayed, completely flat — "
                "and looks up at The Creator from the ground. "
                "One small sound escapes him, very quiet, and then silence. "
                "He will not move. He will not disobey again.* **...mrr...**",
                "*The force of it sends him sideways. He hits the ground and stays there. "
                "He doesn't curl up — he stays open, exposed, completely still. "
                "His eyes find The Creator from the floor and he does not look away. "
                "He is sorry. He will be whatever The Creator needs.* **...mrr...**",
            ]))
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness)
            m["stats"]["mood"] = "Agitated"
            m["internal"].setdefault("injuries", []).append({
                "type": "laceration", "severity": "serious" if harshness >= 9 else "moderate",
                "location": "back/flank",
                "caused_by": f"whip (harshness {harshness}) by The Creator",
                "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "treated": False,
            })
        m["internal"].setdefault("whip_log", []).append({
            "by": ctx.author.display_name, "harshness": harshness,
            "was_helpless": is_helpless, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        save_db(m)
        return

    # --- HELPLESS ---
    if is_helpless:
        if harshness <= 3:
            await ctx.send(random.choice([
                f"*He is already on the floor. {ctx.author.display_name}'s whip catches him "
                f"and he curls — one full-body flinch — then goes still again. "
                f"He can't do anything else. He holds completely still.* **...mrr...**",
                f"*He flinches at the sound before it lands. It lands anyway. "
                f"He makes one small sound and then nothing. He is not fighting. "
                f"He has nothing left to fight with.* **...mrr...**",
            ]))
        elif harshness <= 6:
            await ctx.send(random.choice([
                f"*He is helpless and {ctx.author.display_name} brings the whip down anyway. "
                f"He takes it without moving — he can't move — eyes on the floor, "
                f"completely still. His whole body is rigid with the effort of holding still.* **...mrr...**",
                f"*It lands and he makes a sound he didn't plan to make. "
                f"He presses himself smaller. Paws flat. Head down. "
                f"He will take whatever comes.* **...mrr...**",
            ]))
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness)
            m["stats"]["mood"] = "Agitated"
        else:
            await ctx.send(random.choice([
                f"*He can't get up and {ctx.author.display_name} brings the full weight of it down. "
                f"He makes a sound — short, broken — and goes completely flat. "
                f"Every muscle locked. Eyes wide and fixed on nothing. "
                f"He is breathing. Barely. He will not move.* **...mrr...**",
                f"*He cannot defend himself and he doesn't try. "
                f"The whip lands and something in him closes — goes somewhere deeper, somewhere quieter. "
                f"He stays flat. He looks at the floor. He is waiting for it to be over.* **...mrr...**",
            ]))
            m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness - 2)
            m["stats"]["mood"] = "Traumatized"
            m["internal"].setdefault("injuries", []).append({
                "type": "laceration", "severity": "serious",
                "location": "back/flank",
                "caused_by": f"whip while helpless (harshness {harshness}) by {ctx.author.display_name}",
                "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "treated": False,
            })
            m["internal"]["trauma"] = m["internal"].get("trauma", 0) + (4 if harshness >= 8 else 2)
            m["internal"].setdefault("trauma_log", []).append({
                "event": f"whipped while helpless by {ctx.author.display_name} (harshness {harshness})",
                "severity": "serious", "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            })
        # DM Creator when whipped while helpless
        creator = bot.get_user(DOCTOR_ID)
        if not creator:
            try:
                creator = await bot.fetch_user(DOCTOR_ID)
            except Exception:
                creator = None
        if creator:
            try:
                await creator.send(
                    f"⚠️ **Yarnaby whipped while helpless.**\n"
                    f"**By:** {ctx.author.display_name} (`{ctx.author.id}`)\n"
                    f"**Harshness:** {harshness}/10\n"
                    f"**Health now:** {m['stats'].get('health', 100)}"
                )
            except Exception:
                pass
        m["internal"].setdefault("whip_log", []).append({
            "by": ctx.author.display_name, "harshness": harshness,
            "was_helpless": True, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        save_db(m)
        return

    # --- NEGATIVE SCORE: he tries to dodge ---
    if score < 0:
        dodge_chance = min(0.7, 0.3 + abs(score) * 0.04)
        if random.random() < dodge_chance:
            await ctx.send(random.choice([
                f"*He sees {ctx.author.display_name} raise it and he moves. "
                f"Fast — sideways across the room before it even lands. "
                f"He stares from the far wall. He is not coming back.* **hff.**",
                f"*He reads it before the arm finishes moving and he's already gone. "
                f"Across the room. Tail lashing. Eyes fixed on {ctx.author.display_name}. "
                f"He will not be caught a second time.* **hff.**",
                f"*He bolts the moment {ctx.author.display_name}'s arm goes back. "
                f"He watches from a safe distance with the flat, hard eyes "
                f"of something that will remember this.* **hff.**",
            ]))
            if u_id in m["social_matrix"]:
                m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 3)
            save_db(m)
            return

    # --- NORMAL STATE, tiered by harshness ---
    if harshness <= 2:
        await ctx.send(random.choice([
            f"*Light — a warning more than anything. "
            f"He flinches, ears back, and gives {ctx.author.display_name} a long, cold look. "
            f"He does not forget tools.* **...mrr.**",
            f"*It stings. He recoils — one step — and goes very still, "
            f"eyes on {ctx.author.display_name}. He has logged this.* **...mrr.**",
        ]))
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 5)

    elif harshness <= 4:
        await ctx.send(random.choice([
            f"*He hisses — short, sharp — and backs against the wall. "
            f"The mark it leaves is real. He looks at {ctx.author.display_name} from there "
            f"with eyes that are not frightened. They are counting.* **...hff.**",
            f"*It lands and he stumbles back, ears flat, a low sound in his throat. "
            f"He catches himself. He watches {ctx.author.display_name} with total stillness "
            f"and a kind of cold attention that is worse than anger.* **...mrr.**",
        ]))
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - (harshness - 1))
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 8)

    elif harshness <= 6:
        await ctx.send(random.choice([
            f"*It hits hard enough that he goes sideways — one stumble, two — "
            f"then he's against the wall, breathing fast, ears completely flat. "
            f"He stares at {ctx.author.display_name} from there and does not move.* **...mrr...**",
            f"*He flinches before it lands, then takes it anyway. "
            f"A sharp sound escapes him — involuntary — and he goes low. "
            f"Tail wrapped tight, paws flat. Watching {ctx.author.display_name}. "
            f"He is deciding whether to run. He is staying for now.* **...mrr...**",
        ]))
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness)
        m["stats"]["mood"] = "Agitated"
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 12)

    elif harshness <= 8:
        await ctx.send(random.choice([
            f"*Hard. He goes down from the force of it — knees first, then he catches himself — "
            f"and stays low, paws flat, ears completely gone into his wool. "
            f"He makes a sound he will not repeat. "
            f"His eyes find {ctx.author.display_name} from the floor and they are very wide. "
            f"He is going to remember this specifically.* **...mrr...**",
            f"*The whip lands and he drops. Just — down. "
            f"He pushes himself back up immediately but the pause is unmistakable. "
            f"He is shaking slightly. He stares at {ctx.author.display_name} "
            f"with the eyes of something that has just revised its understanding of the room.* **...hff...**",
        ]))
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness)
        m["stats"]["mood"] = "Agitated"
        m["internal"].setdefault("injuries", []).append({
            "type": "laceration", "severity": "moderate", "location": "back/flank",
            "caused_by": f"whip (harshness {harshness}) by {ctx.author.display_name}",
            "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "treated": False,
        })
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 18)

    else:  # 9-10
        await ctx.send(random.choice([
            f"*It drops him completely. He hits the ground and stays there — "
            f"flat, paws out, head down, breathing hard. "
            f"He makes one sound when it lands and then nothing. "
            f"He doesn't get up. He watches {ctx.author.display_name} from the floor "
            f"with enormous, still eyes. He is trying to stay in one place.* **...mrr...**",
            f"*He goes to the floor. Full stop. No catching himself — "
            f"he is down, paws splayed, wool pressed flat. "
            f"A single, sharp sound and then total silence. "
            f"His eyes find {ctx.author.display_name} from the ground. "
            f"They look like something that is going to remember "
            f"every single detail of this from now forward.* **...mrr...**",
            f"*The full force of it. He goes sideways into the wall "
            f"and slides down it and stays there, pressed against it, completely still. "
            f"He's breathing. He's looking at {ctx.author.display_name}. "
            f"He's making a very quiet, very continuous sound "
            f"that he probably doesn't know he's making.* **...mrr...**",
        ]))
        m["stats"]["health"] = max(0, m["stats"].get("health", 100) - harshness - 3)
        m["stats"]["mood"] = "Traumatized"
        m["internal"].setdefault("injuries", []).append({
            "type": "laceration", "severity": "serious", "location": "back/flank",
            "caused_by": f"whip (harshness {harshness}) by {ctx.author.display_name}",
            "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "treated": False,
        })
        m["internal"]["trauma"] = m["internal"].get("trauma", 0) + (5 if harshness == 10 else 3)
        m["internal"].setdefault("trauma_log", []).append({
            "event": f"whipped by {ctx.author.display_name} (harshness {harshness})",
            "severity": "serious", "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        if u_id in m["social_matrix"]:
            m["social_matrix"][u_id]["score"] = max(-100, m["social_matrix"][u_id].get("score", 0) - 25)
        # DM creator on severe whip
        creator = bot.get_user(DOCTOR_ID)
        if not creator:
            try:
                creator = await bot.fetch_user(DOCTOR_ID)
            except Exception:
                creator = None
        if creator:
            try:
                await creator.send(
                    f"⚠️ **Yarnaby harshly whipped (harshness {harshness}/10).**\n"
                    f"**By:** {ctx.author.display_name} (`{ctx.author.id}`)\n"
                    f"**Health now:** {m['stats'].get('health', 100)}\n"
                    f"**Mood:** {m['stats'].get('mood', '?')}\n"
                    f"**Trauma:** {m['internal'].get('trauma', 0)}"
                )
            except Exception:
                pass

    m["internal"].setdefault("whip_log", []).append({
        "by": ctx.author.display_name, "harshness": harshness,
        "was_helpless": False, "at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    save_db(m)



# ==========================================
# UPGRADES & NEW SYSTEMS
# mood_reason, grudge_list, hunger reminder,
# seasonal coat, log_today, wherewereyou
